INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24136, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "定理就是已经被证明是对的数学道理。", "primary_collocate": null, "pronunciation": "dìng lǐ", "ipa": "tiŋ˥˩ li˨˩˦", "syllable_count": 2, "sentences": [{"text": "这个定理是对的。", "target_word": "定理", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "我们今天学一个新定理。", "target_word": "定理", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "老师说，这个定理很有用。", "target_word": "定理", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "他会用这个定理做数学题。", "target_word": "定理", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "书上写着这个定理的名字。", "target_word": "定理", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个定理已经有人证明过了。", "target_word": "定理", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请你把这个定理抄在本子上。", "target_word": "定理", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "弟弟总是记不住数学书里的定理。", "target_word": "定理", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个定理能帮我们算出答案。", "target_word": "定理", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "大家都不知道这个定理为什么是对的。", "target_word": "定理", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "已经证明是对的数学道理", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '427906b5-fb0b-4248-ba62-52818e8c3b15') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24136, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "定理", "is_correct": true, "explanation": "正确答案：定理（dìng lǐ），指已经证明是对的数学道理。"}, {"text": "地理", "is_correct": false, "explanation": "dì lǐ 与 dìng lǐ 的第一个音节不同：dì 没有韵尾 ng，意思是地理。"}, {"text": "病理", "is_correct": false, "explanation": "bìng lǐ 与 dìng lǐ 的第一个音节声母不同：b 与 d，意思是病理。"}, {"text": "定例", "is_correct": false, "explanation": "dìng lì 与 dìng lǐ 的第二个音节声调不同：lì（第四声）与 lǐ（第三声），意思是惯例、定规。"}], "explanations": {"定理": "正确答案：定理（dìng lǐ），指已经证明是对的数学道理。", "地理": "dì lǐ 与 dìng lǐ 的第一个音节不同：dì 没有韵尾 ng，意思是地理。", "病理": "bìng lǐ 与 dìng lǐ 的第一个音节声母不同：b 与 d，意思是病理。", "定例": "dìng lì 与 dìng lǐ 的第二个音节声调不同：lì（第四声）与 lǐ（第三声），意思是惯例、定规。"}, "sentence_index": null, "correct_answer": "定理"}, "level_3": {"options": [{"text": "定理", "is_correct": true, "explanation": "正确答案：定理。这里指已经证明为对的数学道理，可以说“是对的”。"}, {"text": "石头", "is_correct": false, "explanation": "语义：石头是实物，不能被判断为对或错。"}, {"text": "影子", "is_correct": false, "explanation": "语义：影子是光线形成的暗像，没有对错可言。"}, {"text": "脚步", "is_correct": false, "explanation": "搭配：“对的”用于说法、道理，“这个脚步是对的”搭配不通。"}], "explanations": {"定理": "正确答案：定理。这里指已经证明为对的数学道理，可以说“是对的”。", "石头": "语义：石头是实物，不能被判断为对或错。", "影子": "语义：影子是光线形成的暗像，没有对错可言。", "脚步": "搭配：“对的”用于说法、道理，“这个脚步是对的”搭配不通。"}, "sentence_index": 0, "correct_answer": "定理"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "物理课上老师讲了一条关于天气变化的定理。", "explanation": "这里应该用〈规律〉。定理指经证明的数学或逻辑命题；天气变化的道理属于自然规律，应说“规律”。"}, {"text": "这台机器的工作定理很简单。", "explanation": "这里应该用〈原理〉。讲机器怎样工作的道理叫原理，定理指经证明的数学或逻辑命题。"}, {"text": "他从多年的工作中总结出一条宝贵的定理。", "explanation": "这里应该用〈经验〉。定理指经证明的数学或逻辑命题，从实践中总结的体会要用经验。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '07b6ee61-cecc-48e4-9ec5-c4d0a6ee8713') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24136, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "定理", "is_correct": true, "explanation": "正确答案：定理（dìng lǐ），指已经证明是对的数学道理。"}, {"text": "地里", "is_correct": false, "explanation": "dì lǐ 与 dìng lǐ 的第一个音节韵尾不同：dì 没有 ng，意思是地里。"}, {"text": "命理", "is_correct": false, "explanation": "mìng lǐ 与 dìng lǐ 的第一个音节声母不同：m 与 d，意思是命理。"}, {"text": "订立", "is_correct": false, "explanation": "dìng lì 与 dìng lǐ 的第二个音节声调不同：lì（第四声）与 lǐ（第三声），意思是订立。"}], "explanations": {"定理": "正确答案：定理（dìng lǐ），指已经证明是对的数学道理。", "地里": "dì lǐ 与 dìng lǐ 的第一个音节韵尾不同：dì 没有 ng，意思是地里。", "命理": "mìng lǐ 与 dìng lǐ 的第一个音节声母不同：m 与 d，意思是命理。", "订立": "dìng lì 与 dìng lǐ 的第二个音节声调不同：lì（第四声）与 lǐ（第三声），意思是订立。"}, "sentence_index": null, "correct_answer": "定理"}, "level_3": {"options": [{"text": "定理", "is_correct": true, "explanation": "正确答案：定理。可以抄在本子上的是文字性的道理，定理符合。"}, {"text": "雨伞", "is_correct": false, "explanation": "语义：雨伞是用具，不是文字，不能抄在本子上。"}, {"text": "乐器", "is_correct": false, "explanation": "搭配：“抄”用于文字、数字，不能抄乐器。"}, {"text": "盘子", "is_correct": false, "explanation": "语义：盘子是器皿，与“抄在本子上”的含义不相容。"}], "explanations": {"定理": "正确答案：定理。可以抄在本子上的是文字性的道理，定理符合。", "雨伞": "语义：雨伞是用具，不是文字，不能抄在本子上。", "乐器": "搭配：“抄”用于文字、数字，不能抄乐器。", "盘子": "语义：盘子是器皿，与“抄在本子上”的含义不相容。"}, "sentence_index": 6, "correct_answer": "定理"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我们班一直坚持一个基本定理：不欺负同学。", "explanation": "这里应该用〈原则〉。定理指经证明的数学或逻辑命题，班级共同遵守的准则要用原则。"}, {"text": "这本词典给出了“三角形”的一个清楚的定理。", "explanation": "这里应该用〈定义〉。定义是解释词语含义的文字，定理是经证明的命题。"}, {"text": "这个定理还没人证明，大家只是猜它是对的。", "explanation": "这里应该用〈猜想〉。定理已经证明为对，“还没人证明”与之矛盾；未经证明的推测叫猜想。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '07b6ee61-cecc-48e4-9ec5-c4d0a6ee8713') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24136, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "老师说，这本定理很容易理解。", "corrected_sentence": "老师说，这条定理很容易理解。", "error_description": "“这本定理”错，应为“这条定理”。定理不是书，量词用“条”或“个”，不用“本”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '07b6ee61-cecc-48e4-9ec5-c4d0a6ee8713') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24136, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他在这个定理很感兴趣。", "corrected_sentence": "他对这个定理很感兴趣。", "error_description": "“在这个定理”错，应为“对这个定理”。表示感兴趣的对象要用介词“对”，说“对……感兴趣”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '07b6ee61-cecc-48e4-9ec5-c4d0a6ee8713') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
