INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24146, 1, 'prompt1_core', '{"pos": "情态动词", "semantic_class": "function", "definition": "不够用来做某事。", "primary_collocate": null, "pronunciation": "bù zú yǐ", "ipa": "pu˥˩ tsu˧˥ i˨˩˦", "syllable_count": 3, "sentences": [{"text": "这点米不足以做五个人的饭。", "target_word": "不足以", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "小小的房间不足以放下这么多书。", "target_word": "不足以", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "现在的证据不足以让警察抓人。", "target_word": "不足以", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "老师给的时间不足以写完作文。", "target_word": "不足以", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "一杯水不足以解渴。", "target_word": "不足以", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "我的钱不足以去国外旅行。", "target_word": "不足以", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这张桌子不足以坐十个人。", "target_word": "不足以", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他的话不足以改变我的想法。", "target_word": "不足以", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "一件外套不足以挡住冬天的冷风。", "target_word": "不足以", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这些材料不足以写好一篇文章。", "target_word": "不足以", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "足以", "label": "肯定式"}], "register": "书面", "sense_fingerprint": "不足以：不够用来做某事", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '55e7a08c-7c03-491c-a1cf-48d19ddbaf4d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24146, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "不足以", "is_correct": true, "explanation": "正确。「这点米不足以做五个人的饭」表示米的量不够。"}, {"text": "必须", "is_correct": false, "explanation": "语义：「这点米必须做五个人的饭」表示要求，与「这点米」量不够的语境相矛盾。"}, {"text": "不愿", "is_correct": false, "explanation": "搭配：「不愿」的主语应是有意愿的人，不能用于「这点米」。"}, {"text": "不得", "is_correct": false, "explanation": "语域：「不得」是书面禁令用语，与日常做饭的描述不搭。"}], "explanations": {"不足以": "正确。「这点米不足以做五个人的饭」表示米的量不够。", "必须": "语义：「这点米必须做五个人的饭」表示要求，与「这点米」量不够的语境相矛盾。", "不愿": "搭配：「不愿」的主语应是有意愿的人，不能用于「这点米」。", "不得": "语域：「不得」是书面禁令用语，与日常做饭的描述不搭。"}, "sentence_index": 0, "correct_answer": "不足以"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这间教室很大，不足以坐下三十个学生。", "explanation": "这里应该用〈足以〉。「很大」说明空间够用，应用「足以」，「不足以」表示不够，与语境矛盾。"}, {"text": "这碗饭很多，不足以让我吃饱。", "explanation": "这里应该用〈足以〉。「很多」说明量够，应用「足以」表示足够。"}, {"text": "他的时间很充裕，不足以完成作业。", "explanation": "这里应该用〈足以〉。「很充裕」说明时间够，应用「足以」表示足够。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6e6ba89e-2951-4d3c-b521-1d586643ccc5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24146, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "不足以", "is_correct": true, "explanation": "正确。「这张桌子不足以坐十个人」表示桌子的容量不够。"}, {"text": "必定", "is_correct": false, "explanation": "语义：「必定」表示确定的结果，与「这张桌子」的容量限制不符。"}, {"text": "不肯", "is_correct": false, "explanation": "搭配：「不肯」的主语应是有意愿的人，用于「这张桌子」不通顺。"}, {"text": "不许", "is_correct": false, "explanation": "语义：「不许」表示禁止，与桌子的容量无关。"}], "explanations": {"不足以": "正确。「这张桌子不足以坐十个人」表示桌子的容量不够。", "必定": "语义：「必定」表示确定的结果，与「这张桌子」的容量限制不符。", "不肯": "搭配：「不肯」的主语应是有意愿的人，用于「这张桌子」不通顺。", "不许": "语义：「不许」表示禁止，与桌子的容量无关。"}, "sentence_index": 6, "correct_answer": "不足以"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这份资料很详细，不足以写好一篇论文。", "explanation": "这里应该用〈足以〉。「很详细」说明资料够用，应用「足以」，用「不足以」与语境矛盾。"}, {"text": "这台电脑很快，不足以运行这个程序。", "explanation": "这里应该用〈足以〉。「很快」说明性能够，应用「足以」表示足够。"}, {"text": "这套工具很齐全，不足以修好这台机器。", "explanation": "这里应该用〈足以〉。「很齐全」说明工具够用，应用「足以」表示足够。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6e6ba89e-2951-4d3c-b521-1d586643ccc5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24146, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这些钱很不足以买一张演唱会门票。", "corrected_sentence": "这些钱不足以买一张演唱会门票。", "error_description": "副词错误：「很」不能直接修饰「不足以」，应直接说「不足以买」，去掉「很」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6e6ba89e-2951-4d3c-b521-1d586643ccc5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24146, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这笔奖金不足以的买一辆车。", "corrected_sentence": "这笔奖金不足以买一辆车。", "error_description": "助词错误：「不足以」后直接接动词，「以」之后不能加「的」，应说「不足以买」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6e6ba89e-2951-4d3c-b521-1d586643ccc5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24148, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "固定", "is_correct": false, "explanation": "与“减小”不是反义关系，指使其位置或状态不动。"}, {"text": "增大", "is_correct": true, "explanation": "正确：“增大”与“减小”反义，指让东西变得大一些。"}, {"text": "检验", "is_correct": false, "explanation": "与“减小”不是反义关系，指检查是否合格。"}, {"text": "保持", "is_correct": false, "explanation": "与“减小”不是反义关系，指维持原样。"}], "correct_answer": "增大", "explanations": {"固定": "与“减小”不是反义关系，指使其位置或状态不动。", "增大": "正确：“增大”与“减小”反义，指让东西变得大一些。", "检验": "与“减小”不是反义关系，指检查是否合格。", "保持": "与“减小”不是反义关系，指维持原样。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6e6ba89e-2951-4d3c-b521-1d586643ccc5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24148, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "冷却", "is_correct": false, "explanation": "与“减小”不是反义关系，指降低温度。"}, {"text": "增大", "is_correct": true, "explanation": "正确：“增大”与“减小”反义，指让东西变大。"}, {"text": "挑选", "is_correct": false, "explanation": "与“减小”不是反义关系，指从多个中选出需要的。"}, {"text": "搬运", "is_correct": false, "explanation": "与“减小”不是反义关系，指把东西从一处移到另一处。"}], "correct_answer": "增大", "explanations": {"冷却": "与“减小”不是反义关系，指降低温度。", "增大": "正确：“增大”与“减小”反义，指让东西变大。", "挑选": "与“减小”不是反义关系，指从多个中选出需要的。", "搬运": "与“减小”不是反义关系，指把东西从一处移到另一处。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6e6ba89e-2951-4d3c-b521-1d586643ccc5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24148, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "让东西变得小一点。", "primary_collocate": null, "pronunciation": "jiǎn xiǎo", "ipa": "tɕjɛn˨˩˦ ɕjɑʊ˨˩˦", "syllable_count": 2, "sentences": [{"text": "请把图片的尺寸减小一点。", "target_word": "减小", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他把屏幕上的字体减小了。", "target_word": "减小", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "工人把管子的直径减小了两厘米。", "target_word": "减小", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "为了省地方，他减小了桌子的面积。", "target_word": "减小", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "把文件的体积减小，发邮件就快了。", "target_word": "减小", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "设计师减小了灯的体积，更方便带着走。", "target_word": "减小", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这张照片太大，请减小它的尺寸。", "target_word": "减小", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个箱子的体积需要减小一半。", "target_word": "减小", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "医生说肿块已经减小了一点。", "target_word": "减小", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "把瓶口减小一点，水就不会洒出来了。", "target_word": "减小", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "减小了", "label": "体标"}, {"form": "减小过", "label": "体标"}], "register": "中性", "sense_fingerprint": "把东西的尺寸、体积、面积弄小一点", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '55e7a08c-7c03-491c-a1cf-48d19ddbaf4d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24148, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "分享", "is_correct": false, "explanation": "搭配：“分享”的对象是东西或感受，不能说“分享尺寸”。"}, {"text": "唱", "is_correct": false, "explanation": "语义：尺寸不能被“唱”，句意不通。"}, {"text": "减小", "is_correct": true, "explanation": "正确：让图片的尺寸变小一点，用“减小”。"}, {"text": "测量", "is_correct": false, "explanation": "语义：“测量”是动作，不表示尺寸变小，与“一点”的要求不符。"}], "explanations": {"分享": "搭配：“分享”的对象是东西或感受，不能说“分享尺寸”。", "唱": "语义：尺寸不能被“唱”，句意不通。", "减小": "正确：让图片的尺寸变小一点，用“减小”。", "测量": "语义：“测量”是动作，不表示尺寸变小，与“一点”的要求不符。"}, "sentence_index": 0, "correct_answer": "减小"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他的年龄减小了两岁。", "explanation": "这里不能用〈减小〉。减小指东西变小或数量、程度变少；年龄只会增长，不能减小，想说年纪变小应用“变年轻”。"}, {"text": "会议减小了一个小时。", "explanation": "这里应该用〈缩短〉。时间的长度用“缩短”，“减小”不用于时间。"}, {"text": "他减小了文章的段落。", "explanation": "这里应该用〈删减〉。去掉部分内容用“删减”，“减小”不指删去段落。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6e6ba89e-2951-4d3c-b521-1d586643ccc5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24148, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "哭", "is_correct": false, "explanation": "配价：“哭”是不及物动词，不能带“尺寸”作宾语。"}, {"text": "减小", "is_correct": true, "explanation": "正确：照片太大，所以请把它的尺寸减小。"}, {"text": "放大", "is_correct": false, "explanation": "语义：照片太大却要求放大尺寸，与句中“太大”矛盾。"}, {"text": "吃", "is_correct": false, "explanation": "搭配：“吃”不能与“尺寸”搭配。"}], "explanations": {"哭": "配价：“哭”是不及物动词，不能带“尺寸”作宾语。", "减小": "正确：照片太大，所以请把它的尺寸减小。", "放大": "语义：照片太大却要求放大尺寸，与句中“太大”矛盾。", "吃": "搭配：“吃”不能与“尺寸”搭配。"}, "sentence_index": 6, "correct_answer": "减小"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这次培训减小了员工的水平。", "explanation": "这里应该用〈提高〉。水平要说“提高”，“减小”用于尺寸、体积或程度的变小。"}, {"text": "这张桌子的颜色减小了。", "explanation": "这里应该用〈变浅〉。减小指尺寸、体积或程度的变小；颜色变浅要说“变浅”，不说“减小”。"}, {"text": "这份报告的主题减小了。", "explanation": "这里应该用〈淡化〉。减小指东西变小或数量、程度变少；主题是抽象内容，不说减小，主题变弱要说“淡化”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6e6ba89e-2951-4d3c-b521-1d586643ccc5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24148, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "把铁板的厚度把减小一半。", "corrected_sentence": "把铁板的厚度减小一半。", "error_description": "错误：「把」字句中只能用一个「把」，句中多出的「把」应删去；应说“把铁板的厚度减小一半”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6e6ba89e-2951-4d3c-b521-1d586643ccc5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24148, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "瓶口再减小一条，水就不会洒了。", "corrected_sentence": "瓶口再减小一点，水就不会洒了。", "error_description": "量词错误：表示减小的程度应说“一点”，“条”用于细长的事物，不能用来修饰瓶口。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6e6ba89e-2951-4d3c-b521-1d586643ccc5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
