INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24150, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "大家都很喜欢的、很好的。", "primary_collocate": null, "pronunciation": "jīng diǎn", "ipa": "tɕiŋ˥˥ tjɛn˨˩˦", "syllable_count": 2, "sentences": [{"text": "这首歌很经典，大家都喜欢听。", "target_word": "经典", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这部老电影真经典。", "target_word": "经典", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个红色的包设计很经典。", "target_word": "经典", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她穿了一件经典的黑色裙子。", "target_word": "经典", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这道菜的味道很经典。", "target_word": "经典", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "经典的老歌，我听过很多遍。", "target_word": "经典", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个游戏的画面很经典，所以很多人玩过。", "target_word": "经典", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这句话太经典了，大家都记住了。", "target_word": "经典", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家店的经典蛋糕最好卖。", "target_word": "经典", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他讲的笑话很经典，我们都笑了。", "target_word": "经典", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "经典作品", "label": "复合"}], "register": "中性", "sense_fingerprint": "形容事物很好、深受大家喜爱、有代表性", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '55e7a08c-7c03-491c-a1cf-48d19ddbaf4d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24150, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "经典", "is_correct": true, "explanation": "正确答案。经典 jīng diǎn，形容事物很好、深受大家喜爱。"}, {"text": "景点", "is_correct": false, "explanation": "jǐng（第三声）与 jīng（第一声）声调不同，意思是景点。"}, {"text": "清点", "is_correct": false, "explanation": "qīng 与 jīng 声母不同，意思是清查、点数。"}, {"text": "星点", "is_correct": false, "explanation": "xīng 与 jīng 声母不同，意思是星星般的小点。"}], "explanations": {"经典": "正确答案。经典 jīng diǎn，形容事物很好、深受大家喜爱。", "景点": "jǐng（第三声）与 jīng（第一声）声调不同，意思是景点。", "清点": "qīng 与 jīng 声母不同，意思是清查、点数。", "星点": "xīng 与 jīng 声母不同，意思是星星般的小点。"}, "sentence_index": null, "correct_answer": "经典"}, "level_3": {"options": [{"text": "经典", "is_correct": true, "explanation": "正确。「这首歌很经典」表示很好、深受大家喜爱，与后句「大家都喜欢听」一致。"}, {"text": "冷门", "is_correct": false, "explanation": "语义：「冷门」指少人关注、不受欢迎，与「大家都喜欢听」相反。"}, {"text": "无聊", "is_correct": false, "explanation": "语义：「无聊」是负面评价，与「大家都喜欢听」矛盾。"}, {"text": "粗糙", "is_correct": false, "explanation": "搭配：「粗糙」多形容质地、表面，不用来评价歌曲，与「大家都喜欢听」也不协调。"}], "explanations": {"经典": "正确。「这首歌很经典」表示很好、深受大家喜爱，与后句「大家都喜欢听」一致。", "冷门": "语义：「冷门」指少人关注、不受欢迎，与「大家都喜欢听」相反。", "无聊": "语义：「无聊」是负面评价，与「大家都喜欢听」矛盾。", "粗糙": "搭配：「粗糙」多形容质地、表面，不用来评价歌曲，与「大家都喜欢听」也不协调。"}, "sentence_index": 0, "correct_answer": "经典"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这款游戏的剧情很经典，玩家都觉得是烂剧情。", "explanation": "这里误用了〈经典〉。「经典」表示很好、大家都喜欢，用来形容大家都觉得烂的剧情不合适，此处应改用〈糟糕〉。"}, {"text": "这位科学家很经典，所以大家都不认识他。", "explanation": "这里应该用〈著名〉。「经典」一般不用来形容人，且“很经典，所以大家都不认识他”前后矛盾，应说“很著名，大家都认识他”。"}, {"text": "这家餐厅的服务很经典，客人都投诉了。", "explanation": "这里误用了〈经典〉。「经典」表示事物很好、大家都喜欢，与「客人都投诉」矛盾，服务差应说〈糟糕〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6e6ba89e-2951-4d3c-b521-1d586643ccc5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24150, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "经典", "is_correct": true, "explanation": "正确。「画面很经典」表示很好、深受喜爱，与「很多人玩过」一致。"}, {"text": "难看", "is_correct": false, "explanation": "语义：「难看」是负面评价，与「很多人玩过」的受欢迎之意矛盾。"}, {"text": "低劣", "is_correct": false, "explanation": "语义：「低劣」表示质量差，与「很多人玩过」矛盾。"}, {"text": "呆板", "is_correct": false, "explanation": "体貌：「呆板」多形容神态、外观僵硬，不符合对画面的正面评价，与「很多人玩过」也不协调。"}], "explanations": {"经典": "正确。「画面很经典」表示很好、深受喜爱，与「很多人玩过」一致。", "难看": "语义：「难看」是负面评价，与「很多人玩过」的受欢迎之意矛盾。", "低劣": "语义：「低劣」表示质量差，与「很多人玩过」矛盾。", "呆板": "体貌：「呆板」多形容神态、外观僵硬，不符合对画面的正面评价，与「很多人玩过」也不协调。"}, "sentence_index": 6, "correct_answer": "经典"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这份报告很经典，所以老板把它扔进了垃圾桶。", "explanation": "这里误用了〈经典〉。「经典」表示很好、大家都喜欢，报告被扔掉说明它不受欢迎，此处应改用〈糟糕〉之类的评价。"}, {"text": "这种设计已经经典了，大家都不喜欢。", "explanation": "这里应该用〈陈旧〉。「经典」表示很好、深受喜爱，不能用来形容过时、不受欢迎的设计。"}, {"text": "这家饭店的菜很经典，客人都很失望。", "explanation": "这里误用了〈经典〉。「经典」表示很好、大家都喜欢，与「客人都很失望」矛盾，此处应改用〈难吃〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6e6ba89e-2951-4d3c-b521-1d586643ccc5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24150, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这部电影没经典，但我看了三遍。", "corrected_sentence": "这部电影不经典，但我看了三遍。", "error_description": "否定词错误：形容词「经典」的否定一般用「不」，说「不经典」；「没」多与动词或「有」搭配，「没经典」不自然。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6e6ba89e-2951-4d3c-b521-1d586643ccc5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24150, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这部老片很的经典，我们都爱看。", "corrected_sentence": "这部老片很经典，我们都爱看。", "error_description": "助词错误：「很」修饰形容词「经典」时不加「的」，应说「很经典」，不说「很的经典」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6e6ba89e-2951-4d3c-b521-1d586643ccc5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24154, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "向上", "is_correct": true, "explanation": "向上与向下是反义词，表示指向上面那个方向。"}, {"text": "慢慢", "is_correct": false, "explanation": "慢慢表示速度缓慢，与方向无关，不是向下的反义词。"}, {"text": "突然", "is_correct": false, "explanation": "突然表示出乎意料地发生，与方向无关，不构成反义。"}, {"text": "立刻", "is_correct": false, "explanation": "立刻表示马上，说的是时间，与向下没有反义关系。"}], "correct_answer": "向上", "explanations": {"向上": "向上与向下是反义词，表示指向上面那个方向。", "慢慢": "慢慢表示速度缓慢，与方向无关，不是向下的反义词。", "突然": "突然表示出乎意料地发生，与方向无关，不构成反义。", "立刻": "立刻表示马上，说的是时间，与向下没有反义关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '342756bf-486d-4402-ac39-77679b4abffe') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24154, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "向上", "is_correct": true, "explanation": "向上与向下是反义词，表示指向上面那个方向。"}, {"text": "不断", "is_correct": false, "explanation": "不断表示持续、接连不停，与方向无关，不是向下的反义词。"}, {"text": "缓缓", "is_correct": false, "explanation": "缓缓形容动作慢，与方向无关，不构成反义。"}, {"text": "立即", "is_correct": false, "explanation": "立即表示马上，说的是时间，与向下没有反义关系。"}], "correct_answer": "向上", "explanations": {"向上": "向上与向下是反义词，表示指向上面那个方向。", "不断": "不断表示持续、接连不停，与方向无关，不是向下的反义词。", "缓缓": "缓缓形容动作慢，与方向无关，不构成反义。", "立即": "立即表示马上，说的是时间，与向下没有反义关系。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '342756bf-486d-4402-ac39-77679b4abffe') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24154, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "指向下面那个方向。", "primary_collocate": null, "pronunciation": "xiàng xià", "ipa": "ɕjɑŋ˥˩ ɕja˥˩", "syllable_count": 2, "sentences": [{"text": "箭头向下，表示要往下走。", "target_word": "向下", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他手心向下，放在桌子上。", "target_word": "向下", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个标志的方向向下。", "target_word": "向下", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "图上的箭头都向下。", "target_word": "向下", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那朵花的头向下，好像没力气。", "target_word": "向下", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的手指向下，指着地图。", "target_word": "向下", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "屏幕上的小三角向下，点它就能看到下面的选项。", "target_word": "向下", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这把伞的口向下，雨水会流出来。", "target_word": "向下", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "蝙蝠睡觉时头向下。", "target_word": "向下", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这台机器的喷嘴向下，正在给花园浇水。", "target_word": "向下", "complexity_tier": "T3", "furigana": "zhè tái jī qì de pēn zuǐ xiàng xià zhèng zài gěi huā yuán jiāo shuǐ", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "朝向下面的方向", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b82d5183-2e13-461d-aa42-0ed00adf61ab') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24154, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "向下", "is_correct": true, "explanation": "xiàng xià 意思是指向下面那个方向。"}, {"text": "乡下", "is_correct": false, "explanation": "xiāng xià（第一声）与 xiàng xià（第四声）声调不同，意思是乡村。"}, {"text": "线下", "is_correct": false, "explanation": "xiàn xià 与 xiàng xià 韵母不同（an 与 ang），意思是线下、不在网络上。"}, {"text": "现下", "is_correct": false, "explanation": "xiàn xià 与 xiàng xià 韵母不同（an 与 ang），意思是现在。"}], "explanations": {"向下": "xiàng xià 意思是指向下面那个方向。", "乡下": "xiāng xià（第一声）与 xiàng xià（第四声）声调不同，意思是乡村。", "线下": "xiàn xià 与 xiàng xià 韵母不同（an 与 ang），意思是线下、不在网络上。", "现下": "xiàn xià 与 xiàng xià 韵母不同（an 与 ang），意思是现在。"}, "sentence_index": null, "correct_answer": "向下"}, "level_3": {"options": [{"text": "向下", "is_correct": true, "explanation": "“向下”指箭头指向低处，与后半句“表示要往下走”一致。"}, {"text": "向上", "is_correct": false, "explanation": "语义：箭头向上指的是往上走，与“表示要往下走”矛盾。"}, {"text": "朝左", "is_correct": false, "explanation": "语义：箭头指左，指向的不是下面，与“表示要往下走”不符。"}, {"text": "指右", "is_correct": false, "explanation": "语义：“指右”指朝右边，与“表示要往下走”的意思不符。"}], "explanations": {"向下": "“向下”指箭头指向低处，与后半句“表示要往下走”一致。", "向上": "语义：箭头向上指的是往上走，与“表示要往下走”矛盾。", "朝左": "语义：箭头指左，指向的不是下面，与“表示要往下走”不符。", "指右": "语义：“指右”指朝右边，与“表示要往下走”的意思不符。"}, "sentence_index": 0, "correct_answer": "向下"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他的飞机向下飞，离地越来越远。", "explanation": "这里应该用〈向上〉。离地越来越远是朝上飞，不能用向下。"}, {"text": "他向下买了一本书。", "explanation": "这里不用〈向下〉，直接说“买”即可。“向下”表示朝低处，与买书的动作无关。"}, {"text": "我们向下商量这个问题吧。", "explanation": "这里应该用〈往下〉，表示接着说下去。向下只表示朝低处的方向，不能用来表示接着商量。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '342756bf-486d-4402-ac39-77679b4abffe') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24154, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "向下", "is_correct": true, "explanation": "“向下”指小三角指向下方，与“看到下面的选项”一致。"}, {"text": "向外", "is_correct": false, "explanation": "语义：小三角朝外指的是向外的方向，与句中所说的下方指向不符。"}, {"text": "向左", "is_correct": false, "explanation": "语义：小三角指向左边，与句中的下方指向不符。"}, {"text": "朝右", "is_correct": false, "explanation": "语义：小三角指向右边，与句中的下方指向不符。"}], "explanations": {"向下": "“向下”指小三角指向下方，与“看到下面的选项”一致。", "向外": "语义：小三角朝外指的是向外的方向，与句中所说的下方指向不符。", "向左": "语义：小三角指向左边，与句中的下方指向不符。", "朝右": "语义：小三角指向右边，与句中的下方指向不符。"}, "sentence_index": 6, "correct_answer": "向下"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他把书向下搬到了楼上。", "explanation": "这里应该用〈向上〉。搬到楼上是朝高处，不能用向下。"}, {"text": "他仰头向下看着天空。", "explanation": "这里应该用〈向上〉。仰头看天空是朝上看，不能用向下。"}, {"text": "妈妈向下炒了一盘菜。", "explanation": "这里不用〈向下〉，直接说“炒”即可。“向下”表示朝低处，与炒菜的动作无关。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '342756bf-486d-4402-ac39-77679b4abffe') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24154, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "路牌上的箭头在向下，提示前面有台阶。", "corrected_sentence": "路牌上的箭头向下，提示前面有台阶。", "error_description": "错误：“在向下”；正确：“向下”。“在”后面要接动词表示正在进行，“箭头在向下”缺少动词；“向下”直接描述“箭头”的朝向，不需要“在”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '342756bf-486d-4402-ac39-77679b4abffe') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24154, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "吊灯的灯罩很向下，光线照在桌子上。", "corrected_sentence": "吊灯的灯罩向下，光线照在桌子上。", "error_description": "错误：“很向下”；正确：“向下”。“向下”表示朝向，不能受程度副词“很”修饰。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '342756bf-486d-4402-ac39-77679b4abffe') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
