INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24156, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "飞机或小鸟飞行时，身体和风的方向之间有一个角度，这个角度叫攻角。", "primary_collocate": null, "pronunciation": "gōng jiǎo", "ipa": "kʊŋ˥ tɕjɑʊ˨˩˦", "syllable_count": 2, "sentences": [{"text": "小鸟飞行时，身体和风有一个攻角。", "target_word": "攻角", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老鹰张开翅膀，改变了攻角。", "target_word": "攻角", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "纸飞机的攻角太大，会掉下来。", "target_word": "攻角", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师在黑板上画出了攻角。", "target_word": "攻角", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "攻角合适，飞机才能飞得高。", "target_word": "攻角", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "风从前面吹来，攻角就变小了。", "target_word": "攻角", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这只鸟抬高头，攻角变大了。", "target_word": "攻角", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学生在课上学习了什么是攻角。", "target_word": "攻角", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "飞机起飞时，攻角比平时大。", "target_word": "攻角", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我想看看这个攻角有多大。", "target_word": "攻角", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "专业", "sense_fingerprint": "飞行物身体与风向之间的角度", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b82d5183-2e13-461d-aa42-0ed00adf61ab') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24156, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "攻角", "is_correct": true, "explanation": "“身体和风有一个攻角”指飞行物身体与风向之间的夹角，与句意相符。"}, {"text": "速度", "is_correct": false, "explanation": "语义：速度说明运动的快慢，不是身体与风之间的夹角。"}, {"text": "距离", "is_correct": false, "explanation": "语义：距离说明两者之间的远近，不是两者方向之间的角度。"}, {"text": "温度", "is_correct": false, "explanation": "语义：温度与身体和风的方向关系无关，不能表示二者之间的角度。"}], "explanations": {"攻角": "“身体和风有一个攻角”指飞行物身体与风向之间的夹角，与句意相符。", "速度": "语义：速度说明运动的快慢，不是身体与风之间的夹角。", "距离": "语义：距离说明两者之间的远近，不是两者方向之间的角度。", "温度": "语义：温度与身体和风的方向关系无关，不能表示二者之间的角度。"}, "sentence_index": 0, "correct_answer": "攻角"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "屋顶的攻角很陡。", "explanation": "这里应该用〈角度〉。攻角专指飞行物身体与风向之间的夹角，屋顶的倾斜应用角度。"}, {"text": "他抬头看飞机，攻角很大。", "explanation": "这里应该用〈仰角〉。攻角指飞行物与风向的夹角，观察者抬头看物体的角度应用仰角。"}, {"text": "两条线形成一个攻角。", "explanation": "这里应该用〈夹角〉。攻角只用于飞行物身体与风向之间，两条线形成的一般夹角应用夹角。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '342756bf-486d-4402-ac39-77679b4abffe') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24156, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "攻角", "is_correct": true, "explanation": "“这只鸟抬高头，攻角变大了”指鸟身与风向之间的夹角变大，与句意相符。"}, {"text": "体重", "is_correct": false, "explanation": "语义：抬高头不会让体重变大，与“变大了”的语境不符。"}, {"text": "音量", "is_correct": false, "explanation": "语义：抬头与音量的变化没有关系，句子语义不通。"}, {"text": "价格", "is_correct": false, "explanation": "语义：价格与鸟抬头的动作无关，不能用来描述这一变化。"}], "explanations": {"攻角": "“这只鸟抬高头，攻角变大了”指鸟身与风向之间的夹角变大，与句意相符。", "体重": "语义：抬高头不会让体重变大，与“变大了”的语境不符。", "音量": "语义：抬头与音量的变化没有关系，句子语义不通。", "价格": "语义：价格与鸟抬头的动作无关，不能用来描述这一变化。"}, "sentence_index": 6, "correct_answer": "攻角"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "三角形的一个攻角很大。", "explanation": "这里应该用〈内角〉。攻角只用于飞行物身体与风向之间，三角形的角应用内角。"}, {"text": "从这个攻角看，房子很大。", "explanation": "这里应该用〈视角〉。攻角指飞行物身体与风向的夹角，观察的角度应用视角。"}, {"text": "地轴的攻角是二十三度。", "explanation": "这里应该用〈倾角〉。攻角只用于飞行物身体与风向之间，地轴的倾斜应用倾角。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '342756bf-486d-4402-ac39-77679b4abffe') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24156, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我想看看这三只攻角。", "corrected_sentence": "我想看看这三个攻角。", "error_description": "攻角的量词是“个”，不用“只”。应说“这三个攻角”，不能说“这三只攻角”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '342756bf-486d-4402-ac39-77679b4abffe') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24156, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "那只老鹰抬起头，攻角变了大。", "corrected_sentence": "那只老鹰抬起头，攻角变大了。", "error_description": "错误：“攻角变了大”；正确：“攻角变大了”。“了”要放在结果补语“大”的后面，说明攻角变化的结果。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '342756bf-486d-4402-ac39-77679b4abffe') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24158, 1, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6e6ba89e-2951-4d3c-b521-1d586643ccc5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
