INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24158, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "定律是科学家发现的，世界上的一个规则。", "primary_collocate": null, "pronunciation": "dìng lǜ", "ipa": "tiŋ˥˩ ly˥˩", "syllable_count": 2, "sentences": [{"text": "科学家发现了一条新定律。", "target_word": "定律", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这条定律很有名。", "target_word": "定律", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "苹果会往下掉，这是一条定律。", "target_word": "定律", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "老师讲了一条有关光的定律。", "target_word": "定律", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "世界上有很多定律，科学家还在研究。", "target_word": "定律", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这条定律是几百年前的科学家发现的。", "target_word": "定律", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我们先学这条定律，再做练习。", "target_word": "定律", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "书上写着三条重要的定律。", "target_word": "定律", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子问：“这条定律是谁发现的？”", "target_word": "定律", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "水往低处流，也是自然界的一条定律。", "target_word": "定律", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "条", "label": "量词"}], "register": "中性", "sense_fingerprint": "定律：科学家发现的、世界上的一个规则", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '55e7a08c-7c03-491c-a1cf-48d19ddbaf4d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24158, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "裙子", "is_correct": false, "explanation": "语义：科学家“发现”的是自然界的规律，裙子是服装，句子说不通。"}, {"text": "定律", "is_correct": true, "explanation": "正确。科学家发现的是自然界的规则，“定律”符合这一语境。"}, {"text": "命令", "is_correct": false, "explanation": "搭配：“发现”不跟“命令”搭配，命令要说“下达”或“发出”。"}, {"text": "围巾", "is_correct": false, "explanation": "语义：围巾是人穿戴的物品，科学家不会发现一条新围巾，语义不通。"}], "explanations": {"裙子": "语义：科学家“发现”的是自然界的规律，裙子是服装，句子说不通。", "定律": "正确。科学家发现的是自然界的规则，“定律”符合这一语境。", "命令": "搭配：“发现”不跟“命令”搭配，命令要说“下达”或“发出”。", "围巾": "语义：围巾是人穿戴的物品，科学家不会发现一条新围巾，语义不通。"}, "sentence_index": 0, "correct_answer": "定律"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这是学校的定律，是科学家刚发现的。", "explanation": "这里应该用〈规定〉。定律指科学家发现的自然规律，学校的要求不是科学家发现的，应用〈规定〉。"}, {"text": "我们班的定律是下个月去博物馆。", "explanation": "这里应该用〈计划〉。定律指科学家发现的世界规则，打算要做的事要用〈计划〉。"}, {"text": "这个游戏的定律是牛顿发现的。", "explanation": "这里应该用〈规则〉。定律是科学家发现的自然规律，游戏的约定不是科学家发现的，应用〈规则〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6e6ba89e-2951-4d3c-b521-1d586643ccc5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24158, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "鱼", "is_correct": false, "explanation": "语义：鱼是动物，不能被当作学习的内容，“学这条鱼”说不通。"}, {"text": "河", "is_correct": false, "explanation": "语义：河是自然地理事物，“学”的对象应是知识或规律，学河说不通。"}, {"text": "定律", "is_correct": true, "explanation": "正确。“学”的对象是规律和知识，“这条定律”符合语境。"}, {"text": "雨", "is_correct": false, "explanation": "语义：雨是天气现象，不能被学习，“学这条雨”说不通。"}], "explanations": {"鱼": "语义：鱼是动物，不能被当作学习的内容，“学这条鱼”说不通。", "河": "语义：河是自然地理事物，“学”的对象应是知识或规律，学河说不通。", "定律": "正确。“学”的对象是规律和知识，“这条定律”符合语境。", "雨": "语义：雨是天气现象，不能被学习，“学这条雨”说不通。"}, "sentence_index": 6, "correct_answer": "定律"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这个定律的答案是三，大家算一算。", "explanation": "这里应该用〈题目〉。定律是科学家发现的世界规则，有答案的数学问题要用〈题目〉。"}, {"text": "他教我们弹这个定律。", "explanation": "这里应该用〈曲子〉。定律不能被“弹”，“弹”的对象应是乐曲，应说“弹这首曲子”。"}, {"text": "今天的定律很好，适合出去玩。", "explanation": "这里应该用〈天气〉。定律是科学家发现的规则，说今天的情况要用〈天气〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6e6ba89e-2951-4d3c-b521-1d586643ccc5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24158, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这是科学家提出定律，很多人都学过。", "corrected_sentence": "这是科学家提出的定律，很多人都学过。", "error_description": "错误：“科学家提出”修饰“定律”时，中间要加结构助词“的”，应说“科学家提出的定律”。漏掉“的”，句子不通顺。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6e6ba89e-2951-4d3c-b521-1d586643ccc5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24158, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "老师在课堂上介绍了几条定律们，大家都要记住。", "corrected_sentence": "老师在课堂上介绍了几条定律，大家都要记住。", "error_description": "错误：“几条”已经表示数量，“定律”是抽象名词，后面不能再加“们”，应说“几条定律”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6e6ba89e-2951-4d3c-b521-1d586643ccc5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24160, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "后退", "is_correct": true, "explanation": "“后退”与“前进”（身体向前移动）意义相反，正确。"}, {"text": "休息", "is_correct": false, "explanation": "“休息”与身体移动没有反义对应关系，不是“前进”的反义词。"}, {"text": "站立", "is_correct": false, "explanation": "“站立”描述身体的姿势，与“前进”没有反义关系。"}, {"text": "观望", "is_correct": false, "explanation": "“观望”指观察等待，与“前进”没有反义关系。"}], "correct_answer": "后退", "explanations": {"后退": "“后退”与“前进”（身体向前移动）意义相反，正确。", "休息": "“休息”与身体移动没有反义对应关系，不是“前进”的反义词。", "站立": "“站立”描述身体的姿势，与“前进”没有反义关系。", "观望": "“观望”指观察等待，与“前进”没有反义关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a73fe963-f640-4930-8c6d-59e02e87f32c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24160, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "后退", "is_correct": true, "explanation": "“后退”与“前进”（身体向前移动）意义相反，正确。"}, {"text": "倾听", "is_correct": false, "explanation": "“倾听”指认真地听，与“前进”没有反义关系。"}, {"text": "旋转", "is_correct": false, "explanation": "“旋转”指围绕中心转动，与“前进”没有反义关系。"}, {"text": "观察", "is_correct": false, "explanation": "“观察”指仔细看，与“前进”没有反义关系。"}], "correct_answer": "后退", "explanations": {"后退": "“后退”与“前进”（身体向前移动）意义相反，正确。", "倾听": "“倾听”指认真地听，与“前进”没有反义关系。", "旋转": "“旋转”指围绕中心转动，与“前进”没有反义关系。", "观察": "“观察”指仔细看，与“前进”没有反义关系。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a73fe963-f640-4930-8c6d-59e02e87f32c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24160, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "身体向前移动。", "primary_collocate": null, "pronunciation": "qián jìn", "ipa": "tɕʰjɛn˧˥ tɕin˥˩", "syllable_count": 2, "sentences": [{"text": "队伍开始慢慢前进了。", "target_word": "前进", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请大家排好队，一起前进。", "target_word": "前进", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "天太黑了，我们不敢前进。", "target_word": "前进", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们沿着小路一步一步前进。", "target_word": "前进", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "前面的路很滑，我们小心地前进。", "target_word": "前进", "complexity_tier": "T3", "furigana": "qián miàn de lù hěn huá, wǒ men xiǎo xīn de qián jìn.", "sentence_source": "generated"}, {"text": "士兵们在雪地里艰难地前进。", "target_word": "前进", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "大家跟着向导，在山林里慢慢前进。", "target_word": "前进", "complexity_tier": "T3", "furigana": "dà jiā gēn zhe xiàng dǎo, zài shān lín lǐ màn màn qián jìn.", "sentence_source": "generated"}, {"text": "老师说“出发”，我们就开始前进。", "target_word": "前进", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "山路很难走，我们前进得很慢。", "target_word": "前进", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他背着包，向山顶前进。", "target_word": "前进", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "前进了", "label": "体标"}, {"form": "前进着", "label": "体标"}, {"form": "前进过", "label": "体标"}], "register": "通用", "sense_fingerprint": "人或队伍的身体向前走动", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '17259789-fe49-4308-9f94-df080a361105') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24160, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "前进", "is_correct": true, "explanation": "身体向前移动，正确。"}, {"text": "千金", "is_correct": false, "explanation": "qiān（第一声）与 qián（第二声）声调不同，“千金”意思是贵重的钱财或富家女，不是“前进”。"}, {"text": "前景", "is_correct": false, "explanation": "jǐng（第三声）与 jìn（第四声）韵母和声调都不同（ing / in），“前景”意思是将来的情况，不是“前进”。"}, {"text": "浅近", "is_correct": false, "explanation": "qiǎn（第三声）与 qián（第二声）声调不同，“浅近”意思是浅显易懂，不是“前进”。"}], "explanations": {"前进": "身体向前移动，正确。", "千金": "qiān（第一声）与 qián（第二声）声调不同，“千金”意思是贵重的钱财或富家女，不是“前进”。", "前景": "jǐng（第三声）与 jìn（第四声）韵母和声调都不同（ing / in），“前景”意思是将来的情况，不是“前进”。", "浅近": "qiǎn（第三声）与 qián（第二声）声调不同，“浅近”意思是浅显易懂，不是“前进”。"}, "sentence_index": null, "correct_answer": "前进"}, "level_3": {"options": [{"text": "前进", "is_correct": true, "explanation": "“前进”表示身体向前移动，与“队伍开始慢慢……了”相符，正确。"}, {"text": "飞驰", "is_correct": false, "explanation": "语义：“飞驰”指快速奔跑，与“慢慢”矛盾。"}, {"text": "坠落", "is_correct": false, "explanation": "语义：“坠落”指向下掉落，与队伍向前行进的情境不合。"}, {"text": "升高", "is_correct": false, "explanation": "搭配：“升高”多用于温度、水平，不能说队伍升高。"}], "explanations": {"前进": "“前进”表示身体向前移动，与“队伍开始慢慢……了”相符，正确。", "飞驰": "语义：“飞驰”指快速奔跑，与“慢慢”矛盾。", "坠落": "语义：“坠落”指向下掉落，与队伍向前行进的情境不合。", "升高": "搭配：“升高”多用于温度、水平，不能说队伍升高。"}, "sentence_index": 0, "correct_answer": "前进"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "会议前进了一个星期。", "explanation": "这里应该用〈提前〉。前进指身体或队伍向前移动，不能表示日程提前，会议日期提前要用“提前”。"}, {"text": "这个月我的体重前进了三公斤。", "explanation": "这里应该用〈增加〉。前进表示向前移动或事情向好发展，体重上升这类数量变化要用“增加”。"}, {"text": "我们用力前进这块石头。", "explanation": "这里应该用〈推〉。前进表示自身移动，不能带“石头”作宾语，推动物体要用“推”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a73fe963-f640-4930-8c6d-59e02e87f32c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24160, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "前进", "is_correct": true, "explanation": "“前进”表示身体向前移动，与“大家跟着向导，在山林里慢慢……”相符，正确。"}, {"text": "冲刺", "is_correct": false, "explanation": "语义：“冲刺”指快速向前猛跑，与“慢慢”矛盾。"}, {"text": "飞跃", "is_correct": false, "explanation": "语义：“飞跃”指迅速跳越、快速前进，与“慢慢”矛盾。"}, {"text": "增长", "is_correct": false, "explanation": "搭配：“增长”多用于数量、规模，不能说人在山林里增长。"}], "explanations": {"前进": "“前进”表示身体向前移动，与“大家跟着向导，在山林里慢慢……”相符，正确。", "冲刺": "语义：“冲刺”指快速向前猛跑，与“慢慢”矛盾。", "飞跃": "语义：“飞跃”指迅速跳越、快速前进，与“慢慢”矛盾。", "增长": "搭配：“增长”多用于数量、规模，不能说人在山林里增长。"}, "sentence_index": 6, "correct_answer": "前进"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我们明天前进去爬山。", "explanation": "这里应该用〈出发〉。前进只表示身体向前移动，不表示动身；“出发去爬山”才是自然的说法。"}, {"text": "他去年前进为部长。", "explanation": "这里应该用〈晋升〉。前进表示向前移动或事情向好发展，职位升迁要用“晋升”，不能说“前进为部长”。"}, {"text": "他前进了一封信。", "explanation": "这里应该用〈寄〉。前进表示身体向前移动，不能带“信”作宾语，寄信要用“寄”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a73fe963-f640-4930-8c6d-59e02e87f32c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24160, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这支部队北方前进。", "corrected_sentence": "这支部队朝着北方前进。", "error_description": "缺少介词：表示前进方向要用“朝着”或“向”，应说“朝着北方前进”，不能直接说“北方前进”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a73fe963-f640-4930-8c6d-59e02e87f32c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24160, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他们终于前进了到大本营。", "corrected_sentence": "他们终于前进到了大本营。", "error_description": "了的位置错误：“到”是结果补语，“了”应放在补语之后，应说“前进到了大本营”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a73fe963-f640-4930-8c6d-59e02e87f32c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24162, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "不等", "is_correct": true, "explanation": "“不等”指不相等，与“相等”构成反义关系。"}, {"text": "陌生", "is_correct": false, "explanation": "“陌生”指不熟悉，与“相等”没有反义关系。"}, {"text": "急促", "is_correct": false, "explanation": "“急促”形容节奏快或声音短促，与“相等”无关。"}, {"text": "巨大", "is_correct": false, "explanation": "“巨大”形容体积或数量很大，不是“相等”的反义词。"}], "correct_answer": "不等", "explanations": {"不等": "“不等”指不相等，与“相等”构成反义关系。", "陌生": "“陌生”指不熟悉，与“相等”没有反义关系。", "急促": "“急促”形容节奏快或声音短促，与“相等”无关。", "巨大": "“巨大”形容体积或数量很大，不是“相等”的反义词。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '342756bf-486d-4402-ac39-77679b4abffe') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24162, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "不等", "is_correct": true, "explanation": "“不等”指不相等，与“相等”构成反义关系。"}, {"text": "冷淡", "is_correct": false, "explanation": "“冷淡”形容态度不热情，与“相等”没有反义关系。"}, {"text": "粗糙", "is_correct": false, "explanation": "“粗糙”形容表面不光滑，与“相等”无关。"}, {"text": "轻快", "is_correct": false, "explanation": "“轻快”形容动作或节奏轻松，与“相等”不构成反义。"}], "correct_answer": "不等", "explanations": {"不等": "“不等”指不相等，与“相等”构成反义关系。", "冷淡": "“冷淡”形容态度不热情，与“相等”没有反义关系。", "粗糙": "“粗糙”形容表面不光滑，与“相等”无关。", "轻快": "“轻快”形容动作或节奏轻松，与“相等”不构成反义。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '342756bf-486d-4402-ac39-77679b4abffe') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24162, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "两个东西一样大、一样多、一样好。", "primary_collocate": null, "pronunciation": "xiāng děng", "ipa": "ɕjaŋ˥ tɤŋ˨˩˦", "syllable_count": 2, "sentences": [{"text": "两个杯子的容量相等。", "target_word": "相等", "complexity_tier": "T3", "furigana": "liǎng gè bēi zi de róng liàng xiāng děng", "sentence_source": "generated"}, {"text": "哥哥和弟弟的身高几乎相等，站在一起看不出差别。", "target_word": "相等", "complexity_tier": "T3", "furigana": "gē ge hé dì di de shēn gāo jī hū xiāng děng, zhàn zài yì qǐ kàn bu chū chā bié", "sentence_source": "generated"}, {"text": "这两块蛋糕大小相等，你随便选。", "target_word": "相等", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "两个人的分数相等，都是九十分。", "target_word": "相等", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们两个人的水平相等。", "target_word": "相等", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这两种笔的价格相等。", "target_word": "相等", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "两个孩子分到的糖果数量相等。", "target_word": "相等", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "左右两边的重量相等，天平不动。", "target_word": "相等", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们的成绩相等，所以并列第一。", "target_word": "相等", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "两个队的人数相等，各十个人。", "target_word": "相等", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "不相等", "label": "否定"}], "register": "中性", "sense_fingerprint": "两个东西一样大、一样多或一样好", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b82d5183-2e13-461d-aa42-0ed00adf61ab') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24162, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "相等", "is_correct": true, "explanation": "“相等”指容量一样大，正好描述两个杯子的比较。"}, {"text": "高大", "is_correct": false, "explanation": "体貌：“高大”形容外形或个子，不用来形容容量。"}, {"text": "清脆", "is_correct": false, "explanation": "语义：“清脆”形容声音，与杯子的容量无关。"}, {"text": "严肃", "is_correct": false, "explanation": "语义：“严肃”形容神情或态度，不能用来说容量。"}], "explanations": {"相等": "“相等”指容量一样大，正好描述两个杯子的比较。", "高大": "体貌：“高大”形容外形或个子，不用来形容容量。", "清脆": "语义：“清脆”形容声音，与杯子的容量无关。", "严肃": "语义：“严肃”形容神情或态度，不能用来说容量。"}, "sentence_index": 0, "correct_answer": "相等"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这两个人的衣服颜色相等。", "explanation": "这里应该用〈相同〉。相等用于数量、程度等可以量化的情况，颜色要用相同。"}, {"text": "我们对这件事的看法很相等。", "explanation": "这里应该用〈一致〉。相等指数量或程度完全相同，看法的统一要用一致。"}, {"text": "这对双胞胎长得很相等。", "explanation": "这里应该用〈相像〉。相等强调数量或程度完全相同，说长相接近要用相像。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '342756bf-486d-4402-ac39-77679b4abffe') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24162, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "相等", "is_correct": true, "explanation": "“相等”指每人分到的数量一样多，与句中的语境一致。"}, {"text": "宽阔", "is_correct": false, "explanation": "体貌：“宽阔”形容空间或面积，不能用来形容糖果数量。"}, {"text": "陈旧", "is_correct": false, "explanation": "语义：“陈旧”指东西古老、不新，与分配的数量无关。"}, {"text": "懒惰", "is_correct": false, "explanation": "语义：“懒惰”形容人的态度，不能用来描述数量。"}], "explanations": {"相等": "“相等”指每人分到的数量一样多，与句中的语境一致。", "宽阔": "体貌：“宽阔”形容空间或面积，不能用来形容糖果数量。", "陈旧": "语义：“陈旧”指东西古老、不新，与分配的数量无关。", "懒惰": "语义：“懒惰”形容人的态度，不能用来描述数量。"}, "sentence_index": 6, "correct_answer": "相等"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这两幅画的风格很相等。", "explanation": "这里应该用〈相似〉。相等指数量或程度完全相同，风格的接近要用相似。"}, {"text": "这两个部门的口味很相等。", "explanation": "这里应该用〈一致〉。相等指数量或程度完全相同，口味的统一要用一致。"}, {"text": "这件外套和你的气质很相等。", "explanation": "这里应该用〈相称〉。相等指数量或程度完全相同，外套与气质的协调要用相称。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '342756bf-486d-4402-ac39-77679b4abffe') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24162, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这个杯子的容量像那个杯子相等。", "corrected_sentence": "这个杯子的容量和那个杯子相等。", "error_description": "“相等”的比较对象要用“和/跟”引出，不能用“像”。应说“这个杯子的容量和那个杯子相等”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '342756bf-486d-4402-ac39-77679b4abffe') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24162, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我们把两根绳子的长度相等。", "corrected_sentence": "我们把两根绳子的长度弄得相等。", "error_description": "“相等”是形容词，不能直接放在“把”的后面作谓语。要表示使绳子的长度变得相等，需要补上“弄得”，应说“把……弄得相等”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '342756bf-486d-4402-ac39-77679b4abffe') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24164, 1, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '342756bf-486d-4402-ac39-77679b4abffe') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24164, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '342756bf-486d-4402-ac39-77679b4abffe') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24164, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "东西转了个方向。", "primary_collocate": null, "pronunciation": "piān zhuǎn", "ipa": "pʰjɛn˥ ʈʂwan˨˩˦", "syllable_count": 2, "sentences": [{"text": "风向变了，旗子偏转到另一边。", "target_word": "偏转", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这支箭碰到树枝，偏转了方向。", "target_word": "偏转", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "球打到墙角后，往左偏转。", "target_word": "偏转", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "河水遇到大石头，向右偏转了。", "target_word": "偏转", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请你把镜子稍微偏转一点。", "target_word": "偏转", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "望远镜偏转了一点，看不到月亮了。", "target_word": "偏转", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小船撞到石头后，船头偏转了。", "target_word": "偏转", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "台灯太亮，把灯头偏转一点吧。", "target_word": "偏转", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "太阳能板要跟着太阳偏转。", "target_word": "偏转", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "铁球经过磁铁旁边，路线偏转了。", "target_word": "偏转", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "偏转了", "label": "体标"}, {"form": "偏转角", "label": "复合"}, {"form": "偏轉", "label": "繁体"}], "register": "书面", "sense_fingerprint": "东西转向，方向有了变化", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b82d5183-2e13-461d-aa42-0ed00adf61ab') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24164, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "偏转", "is_correct": true, "explanation": "“偏转”指旗子转向另一边，与“风向变了”的情境一致。"}, {"text": "转移", "is_correct": false, "explanation": "搭配：“转移”指位置交给别人或改换地方，旗子不能“转移到另一边”。"}, {"text": "冷却", "is_correct": false, "explanation": "语义：冷却指温度降低，与旗子转向另一边无关。"}, {"text": "熔化", "is_correct": false, "explanation": "语义：熔化指固体受热变成液体，与旗子转向另一边无关。"}], "explanations": {"偏转": "“偏转”指旗子转向另一边，与“风向变了”的情境一致。", "转移": "搭配：“转移”指位置交给别人或改换地方，旗子不能“转移到另一边”。", "冷却": "语义：冷却指温度降低，与旗子转向另一边无关。", "熔化": "语义：熔化指固体受热变成液体，与旗子转向另一边无关。"}, "sentence_index": 0, "correct_answer": "偏转"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这辆车的车轮偏转了一圈。", "explanation": "这里应该用〈转动〉。偏转指方向改变，不指物体绕轴转一圈。"}, {"text": "墙壁偏转得歪歪斜斜。", "explanation": "这里应该用〈倾斜〉。偏转指方向的改变，形容墙面向一侧斜过去要用倾斜。"}, {"text": "他的身高偏转了五厘米。", "explanation": "这里应该用〈增长〉。偏转指方向的改变，身高的增加要用增长。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '342756bf-486d-4402-ac39-77679b4abffe') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24164, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "偏转", "is_correct": true, "explanation": "“偏转”指船头因撞击改变方向，与句意一致。"}, {"text": "颠倒", "is_correct": false, "explanation": "语义：颠倒是整个上下翻转，与船头小幅改变方向的意思不符。"}, {"text": "撞击", "is_correct": false, "explanation": "语义：句中已有“撞到”，再说撞击重复，而且不是改变方向的意思。"}, {"text": "沸腾", "is_correct": false, "explanation": "语义：沸腾指液体受热剧烈翻滚，与船头方向的改变无关。"}], "explanations": {"偏转": "“偏转”指船头因撞击改变方向，与句意一致。", "颠倒": "语义：颠倒是整个上下翻转，与船头小幅改变方向的意思不符。", "撞击": "语义：句中已有“撞到”，再说撞击重复，而且不是改变方向的意思。", "沸腾": "语义：沸腾指液体受热剧烈翻滚，与船头方向的改变无关。"}, "sentence_index": 6, "correct_answer": "偏转"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "铁球在桌上快速偏转了几圈。", "explanation": "这里应该用〈旋转〉。偏转指方向改变，不表示物体连续绕轴转圈。"}, {"text": "他把铁丝偏转成了一个圆圈。", "explanation": "这里应该用〈弯〉。偏转指方向的改变，不表示把细长物体弯成圆形。"}, {"text": "他的收入偏转了一万元。", "explanation": "这里应该用〈增加〉。偏转指方向的改变，收入的增加要用增加。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '342756bf-486d-4402-ac39-77679b4abffe') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24164, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "风吹过来，树枝偏转了到一边。", "corrected_sentence": "风吹过来，树枝偏转到了一边。", "error_description": "错误：“偏转了到”；正确：“偏转到了”。“了”要放在“到一边”之后。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '342756bf-486d-4402-ac39-77679b4abffe') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24164, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他把镜子稍微偏转得一下。", "corrected_sentence": "他把镜子稍微偏转了一下。", "error_description": "错误：“偏转得一下”；正确：“偏转了一下”。“得”用于程度补语，不能接“一下”，动作完成应在“偏转”后用“了”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '342756bf-486d-4402-ac39-77679b4abffe') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
