INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24166, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "把力量、压力或影响加在人或物体上。", "primary_collocate": null, "pronunciation": "shī jiā", "ipa": "ʂɨ⁵⁵ tɕja⁵⁵", "syllable_count": 2, "sentences": [{"text": "工人对钢板施加压力，钢板慢慢弯了。", "target_word": "施加", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "给弹簧施加一点力，它就会变短。", "target_word": "施加", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "医生在伤口上施加压力，血很快就止住了。", "target_word": "施加", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "父母不应该对孩子施加太大的压力。", "target_word": "施加", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师没有对我们施加任何压力。", "target_word": "施加", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你对门施加一点力，它就开了。", "target_word": "施加", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "工程师对桥面施加了很大的力来做测试。", "target_word": "施加", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "外界不断对他施加影响，他的想法慢慢变了。", "target_word": "施加", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "朋友们一起对公司施加压力，要求他们道歉。", "target_word": "施加", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "实验时，我们对水管施加了压力，水就喷出来了。", "target_word": "施加", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "施加了", "label": "完成体"}, {"form": "施加过", "label": "经历体"}], "register": "书面", "sense_fingerprint": "对物体或人用力、加压", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '65ed119e-0d7b-4fd6-9dc2-f9c5d6a85cda') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24166, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "施加", "is_correct": true, "explanation": "正确。施加 shī jiā，指对物体或人用力、加压。"}, {"text": "事假", "is_correct": false, "explanation": "shì（第四声）与 shī（第一声）声调不同，“事假”意思是因私事请的假。"}, {"text": "私家", "is_correct": false, "explanation": "sī 与 shī 声母不同（s 与 sh），“私家”意思是私人的。"}, {"text": "世家", "is_correct": false, "explanation": "shì（第四声）与 shī（第一声）声调不同，“世家”意思是世代有名望的家族。"}], "explanations": {"施加": "正确。施加 shī jiā，指对物体或人用力、加压。", "事假": "shì（第四声）与 shī（第一声）声调不同，“事假”意思是因私事请的假。", "私家": "sī 与 shī 声母不同（s 与 sh），“私家”意思是私人的。", "世家": "shì（第四声）与 shī（第一声）声调不同，“世家”意思是世代有名望的家族。"}, "sentence_index": null, "correct_answer": "施加"}, "level_3": {"options": [{"text": "施加", "is_correct": true, "explanation": "正确。施加表示对钢板用力、加压，与“工人对钢板施加压力，钢板慢慢弯了”相符。"}, {"text": "感觉", "is_correct": false, "explanation": "语义：“感觉”表示人自身的感受，不能用“对钢板感觉压力”表示把压力加到钢板上。"}, {"text": "理解", "is_correct": false, "explanation": "语义：“理解”的施事必须是人，“工人对钢板理解压力”不通。"}, {"text": "提出", "is_correct": false, "explanation": "搭配：“提出”多接意见、要求，不能接“压力”作宾语。"}], "explanations": {"施加": "正确。施加表示对钢板用力、加压，与“工人对钢板施加压力，钢板慢慢弯了”相符。", "感觉": "语义：“感觉”表示人自身的感受，不能用“对钢板感觉压力”表示把压力加到钢板上。", "理解": "语义：“理解”的施事必须是人，“工人对钢板理解压力”不通。", "提出": "搭配：“提出”多接意见、要求，不能接“压力”作宾语。"}, "sentence_index": 0, "correct_answer": "施加"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "学校对他施加了一笔奖学金。", "explanation": "这里应该用〈给予〉。施加表示把压力或影响加于对象，奖学金是授予的，应说给予。"}, {"text": "他施加了这次旅行的全部费用。", "explanation": "这里应该用〈承担〉。施加指把压力或力量加于对象，费用要自己承担，应说承担。"}, {"text": "他施加了一篇文章。", "explanation": "这里应该用〈发表〉。施加用于压力、力量等，文章要说发表。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a5d18738-51dc-4bdc-98ce-94563e09fdad') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24166, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "施加", "is_correct": true, "explanation": "正确。施加表示用力加压，与“工程师对桥面施加了很大的力来做测试”相符。"}, {"text": "感到", "is_correct": false, "explanation": "语义：“感到”表示人自身的感受，不能用“对桥面感到很大的力”表示把力加到桥面上。"}, {"text": "回答", "is_correct": false, "explanation": "语义：“回答”的施事须是能说话的人，“回答很大的力”不通。"}, {"text": "发表", "is_correct": false, "explanation": "搭配：“发表”的宾语多是文章、意见，不能说发表“力”。"}], "explanations": {"施加": "正确。施加表示用力加压，与“工程师对桥面施加了很大的力来做测试”相符。", "感到": "语义：“感到”表示人自身的感受，不能用“对桥面感到很大的力”表示把力加到桥面上。", "回答": "语义：“回答”的施事须是能说话的人，“回答很大的力”不通。", "发表": "搭配：“发表”的宾语多是文章、意见，不能说发表“力”。"}, "sentence_index": 6, "correct_answer": "施加"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他充分施加了自己的才能。", "explanation": "这里应该用〈发挥〉。施加用于把力量或压力加于对象，才能要说发挥。"}, {"text": "学校施加了一次调查。", "explanation": "这里应该用〈进行〉。施加用于压力、力量或影响，调查要说进行。"}, {"text": "他施加了一个判断。", "explanation": "这里应该用〈作出〉。判断是人做出的，不能说施加，应说作出。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a5d18738-51dc-4bdc-98ce-94563e09fdad') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24166, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "老师在学生施加了一点影响。", "corrected_sentence": "老师对学生施加了一点影响。", "error_description": "“施加”的受事前要用介词“对”引出，“在”不能引出施加的对象，应写作“老师对学生施加了一点影响”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a5d18738-51dc-4bdc-98ce-94563e09fdad') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24166, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他把绳子施加了很大的力。", "corrected_sentence": "他对绳子施加了很大的力。", "error_description": "“施加”的受事不能用“把”字句引出，应将“把”改为“对”，写作“他对绳子施加了很大的力”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a5d18738-51dc-4bdc-98ce-94563e09fdad') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24168, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "合并", "is_correct": true, "explanation": "“合并”指把分开的部分合成一体，与“细分”的意思相对。"}, {"text": "寻找", "is_correct": false, "explanation": "“寻找”指设法找到，与“细分”没有反义关系。"}, {"text": "发表", "is_correct": false, "explanation": "“发表”指公开说出或刊登，与“细分”无相对关系。"}, {"text": "欢迎", "is_correct": false, "explanation": "“欢迎”指热情接待，与“细分”不构成反义。"}], "correct_answer": "合并", "explanations": {"合并": "“合并”指把分开的部分合成一体，与“细分”的意思相对。", "寻找": "“寻找”指设法找到，与“细分”没有反义关系。", "发表": "“发表”指公开说出或刊登，与“细分”无相对关系。", "欢迎": "“欢迎”指热情接待，与“细分”不构成反义。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '342756bf-486d-4402-ac39-77679b4abffe') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24168, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "合并", "is_correct": true, "explanation": "“合并”指把分开的部分合成一体，与“细分”的意思相对。"}, {"text": "唱歌", "is_correct": false, "explanation": "“唱歌”指发出乐音演唱，与“细分”无反义关系。"}, {"text": "等候", "is_correct": false, "explanation": "“等候”指等待，与“细分”没有相对的关系。"}, {"text": "冷却", "is_correct": false, "explanation": "“冷却”指温度降低，与“细分”不构成反义。"}], "correct_answer": "合并", "explanations": {"合并": "“合并”指把分开的部分合成一体，与“细分”的意思相对。", "唱歌": "“唱歌”指发出乐音演唱，与“细分”无反义关系。", "等候": "“等候”指等待，与“细分”没有相对的关系。", "冷却": "“冷却”指温度降低，与“细分”不构成反义。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '342756bf-486d-4402-ac39-77679b4abffe') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24168, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "把一个整体分成很多小的部分。", "primary_collocate": null, "pronunciation": "xì fēn", "ipa": "ɕi˥˩ fən˥", "syllable_count": 2, "sentences": [{"text": "这片地区太大，政府把它细分为许多小区。", "target_word": "细分", "complexity_tier": "T3", "furigana": "zhè piàn dì qū tài dà, zhèng fǔ bǎ tā xì fēn wéi xǔ duō xiǎo qū", "sentence_source": "generated"}, {"text": "请把这些书细分成三类。", "target_word": "细分", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈妈把一大盒糖细分成十小包。", "target_word": "细分", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "地图上的区域可以细分得更小。", "target_word": "细分", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师把一天的课细分成六节。", "target_word": "细分", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这块地太大，我们把它细分了。", "target_word": "细分", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "农民把大田细分成很多小块。", "target_word": "细分", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "每个月的钱要细分到每一天。", "target_word": "细分", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "研究人员把这些数据细分成很多小类。", "target_word": "细分", "complexity_tier": "T3", "furigana": "yán jiū rén yuán bǎ zhè xiē shù jù xì fēn chéng hěn duō xiǎo lèi", "sentence_source": "generated"}, {"text": "把时间细分，每一段只做一件事。", "target_word": "细分", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "细分了", "label": "体标"}, {"form": "细分化", "label": "复合"}, {"form": "細分", "label": "繁体"}], "register": "书面", "sense_fingerprint": "把一个整体分成很多小的部分", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b82d5183-2e13-461d-aa42-0ed00adf61ab') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24168, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "细分", "is_correct": true, "explanation": "“细分”指把一个整体分成很多小的部分。"}, {"text": "细粉", "is_correct": false, "explanation": "fěn（第三声）与 fēn（第一声）声调不同，“细粉”指很细的粉末。"}, {"text": "戏份", "is_correct": false, "explanation": "fèn（第四声）与 fēn（第一声）声调不同，“戏份”指角色在戏中的分量。"}, {"text": "戏粉", "is_correct": false, "explanation": "fěn（第三声）与 fēn（第一声）声调不同，“戏粉”指喜欢戏曲的人。"}], "explanations": {"细分": "“细分”指把一个整体分成很多小的部分。", "细粉": "fěn（第三声）与 fēn（第一声）声调不同，“细粉”指很细的粉末。", "戏份": "fèn（第四声）与 fēn（第一声）声调不同，“戏份”指角色在戏中的分量。", "戏粉": "fěn（第三声）与 fēn（第一声）声调不同，“戏粉”指喜欢戏曲的人。"}, "sentence_index": null, "correct_answer": "细分"}, "level_3": {"options": [{"text": "细分", "is_correct": true, "explanation": "“细分”表示把整片地区划分成许多小区，与“太大”的语境相符。"}, {"text": "组建", "is_correct": false, "explanation": "语义：“组建”指组成团体或机构，不用来指把地区划分成小区。"}, {"text": "种植", "is_correct": false, "explanation": "语义：种植指栽培植物，与把地区划分为小区无关。"}, {"text": "保留", "is_correct": false, "explanation": "语义：“保留”指留下不动，与把地区分成许多小区的意思相反。"}], "explanations": {"细分": "“细分”表示把整片地区划分成许多小区，与“太大”的语境相符。", "组建": "语义：“组建”指组成团体或机构，不用来指把地区划分成小区。", "种植": "语义：种植指栽培植物，与把地区划分为小区无关。", "保留": "语义：“保留”指留下不动，与把地区分成许多小区的意思相反。"}, "sentence_index": 0, "correct_answer": "细分"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "一堵墙把一只猫细分开了。", "explanation": "这里应该用〈隔开〉。细分指按标准把整体划分为部分，墙把猫隔在一侧要用隔开。"}, {"text": "他把快乐细分给了大家。", "explanation": "这里应该用〈分享〉。细分指把整体划分为部分，把快乐与他人共享要用分享。"}, {"text": "他把作业细分给了老师。", "explanation": "这里应该用〈交〉。细分指把整体划分为部分，把作业递给老师要用交。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '342756bf-486d-4402-ac39-77679b4abffe') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24168, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "细分", "is_correct": true, "explanation": "“细分”指把大田分成很多小块，与“农民”和“很多小块”的语境相符。"}, {"text": "合并", "is_correct": false, "explanation": "语义：“合并”指把几块合为一体，与分成很多小块的意思相反。"}, {"text": "清点", "is_correct": false, "explanation": "搭配：“清点”指一件件数，不能说“清点成很多小块”。"}, {"text": "批发", "is_correct": false, "explanation": "语义：“批发”指成批卖出，与把大田分成小块的意思不符。"}], "explanations": {"细分": "“细分”指把大田分成很多小块，与“农民”和“很多小块”的语境相符。", "合并": "语义：“合并”指把几块合为一体，与分成很多小块的意思相反。", "清点": "搭配：“清点”指一件件数，不能说“清点成很多小块”。", "批发": "语义：“批发”指成批卖出，与把大田分成小块的意思不符。"}, "sentence_index": 6, "correct_answer": "细分"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这个乐队因为矛盾细分了。", "explanation": "这里应该用〈分裂〉。细分指按标准划分整体，乐队因矛盾而散裂要用分裂。"}, {"text": "警察把人群细分进了车里。", "explanation": "这里应该用〈押〉。细分指按标准划分整体，把人押送上车要用押。"}, {"text": "两位队友细分了一次拥抱。", "explanation": "这里应该用〈分享〉。细分指把整体划分为部分，拥抱不能划分，两人共同拥有要用分享。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '342756bf-486d-4402-ac39-77679b4abffe') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24168, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这家公司把员工细分得三个小组。", "corrected_sentence": "这家公司把员工细分成三个小组。", "error_description": "“细分”后面引出结果要用“成”，“得”用于程度补语，不能用在这里。应说“细分成三个小组”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '342756bf-486d-4402-ac39-77679b4abffe') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24168, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "老师把图形细分在很多三角形。", "corrected_sentence": "老师把图形细分成很多三角形。", "error_description": "错误：“细分在很多三角形”；正确：“细分成很多三角形”。“在”表示处所，不能引出细分的结果，结果要用“成”或“为”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '342756bf-486d-4402-ac39-77679b4abffe') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24170, 1, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0ab575c9-0f12-4e6d-97c2-3e74b9251644') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24170, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0ab575c9-0f12-4e6d-97c2-3e74b9251644') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24170, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "东西动起来时，被挡住不让动的那种力。", "primary_collocate": null, "pronunciation": "mó cā zǔ lì", "ipa": "mwo˧˥ tsʰa˥ tsu˨˩ li˥˩", "syllable_count": 4, "sentences": [{"text": "汽车刹车时，轮胎和地面之间有摩擦阻力。", "target_word": "摩擦阻力", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "冰面很滑，摩擦阻力很小，所以人容易摔倒。", "target_word": "摩擦阻力", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "在鞋底加上花纹，可以增大摩擦阻力。", "target_word": "摩擦阻力", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "物体表面越粗糙，摩擦阻力就越大。", "target_word": "摩擦阻力", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "给自行车链条上油，能减小摩擦阻力。", "target_word": "摩擦阻力", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "木箱太重，推不动是因为地面的摩擦阻力大。", "target_word": "摩擦阻力", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "滑雪板底部很光滑，是为了减小摩擦阻力。", "target_word": "摩擦阻力", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小球在桌上滚了一会儿，因为摩擦阻力停下来了。", "target_word": "摩擦阻力", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "冬天路上结冰，车轮的摩擦阻力变小了。", "target_word": "摩擦阻力", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师说，空气也会对飞机产生摩擦阻力。", "target_word": "摩擦阻力", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "物体接触面相对运动时产生的、阻碍物体运动的力", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1b4bed82-fa15-4388-b52a-548bab14ed95') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24170, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "摩擦阻力", "is_correct": true, "explanation": "正确：刹车时轮胎与地面接触并相对滑动，产生的正是摩擦阻力。"}, {"text": "空气阻力", "is_correct": false, "explanation": "语义：轮胎和地面之间不是空气，空气阻力不会在这个位置产生。"}, {"text": "重量", "is_correct": false, "explanation": "语义：轮胎和地面之间不能“有重量”，句意不通。"}, {"text": "颜色", "is_correct": false, "explanation": "体貌：颜色属于外观，与刹车时轮胎和地面之间的作用无关。"}], "explanations": {"摩擦阻力": "正确：刹车时轮胎与地面接触并相对滑动，产生的正是摩擦阻力。", "空气阻力": "语义：轮胎和地面之间不是空气，空气阻力不会在这个位置产生。", "重量": "语义：轮胎和地面之间不能“有重量”，句意不通。", "颜色": "体貌：颜色属于外观，与刹车时轮胎和地面之间的作用无关。"}, "sentence_index": 0, "correct_answer": "摩擦阻力"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "用力推箱子时，箱子前进靠的是摩擦阻力。", "explanation": "这里应该用〈推力〉。摩擦阻力是阻碍运动的力，推动箱子前进的力要用推力。"}, {"text": "最近工作太忙，我感到摩擦阻力很大。", "explanation": "这里应该用〈压力〉。摩擦阻力是物理上的力，心理上的负担要用压力。"}, {"text": "两家人之间的摩擦阻力越来越大。", "explanation": "这里应该用〈矛盾〉。摩擦阻力是物理上的力，人与人之间的冲突要用矛盾。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0ab575c9-0f12-4e6d-97c2-3e74b9251644') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24170, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "摩擦阻力", "is_correct": true, "explanation": "正确：滑雪板底部光滑，是为了减小雪面与板之间的摩擦阻力。"}, {"text": "光泽", "is_correct": false, "explanation": "体貌：光泽属于外观，减小光泽不是滑雪板光滑的目的。"}, {"text": "高度", "is_correct": false, "explanation": "语义：底部光滑与高度无关，“减小高度”不能作为光滑的目的。"}, {"text": "体重", "is_correct": false, "explanation": "语义：滑雪板光滑是为了减少阻力，与体重无关。"}], "explanations": {"摩擦阻力": "正确：滑雪板底部光滑，是为了减小雪面与板之间的摩擦阻力。", "光泽": "体貌：光泽属于外观，减小光泽不是滑雪板光滑的目的。", "高度": "语义：底部光滑与高度无关，“减小高度”不能作为光滑的目的。", "体重": "语义：滑雪板光滑是为了减少阻力，与体重无关。"}, "sentence_index": 6, "correct_answer": "摩擦阻力"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这台机器的摩擦阻力越大，它转得越快。", "explanation": "这里应该用〈动力〉。摩擦阻力是阻碍运动的力，使机器转得越来越快的力要用动力。"}, {"text": "月亮的摩擦阻力把海水拉向岸边。", "explanation": "这里应该用〈引力〉。摩擦阻力是阻碍运动的力，把海水拉向岸边的力要用引力。"}, {"text": "弹簧被压缩后，它的摩擦阻力会把物体弹开。", "explanation": "这里应该用〈弹力〉。摩擦阻力是阻碍运动的力，弹簧恢复形变时把物体弹开的力要用弹力。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0ab575c9-0f12-4e6d-97c2-3e74b9251644') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24170, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "在鞋底加上花纹，能使摩擦阻力变多。", "corrected_sentence": "在鞋底加上花纹，能使摩擦阻力变大。", "error_description": "错误：“摩擦阻力变多”。阻力的程度用“大/小”表示，不说“多/少”；正确为“摩擦阻力变大”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0ab575c9-0f12-4e6d-97c2-3e74b9251644') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24170, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "给门轴上点油，能缩短摩擦阻力。", "corrected_sentence": "给门轴上点油，能减小摩擦阻力。", "error_description": "错误：“缩短摩擦阻力”。“缩短”用于长度或时间，摩擦阻力应搭配“减小”；正确为“能减小摩擦阻力”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0ab575c9-0f12-4e6d-97c2-3e74b9251644') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
