INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24174, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0ab575c9-0f12-4e6d-97c2-3e74b9251644') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24174, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "压差是两个地方压力大小的不同。", "primary_collocate": null, "pronunciation": "yā chā", "ipa": "ja˥ ʈʂʰa˥", "syllable_count": 2, "sentences": [{"text": "山顶和山下有压差，耳朵会不舒服。", "target_word": "压差", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "管子两端的压差太小，水流不出来。", "target_word": "压差", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "两地的压差越大，风就越大。", "target_word": "压差", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "打开窗，屋里屋外的压差变小了。", "target_word": "压差", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "水泵靠压差把水送到楼上。", "target_word": "压差", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "压差太大时，玻璃可能会碎。", "target_word": "压差", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "检修时发现这段管道的压差异常。", "target_word": "压差", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这里的压差是多少？", "target_word": "压差", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "飞机起飞时，机翼上下的压差很重要。", "target_word": "压差", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "压差让空气从高压处流向低压处。", "target_word": "压差", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "两个地方压力大小的不同（名词，通俗说法）", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1b4bed82-fa15-4388-b52a-548bab14ed95') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24174, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "压差", "is_correct": true, "explanation": "正确：压差指两地压力大小的不同，山顶与山下气压不同，耳朵因此会不舒服。"}, {"text": "温差", "is_correct": false, "explanation": "语义：耳朵不适是气压变化引起的，温差指温度的差别，与此无关。"}, {"text": "高度", "is_correct": false, "explanation": "搭配：说两地的差别要用“高度差”，“有高度”不能直接表示这种差别。"}, {"text": "风速", "is_correct": false, "explanation": "语义：风速指风的快慢，与山顶和山下的耳朵不适没有因果关系。"}], "explanations": {"压差": "正确：压差指两地压力大小的不同，山顶与山下气压不同，耳朵因此会不舒服。", "温差": "语义：耳朵不适是气压变化引起的，温差指温度的差别，与此无关。", "高度": "搭配：说两地的差别要用“高度差”，“有高度”不能直接表示这种差别。", "风速": "语义：风速指风的快慢，与山顶和山下的耳朵不适没有因果关系。"}, "sentence_index": 0, "correct_answer": "压差"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "最近工作太累，我的压差很大。", "explanation": "这里应该用〈压力〉。压差指两地之间压力大小的差别，人的心理负担要用压力。"}, {"text": "今天压差很大，出门要多穿一件衣服。", "explanation": "这里应该用〈温差〉。压差指压力的差别，冷热的差别要用温差。"}, {"text": "两人的性格压差很大，常常意见不合。", "explanation": "这里应该用〈差异〉。压差只指两地压力大小的不同，两人性格的不同要用差异。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0ab575c9-0f12-4e6d-97c2-3e74b9251644') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24174, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "压差", "is_correct": true, "explanation": "正确：压差是两处压力之差，管道压力异常可以通过测量压差发现，符合检修的语境。"}, {"text": "身材", "is_correct": false, "explanation": "体貌：身材指人或动物的体形，管道没有身材，不能这样说。"}, {"text": "人数", "is_correct": false, "explanation": "语义：管道不是人群，没有人数，句意不通。"}, {"text": "性格", "is_correct": false, "explanation": "语义：管道没有性格，与检修时发现的异常无关。"}], "explanations": {"压差": "正确：压差是两处压力之差，管道压力异常可以通过测量压差发现，符合检修的语境。", "身材": "体貌：身材指人或动物的体形，管道没有身材，不能这样说。", "人数": "语义：管道不是人群，没有人数，句意不通。", "性格": "语义：管道没有性格，与检修时发现的异常无关。"}, "sentence_index": 6, "correct_answer": "压差"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这块砖对地面的压差很大，所以容易压坏地面。", "explanation": "这里应该用〈压强〉。压差指两个地方压力大小的不同，单位面积上受到的压力要用压强。"}, {"text": "这块铁的压差很大，所以特别重。", "explanation": "这里应该用〈密度〉。压差指压力的差别，单位体积的质量要用密度。"}, {"text": "这辆车的压差很大，跑得很快。", "explanation": "这里应该用〈速度〉。压差指两地压力的差别，车跑得快慢要用速度。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0ab575c9-0f12-4e6d-97c2-3e74b9251644') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24174, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "通风以后，房间和外面的压差变了小。", "corrected_sentence": "通风以后，房间和外面的压差变小了。", "error_description": "错误：补语“小”与“了”的位置颠倒。正确的是“变小了”，“了”要放在补语之后，不能写成“变了小”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0ab575c9-0f12-4e6d-97c2-3e74b9251644') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24174, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这里的压差大很。", "corrected_sentence": "这里的压差很大。", "error_description": "错误：副词“很”放在了形容词“大”之后。正确的是“很大”，“很”要放在形容词之前。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0ab575c9-0f12-4e6d-97c2-3e74b9251644') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
