INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24176, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "让别人做你想让他做的事。", "primary_collocate": null, "pronunciation": "yòu dǎo", "ipa": "jou̯˥˩ tau̯˨˩˦", "syllable_count": 2, "sentences": [{"text": "他想诱导我签下这份合同。", "target_word": "诱导", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "广告诱导人们买不需要的东西。", "target_word": "诱导", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她笑着诱导小弟弟说出了秘密。", "target_word": "诱导", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "骗子诱导受害人转钱给陌生人。", "target_word": "诱导", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老板诱导新人加班，却不给加班费。", "target_word": "诱导", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "大人不应该诱导孩子说谎。", "target_word": "诱导", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "警察没有诱导他，是他自己说的。", "target_word": "诱导", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "网上的游戏诱导学生花很多钱。", "target_word": "诱导", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "商店把糖放在门口，诱导小孩进来买。", "target_word": "诱导", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他用好听的话诱导朋友投资。", "target_word": "诱导", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "诱导了", "label": "体标"}, {"form": "诱导过", "label": "体标"}], "register": "中性", "sense_fingerprint": "设法让别人按自己的想法去做事", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1b4bed82-fa15-4388-b52a-548bab14ed95') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24176, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "诱导", "is_correct": true, "explanation": "诱导：用好处或手段引人去做，与“想签下这份合同”的意图相合。"}, {"text": "保护", "is_correct": false, "explanation": "语义：保护是护住对方、使其免受伤害，不能让人去签合同。"}, {"text": "修改", "is_correct": false, "explanation": "配价：“修改”的宾语是文件、计划，不能以“我”作宾语，也不能接“签下合同”。"}, {"text": "包括", "is_correct": false, "explanation": "配价：“包括”后接事物或范围，不能接动作短语“签下这份合同”。"}], "explanations": {"诱导": "诱导：用好处或手段引人去做，与“想签下这份合同”的意图相合。", "保护": "语义：保护是护住对方、使其免受伤害，不能让人去签合同。", "修改": "配价：“修改”的宾语是文件、计划，不能以“我”作宾语，也不能接“签下合同”。", "包括": "配价：“包括”后接事物或范围，不能接动作短语“签下这份合同”。"}, "sentence_index": 0, "correct_answer": "诱导"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他诱导了我的感情。", "explanation": "这里应该用〈欺骗〉。诱导的宾语是要对方去做的事，不能说“诱导感情”；“欺骗感情”才是正确说法。"}, {"text": "这场暴雨诱导了山体滑坡。", "explanation": "这里应该用〈诱发〉。诱导的对象是人，要使人去做某事；山体滑坡是自然现象造成的结果，应用〈诱发〉。"}, {"text": "这件事诱导了大家的注意。", "explanation": "这里应该用〈引起〉。诱导的宾语是要对方去做的事，不能与“注意”搭配；“引起注意”应用〈引起〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0ab575c9-0f12-4e6d-97c2-3e74b9251644') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24176, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "诱导", "is_correct": true, "explanation": "诱导：用手段或利益引人做事，与“没有诱导他”的否定相呼应，说明警察没有用手段。"}, {"text": "翻阅", "is_correct": false, "explanation": "配价：“翻阅”的对象是书报、文件，不能以人作宾语。"}, {"text": "打扮", "is_correct": false, "explanation": "语义：打扮是修饰外表，与“是他自己说的”不相干，句意不通。"}, {"text": "翻译", "is_correct": false, "explanation": "配价：“翻译”的对象是语言或文字，不能以人作宾语。"}], "explanations": {"诱导": "诱导：用手段或利益引人做事，与“没有诱导他”的否定相呼应，说明警察没有用手段。", "翻阅": "配价：“翻阅”的对象是书报、文件，不能以人作宾语。", "打扮": "语义：打扮是修饰外表，与“是他自己说的”不相干，句意不通。", "翻译": "配价：“翻译”的对象是语言或文字，不能以人作宾语。"}, "sentence_index": 6, "correct_answer": "诱导"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "妈妈诱导我去超市买瓶酱油。", "explanation": "这里应该用〈叫〉。诱导是用手段或好处暗中引人去做某事；妈妈直接让我去买东西，应用〈叫〉。"}, {"text": "队长诱导队员立即出发。", "explanation": "这里应该用〈命令〉。诱导是间接引人去做，不是直接下令；要求队员立即行动应用〈命令〉。"}, {"text": "这首歌诱导了我的泪水。", "explanation": "这里应该用〈引出〉。诱导是促使人去做某事，不能与“泪水”搭配；这首歌使人流泪，应用〈引出〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0ab575c9-0f12-4e6d-97c2-3e74b9251644') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24176, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "那个人用假消息诱导很多老人的买保健品。", "corrected_sentence": "那个人用假消息诱导很多老人买保健品。", "error_description": "错误：「老人」与「买」之间多出「的」，「的」不能插在兼语「老人」与动词「买」之间，应删去，正确为「那个人用假消息诱导很多老人买保健品」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0ab575c9-0f12-4e6d-97c2-3e74b9251644') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24176, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他用奖金诱导员工了加班。", "corrected_sentence": "他用奖金诱导员工加班。", "error_description": "错误：“员工了加班”。“了”不能插在兼语“员工”与动词“加班”之间，应删去；正确为“他用奖金诱导员工加班”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0ab575c9-0f12-4e6d-97c2-3e74b9251644') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
