INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24180, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "用刀切东西后，露出来的那个平平的面。", "primary_collocate": null, "pronunciation": "jié miàn", "ipa": "tɕjɛ˧˥ mjɛn˥˩", "syllable_count": 2, "sentences": [{"text": "苹果切开后，截面很快就变黄了。", "target_word": "截面", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这块牛肉的截面是红色的。", "target_word": "截面", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他用刀把面包切开，截面很平。", "target_word": "截面", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "洋葱的截面上有很多一圈一圈的线。", "target_word": "截面", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "桃子切好了，截面上有一点水。", "target_word": "截面", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "刀不快，切出来的截面不平。", "target_word": "截面", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "看一看萝卜的截面，就知道它新不新鲜。", "target_word": "截面", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "妈妈把西瓜切成两半，截面红红的。", "target_word": "截面", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这条鱼的截面发白，说明已经熟了。", "target_word": "截面", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "蛋糕的截面有三层，每一层颜色都不一样。", "target_word": "截面", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "个", "label": "量词"}, {"form": "横截面", "label": "复合"}], "register": "中性", "sense_fingerprint": "用刀切开食物或物品后露出的平面", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c3cad82c-93f9-4f2a-a9b9-419707bd24f6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24180, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "截面", "is_correct": true, "explanation": "jié miàn，指用刀切东西后露出的平面。"}, {"text": "界面", "is_correct": false, "explanation": "jiè（第四声）与 jié（第二声）声调不同，意思是交界处的表面或界面。"}, {"text": "斜面", "is_correct": false, "explanation": "xié 与 jié 声母不同（x 与 j），意思是倾斜的平面。"}, {"text": "街面", "is_correct": false, "explanation": "jiē（第一声）与 jié（第二声）声调不同，意思是街道、街上。"}], "explanations": {"截面": "jié miàn，指用刀切东西后露出的平面。", "界面": "jiè（第四声）与 jié（第二声）声调不同，意思是交界处的表面或界面。", "斜面": "xié 与 jié 声母不同（x 与 j），意思是倾斜的平面。", "街面": "jiē（第一声）与 jié（第二声）声调不同，意思是街道、街上。"}, "sentence_index": null, "correct_answer": "截面"}, "level_3": {"options": [{"text": "天空", "is_correct": false, "explanation": "语义：天空不能在苹果切开后变黄，此句说的是切面。"}, {"text": "截面", "is_correct": true, "explanation": "“截面”指切开后露出的平面，切开后会很快变黄，符合句意。"}, {"text": "乘客", "is_correct": false, "explanation": "语义：乘客是人，不会在苹果切开后变黄。"}, {"text": "体重", "is_correct": false, "explanation": "搭配：“体重”用于人或动物，不能说苹果的体重变黄。"}], "explanations": {"天空": "语义：天空不能在苹果切开后变黄，此句说的是切面。", "截面": "“截面”指切开后露出的平面，切开后会很快变黄，符合句意。", "乘客": "语义：乘客是人，不会在苹果切开后变黄。", "体重": "搭配：“体重”用于人或动物，不能说苹果的体重变黄。"}, "sentence_index": 0, "correct_answer": "截面"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这个桃子的截面很甜，好吃极了。", "explanation": "这里应该用〈味道〉。截面指切开后露出的平面，甜不甜要说味道。"}, {"text": "这个西瓜的截面有五公斤，拿在手里很沉。", "explanation": "这里应该用〈重量〉。截面指切开后露出的平面，东西的轻重要说重量。"}, {"text": "这块蛋糕的截面很香，闻起来很诱人。", "explanation": "这里应该用〈香味〉。截面指切开后露出的平面，闻到的气味要说香味。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e4494b83-e876-485d-8dbd-a83380e357f3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24180, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "座位", "is_correct": false, "explanation": "语义：座位不是萝卜的部分，看座位无法判断萝卜的新鲜程度。"}, {"text": "截面", "is_correct": true, "explanation": "“截面”是切开后露出的面，看截面可以判断萝卜新不新鲜。"}, {"text": "跑道", "is_correct": false, "explanation": "语义：跑道是机场的设施，与萝卜无关，不能用来判断新鲜程度。"}, {"text": "速度", "is_correct": false, "explanation": "搭配：“速度”不能用来说萝卜的新鲜程度，与此语境不搭配。"}], "explanations": {"座位": "语义：座位不是萝卜的部分，看座位无法判断萝卜的新鲜程度。", "截面": "“截面”是切开后露出的面，看截面可以判断萝卜新不新鲜。", "跑道": "语义：跑道是机场的设施，与萝卜无关，不能用来判断新鲜程度。", "速度": "搭配：“速度”不能用来说萝卜的新鲜程度，与此语境不搭配。"}, "sentence_index": 6, "correct_answer": "截面"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "苹果的截面上有一层蜡，洗的时候要注意。", "explanation": "这里应该用〈表面〉。截面是切开后露出的面，果皮上的蜡要说表面。"}, {"text": "橘子的截面很薄，很好剥。", "explanation": "这里应该用〈果皮〉。截面是切开后露出的面，果皮薄、好剥要说果皮。"}, {"text": "盘子的截面有一个标签。", "explanation": "这里应该用〈底面〉。截面是切开后的断面，贴标签的盘子一面要说底面。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e4494b83-e876-485d-8dbd-a83380e357f3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24180, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "切开以后，这只截面很平整。", "corrected_sentence": "切开以后，这个截面很平整。", "error_description": "量词错误：“截面”应搭配“个”，不能说“这只截面”。“只”多用于动物或成对物件中的一个。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e4494b83-e876-485d-8dbd-a83380e357f3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24180, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "妈妈切西瓜，这条截面很整齐。", "corrected_sentence": "妈妈切西瓜，这个截面很整齐。", "error_description": "量词错误：“截面”应搭配“个”，不能说“这条”。“条”多用于细长的东西，不能用来修饰切面。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e4494b83-e876-485d-8dbd-a83380e357f3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24182, 1, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e4494b83-e876-485d-8dbd-a83380e357f3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24182, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e4494b83-e876-485d-8dbd-a83380e357f3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24182, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "动得很快、很猛。", "primary_collocate": null, "pronunciation": "jù liè", "ipa": "tɕy˥˩ ljɛ˥˩", "syllable_count": 2, "sentences": [{"text": "地震时，房子剧烈地摇晃。", "target_word": "剧烈", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他吓得心脏剧烈跳动。", "target_word": "剧烈", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "大风里，小船剧烈地上下摇动。", "target_word": "剧烈", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "飞机遇到气流，开始剧烈抖动。", "target_word": "剧烈", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "她笑得肩膀剧烈地抖动起来。", "target_word": "剧烈", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "洗衣机转得太剧烈，地板也跟着震动。", "target_word": "剧烈", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "车突然停下，车里的人剧烈地向前冲。", "target_word": "剧烈", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "火山喷发时，大地剧烈地震动。", "target_word": "剧烈", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "鱼一离开水，就在网里剧烈地跳动。", "target_word": "剧烈", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他用力一拉，绳子剧烈地晃了几下。", "target_word": "剧烈", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "剧烈地", "label": "副词形式"}, {"form": "劇烈", "label": "繁体"}], "register": "书面", "sense_fingerprint": "物体或身体动作幅度大、速度快，如晃动、抖动、跳动", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c3cad82c-93f9-4f2a-a9b9-419707bd24f6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24182, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "剧烈", "is_correct": true, "explanation": "剧烈修饰“摇晃”，表示幅度大、速度快，符合地震时的情境，可以填入空格。"}, {"text": "清淡", "is_correct": false, "explanation": "搭配：清淡多用于形容饮食，不能用来修饰摇晃。"}, {"text": "冷淡", "is_correct": false, "explanation": "语义：冷淡形容态度，与地震时房子的动荡不符。"}, {"text": "寂静", "is_correct": false, "explanation": "语义：寂静指没有声音，与摇晃的动态特点不符。"}], "explanations": {"剧烈": "剧烈修饰“摇晃”，表示幅度大、速度快，符合地震时的情境，可以填入空格。", "清淡": "搭配：清淡多用于形容饮食，不能用来修饰摇晃。", "冷淡": "语义：冷淡形容态度，与地震时房子的动荡不符。", "寂静": "语义：寂静指没有声音，与摇晃的动态特点不符。"}, "sentence_index": 0, "correct_answer": "剧烈"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "夏天的阳光非常剧烈。", "explanation": "这里应该用〈强烈〉。剧烈形容动作的猛烈程度，阳光的强弱要用强烈。"}, {"text": "这幅画的颜色非常剧烈。", "explanation": "这里应该用〈强烈〉。颜色的鲜明程度要用强烈，剧烈只形容动作。"}, {"text": "他思考这个问题时非常剧烈。", "explanation": "这里应该用〈认真〉。剧烈表示动得很快很猛，思考是内在活动，不能用剧烈修饰；描述思考的投入要说〈认真〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e4494b83-e876-485d-8dbd-a83380e357f3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24182, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "剧烈", "is_correct": true, "explanation": "剧烈修饰“向前冲”，表示动作猛烈，符合车急停时的情境，可以填入空格。"}, {"text": "明亮", "is_correct": false, "explanation": "搭配：明亮形容光线或色彩，不能修饰冲的动作。"}, {"text": "平淡", "is_correct": false, "explanation": "语义：平淡指平稳、没有波澜，与急停后的猛冲相反。"}, {"text": "清脆", "is_correct": false, "explanation": "搭配：清脆形容声音，不能用来形容人的动作。"}], "explanations": {"剧烈": "剧烈修饰“向前冲”，表示动作猛烈，符合车急停时的情境，可以填入空格。", "明亮": "搭配：明亮形容光线或色彩，不能修饰冲的动作。", "平淡": "语义：平淡指平稳、没有波澜，与急停后的猛冲相反。", "清脆": "搭配：清脆形容声音，不能用来形容人的动作。"}, "sentence_index": 6, "correct_answer": "剧烈"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这幅画剧烈地挂在墙上。", "explanation": "这里误把〈剧烈〉当作“牢牢地”来用；剧烈指动得很快很猛，挂画是平稳的动作，应说〈牢牢地〉。"}, {"text": "老师剧烈地讲解数学题。", "explanation": "这里误把〈剧烈〉当作“仔细、详尽”来用；讲解是平和的活动，剧烈表示动得很快很猛，应说〈仔细〉。"}, {"text": "那个人剧烈地坐在椅子上发呆。", "explanation": "这里应该用〈安静〉。剧烈表示动得很快很猛，坐着发呆是静止的，不能用剧烈修饰，应说安静地坐着。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e4494b83-e876-485d-8dbd-a83380e357f3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24182, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "小船在风里剧烈的摇动。", "corrected_sentence": "小船在风里剧烈地摇动。", "error_description": "“剧烈”修饰动词“摇动”时要用“地”，写成“的”是误用（“剧烈的”只修饰名词）。正确形式为“剧烈地摇动”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e4494b83-e876-485d-8dbd-a83380e357f3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24182, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他猛地一拉，车门剧烈的晃了几下。", "corrected_sentence": "他猛地一拉，车门剧烈地晃了几下。", "error_description": "修饰动词“晃”要用“地”，写成“的”是误用。“剧烈的”只能修饰名词，正确形式为“剧烈地晃”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e4494b83-e876-485d-8dbd-a83380e357f3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
