INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24188, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "分子是分数中上面的数，告诉你有几份。", "primary_collocate": null, "pronunciation": "fēn zǐ", "ipa": "fən˥˥ tsɹ̩˨˩˦", "syllable_count": 2, "sentences": [{"text": "二分之一的分子是一。", "target_word": "分子", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "三分之二里，分子是二，分母是三。", "target_word": "分子", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个分数的分子比分母小。", "target_word": "分子", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请把分子写在分数线上面。", "target_word": "分子", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "五分之四的分子是四。", "target_word": "分子", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "分数线上面的数叫分子。", "target_word": "分子", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "分母是八，分子是三，这个分数是八分之三。", "target_word": "分子", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "分子和分母一样大，这个分数就是一。", "target_word": "分子", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师问我：“七分之五的分子是多少？”", "target_word": "分子", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "分母不变时，这个分子越大，分数越大。", "target_word": "分子", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "分数线上面的数", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4242725a-da6e-4fb3-b896-246ef3d081ae') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24188, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "分子", "is_correct": true, "explanation": "分子指分数线上面的数，读作 fēn zǐ，例如二分之一的分子是一。"}, {"text": "分支", "is_correct": false, "explanation": "zhī（第一声）与 zǐ（第三声）声母与声调都不同，意思是分支。"}, {"text": "分值", "is_correct": false, "explanation": "zhí（第二声）与 zǐ（第三声）声母与声调不同，意思是分值。"}, {"text": "分词", "is_correct": false, "explanation": "cí（第二声）与 zǐ（第三声）声母与声调不同，意思是分词（语法中的一类词）。"}, {"text": "份子", "is_correct": false, "explanation": "fèn（第四声）与 fēn（第一声）声调不同，份子指随礼送的钱，与分数无关。"}], "explanations": {"分子": "分子指分数线上面的数，读作 fēn zǐ，例如二分之一的分子是一。", "分支": "zhī（第一声）与 zǐ（第三声）声母与声调都不同，意思是分支。", "分值": "zhí（第二声）与 zǐ（第三声）声母与声调不同，意思是分值。", "分词": "cí（第二声）与 zǐ（第三声）声母与声调不同，意思是分词（语法中的一类词）。", "份子": "fèn（第四声）与 fēn（第一声）声调不同，份子指随礼送的钱，与分数无关。"}, "sentence_index": null, "correct_answer": "分子"}, "level_3": {"options": [{"text": "分子", "is_correct": true, "explanation": "分子是分数线上面的数，“二分之一的分子是一”句意正确。"}, {"text": "分母", "is_correct": false, "explanation": "语义：分母是分数线下面的数，二分之一的分母是二，不能是一。"}, {"text": "整数", "is_correct": false, "explanation": "语义：二分之一是分数，不是整数，不能说它的整数是一。"}, {"text": "小数", "is_correct": false, "explanation": "语义：二分之一的小数是0.5，不是一，与句意不符。"}], "explanations": {"分子": "分子是分数线上面的数，“二分之一的分子是一”句意正确。", "分母": "语义：分母是分数线下面的数，二分之一的分母是二，不能是一。", "整数": "语义：二分之一是分数，不是整数，不能说它的整数是一。", "小数": "语义：二分之一的小数是0.5，不是一，与句意不符。"}, "sentence_index": 0, "correct_answer": "分子"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这份工作的分子很重。", "explanation": "这里应该用〈分量〉。“分子”只指分数线上面的数或化学中的微粒，说工作的轻重要用“分量”。"}, {"text": "这个分子是八分之三。", "explanation": "这里应该用〈分数〉。分子只是分数线上面的那个数，整个八分之三才叫分数。"}, {"text": "我们班的分子都很热心。", "explanation": "这里应该用〈成员〉。“分子”指人时只见于“积极分子”“知识分子”等复合词，说班里的人要用“成员”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd2e5a0de-8f20-49ae-ab04-d651f3bdb347') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24188, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "分子", "is_correct": true, "explanation": "分子指分数线上面的数，读作 fēn zǐ。"}, {"text": "分组", "is_correct": false, "explanation": "zǔ（第三声）与 zǐ（第三声）韵母不同，意思是分组。"}, {"text": "方子", "is_correct": false, "explanation": "fāng（第一声）与 fēn（第一声）韵母不同，zi 读轻声，意思是药方。"}, {"text": "分制", "is_correct": false, "explanation": "zhì（第四声）与 zǐ（第三声）声母与声调都不同，意思是按分数计算的制度，如学分制。"}], "explanations": {"分子": "分子指分数线上面的数，读作 fēn zǐ。", "分组": "zǔ（第三声）与 zǐ（第三声）韵母不同，意思是分组。", "方子": "fāng（第一声）与 fēn（第一声）韵母不同，zi 读轻声，意思是药方。", "分制": "zhì（第四声）与 zǐ（第三声）声母与声调都不同，意思是按分数计算的制度，如学分制。"}, "sentence_index": null, "correct_answer": "分子"}, "level_3": {"options": [{"text": "分子", "is_correct": true, "explanation": "分子是分数线上面的数，“分子是三”与“八分之三”的分数相符。"}, {"text": "因数", "is_correct": false, "explanation": "语义：句中说的是分数的分子，“因数是三”与分数的构成不符。"}, {"text": "积", "is_correct": false, "explanation": "语义：积是乘法的结果，与分数的分子是三无关。"}, {"text": "余数", "is_correct": false, "explanation": "搭配：“余数”要与除法连用，不能与“分母是八”并列作分数的组成部分。"}], "explanations": {"分子": "分子是分数线上面的数，“分子是三”与“八分之三”的分数相符。", "因数": "语义：句中说的是分数的分子，“因数是三”与分数的构成不符。", "积": "语义：积是乘法的结果，与分数的分子是三无关。", "余数": "搭配：“余数”要与除法连用，不能与“分母是八”并列作分数的组成部分。"}, "sentence_index": 6, "correct_answer": "分子"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "分母不变时，这位分子越大，分数越大。", "explanation": "这里应该用〈个〉。“位”用于人，分子是抽象的数，不能用“位”计量。"}, {"text": "分母不变时，这条分子越大，分数越大。", "explanation": "这里应该用〈个〉。“条”用于细长的东西，分子是抽象的数，不能用“条”计量。"}, {"text": "分母不变时，这只分子越大，分数越大。", "explanation": "这里应该用〈个〉。“只”用于动物等，分子是抽象的数，不能用“只”计量。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd2e5a0de-8f20-49ae-ab04-d651f3bdb347') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24188, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "九分之二的分子是九。", "corrected_sentence": "九分之二的分子是二。", "error_description": "分子是分数线上面的数。九分之二的分子是二，九是分母，不能说分子是九。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd2e5a0de-8f20-49ae-ab04-d651f3bdb347') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24188, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这张分子是六，分母是十一。", "corrected_sentence": "这个分子是六，分母是十一。", "error_description": "“分子”是抽象的数，量词用“个”；“张”用于平面的东西，不能计量分子，应说“这个分子是六”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd2e5a0de-8f20-49ae-ab04-d651f3bdb347') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24190, 1, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '04c7c8ea-6bbb-414b-a408-d1d15d5ecbcf') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
