INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24190, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "property", "definition": "粗糙度就是东西表面不光滑的程度，比如摸起来很粗或者很细的感觉。", "primary_collocate": null, "pronunciation": "cū cāo dù", "ipa": "tsʰu˥˥ tsʰaʊ˥˥ tu˥˩", "syllable_count": 3, "sentences": [{"text": "这块布的粗糙度很高，摸起来有点扎手。", "target_word": "粗糙度", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你摸一摸，就知道墙面的粗糙度。", "target_word": "粗糙度", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "砂纸的粗糙度比纸巾大得多。", "target_word": "粗糙度", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "手上长了茧，我能感觉到皮肤的粗糙度。", "target_word": "粗糙度", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个杯子表面很滑，几乎没有粗糙度。", "target_word": "粗糙度", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "买木桌时，我会用手摸一摸桌面的粗糙度。", "target_word": "粗糙度", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子用手一摸，就能感觉到石头的粗糙度。", "target_word": "粗糙度", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我用手指感受着纸的粗糙度。", "target_word": "粗糙度", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "厨房地砖的粗糙度刚好，不容易滑倒。", "target_word": "粗糙度", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "两块木板的粗糙度不一样。", "target_word": "粗糙度", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "表面粗糙度", "label": "复合"}], "register": "中性", "sense_fingerprint": "粗糙度：东西表面摸起来粗或细的程度", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '36bfebba-bc72-41eb-b676-3a5d37f4b25e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24190, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "粗糙度", "is_correct": true, "explanation": "正确：“粗糙度很高”指表面摸起来粗，与“摸起来有点扎手”相符。"}, {"text": "颜色", "is_correct": false, "explanation": "语义：颜色不能靠摸来感受粗细，与“摸起来扎手”不符。"}, {"text": "长度", "is_correct": false, "explanation": "搭配：布的“长度”不用“很高”来形容，与句子搭配不当。"}, {"text": "年龄", "is_correct": false, "explanation": "搭配：布料不说“年龄很高”，与句中描述的触感不符。"}], "explanations": {"粗糙度": "正确：“粗糙度很高”指表面摸起来粗，与“摸起来有点扎手”相符。", "颜色": "语义：颜色不能靠摸来感受粗细，与“摸起来扎手”不符。", "长度": "搭配：布的“长度”不用“很高”来形容，与句子搭配不当。", "年龄": "搭配：布料不说“年龄很高”，与句中描述的触感不符。"}, "sentence_index": 0, "correct_answer": "粗糙度"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这块玻璃的粗糙度很高，所以很透明。", "explanation": "这里应该用〈透明度〉。玻璃通透与否要说“透明度”，粗糙度只描述表面不平整的程度，不能用来说明透明与否。"}, {"text": "今天空气的粗糙度很高，闷得人喘不过气。", "explanation": "这里应该用〈湿度〉。空气潮湿要说“湿度”，粗糙度只描述物体表面。"}, {"text": "杯子里的粗糙度很高，喝的时候要小心。", "explanation": "这里应该用〈温度〉。烫不烫要说“温度”，粗糙度只描述物体表面。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '04c7c8ea-6bbb-414b-a408-d1d15d5ecbcf') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24190, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "粗糙度", "is_correct": true, "explanation": "正确：用手一摸就能感觉到的表面粗细，符合句中的触感语境。"}, {"text": "味道", "is_correct": false, "explanation": "语义：味道要用嘴尝，不能“用手一摸”就感觉到。"}, {"text": "气味", "is_correct": false, "explanation": "语义：气味是嗅觉的感受，不能用来说石头的触感。"}, {"text": "价格", "is_correct": false, "explanation": "语义：价格指买卖的代价，与孩子的感受无关。"}], "explanations": {"粗糙度": "正确：用手一摸就能感觉到的表面粗细，符合句中的触感语境。", "味道": "语义：味道要用嘴尝，不能“用手一摸”就感觉到。", "气味": "语义：气味是嗅觉的感受，不能用来说石头的触感。", "价格": "语义：价格指买卖的代价，与孩子的感受无关。"}, "sentence_index": 6, "correct_answer": "粗糙度"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这首歌的粗糙度太大了，邻居都听到了。", "explanation": "这里应该用〈音量〉。声音大小要说“音量”，粗糙度只描述物体表面。"}, {"text": "房间里的粗糙度太低，看不清字。", "explanation": "这里应该用〈亮度〉。光线明暗要说“亮度”，粗糙度不能用来形容房间。"}, {"text": "这箱书的粗糙度太重，搬不动。", "explanation": "这里应该用〈重量〉。轻重要说“重量”，粗糙度只描述物体表面。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '04c7c8ea-6bbb-414b-a408-d1d15d5ecbcf') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24190, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这块木头的一只粗糙度很低，摸起来很光滑。", "corrected_sentence": "这块木头的粗糙度很低，摸起来很光滑。", "error_description": "错误形式：一只粗糙度；正确形式：粗糙度。原因：“只”多用于动物或成对的小物，抽象名词“粗糙度”不能用“只”计量，应直接说“这块木头的粗糙度”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '04c7c8ea-6bbb-414b-a408-d1d15d5ecbcf') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24190, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这只粗糙度让我觉得很舒服。", "corrected_sentence": "这种粗糙度让我觉得很舒服。", "error_description": "错误形式：这只粗糙度；正确形式：这种粗糙度。原因：“只”多用于动物或成对的小物，抽象名词“粗糙度”要用量词“种”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '04c7c8ea-6bbb-414b-a408-d1d15d5ecbcf') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
