INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24196, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "非常大，比大还要大。", "primary_collocate": null, "pronunciation": "jí dà", "ipa": "tɕi˧˥ ta˥˩", "syllable_count": 2, "sentences": [{"text": "这件事的影响极大。", "target_word": "极大", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他有极大的耐心。", "target_word": "极大", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个湖的面积极大。", "target_word": "极大", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那只狗的力气极大。", "target_word": "极大", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我对这本书有极大的兴趣。", "target_word": "极大", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这次比赛的压力极大。", "target_word": "极大", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "夏天的雨量极大。", "target_word": "极大", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他给了我极大的帮助。", "target_word": "极大", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个城市的变化极大。", "target_word": "极大", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这次旅行的收获极大。", "target_word": "极大", "complexity_tier": "T3", "furigana": "zhè cì lǚ xíng de shōu huò jí dà", "sentence_source": "generated"}], "morphological_forms": [{"form": "极大的", "label": "定语形式"}, {"form": "极大地", "label": "状语形式"}], "register": "中性", "sense_fingerprint": "程度、规模或数量大到了最高的程度", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a89628db-2a92-48c4-bb2a-aa8338e4bf66') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24196, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "极大", "is_correct": true, "explanation": "目标词，读作 jí dà，意思是非常大。"}, {"text": "嫉妒", "is_correct": false, "explanation": "dù（第四声）与 dà（第四声）只有韵母不同（u 与 a），意思是嫉妒。"}, {"text": "极地", "is_correct": false, "explanation": "dì（第四声）与 dà（第四声）只有韵母不同（i 与 a），意思是极地。"}, {"text": "击打", "is_correct": false, "explanation": "jī 与 jí、dǎ 与 dà 声调都不同（第一声与第二声、第三声与第四声），意思是击打。"}], "explanations": {"极大": "目标词，读作 jí dà，意思是非常大。", "嫉妒": "dù（第四声）与 dà（第四声）只有韵母不同（u 与 a），意思是嫉妒。", "极地": "dì（第四声）与 dà（第四声）只有韵母不同（i 与 a），意思是极地。", "击打": "jī 与 jí、dǎ 与 dà 声调都不同（第一声与第二声、第三声与第四声），意思是击打。"}, "sentence_index": null, "correct_answer": "极大"}, "level_3": {"options": [{"text": "极大", "is_correct": true, "explanation": "“极大”修饰“影响”，表示程度非常大，符合句意。"}, {"text": "聪明", "is_correct": false, "explanation": "语义：聪明形容人的智慧，不能用来形容影响。"}, {"text": "清楚", "is_correct": false, "explanation": "搭配：清楚多用于说明情况或道理明白，不说“影响清楚”。"}, {"text": "善良", "is_correct": false, "explanation": "语义：善良形容人的品性，不能用来形容影响。"}], "explanations": {"极大": "“极大”修饰“影响”，表示程度非常大，符合句意。", "聪明": "语义：聪明形容人的智慧，不能用来形容影响。", "清楚": "搭配：清楚多用于说明情况或道理明白，不说“影响清楚”。", "善良": "语义：善良形容人的品性，不能用来形容影响。"}, "sentence_index": 0, "correct_answer": "极大"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他的心跳极大。", "explanation": "这里应该用〈极快〉。极大说的是大小、数量，心跳说的是快慢，要用“快”，不说“心跳极大”。"}, {"text": "他的成绩极大。", "explanation": "这里应该用〈极高〉。极大说的是大小，成绩说的是高低，要用“高”，不说“成绩极大”。"}, {"text": "这次会议的时间极大。", "explanation": "这里应该用〈极长〉。极大说的是大小，时间的长短要用“长”，不说“时间极大”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b9405f69-aefb-4e89-9803-91f08f3f19d9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24196, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "极大", "is_correct": true, "explanation": "“极大”修饰“雨量”，表示雨量非常大，符合句意。"}, {"text": "漂亮", "is_correct": false, "explanation": "语义：漂亮多形容外貌或事物好看，不能用来评价雨量的多少。"}, {"text": "清澈", "is_correct": false, "explanation": "搭配：清澈多形容水或眼神透明，不说“雨量清澈”。"}, {"text": "友好", "is_correct": false, "explanation": "语义：友好形容人与人之间的态度，不能用来形容雨量。"}], "explanations": {"极大": "“极大”修饰“雨量”，表示雨量非常大，符合句意。", "漂亮": "语义：漂亮多形容外貌或事物好看，不能用来评价雨量的多少。", "清澈": "搭配：清澈多形容水或眼神透明，不说“雨量清澈”。", "友好": "语义：友好形容人与人之间的态度，不能用来形容雨量。"}, "sentence_index": 6, "correct_answer": "极大"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这次旅行结识的朋友极大。", "explanation": "这里应该用〈极多〉。极大说的是大小，人数多要用“多”，不说“朋友极大”。"}, {"text": "这次旅行的路程极大。", "explanation": "这里应该用〈极长〉。极大说的是大小，路程的远近要用“长”，不说“路程极大”。"}, {"text": "这次旅行的气温极大。", "explanation": "这里应该用〈极高〉。极大说的是大小，气温说的是高低，要用“高”，不说“气温极大”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b9405f69-aefb-4e89-9803-91f08f3f19d9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24196, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这次事故给公司带来了很极大的损失。", "corrected_sentence": "这次事故给公司带来了极大的损失。", "error_description": "错误是“很极大”，正确是“极大的”。“极大”本身已表示程度最高，前面不能再加“很”，应删去“很”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b9405f69-aefb-4e89-9803-91f08f3f19d9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24196, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这本书极大的提高了我的兴趣。", "corrected_sentence": "这本书极大地提高了我的兴趣。", "error_description": "错误是“极大的提高”，正确是“极大地提高”。“极大”修饰动词“提高”作状语时要用“地”，不能用“的”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b9405f69-aefb-4e89-9803-91f08f3f19d9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
