INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24200, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "接受别人给予的表扬、批评、教育、帮助、关心或影响。", "primary_collocate": null, "pronunciation": "shòu", "ipa": "ʂou̯˥˩", "syllable_count": 1, "sentences": [{"text": "他今天受了老师的表扬。", "target_word": "受", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们都受过很好的教育。", "target_word": "受", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她小时候受了很多关爱。", "target_word": "受", "complexity_tier": "T3", "furigana": "tā xiǎo shí hou shòu le hěn duō guān ài", "sentence_source": "generated"}, {"text": "这个孩子受了妈妈的影响。", "target_word": "受", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他做错了事，受了大家的批评。", "target_word": "受", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他受了朋友的帮助。", "target_word": "受", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小明受了奶奶的照顾。", "target_word": "受", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她在国外受过三年教育。", "target_word": "受", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他昨天受了一次表彰。", "target_word": "受", "complexity_tier": "T3", "furigana": "tā zuó tiān shòu le yí cì biǎo zhāng", "sentence_source": "generated"}, {"text": "他们受着大家的关心。", "target_word": "受", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "受了", "label": "完成体"}, {"form": "受过", "label": "经历体"}, {"form": "受着", "label": "持续体"}], "register": "中性", "sense_fingerprint": "得到或接受表扬、批评、教育、帮助等", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a89628db-2a92-48c4-bb2a-aa8338e4bf66') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24200, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "受", "is_correct": true, "explanation": "目标词，读作 shòu，意思是得到或接受。"}, {"text": "收", "is_correct": false, "explanation": "shōu（第一声）与 shòu（第四声）声调不同，意思是收取、收到。"}, {"text": "手", "is_correct": false, "explanation": "shǒu（第三声）与 shòu（第四声）声调不同，意思是手。"}, {"text": "肉", "is_correct": false, "explanation": "ròu 与 shòu 声母不同（r 与 sh），意思是肉。"}], "explanations": {"受": "目标词，读作 shòu，意思是得到或接受。", "收": "shōu（第一声）与 shòu（第四声）声调不同，意思是收取、收到。", "手": "shǒu（第三声）与 shòu（第四声）声调不同，意思是手。", "肉": "ròu 与 shòu 声母不同（r 与 sh），意思是肉。"}, "sentence_index": null, "correct_answer": "受"}, "level_3": {"options": [{"text": "受", "is_correct": true, "explanation": "“受”与“了老师的表扬”搭配，表示接受表扬，符合句意。"}, {"text": "写", "is_correct": false, "explanation": "搭配：写的对象是文字，不说“写表扬”。"}, {"text": "吃", "is_correct": false, "explanation": "语义：吃指进食，不能与表扬搭配。"}, {"text": "打", "is_correct": false, "explanation": "搭配：打多指击打或打电话，不说“打表扬”。"}], "explanations": {"受": "“受”与“了老师的表扬”搭配，表示接受表扬，符合句意。", "写": "搭配：写的对象是文字，不说“写表扬”。", "吃": "语义：吃指进食，不能与表扬搭配。", "打": "搭配：打多指击打或打电话，不说“打表扬”。"}, "sentence_index": 0, "correct_answer": "受"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "她受了一次机会。", "explanation": "这里应该用〈得到〉。“受”多用于受到表扬、教育、帮助等，不能说“受一次机会”，应说“得到一次机会”。"}, {"text": "这份计划受了大家的同意。", "explanation": "这里应该用〈得到〉。“受”后面接的多是表扬、教育、帮助这类对待，“同意”要说“得到大家的同意”，不说“受了同意”。"}, {"text": "他受了这件礼物。", "explanation": "这里应该用〈收下〉。“受”多接表扬、教育、帮助这类对待，礼物要说“收下这件礼物”，不说“受了礼物”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b9405f69-aefb-4e89-9803-91f08f3f19d9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24200, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "受", "is_correct": true, "explanation": "目标词，读作 shòu，意思是得到或接受。"}, {"text": "守", "is_correct": false, "explanation": "shǒu（第三声）与 shòu（第四声）声调不同，意思是守护。"}, {"text": "首", "is_correct": false, "explanation": "shǒu（第三声）与 shòu（第四声）声调不同，意思是首先、头。"}, {"text": "奏", "is_correct": false, "explanation": "zòu 与 shòu 声母不同（z 与 sh），意思是演奏。"}, {"text": "漏", "is_correct": false, "explanation": "lòu 与 shòu 声母不同（l 与 sh），意思是漏掉。"}], "explanations": {"受": "目标词，读作 shòu，意思是得到或接受。", "守": "shǒu（第三声）与 shòu（第四声）声调不同，意思是守护。", "首": "shǒu（第三声）与 shòu（第四声）声调不同，意思是首先、头。", "奏": "zòu 与 shòu 声母不同（z 与 sh），意思是演奏。", "漏": "lòu 与 shòu 声母不同（l 与 sh），意思是漏掉。"}, "sentence_index": null, "correct_answer": "受"}, "level_3": {"options": [{"text": "受", "is_correct": true, "explanation": "“受”与“奶奶的照顾”搭配，表示接受照顾，符合句意。"}, {"text": "送", "is_correct": false, "explanation": "搭配：送多指送出物品，不说“送照顾”。"}, {"text": "挨", "is_correct": false, "explanation": "语义：挨多指遭受责罚或痛苦，与“照顾”的语义不符。"}, {"text": "赐", "is_correct": false, "explanation": "语域：赐是书面或古雅用语，口语中不说“赐了照顾”。"}], "explanations": {"受": "“受”与“奶奶的照顾”搭配，表示接受照顾，符合句意。", "送": "搭配：送多指送出物品，不说“送照顾”。", "挨": "语义：挨多指遭受责罚或痛苦，与“照顾”的语义不符。", "赐": "语域：赐是书面或古雅用语，口语中不说“赐了照顾”。"}, "sentence_index": 6, "correct_answer": "受"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他受了一个冠军。", "explanation": "这里应该用〈获得〉。“受”不能直接带“冠军”这类成绩作宾语，应说“获得冠军”。"}, {"text": "我们受着假期。", "explanation": "这里应该用〈享受〉。“受”后接的多是别人的对待，不能说“受着假期”，享受假期才自然。"}, {"text": "她受了一封信。", "explanation": "这里应该用〈收到〉。“受”不接“信”这类可以收到的东西，应说“收到一封信”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b9405f69-aefb-4e89-9803-91f08f3f19d9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24200, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他在国外被受了很好的训练。", "corrected_sentence": "他在国外受了很好的训练。", "error_description": "错误是“被受”，正确是“受”。“被”和“受”都表示被动，不能并用，应删去“被”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b9405f69-aefb-4e89-9803-91f08f3f19d9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24200, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他上个月受着一次表彰。", "corrected_sentence": "他上个月受了一次表彰。", "error_description": "错误是“受着”，正确是“受了”。“着”表示持续状态，不能用于“上个月”这种已经结束的时间，应改为“受了”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b9405f69-aefb-4e89-9803-91f08f3f19d9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
