INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24206, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "水转着圈流动，像洗澡水转圈的样子。", "primary_collocate": null, "pronunciation": "wō liú", "ipa": "uo˥ ljoʊ˧˥", "syllable_count": 2, "sentences": [{"text": "洗澡水流走时，会有涡流。", "target_word": "涡流", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "水池里的涡流转得很快。", "target_word": "涡流", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "拔掉塞子，水里出现了涡流。", "target_word": "涡流", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "涡流把小船卷了进去。", "target_word": "涡流", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "河中间有一个涡流。", "target_word": "涡流", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子看着涡流里的树叶转圈。", "target_word": "涡流", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "水流到石头后面，打出一个小涡流。", "target_word": "涡流", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他用勺子在杯子里搅出涡流。", "target_word": "涡流", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "游泳时要远离涡流。", "target_word": "涡流", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "水槽里的涡流越转越小。", "target_word": "涡流", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "一个涡流", "label": "量词"}, {"form": "渦流", "label": "繁体"}], "register": "中性", "sense_fingerprint": "水转着圈流动的样子", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '36bfebba-bc72-41eb-b676-3a5d37f4b25e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24206, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "涡流", "is_correct": true, "explanation": "涡流：水转着圈流动的样子，洗澡水流走时会出现，与句意相符。"}, {"text": "火焰", "is_correct": false, "explanation": "语义：洗澡水流走时不会产生火焰，火焰与水流无关。"}, {"text": "鱼", "is_correct": false, "explanation": "语义：水流走时不会出现鱼，“会有”后不能接鱼。"}, {"text": "方块", "is_correct": false, "explanation": "体貌：涡流是旋转的水流，没有方块的形状。"}], "explanations": {"涡流": "涡流：水转着圈流动的样子，洗澡水流走时会出现，与句意相符。", "火焰": "语义：洗澡水流走时不会产生火焰，火焰与水流无关。", "鱼": "语义：水流走时不会出现鱼，“会有”后不能接鱼。", "方块": "体貌：涡流是旋转的水流，没有方块的形状。"}, "sentence_index": 0, "correct_answer": "涡流"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "水池里有一张涡流。", "explanation": "这里应该用〈个〉。“张”用于纸、床等平面的东西，涡流不能用“张”计量。"}, {"text": "桌子上放着一碗涡流。", "explanation": "这里应该用〈水〉。涡流是水转圈流动的样子，不能装在碗里放着。"}, {"text": "风吹过树林，树叶上开出了涡流。", "explanation": "这里应该用〈花〉。涡流是转圈流动的水，不会在树上“开出来”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '04c7c8ea-6bbb-414b-a408-d1d15d5ecbcf') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24206, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "涡流", "is_correct": true, "explanation": "涡流：水流到石头后形成的小旋转，与“打出”搭配，句意相符。"}, {"text": "小拳头", "is_correct": false, "explanation": "体貌：水流没有拳头的形状，不能说“打出一个小拳头”。"}, {"text": "小石子", "is_correct": false, "explanation": "语义：水流不能“打出”石子，句子所指的并非石子。"}, {"text": "小铃铛", "is_correct": false, "explanation": "语义：水流不会发出或变成铃铛，句子不合理。"}], "explanations": {"涡流": "涡流：水流到石头后形成的小旋转，与“打出”搭配，句意相符。", "小拳头": "体貌：水流没有拳头的形状，不能说“打出一个小拳头”。", "小石子": "语义：水流不能“打出”石子，句子所指的并非石子。", "小铃铛": "语义：水流不会发出或变成铃铛，句子不合理。"}, "sentence_index": 6, "correct_answer": "涡流"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "涡流一直往前冲，把船推向岸边。", "explanation": "这里应该用〈水流〉。涡流是原地打转的水，不能用于一直向前冲的流动。"}, {"text": "涡流直直地喷上天。", "explanation": "这里应该用〈水柱〉。涡流是打转的，不会直直向上喷，应说水柱。"}, {"text": "涡流从山上直直地落下来。", "explanation": "这里应该用〈瀑布〉。涡流是打转的，直直落下的水应说瀑布。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '04c7c8ea-6bbb-414b-a408-d1d15d5ecbcf') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24206, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "洗澡水里的一只涡流转得很慢。", "corrected_sentence": "洗澡水里的一个涡流转得很慢。", "error_description": "量词错误：涡流应用“个”计量，“只”用于动物等，不能用来计量涡流。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '04c7c8ea-6bbb-414b-a408-d1d15d5ecbcf') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24206, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "杯底的涡流的还在转着。", "corrected_sentence": "杯底的涡流还在转着。", "error_description": "结构助词多余：“杯底的涡流”已用“的”连接定语，主语后不能再加“的”，应说“杯底的涡流还在转着”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '04c7c8ea-6bbb-414b-a408-d1d15d5ecbcf') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
