INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24210, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "船或飞机在海上或空中来回走动，看看有没有危险。", "primary_collocate": null, "pronunciation": "xún háng", "ipa": "/ɕyn˧˥ xɑŋ˧˥/", "syllable_count": 2, "sentences": [{"text": "海警船在海上来回巡航，检查有没有危险。", "target_word": "巡航", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "夜里，一艘小船在港口附近巡航。", "target_word": "巡航", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "飞机在山区上空巡航，寻找起火的地方。", "target_word": "巡航", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "救生艇每天在海边巡航，保护游泳的人。", "target_word": "巡航", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "边防艇在江上巡航，看有没有可疑的船。", "target_word": "巡航", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "台风来了，海军的船仍在海上巡航。", "target_word": "巡航", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "无人机每晚在森林上空巡航，防止火灾。", "target_word": "巡航", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "警用直升机在城市上空来回巡航。", "target_word": "巡航", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这艘船在海面巡航，注意有没有冰山。", "target_word": "巡航", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那架飞机在山谷里巡航了一圈，没发现危险。", "target_word": "巡航", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "巡航了", "label": "完成体"}, {"form": "巡航过", "label": "经历体"}, {"form": "巡航着", "label": "持续体"}, {"form": "巡航导弹", "label": "复合词"}, {"form": "巡航速度", "label": "复合词"}], "register": "书面语", "sense_fingerprint": "巡航|动词|船或飞机来回巡查，查看有无危险", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '29912ec1-1b02-4999-9515-ab237eadac0e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24210, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "巡航", "is_correct": true, "explanation": "巡航：船在海上来回巡查，与「来回」和「检查有没有危险」的语境相合。"}, {"text": "休息", "is_correct": false, "explanation": "语义：“休息”指停止活动，与“来回”巡查、检查危险的行动相矛盾。"}, {"text": "装卸", "is_correct": false, "explanation": "配价：“装卸”需带宾语（如装卸货物），这里缺少宾语。"}, {"text": "停泊", "is_correct": false, "explanation": "语义：“停泊”指停靠不动，与“来回”相矛盾。"}], "explanations": {"巡航": "巡航：船在海上来回巡查，与「来回」和「检查有没有危险」的语境相合。", "休息": "语义：“休息”指停止活动，与“来回”巡查、检查危险的行动相矛盾。", "装卸": "配价：“装卸”需带宾语（如装卸货物），这里缺少宾语。", "停泊": "语义：“停泊”指停靠不动，与“来回”相矛盾。"}, "sentence_index": 0, "correct_answer": "巡航"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "值班员每天在海滩上巡航，看有没有危险。", "explanation": "这里应该用〈巡视〉。巡航只用于舰船、飞机，人在海滩上查看要用巡视。"}, {"text": "老人每天在海边巡航，看看风景。", "explanation": "这里应该用〈散步〉。巡航只用于舰船、飞机，人在海边走动不说巡航。"}, {"text": "木筏在河上巡航，顺水而下。", "explanation": "这里应该用〈漂流〉。巡航只用于舰船或飞机，木筏顺水漂下不说巡航。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ab0a75be-c87d-4c9e-905b-129f6ad5f2a2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24210, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "巡航", "is_correct": true, "explanation": "巡航：无人机在上空来回查看，与「防止火灾」的目的相合。"}, {"text": "睡觉", "is_correct": false, "explanation": "语义：无人机不睡觉，与防火的目的不符。"}, {"text": "散步", "is_correct": false, "explanation": "搭配：“散步”的主语应为人，无人机不说散步。"}, {"text": "游泳", "is_correct": false, "explanation": "语义：无人机不能游泳，与森林上空的语境不符。"}], "explanations": {"巡航": "巡航：无人机在上空来回查看，与「防止火灾」的目的相合。", "睡觉": "语义：无人机不睡觉，与防火的目的不符。", "散步": "搭配：“散步”的主语应为人，无人机不说散步。", "游泳": "语义：无人机不能游泳，与森林上空的语境不符。"}, "sentence_index": 6, "correct_answer": "巡航"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "游艇在码头巡航，等待天气转好。", "explanation": "这里应该用〈停泊〉。巡航指来回查看或行驶，停在码头等待时不说巡航。"}, {"text": "一只鸡在院子里巡航，找虫子吃。", "explanation": "这里应该用〈踱步〉。鸡在院子里慢慢走动找吃的，用踱步；巡航只用于来回查看有无危险的船或飞机。"}, {"text": "电梯在楼道里巡航，来回运行。", "explanation": "这里应该用〈运行〉。电梯在楼道里上下往返用运行，巡航只用于在海上或空中按路线行驶的船和飞机。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ab0a75be-c87d-4c9e-905b-129f6ad5f2a2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24210, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "夜里，巡逻艇港湾里来回巡航。", "corrected_sentence": "夜里，巡逻艇在港湾里来回巡航。", "error_description": "错误：“港湾里”前缺少介词“在”。正确：“在港湾里来回巡航”。表示地点的词语放在动词前要用“在”引出。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ab0a75be-c87d-4c9e-905b-129f6ad5f2a2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24210, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他们每晚都在湖面上巡航一个。", "corrected_sentence": "他们每晚都在湖面上巡航一次。", "error_description": "错误：计次的量词用错。正确：“巡航一次”。巡航是动作，计次要用“次”，“个”用于指称具体事物。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ab0a75be-c87d-4c9e-905b-129f6ad5f2a2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
