INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24212, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "让一件事发生。", "primary_collocate": null, "pronunciation": "yǐn qǐ", "ipa": "in˨˩˦ tɕʰi˨˩˦", "syllable_count": 2, "sentences": [{"text": "这件事引起了大家的注意。", "target_word": "引起", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "大雨引起了严重的堵车。", "target_word": "引起", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的话引起了老师的不满。", "target_word": "引起", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "吃太多糖会引起牙疼。", "target_word": "引起", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个问题引起了很多人的讨论。", "target_word": "引起", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "好的广告能引起客人的兴趣。", "target_word": "引起", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "一句玩笑话引起了大家的笑声。", "target_word": "引起", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "新电影引起了年轻人的关注。", "target_word": "引起", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "天气太冷，容易引起感冒。", "target_word": "引起", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的错误引起了很大的麻烦。", "target_word": "引起", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "引起了", "label": "体标"}, {"form": "引起过", "label": "体标"}], "register": "中性", "sense_fingerprint": "使某事、某种情况产生", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cdc1bb5e-b14c-41de-8ff0-76ccf8bb8da0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24212, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "发生", "is_correct": false, "explanation": "配价：“发生”是不及物动词，后面不能直接带“注意”作宾语，“发生了大家的注意”说不通。"}, {"text": "引起", "is_correct": true, "explanation": "引起：使大家对这件事产生注意，符合句意。"}, {"text": "造成", "is_correct": false, "explanation": "搭配：“造成”多接损失、影响、麻烦，不能说“造成注意”。"}, {"text": "收到", "is_correct": false, "explanation": "搭配：“收到”多接信件、礼物，不能与“注意”搭配。"}], "explanations": {"发生": "配价：“发生”是不及物动词，后面不能直接带“注意”作宾语，“发生了大家的注意”说不通。", "引起": "引起：使大家对这件事产生注意，符合句意。", "造成": "搭配：“造成”多接损失、影响、麻烦，不能说“造成注意”。", "收到": "搭配：“收到”多接信件、礼物，不能与“注意”搭配。"}, "sentence_index": 0, "correct_answer": "引起"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这个展览引起了很多游客。", "explanation": "这里应该用〈吸引〉。吸引可以直接带人作宾语，引起的宾语是注意、兴趣、反应等，不能说“引起游客”。"}, {"text": "冬天过去，我们引起了春天。", "explanation": "这里应该用〈迎来〉。引起的宾语是由某事产生的结果或反应，春天是时节，应说“迎来春天”。"}, {"text": "他总爱引起同学，老师很生气。", "explanation": "这里应该用〈招惹〉。引起不能直接以人作宾语，“引起同学”说不通，应说“招惹同学”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd63076ef-1850-48aa-a439-995318801ef7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24212, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "忍住", "is_correct": false, "explanation": "语义：“忍住”的施事须是人，玩笑话不能忍住笑声。"}, {"text": "引起", "is_correct": true, "explanation": "引起：使大家产生笑声，符合句意。"}, {"text": "听见", "is_correct": false, "explanation": "语义：“听见”的主语须是有感官的人，玩笑话不能听见笑声。"}, {"text": "理解", "is_correct": false, "explanation": "搭配：“理解”的对象是意思、内容，不能与“笑声”搭配。"}], "explanations": {"忍住": "语义：“忍住”的施事须是人，玩笑话不能忍住笑声。", "引起": "引起：使大家产生笑声，符合句意。", "听见": "语义：“听见”的主语须是有感官的人，玩笑话不能听见笑声。", "理解": "搭配：“理解”的对象是意思、内容，不能与“笑声”搭配。"}, "sentence_index": 6, "correct_answer": "引起"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他引起了很强的写作能力。", "explanation": "这里应该用〈具备〉。能力是人本身拥有的，引起的宾语应是结果或反应，应说“具备能力”。"}, {"text": "他很快引起了这门技术。", "explanation": "这里应该用〈掌握〉。掌握表示学会知识或技术，引起不能带技术作宾语。"}, {"text": "学校引起了一场运动会。", "explanation": "这里应该用〈举办〉。运动会是活动，应说“举办”，引起的宾语应是由事件产生的反应或结果。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd63076ef-1850-48aa-a439-995318801ef7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24212, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他这次的表现引起的老师的注意。", "corrected_sentence": "他这次的表现引起了老师的注意。", "error_description": "语法错误：“引起的”只是定语，整句缺少谓语；应改为“引起了”作谓语，即“他这次的表现引起了老师的注意”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd63076ef-1850-48aa-a439-995318801ef7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24212, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这次改革引起得社会的广泛关注。", "corrected_sentence": "这次改革引起了社会的广泛关注。", "error_description": "错误在体标：“得”不能接在动词“引起”后，完成体应为“了”，正确为“引起了”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd63076ef-1850-48aa-a439-995318801ef7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
