INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24218, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "空气从上往下流动，像风一样吹下来。", "primary_collocate": null, "pronunciation": "xià xǐ", "ipa": "ɕja˥˩ ɕi˨˩˦", "syllable_count": 2, "sentences": [{"text": "直升机降落时，下洗把草吹得趴在地上。", "target_word": "下洗", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "无人机飞得很低，下洗吹乱了她的头发。", "target_word": "下洗", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "站在直升机下面，能感到很大的下洗。", "target_word": "下洗", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "下洗太大，帐篷差点被吹跑了。", "target_word": "下洗", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "救援直升机的下洗把河面吹出了水纹。", "target_word": "下洗", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子们站得远远的，怕被下洗吹倒。", "target_word": "下洗", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "下洗一来，地上的雪全飞起来了。", "target_word": "下洗", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "飞机刚过去，我们就感到一阵下洗。", "target_word": "下洗", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这架无人机的下洗很小，不会吹走纸。", "target_word": "下洗", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "直升机在屋顶上方，下洗震得窗户响。", "target_word": "下洗", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "专业", "sense_fingerprint": "从上往下吹的气流，像风一样", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '29912ec1-1b02-4999-9515-ab237eadac0e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24218, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "下洗", "is_correct": true, "explanation": "正确。下洗是从上往下吹的气流，能把草吹得趴在地上。"}, {"text": "墨水", "is_correct": false, "explanation": "语义：墨水是液体，不能从上往下吹，无法把草吹倒。"}, {"text": "手机", "is_correct": false, "explanation": "搭配：“吹得趴在地上”需要气流一类的施力者，手机不能产生这种作用。"}, {"text": "沙发", "is_correct": false, "explanation": "语义：沙发是家具，与直升机降落时的气流无关。"}], "explanations": {"下洗": "正确。下洗是从上往下吹的气流，能把草吹得趴在地上。", "墨水": "语义：墨水是液体，不能从上往下吹，无法把草吹倒。", "手机": "搭配：“吹得趴在地上”需要气流一类的施力者，手机不能产生这种作用。", "沙发": "语义：沙发是家具，与直升机降落时的气流无关。"}, "sentence_index": 0, "correct_answer": "下洗"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "热气球靠下洗慢慢升到高空。", "explanation": "这里应该用〈上升气流〉。下洗是向下吹的气流，不能让热气球上升。"}, {"text": "吹风机吹出的下洗暖和了手。", "explanation": "这里应该用〈热风〉。下洗专指空气从上往下流动，吹风机的风是从前方吹出，不能说成下洗。"}, {"text": "山谷里的下洗托着鹰飞翔。", "explanation": "这里应该用〈热气流〉。下洗向下吹，不能托起鹰向上飞翔。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ab0a75be-c87d-4c9e-905b-129f6ad5f2a2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24218, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "下洗", "is_correct": true, "explanation": "正确。下洗是直升机等产生的向下气流，一来就能把地上的雪吹起来。"}, {"text": "考试", "is_correct": false, "explanation": "语义：考试是一种测验，与吹起地上的雪没有关系。"}, {"text": "寒假", "is_correct": false, "explanation": "语义：寒假是假期，不会把地上的雪吹飞。"}, {"text": "饭局", "is_correct": false, "explanation": "搭配：“……一来”后接的应是能引起雪飞起来的力量或天气，饭局不能如此。"}], "explanations": {"下洗": "正确。下洗是直升机等产生的向下气流，一来就能把地上的雪吹起来。", "考试": "语义：考试是一种测验，与吹起地上的雪没有关系。", "寒假": "语义：寒假是假期，不会把地上的雪吹飞。", "饭局": "搭配：“……一来”后接的应是能引起雪飞起来的力量或天气，饭局不能如此。"}, "sentence_index": 6, "correct_answer": "下洗"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "湍急的下洗冲走了河里的石头。", "explanation": "这里应该用〈水流〉。下洗只指空气向下的流动，不用于描述水中的流动。"}, {"text": "下洗从西北卷来，遮天蔽日。", "explanation": "这里应该用〈沙尘暴〉。下洗是飞行器等产生的从上往下吹的局部气流，不能形容从远处卷来、遮天蔽日的大范围风沙。"}, {"text": "下洗把屋顶掀上了天空。", "explanation": "这里应该用〈龙卷风〉。龙卷风是向上卷动的强气流，下洗向下，不能把屋顶掀上天空。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ab0a75be-c87d-4c9e-905b-129f6ad5f2a2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24218, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "直升机降落时，一只下洗把草吹倒了。", "corrected_sentence": "直升机降落时，一阵下洗把草吹倒了。", "error_description": "量词错误：“下洗”是气流，应说“一阵下洗”；“只”不用于气流。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ab0a75be-c87d-4c9e-905b-129f6ad5f2a2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24218, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "直升机在屋顶上方停了一会儿，下洗了震得窗户响。", "corrected_sentence": "直升机在屋顶上方停了一会儿，下洗震得窗户响。", "error_description": "“了”放错位置：不能加在名词“下洗”后面，应直接说“下洗震得窗户响”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ab0a75be-c87d-4c9e-905b-129f6ad5f2a2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24220, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "最小化", "is_correct": true, "explanation": "与“最大化”构成反义：一个指变到最大，一个指变到最小。"}, {"text": "保持", "is_correct": false, "explanation": "无反义关系：“保持”指维持原状，与“让某样东西变得最大”不构成相反。"}, {"text": "研究", "is_correct": false, "explanation": "无反义关系：“研究”指探究事理，与“让某样东西变得最大”无相反关系。"}, {"text": "收集", "is_correct": false, "explanation": "无反义关系：“收集”指聚拢事物，与“让某样东西变得最大”无相反关系。"}], "correct_answer": "最小化", "explanations": {"最小化": "与“最大化”构成反义：一个指变到最大，一个指变到最小。", "保持": "无反义关系：“保持”指维持原状，与“让某样东西变得最大”不构成相反。", "研究": "无反义关系：“研究”指探究事理，与“让某样东西变得最大”无相反关系。", "收集": "无反义关系：“收集”指聚拢事物，与“让某样东西变得最大”无相反关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3995bbd3-30f8-4c0f-9a78-6e3664693c5d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24220, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "最小化", "is_correct": true, "explanation": "与“最大化”构成反义：一个指变到最大，一个指变到最小。"}, {"text": "讨论", "is_correct": false, "explanation": "无反义关系：“讨论”指交换意见，与“让某样东西变得最大”无相反关系。"}, {"text": "喜欢", "is_correct": false, "explanation": "无反义关系：“喜欢”指心理态度，与“让某样东西变得最大”无相反关系。"}, {"text": "整理", "is_correct": false, "explanation": "无反义关系：“整理”指使有秩序，与“让某样东西变得最大”无相反关系。"}], "correct_answer": "最小化", "explanations": {"最小化": "与“最大化”构成反义：一个指变到最大，一个指变到最小。", "讨论": "无反义关系：“讨论”指交换意见，与“让某样东西变得最大”无相反关系。", "喜欢": "无反义关系：“喜欢”指心理态度，与“让某样东西变得最大”无相反关系。", "整理": "无反义关系：“整理”指使有秩序，与“让某样东西变得最大”无相反关系。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3995bbd3-30f8-4c0f-9a78-6e3664693c5d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24220, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "让某样东西变得最大。", "primary_collocate": null, "pronunciation": "zuì dà huà", "ipa": "tsweɪ˥˩ ta˥˩ xwa˥˩", "syllable_count": 3, "sentences": [{"text": "请把这个窗口最大化。", "target_word": "最大化", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "点这个按钮，图片就会最大化。", "target_word": "最大化", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他想把照片最大化，看清楚一点。", "target_word": "最大化", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "为了看清楚表格，他把窗口最大化了。", "target_word": "最大化", "complexity_tier": "T3", "furigana": "wèi le kàn qīng chu biǎo gé, tā bǎ chuāng kǒu zuì dà huà le", "sentence_source": "generated"}, {"text": "我们把房间的空间最大化了。", "target_word": "最大化", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "设计师想把桌子的空间最大化。", "target_word": "最大化", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她把音量最大化，结果太吵了。", "target_word": "最大化", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "先把视频最大化，再看细节。", "target_word": "最大化", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "只要点一下，窗口就能最大化。", "target_word": "最大化", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他把盒子里的空间最大化，放进了更多东西。", "target_word": "最大化", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "最大化了", "label": "体标"}], "register": "书面", "sense_fingerprint": "让某样东西变得最大", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '77085c74-6cb5-4c24-9776-6ad1cbffcff0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24220, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "最大化", "is_correct": true, "explanation": "与“窗口”搭配，指把窗口放到最大（如全屏），符合句意。"}, {"text": "保存", "is_correct": false, "explanation": "搭配：“保存”的对象是文件、数据，不说保存窗口。"}, {"text": "浪费", "is_correct": false, "explanation": "语义：“浪费”指白白耗费，与“请把窗口……”的操作指令不合。"}, {"text": "切开", "is_correct": false, "explanation": "语义：“切开”指用刀等分割，窗口不能被切开，句意不通。"}], "explanations": {"最大化": "与“窗口”搭配，指把窗口放到最大（如全屏），符合句意。", "保存": "搭配：“保存”的对象是文件、数据，不说保存窗口。", "浪费": "语义：“浪费”指白白耗费，与“请把窗口……”的操作指令不合。", "切开": "语义：“切开”指用刀等分割，窗口不能被切开，句意不通。"}, "sentence_index": 0, "correct_answer": "最大化"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他把图片最大化了一点点，看清楚一些。", "explanation": "这里应该用〈放大〉。最大化指放到最大，不表示稍微变大；只想稍微放大图片应说〈放大〉。"}, {"text": "他把手机最大化了。", "explanation": "这里应该用〈关机〉。最大化只用于窗口、画面等可以变大的对象，手机关闭应说〈关机〉。"}, {"text": "他把朋友最大化了。", "explanation": "这里应该用〈结交〉。最大化只用于窗口、画面等可以变大的对象，人与人之间的交往要说结交。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3995bbd3-30f8-4c0f-9a78-6e3664693c5d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24220, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "最大化", "is_correct": true, "explanation": "与“音量”搭配，指把音量调到最大，与“结果太吵了”的语境一致。"}, {"text": "关掉", "is_correct": false, "explanation": "语义：关掉音量后声音消失，不会“太吵”，与后半句矛盾。"}, {"text": "忽略", "is_correct": false, "explanation": "搭配：“忽略”的对象是意见、问题，不说忽略“音量”。"}, {"text": "降低", "is_correct": false, "explanation": "语义：降低音量会让声音变小，与“结果太吵了”矛盾。"}], "explanations": {"最大化": "与“音量”搭配，指把音量调到最大，与“结果太吵了”的语境一致。", "关掉": "语义：关掉音量后声音消失，不会“太吵”，与后半句矛盾。", "忽略": "搭配：“忽略”的对象是意见、问题，不说忽略“音量”。", "降低": "语义：降低音量会让声音变小，与“结果太吵了”矛盾。"}, "sentence_index": 6, "correct_answer": "最大化"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我把饼干最大化成了两半。", "explanation": "这里应该用〈分〉。最大化表示达到最大程度，不表示切开；把饼干分成两半应说〈分〉。"}, {"text": "老师把答案最大化在黑板上。", "explanation": "这里应该用〈写〉。最大化不带表示地点的结果，把答案写在黑板上应说〈写〉。"}, {"text": "他把头发最大化短了。", "explanation": "这里应该用〈剪〉。最大化不表示使物体变短，把头发剪短应说〈剪〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3995bbd3-30f8-4c0f-9a78-6e3664693c5d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24220, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "请把这个程序很最大化，看得更清楚。", "corrected_sentence": "请把这个程序最大化，看得更清楚。", "error_description": "错误：副词“很”不能修饰动词“最大化”，应去掉“很”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3995bbd3-30f8-4c0f-9a78-6e3664693c5d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24220, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这个窗口把最大化了，看得更清楚了。", "corrected_sentence": "这个窗口最大化了，看得更清楚了。", "error_description": "错误：“把”后面要接名词宾语，不能直接接动词“最大化”；这里应去掉“把”，说“这个窗口最大化了”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3995bbd3-30f8-4c0f-9a78-6e3664693c5d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
