INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24228, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "比较、衡量几种选择的利弊得失，考虑哪个更好。", "primary_collocate": null, "pronunciation": "quán héng", "ipa": "tɕʰɥɛn³⁵ xɤŋ³⁵", "syllable_count": 2, "sentences": [{"text": "两个办法都不错，你要权衡一下。", "target_word": "权衡", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我正在权衡去哪所大学。", "target_word": "权衡", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他权衡了半天，还是买了那件红衣服。", "target_word": "权衡", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请你权衡一下，哪个办法更好。", "target_word": "权衡", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈妈在权衡该选哪家饭馆。", "target_word": "权衡", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "选工作以前，要好好权衡。", "target_word": "权衡", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她权衡过两个城市，最后去了成都。", "target_word": "权衡", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我权衡了一下，觉得坐火车更好。", "target_word": "权衡", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "买手机时，他权衡价格和功能。", "target_word": "权衡", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子们权衡着该先写作业还是先玩。", "target_word": "权衡", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "权衡了", "label": "体标"}, {"form": "权衡过", "label": "体标"}, {"form": "权衡着", "label": "体标"}, {"form": "權衡", "label": "繁体"}], "register": "中性", "sense_fingerprint": "比较利弊得失；权衡利弊、权衡一下", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6400fda1-5aa5-4407-a552-0ac0924ed60e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24228, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "权衡", "is_correct": true, "explanation": "正确。“权衡一下”指比较两个办法后再选择，与“都不错”的语境相符。"}, {"text": "放弃", "is_correct": false, "explanation": "语义：“两个办法都不错”时“放弃一下”与比较选择的语境不符，句意不通。"}, {"text": "装饰", "is_correct": false, "explanation": "搭配：“装饰”用于物件或场所，不能用于“办法”。"}, {"text": "复制", "is_correct": false, "explanation": "语义：“复制”与“比较两个办法”的思考无关，不能用于此处。"}], "explanations": {"权衡": "正确。“权衡一下”指比较两个办法后再选择，与“都不错”的语境相符。", "放弃": "语义：“两个办法都不错”时“放弃一下”与比较选择的语境不符，句意不通。", "装饰": "搭配：“装饰”用于物件或场所，不能用于“办法”。", "复制": "语义：“复制”与“比较两个办法”的思考无关，不能用于此处。"}, "sentence_index": 0, "correct_answer": "权衡"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "请你权衡一下黑板。", "explanation": "这里应该用〈擦〉。权衡是比较利弊后做决定，不用于擦黑板这类清洁动作。"}, {"text": "他权衡了一下门铃。", "explanation": "这里应该用〈按〉。权衡是思考比较的活动，不用于按门铃这类动作。"}, {"text": "她权衡了一首歌。", "explanation": "这里应该用〈唱〉。权衡是思考比较的活动，不用于演唱。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ff79a57e-830b-49cb-a3be-ec378a51b0be') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24228, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "权衡", "is_correct": true, "explanation": "正确。“权衡过两个城市”指比较之后再做决定，与“最后去了成都”相符。"}, {"text": "修建", "is_correct": false, "explanation": "搭配：“修建”的宾语是房屋、道路等，不能说“修建两个城市”。"}, {"text": "惩罚", "is_correct": false, "explanation": "搭配：“惩罚”的对象是人或行为，不能说“惩罚两个城市”。"}, {"text": "忘却", "is_correct": false, "explanation": "语义：“忘却”指不再记得，与“最后去了成都”所表达的有意选择相矛盾。"}], "explanations": {"权衡": "正确。“权衡过两个城市”指比较之后再做决定，与“最后去了成都”相符。", "修建": "搭配：“修建”的宾语是房屋、道路等，不能说“修建两个城市”。", "惩罚": "搭配：“惩罚”的对象是人或行为，不能说“惩罚两个城市”。", "忘却": "语义：“忘却”指不再记得，与“最后去了成都”所表达的有意选择相矛盾。"}, "sentence_index": 6, "correct_answer": "权衡"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "工人权衡了窗户。", "explanation": "这里应该用〈修〉。权衡指比较选项的利弊，不用于修理窗户这类物品。"}, {"text": "妈妈权衡了那只碗。", "explanation": "这里应该用〈洗〉。权衡是比较利弊后做决定，不用于清洗餐具。"}, {"text": "奶奶权衡了那块饼干。", "explanation": "这里应该用〈吃〉。权衡是比较利弊的思考活动，不用于吃东西。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ff79a57e-830b-49cb-a3be-ec378a51b0be') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24228, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这两个方案各有利弊，你应该好好权衡着一下。", "corrected_sentence": "这两个方案各有利弊，你应该好好权衡一下。", "error_description": "体标“着”误用。“着”表示动作持续，不能与表示短时尝试的“一下”同用，应为“好好权衡一下”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ff79a57e-830b-49cb-a3be-ec378a51b0be') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24228, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我还没有权衡了这两条路线。", "corrected_sentence": "我还没有权衡这两条路线。", "error_description": "否定句中不能用“了”。“没有”否定已经发生的动作时，句中不能再加“了”，应为“我还没有权衡这两条路线”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ff79a57e-830b-49cb-a3be-ec378a51b0be') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
