INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24230, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "你做事情时能做到的最大程度。", "primary_collocate": null, "pronunciation": "suǒ néng", "ipa": "swo˨˩˦ nəŋ˧˥", "syllable_count": 2, "sentences": [{"text": "我会尽我所能帮助你。", "target_word": "所能", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他已经尽了自己所能。", "target_word": "所能", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们尽我们所能去练习。", "target_word": "所能", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们一定尽我们所能。", "target_word": "所能", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "比赛时，他尽自己所能跑得最快。", "target_word": "所能", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "在这件事上，我已尽我所能。", "target_word": "所能", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他尽其所能攒钱买房子。", "target_word": "所能", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "同学们尽自己所能复习功课。", "target_word": "所能", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她尽己所能照顾老人。", "target_word": "所能", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "医生尽其所能救治病人。", "target_word": "所能", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "做事时自己能达到的最大程度", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f4f8477c-c623-4811-8372-e8a5d9f6c5fc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24230, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "所能", "is_correct": true, "explanation": "正确：“尽我所能”指尽自己能达到的最大程度去帮助。"}, {"text": "手机", "is_correct": false, "explanation": "语义：手机是通讯工具，不指做事能达到的程度。"}, {"text": "椅子", "is_correct": false, "explanation": "语义：椅子是家具，不能说“尽我椅子”。"}, {"text": "天气", "is_correct": false, "explanation": "搭配：“尽我”后不接“天气”，不表示能力程度。"}], "explanations": {"所能": "正确：“尽我所能”指尽自己能达到的最大程度去帮助。", "手机": "语义：手机是通讯工具，不指做事能达到的程度。", "椅子": "语义：椅子是家具，不能说“尽我椅子”。", "天气": "搭配：“尽我”后不接“天气”，不表示能力程度。"}, "sentence_index": 0, "correct_answer": "所能"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他把所能藏进了抽屉。", "explanation": "这里应该用〈钱〉。所能指做事时能达到的最大程度，是抽象的能力，不能藏进抽屉，藏起来的应是“钱”。"}, {"text": "这首歌的所能很美。", "explanation": "这里应该用〈旋律〉。所能只指人做事时能达到的最大程度，不能用来形容歌曲的美。"}, {"text": "会场的所能很热烈。", "explanation": "这里应该用〈气氛〉。所能不能用来描述场面的热烈程度。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '73b6de39-9b1c-4462-afcd-62cb8c028ff7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24230, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "所能", "is_correct": true, "explanation": "正确：尽其所能，即尽力做到能力范围内的最大限度，与“攒钱”相合。"}, {"text": "茶杯", "is_correct": false, "explanation": "语义：茶杯是盛水的器具，不指做事能达到的程度。"}, {"text": "地图", "is_correct": false, "explanation": "语义：地图是标示地理的图纸，与“尽其”的意思不符。"}, {"text": "体温", "is_correct": false, "explanation": "搭配：“尽其”不与“体温”搭配，不能说“尽其体温”。"}], "explanations": {"所能": "正确：尽其所能，即尽力做到能力范围内的最大限度，与“攒钱”相合。", "茶杯": "语义：茶杯是盛水的器具，不指做事能达到的程度。", "地图": "语义：地图是标示地理的图纸，与“尽其”的意思不符。", "体温": "搭配：“尽其”不与“体温”搭配，不能说“尽其体温”。"}, "sentence_index": 6, "correct_answer": "所能"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这道菜的所能很好。", "explanation": "这里应该用〈味道〉。所能指做事能达到的最大程度，不能用来评价菜的味道。"}, {"text": "这杯水的所能很高。", "explanation": "这里应该用〈温度〉。所能不能用来描述温度的高低。"}, {"text": "灯的所能很高。", "explanation": "这里应该用〈亮度〉。所能只指人做事的最大程度，不能描述灯光的亮度。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '73b6de39-9b1c-4462-afcd-62cb8c028ff7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24230, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他自己所能跑得很快。", "corrected_sentence": "他尽自己所能跑得很快。", "error_description": "“所能”前须用“尽”，应说“尽自己所能”；此句只漏掉了“尽”，这是唯一的错误。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '73b6de39-9b1c-4462-afcd-62cb8c028ff7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24230, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我们自己所能去帮助灾区。", "corrected_sentence": "我们尽自己所能去帮助灾区。", "error_description": "“所能”前缺少“尽”，应为“尽自己所能”，构成“尽……所能”；这里漏了“尽”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '73b6de39-9b1c-4462-afcd-62cb8c028ff7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
