INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24234, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "学科是学校里要学的不同知识，比如语文、数学。", "primary_collocate": null, "pronunciation": "xué kē", "ipa": "ɕɥɛ˧˥ kʰɤ˥", "syllable_count": 2, "sentences": [{"text": "语文是我喜欢的学科。", "target_word": "学科", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "你每天学几门学科？", "target_word": "学科", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "小学生要学很多学科。", "target_word": "学科", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "数学是最难的学科。", "target_word": "学科", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "英语是我最好的学科。", "target_word": "学科", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "老师说这个学科很有用。", "target_word": "学科", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "今天有三门学科的考试。", "target_word": "学科", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他的每个学科都学得很好。", "target_word": "学科", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "孩子对这个学科没有兴趣。", "target_word": "学科", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "如果学科太多，学生就会很累。", "target_word": "学科", "complexity_tier": "T4", "sentence_source": "generated"}], "morphological_forms": [{"form": "一门学科", "label": "量词"}, {"form": "基础学科", "label": "复合"}, {"form": "學科", "label": "繁体"}], "register": "中性", "sense_fingerprint": "学校里要学习的不同科目", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '13b5a66e-7b75-47f7-a8ec-a1433fb6fbd0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24234, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "老师", "is_correct": false, "explanation": "语义：“语文”是一门课程，不是人，不能说“语文是老师”。"}, {"text": "同学", "is_correct": false, "explanation": "语义：“同学”指同班的人，与“语文是……”的主语不能等同。"}, {"text": "作业", "is_correct": false, "explanation": "搭配：“语文”是科目，不能等同于“作业”，“我喜欢的作业”与句子主语不搭配。"}, {"text": "学科", "is_correct": true, "explanation": "“学科”指学校里要学的一门知识，“语文是我喜欢的学科”符合句意。"}], "explanations": {"老师": "语义：“语文”是一门课程，不是人，不能说“语文是老师”。", "同学": "语义：“同学”指同班的人，与“语文是……”的主语不能等同。", "作业": "搭配：“语文”是科目，不能等同于“作业”，“我喜欢的作业”与句子主语不搭配。", "学科": "“学科”指学校里要学的一门知识，“语文是我喜欢的学科”符合句意。"}, "sentence_index": 0, "correct_answer": "学科"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这位老先生很有学科。", "explanation": "这里应该用〈学问〉。“学问”指一个人的知识修养，可以说“很有学问”；“学科”是知识的分类，不能用来形容人的修养。"}, {"text": "他带来了三本学科。", "explanation": "这里应该用〈门〉。学科用量词“门”计量；“本”用于书籍，学科不是书，不能用“本”。"}, {"text": "我们今天上了三节学科。", "explanation": "这里应该用〈课〉。“三节”指课时，学科是知识分类，不能按节计数，也不能说“上学科”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '87d323d0-9ac7-4f2a-8051-0f1e63c4561c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24234, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "天气", "is_correct": false, "explanation": "语义：“天气”不能作为考试科目，“三门天气的考试”句意不通。"}, {"text": "颜色", "is_correct": false, "explanation": "语义：“颜色”不能作为考试科目，“三门颜色的考试”句意不通。"}, {"text": "午饭", "is_correct": false, "explanation": "语义：“午饭”不能作为考试科目，“三门午饭的考试”句意不通。"}, {"text": "学科", "is_correct": true, "explanation": "“学科”指学校里的一门知识，“今天有三门学科的考试”符合句意。"}], "explanations": {"天气": "语义：“天气”不能作为考试科目，“三门天气的考试”句意不通。", "颜色": "语义：“颜色”不能作为考试科目，“三门颜色的考试”句意不通。", "午饭": "语义：“午饭”不能作为考试科目，“三门午饭的考试”句意不通。", "学科": "“学科”指学校里的一门知识，“今天有三门学科的考试”符合句意。"}, "sentence_index": 6, "correct_answer": "学科"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我把学科装进了书包。", "explanation": "这里应该用〈教材〉。教材是可以拿在手里的书，学科是抽象的知识分类，不能装进书包。"}, {"text": "他是一位很有名的学科。", "explanation": "这里应该用〈学者〉。“学者”指有学问的人，可以说“很有名的学者”；“学科”指知识分类，不能指人。"}, {"text": "这个学生写了一篇很好的学科。", "explanation": "这里应该用〈论文〉。论文可以写成“一篇”，学科是知识分类，不能被“写”，也不能用“篇”计数。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '87d323d0-9ac7-4f2a-8051-0f1e63c4561c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24234, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "她这学期要学三本学科。", "corrected_sentence": "她这学期要学三门学科。", "error_description": "量词错误：“学科”应使用量词“门”，“本”用于书籍，不能用于学科。正确说法是“三门学科”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '87d323d0-9ac7-4f2a-8051-0f1e63c4561c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24234, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这几门学科们都很难。", "corrected_sentence": "这几门学科都很难。", "error_description": "“们”只用于指人的名词，“学科”后面不能加“们”。正确说法是“这几门学科都很难”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '87d323d0-9ac7-4f2a-8051-0f1e63c4561c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
