INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24236, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "东西有多沉。", "primary_collocate": null, "pronunciation": "zhòng liàng", "ipa": "tʂʊŋ˥˩ ljɑŋ˥˩", "syllable_count": 2, "sentences": [{"text": "买水果的时候，妈妈先看重量。", "target_word": "重量", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个行李箱的重量让我很吃惊。", "target_word": "重量", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他用手掂了掂西瓜的重量。", "target_word": "重量", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这把椅子的重量很轻，小孩也搬得动。", "target_word": "重量", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你知道你的书包有多少重量吗？", "target_word": "重量", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这块布的重量不到一斤。", "target_word": "重量", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我背着重量不小的包走了一路。", "target_word": "重量", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子抱着小狗，感觉到它的重量。", "target_word": "重量", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "路上我觉得手里的重量越来越大。", "target_word": "重量", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这袋米的重量，一个人提不动。", "target_word": "重量", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "重量级", "label": "复合"}, {"form": "总重量", "label": "复合"}], "register": "中性", "sense_fingerprint": "日常义：东西拿在手里或背在身上有多沉", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '37e3a5b6-7c2b-4c3d-9201-526e04e5c049') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24236, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "重量", "is_correct": true, "explanation": "“先看重量”指拿在手里的沉重程度，买水果时看重量很自然。"}, {"text": "年龄", "is_correct": false, "explanation": "语义：水果不论年龄，“先看年龄”不合理。"}, {"text": "辈分", "is_correct": false, "explanation": "语义：辈分指家族中的代次，与水果无关。"}, {"text": "身高", "is_correct": false, "explanation": "搭配：身高用于人或动物，不与水果搭配。"}], "explanations": {"重量": "“先看重量”指拿在手里的沉重程度，买水果时看重量很自然。", "年龄": "语义：水果不论年龄，“先看年龄”不合理。", "辈分": "语义：辈分指家族中的代次，与水果无关。", "身高": "搭配：身高用于人或动物，不与水果搭配。"}, "sentence_index": 0, "correct_answer": "重量"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这块布的重量是两米，够做一件衣服。", "explanation": "这里应该用〈长度〉。“重量”指东西有多沉，不用来说长短；说布有多长要用〈长度〉。"}, {"text": "这把椅子的重量很便宜，小孩也买得起。", "explanation": "这里应该用〈价格〉。“重量”指沉的程度，不说价钱便宜与否。"}, {"text": "这把椅子的重量很漂亮，很多人喜欢。", "explanation": "这里应该用〈外观〉。“重量”指东西的沉重程度，不用来说外形好看与否；说外表漂亮要用〈外观〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b629d11b-5c79-4c2f-9d80-d528401aacc7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24236, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "重量", "is_correct": true, "explanation": "“重量不小”说包的沉，与“背着包走了一路”的语境吻合。"}, {"text": "颜色", "is_correct": false, "explanation": "语义：颜色没有大小之说，“颜色不小”不通。"}, {"text": "时间", "is_correct": false, "explanation": "语义：时间是时长，不能说包的时间不小。"}, {"text": "速度", "is_correct": false, "explanation": "语义：速度指快慢，不能说包的速度不小。"}], "explanations": {"重量": "“重量不小”说包的沉，与“背着包走了一路”的语境吻合。", "颜色": "语义：颜色没有大小之说，“颜色不小”不通。", "时间": "语义：时间是时长，不能说包的时间不小。", "速度": "语义：速度指快慢，不能说包的速度不小。"}, "sentence_index": 6, "correct_answer": "重量"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这块地的重量是五亩。", "explanation": "这里应该用〈面积〉。“重量”用公斤、斤计量，亩是面积单位。"}, {"text": "这辆车的重量很快，一小时能跑一百公里。", "explanation": "这里应该用〈速度〉。“重量”指沉的程度，说跑得快慢要用〈速度〉。"}, {"text": "这场比赛的重量很长，我们等了两个小时。", "explanation": "这里应该用〈时间〉。“重量”不指时长，说持续多久要用〈时间〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b629d11b-5c79-4c2f-9d80-d528401aacc7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24236, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这袋大米的重量是二十个。", "corrected_sentence": "这袋大米的重量是二十斤。", "error_description": "错误：“二十个”，正确：“二十斤”。“个”用于可数事物，重量的单位应为“斤”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b629d11b-5c79-4c2f-9d80-d528401aacc7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24236, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "小狗越长越大，它的重量也越来越长。", "corrected_sentence": "小狗越长越大，它的重量也越来越大。", "error_description": "错误：“重量越来越长”，正确：“重量越来越大”。重量说大小、轻重，不能说长短。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b629d11b-5c79-4c2f-9d80-d528401aacc7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
