INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24238, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "复合材料是用两种或多种不同的东西做成的材料。", "primary_collocate": null, "pronunciation": "fù hé cái liào", "ipa": "fu˥˩ xɤ˧˥ tsʰaɪ˧˥ ljaʊ˥˩", "syllable_count": 4, "sentences": [{"text": "这个球拍是用复合材料做的。", "target_word": "复合材料", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "复合材料是由几种东西做成的。", "target_word": "复合材料", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "新车的外壳用了复合材料，所以很轻。", "target_word": "复合材料", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这种复合材料又轻又结实。", "target_word": "复合材料", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "玻璃钢是一种复合材料。", "target_word": "复合材料", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "钓鱼竿常用复合材料来做。", "target_word": "复合材料", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们把塑料和纤维做成复合材料。", "target_word": "复合材料", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "复合材料不容易坏，可以用很久。", "target_word": "复合材料", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家工厂专门生产复合材料。", "target_word": "复合材料", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "滑雪板的材料是复合材料，不是木头。", "target_word": "复合材料", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "一种复合材料", "label": "量词搭配"}, {"form": "碳纤维复合材料", "label": "复合词"}, {"form": "複合材料", "label": "繁体"}], "register": "中性", "sense_fingerprint": "用两种或多种不同东西做成的材料", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd0a0f57a-406e-4360-81b4-dcb946f1ae89') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24238, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "复合材料", "is_correct": true, "explanation": "复合材料：用两种或多种不同东西做成，符合句中球拍的语境。"}, {"text": "空气", "is_correct": false, "explanation": "语义：空气无法做成球拍，句子说不通。"}, {"text": "水", "is_correct": false, "explanation": "语义：水不能用来做球拍，句意不通。"}, {"text": "面粉", "is_correct": false, "explanation": "搭配：面粉用于做食物，不用于做球拍。"}], "explanations": {"复合材料": "复合材料：用两种或多种不同东西做成，符合句中球拍的语境。", "空气": "语义：空气无法做成球拍，句子说不通。", "水": "语义：水不能用来做球拍，句意不通。", "面粉": "搭配：面粉用于做食物，不用于做球拍。"}, "sentence_index": 0, "correct_answer": "复合材料"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他生病了，在医院打了一针复合材料。", "explanation": "这里应该用〈药〉。复合材料不是药物，不能拿来打针，打针的是药。"}, {"text": "我今天煮了一碗复合材料。", "explanation": "这里应该用〈面条〉。复合材料不能吃，不能当作食物煮来吃。"}, {"text": "我给妈妈打了复合材料。", "explanation": "这里应该用〈电话〉。复合材料不是通讯工具，打电话才用打。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4d1481fe-33c0-4c92-b450-0540642db1fa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24238, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "复合材料", "is_correct": true, "explanation": "复合材料：用塑料和纤维等做成，符合句中的语境。"}, {"text": "面条", "is_correct": false, "explanation": "语义：塑料和纤维不能做成面条，句子说不通。"}, {"text": "面包", "is_correct": false, "explanation": "搭配：面包是食物，不能用塑料和纤维做成。"}, {"text": "冰块", "is_correct": false, "explanation": "语义：塑料和纤维不会凝结成冰块，句意不通。"}], "explanations": {"复合材料": "复合材料：用塑料和纤维等做成，符合句中的语境。", "面条": "语义：塑料和纤维不能做成面条，句子说不通。", "面包": "搭配：面包是食物，不能用塑料和纤维做成。", "冰块": "语义：塑料和纤维不会凝结成冰块，句意不通。"}, "sentence_index": 6, "correct_answer": "复合材料"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我住在复合材料里。", "explanation": "这里应该用〈房子〉。复合材料不是居住的地方，住要在房子里。"}, {"text": "他开着复合材料去上班。", "explanation": "这里应该用〈汽车〉。复合材料不能用来开，开的是汽车。"}, {"text": "他在台上唱复合材料。", "explanation": "这里应该用〈歌〉。复合材料不能唱，唱的是歌。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4d1481fe-33c0-4c92-b450-0540642db1fa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24238, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这把复合材料很轻。", "corrected_sentence": "这块复合材料很轻。", "error_description": "错误形式：「这把复合材料」，量词错误。正确形式：「这块复合材料」。「把」用于有柄、可握持的器具，材料要用「块」等量词。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4d1481fe-33c0-4c92-b450-0540642db1fa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24238, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "工厂用这批复合材料了做三个箱子。", "corrected_sentence": "工厂用这批复合材料做了三个箱子。", "error_description": "错误形式：「复合材料了做」，「了」位置错误。正确形式：「做了三个箱子」。「了」应紧跟主要动词「做」，不能放在介词宾语「复合材料」后面。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4d1481fe-33c0-4c92-b450-0540642db1fa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
