INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24240, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "研究东西怎么做成的学问。", "primary_collocate": null, "pronunciation": "cái liào kē xué", "ipa": "tsʰaɪ˧˥ ljɑʊ˥˩ kʰɤ˥ ɕɥɛ˧˥", "syllable_count": 4, "sentences": [{"text": "他在大学学习材料科学。", "target_word": "材料科学", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "材料科学研究东西是怎么做成的。", "target_word": "材料科学", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我姐姐是材料科学的老师。", "target_word": "材料科学", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "材料科学能帮我们做出更轻的手机。", "target_word": "材料科学", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学材料科学要懂化学和物理。", "target_word": "材料科学", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家公司需要懂材料科学的人。", "target_word": "材料科学", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他对材料科学很有兴趣。", "target_word": "材料科学", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "研究材料科学的人能做出更轻的衣服。", "target_word": "材料科学", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我想考材料科学这个专业。", "target_word": "材料科学", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她毕业后继续研究材料科学。", "target_word": "材料科学", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "材料科学家", "label": "复合"}], "register": "书面", "sense_fingerprint": "研究材料的组成、性能和制造的学科", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '61123057-4989-4a95-82bf-725897152c51') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24240, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "材料科学", "is_correct": true, "explanation": "正确：“材料科学”是学科名，可以作“学习”的宾语，符合句意。"}, {"text": "大海", "is_correct": false, "explanation": "语义：“大海”不是可以学习的学科，句子说不通。"}, {"text": "空气", "is_correct": false, "explanation": "搭配：“学习”后面接学科或技能，不能接“空气”这类自然物。"}, {"text": "星期三", "is_correct": false, "explanation": "语义：“星期三”是时间，不能作为“学习”的内容。"}], "explanations": {"材料科学": "正确：“材料科学”是学科名，可以作“学习”的宾语，符合句意。", "大海": "语义：“大海”不是可以学习的学科，句子说不通。", "空气": "搭配：“学习”后面接学科或技能，不能接“空气”这类自然物。", "星期三": "语义：“星期三”是时间，不能作为“学习”的内容。"}, "sentence_index": 0, "correct_answer": "材料科学"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这座房子用的材料科学很好。", "explanation": "这里应该用〈建材〉。“材料科学”指研究材料的学科，不指盖房子用的物料；盖房子用的物料要说〈建材〉。"}, {"text": "我哥哥是一位有名的材料科学。", "explanation": "这里应该用〈科学家〉。材料科学是学科名，不能指人；说研究者要用〈科学家〉。"}, {"text": "这座材料科学很有名。", "explanation": "这里应该用〈门〉。“座”用于山、桥、楼等大型固定物，学科要用量词〈门〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '82282c0f-c852-4e81-8345-ad24bbafabfb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24240, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "材料科学", "is_correct": true, "explanation": "正确：“对……很有兴趣”后接事物或活动，“材料科学”是学科，符合句意。"}, {"text": "中午", "is_correct": false, "explanation": "语义：“中午”是时间，不能成为“兴趣”的对象。"}, {"text": "星期三", "is_correct": false, "explanation": "语义：“星期三”是时间名词，不能作“兴趣”的对象，句子说不通。"}, {"text": "脚趾", "is_correct": false, "explanation": "搭配：“对……有兴趣”的对象一般是事物或活动，“脚趾”这类身体部位不能作兴趣对象。"}], "explanations": {"材料科学": "正确：“对……很有兴趣”后接事物或活动，“材料科学”是学科，符合句意。", "中午": "语义：“中午”是时间，不能成为“兴趣”的对象。", "星期三": "语义：“星期三”是时间名词，不能作“兴趣”的对象，句子说不通。", "脚趾": "搭配：“对……有兴趣”的对象一般是事物或活动，“脚趾”这类身体部位不能作兴趣对象。"}, "sentence_index": 6, "correct_answer": "材料科学"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "她毕业后成了一名材料科学。", "explanation": "这里应该用〈工程师〉。材料科学是学科名，不能用“一名”来指人；表示职业时应说〈工程师〉。"}, {"text": "他是这个领域的材料科学。", "explanation": "这里应该用〈专家〉。材料科学指学科，不能用来指人；指这个领域的人要说〈专家〉。"}, {"text": "她选修了一把材料科学，很难。", "explanation": "这里应该用〈门〉。“把”用于有柄的东西，学科课程要用量词〈门〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '82282c0f-c852-4e81-8345-ad24bbafabfb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24240, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他在大学学了一本材料科学。", "corrected_sentence": "他在大学学了一门材料科学。", "error_description": "量词错误：学科应该用量词“门”，“本”用于书籍等，不能用来修饰“材料科学”。正确说法是“一门材料科学”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '82282c0f-c852-4e81-8345-ad24bbafabfb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24240, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "她材料科学很感兴趣。", "corrected_sentence": "她对材料科学很感兴趣。", "error_description": "介词错误：“感兴趣”要用“对”引出对象，应说“对材料科学很感兴趣”，不能省略“对”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '82282c0f-c852-4e81-8345-ad24bbafabfb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24242, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "加重", "is_correct": true, "explanation": "“加重”指使重量变大，与“减轻”构成反义关系。"}, {"text": "生长", "is_correct": false, "explanation": "与“减轻”没有反义关系，“生长”的意思是长大。"}, {"text": "建造", "is_correct": false, "explanation": "与“减轻”没有反义关系，“建造”的意思是修建。"}, {"text": "讨论", "is_correct": false, "explanation": "与“减轻”没有反义关系，“讨论”的意思是交流意见。"}], "correct_answer": "加重", "explanations": {"加重": "“加重”指使重量变大，与“减轻”构成反义关系。", "生长": "与“减轻”没有反义关系，“生长”的意思是长大。", "建造": "与“减轻”没有反义关系，“建造”的意思是修建。", "讨论": "与“减轻”没有反义关系，“讨论”的意思是交流意见。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '87d323d0-9ac7-4f2a-8051-0f1e63c4561c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24242, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "加重", "is_correct": true, "explanation": "“加重”指使重量变大，与“减轻”构成反义关系。"}, {"text": "观察", "is_correct": false, "explanation": "与“减轻”没有反义关系，“观察”的意思是仔细看。"}, {"text": "完成", "is_correct": false, "explanation": "与“减轻”没有反义关系，“完成”的意思是做成某件事。"}, {"text": "发展", "is_correct": false, "explanation": "与“减轻”没有反义关系，“发展”的意思是向前变化。"}], "correct_answer": "加重", "explanations": {"加重": "“加重”指使重量变大，与“减轻”构成反义关系。", "观察": "与“减轻”没有反义关系，“观察”的意思是仔细看。", "完成": "与“减轻”没有反义关系，“完成”的意思是做成某件事。", "发展": "与“减轻”没有反义关系，“发展”的意思是向前变化。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '87d323d0-9ac7-4f2a-8051-0f1e63c4561c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24242, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "让东西的重量变轻。", "primary_collocate": null, "pronunciation": "jiǎn qīng", "ipa": "tɕjɛn˨˩ tɕʰiŋ˥˥", "syllable_count": 2, "sentences": [{"text": "他拿出两本书，减轻了背包的重量。", "target_word": "减轻", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "为了跑得快，运动员减轻了鞋子的重量。", "target_word": "减轻", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "新手机比旧手机减轻了五十克。", "target_word": "减轻", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "把箱子里的东西拿出来一些，就能减轻重量。", "target_word": "减轻", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公司用新材料减轻了汽车的重量。", "target_word": "减轻", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "爬山前我们减轻了行李的重量。", "target_word": "减轻", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他每天跑步，想减轻体重。", "target_word": "减轻", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "书包太重了，请把它减轻一点。", "target_word": "减轻", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这辆车减轻了两百公斤，开起来更快。", "target_word": "减轻", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "新桌子用了轻木头，减轻了不少重量，一个人就能搬。", "target_word": "减轻", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "减轻了", "label": "完成体"}, {"form": "减轻过", "label": "经历体"}], "register": "中性", "sense_fingerprint": "使东西的重量变轻", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '13b5a66e-7b75-47f7-a8ec-a1433fb6fbd0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24242, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "增加", "is_correct": false, "explanation": "语义：句中“拿出两本书”会使背包变轻，“增加”使重量变大，与句意矛盾。"}, {"text": "加重", "is_correct": false, "explanation": "语义：“加重”指使分量变大，与“拿出两本书”的动作矛盾。"}, {"text": "扩大", "is_correct": false, "explanation": "搭配：“扩大”用于范围、规模，不修饰重量，“扩大了背包的重量”不通。"}, {"text": "减轻", "is_correct": true, "explanation": "“减轻”指使重量变轻，与“拿出两本书”的动作一致。"}], "explanations": {"增加": "语义：句中“拿出两本书”会使背包变轻，“增加”使重量变大，与句意矛盾。", "加重": "语义：“加重”指使分量变大，与“拿出两本书”的动作矛盾。", "扩大": "搭配：“扩大”用于范围、规模，不修饰重量，“扩大了背包的重量”不通。", "减轻": "“减轻”指使重量变轻，与“拿出两本书”的动作一致。"}, "sentence_index": 0, "correct_answer": "减轻"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "公司的员工减轻了一百人。", "explanation": "这里应该用〈减少〉。减少用于人数、数量；减轻用于重量，不用于人数。"}, {"text": "河水的水位减轻了两米。", "explanation": "这里应该用〈降低〉。水位的下降用“降低”；减轻表示重量变轻，不用于水位。"}, {"text": "这条新路减轻了三公里的路程。", "explanation": "这里应该用〈缩短〉。路程的缩减用“缩短”；减轻表示重量变轻，不用于路程。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '87d323d0-9ac7-4f2a-8051-0f1e63c4561c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24242, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "支撑", "is_correct": false, "explanation": "搭配：“支撑”多指承托，跑步的目的不是承托体重。"}, {"text": "遗忘", "is_correct": false, "explanation": "语义：“遗忘”指忘记，不能与“体重”组成想要达到的目的。"}, {"text": "逃避", "is_correct": false, "explanation": "语义：“逃避”指躲开，与“每天跑步，想……体重”的目的不合。"}, {"text": "减轻", "is_correct": true, "explanation": "“减轻”指使体重变轻，与“每天跑步”的目的一致。"}], "explanations": {"支撑": "搭配：“支撑”多指承托，跑步的目的不是承托体重。", "遗忘": "语义：“遗忘”指忘记，不能与“体重”组成想要达到的目的。", "逃避": "语义：“逃避”指躲开，与“每天跑步，想……体重”的目的不合。", "减轻": "“减轻”指使体重变轻，与“每天跑步”的目的一致。"}, "sentence_index": 6, "correct_answer": "减轻"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这间屋子减轻了一半。", "explanation": "这里应该用〈缩小〉。缩小用于面积、空间；减轻用于重量、负担，不能用于房间。"}, {"text": "药物减轻了病毒的活性。", "explanation": "这里应该用〈削弱〉。削弱用于活性、力量；减轻不用于病毒的活性。"}, {"text": "这个方法减轻了工作效率。", "explanation": "这里应该用〈提高〉。提高用于效率、水平；减轻不能用于效率。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '87d323d0-9ac7-4f2a-8051-0f1e63c4561c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24242, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这个箱子太重了，请把它减轻得一点。", "corrected_sentence": "这个箱子太重了，请把它减轻一点。", "error_description": "多用了“得”：“减轻”后面直接加“一点”表示程度，不加“得”。应说“把它减轻一点”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '87d323d0-9ac7-4f2a-8051-0f1e63c4561c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24242, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这个箱子很减轻了三公斤。", "corrected_sentence": "这个箱子减轻了三公斤。", "error_description": "程度副词误用：“很”是程度副词，不能修饰“减轻了三公斤”这样的动词短语。应去掉“很”，说“这个箱子减轻了三公斤”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '87d323d0-9ac7-4f2a-8051-0f1e63c4561c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
