INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24244, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "让东西变得更好。", "primary_collocate": null, "pronunciation": "yōu huà", "ipa": "iou̯˥ xua˥˩", "syllable_count": 2, "sentences": [{"text": "公司优化了工作流程，效率高多了。", "target_word": "优化", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我们要优化这个网页的速度。", "target_word": "优化", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "工程师正在优化手机的系统。", "target_word": "优化", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他把自己的时间安排优化了一下。", "target_word": "优化", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们优化了软件，运行更快了。", "target_word": "优化", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "医院优化了看病的步骤，病人不用等太久。", "target_word": "优化", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师帮我优化了学习计划。", "target_word": "优化", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "城市想优化交通，让大家出行更方便。", "target_word": "优化", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这家店优化过菜单，生意好了很多。", "target_word": "优化", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们该优化一下网站的设计。", "target_word": "优化", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "优化了", "label": "体标"}, {"form": "优化过", "label": "体标"}], "register": "中性", "sense_fingerprint": "把已有的流程、系统、方案改得更好", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '22aa5821-43c2-4f1a-bd68-eccc7ce09b8e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24244, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "优化", "is_correct": true, "explanation": "正确：优化 yōu huà，指让方案、系统等变得更好。"}, {"text": "油画", "is_correct": false, "explanation": "yóu（第二声）与 yōu（第一声）声调不同，意思是油画，不是“让东西变得更好”。"}, {"text": "有话", "is_correct": false, "explanation": "yǒu（第三声）与 yōu（第一声）声调不同，意思是“有话要说”。"}, {"text": "幽会", "is_correct": false, "explanation": "huì 与 huà 韵母不同，yōu huì 意思是私下约会。"}], "explanations": {"优化": "正确：优化 yōu huà，指让方案、系统等变得更好。", "油画": "yóu（第二声）与 yōu（第一声）声调不同，意思是油画，不是“让东西变得更好”。", "有话": "yǒu（第三声）与 yōu（第一声）声调不同，意思是“有话要说”。", "幽会": "huì 与 huà 韵母不同，yōu huì 意思是私下约会。"}, "sentence_index": null, "correct_answer": "优化"}, "level_3": {"options": [{"text": "保护", "is_correct": false, "explanation": "语义：保护指防护，与“效率高多了”的改进结果相反。"}, {"text": "吃", "is_correct": false, "explanation": "搭配：“吃”的宾语是食物，不能说“吃工作流程”。"}, {"text": "优化", "is_correct": true, "explanation": "正确：优化指让已有的流程变得更好，与“效率高多了”的结果相符。"}, {"text": "偷窃", "is_correct": false, "explanation": "语义：偷窃是非法拿取，与“效率高多了”的积极结果无关。"}], "explanations": {"保护": "语义：保护指防护，与“效率高多了”的改进结果相反。", "吃": "搭配：“吃”的宾语是食物，不能说“吃工作流程”。", "优化": "正确：优化指让已有的流程变得更好，与“效率高多了”的结果相符。", "偷窃": "语义：偷窃是非法拿取，与“效率高多了”的积极结果无关。"}, "sentence_index": 0, "correct_answer": "优化"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这个月我的体重优化了，胖了三公斤。", "explanation": "这里应该用〈增加〉。优化用于让方案、系统变得更好，体重的变化要用“增加”。"}, {"text": "消防员优化了那场大火，很快控制住了局面。", "explanation": "这里应该用〈扑灭〉。优化的对象是方案、系统，大火要用“扑灭”。"}, {"text": "这所学校的学生人数优化了一半。", "explanation": "这里应该用〈减少〉。优化用于让方案变得更好，人数的变化要用“减少”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '70be7a17-cd0a-4913-9080-5d7b3005c701') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24244, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "撕毁", "is_correct": false, "explanation": "语义：撕毁是破坏，与“老师帮我”的帮助义相反。"}, {"text": "唱", "is_correct": false, "explanation": "搭配：“唱”的宾语是歌曲，不说“唱学习计划”。"}, {"text": "优化", "is_correct": true, "explanation": "正确：优化指让计划变得更好，与“老师帮我”的语境相符。"}, {"text": "颁发", "is_correct": false, "explanation": "搭配：“颁发”接证书、奖项，不说“颁发学习计划”。"}], "explanations": {"撕毁": "语义：撕毁是破坏，与“老师帮我”的帮助义相反。", "唱": "搭配：“唱”的宾语是歌曲，不说“唱学习计划”。", "优化": "正确：优化指让计划变得更好，与“老师帮我”的语境相符。", "颁发": "搭配：“颁发”接证书、奖项，不说“颁发学习计划”。"}, "sentence_index": 6, "correct_answer": "优化"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "工人优化了漏水的管道，很快就修好了。", "explanation": "这里应该用〈修理〉。优化是让方案变得更好，修复漏水的管道要用“修理”。"}, {"text": "他优化了那只受伤的狗，很快它就好了。", "explanation": "这里应该用〈治疗〉。优化不用于活体的伤病，治疗受伤的动物要用“治疗”。"}, {"text": "妈妈优化了那件毛衣，衣服很快就干净了。", "explanation": "这里应该用〈清洗〉。“优化”指让方案、系统变得更好，把衣服弄干净要用“清洗”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '70be7a17-cd0a-4913-9080-5d7b3005c701') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24244, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这家公司优化了一本考勤流程，员工很满意。", "corrected_sentence": "这家公司优化了一套考勤流程，员工很满意。", "error_description": "量词错误：“流程”应搭配“套”，“本”用于书籍。正确说法是“优化了一套考勤流程”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '70be7a17-cd0a-4913-9080-5d7b3005c701') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24244, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我们该把网站的设计优化得一下。", "corrected_sentence": "我们该把网站的设计优化一下。", "error_description": "补语标记错误：“优化一下”中“一下”直接接在动词后面，中间不能加“得”。不能说“优化得一下”，正确说法是“优化一下”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '70be7a17-cd0a-4913-9080-5d7b3005c701') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
