INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24248, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1c111ab3-6829-4c95-9540-89a478329293') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24248, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "假装做某件事情来练习或学习。", "primary_collocate": null, "pronunciation": "mó nǐ", "ipa": "mo˧˥ ni˨˩˦", "syllable_count": 2, "sentences": [{"text": "学生们模拟开会的情景。", "target_word": "模拟", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们在课上模拟打电话。", "target_word": "模拟", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "飞行员在机器里模拟飞行。", "target_word": "模拟", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师让我们模拟买东西的对话。", "target_word": "模拟", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们模拟了一次火灾逃生。", "target_word": "模拟", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学生们模拟开商店，练习怎么算账。", "target_word": "模拟", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "为了面试，我先模拟了一遍。", "target_word": "模拟", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子们正在模拟医生看病。", "target_word": "模拟", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "考试前，我们模拟过两次。", "target_word": "模拟", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请大家模拟一下坐飞机的过程。", "target_word": "模拟", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "模拟了", "label": "体标"}, {"form": "模拟过", "label": "体标"}, {"form": "模拟一下", "label": "动量"}, {"form": "模拟考试", "label": "复合"}], "register": "中性", "sense_fingerprint": "仿照真实情景来练习", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cca8c494-ae71-4330-9c72-7312641af8a3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24248, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "模拟", "is_correct": true, "explanation": "正确：模拟指仿照真实情景来练习，与“学生们……开会的情景”相符。"}, {"text": "参加", "is_correct": false, "explanation": "搭配：“参加”的宾语是活动，不说“参加开会的情景”。"}, {"text": "结束", "is_correct": false, "explanation": "语义：“结束”指使某事停止，与“练习”的意思不符。"}, {"text": "打扫", "is_correct": false, "explanation": "搭配：“打扫”的对象是场所或脏物，不说“打扫开会的情景”。"}], "explanations": {"模拟": "正确：模拟指仿照真实情景来练习，与“学生们……开会的情景”相符。", "参加": "搭配：“参加”的宾语是活动，不说“参加开会的情景”。", "结束": "语义：“结束”指使某事停止，与“练习”的意思不符。", "打扫": "搭配：“打扫”的对象是场所或脏物，不说“打扫开会的情景”。"}, "sentence_index": 0, "correct_answer": "模拟"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "工人模拟了房间的装修，还真的刷了墙。", "explanation": "这里应该用〈装修〉。装修是真的布置房屋，模拟指假装做某事来练习，这里说还真的刷了墙，应改用装修。"}, {"text": "爸爸模拟了那把坏掉的椅子，已经修好了。", "explanation": "这里应该用〈修理〉。修理是把坏的东西修好，模拟指假装做某事来练习，椅子真的修好了，不能说模拟。"}, {"text": "妈妈模拟了孩子的作业，然后把作业交给了老师。", "explanation": "这里应该用〈检查〉。检查是查看作业的对错，模拟指假装做某事来练习，作业已经交给老师，不能说模拟。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1c111ab3-6829-4c95-9540-89a478329293') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24248, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "模拟", "is_correct": true, "explanation": "正确：模拟指仿照真实情景来练习，与“为了面试”相符。"}, {"text": "废除", "is_correct": false, "explanation": "语义：“废除”指取消制度或规定，与面试准备的意思不符。"}, {"text": "停止", "is_correct": false, "explanation": "语义：“停止”指中途结束，与“先……一遍”的练习意思相抵。"}, {"text": "忘记", "is_correct": false, "explanation": "搭配：“忘记”的宾语多为事情或内容，不说“忘记了一遍”。"}], "explanations": {"模拟": "正确：模拟指仿照真实情景来练习，与“为了面试”相符。", "废除": "语义：“废除”指取消制度或规定，与面试准备的意思不符。", "停止": "语义：“停止”指中途结束，与“先……一遍”的练习意思相抵。", "忘记": "搭配：“忘记”的宾语多为事情或内容，不说“忘记了一遍”。"}, "sentence_index": 6, "correct_answer": "模拟"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他模拟了昨天的车祸，现在还在医院里躺着。", "explanation": "这里应该用〈经历〉。经历是亲身遇到某事，模拟指假装做某事来练习，这里说人还在医院里，表示真的发生过，应改用经历。"}, {"text": "班长模拟了新同学。", "explanation": "这里应该用〈欢迎〉。欢迎是迎接客人，模拟指仿照真实情景来练习，不能用于迎接人。"}, {"text": "他模拟了一次买票，结果真的买到了票。", "explanation": "这里应该用〈买〉。买是真的付钱得到东西，模拟指假装做某事来练习，这里说真的买到了票，应改用买。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1c111ab3-6829-4c95-9540-89a478329293') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24248, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我们正在模拟了地震的过程。", "corrected_sentence": "我们正在模拟地震的过程。", "error_description": "“正在”表示动作进行，不能与动态助词“了”同用；应说“正在模拟地震的过程”，不说“正在模拟了地震的过程”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1c111ab3-6829-4c95-9540-89a478329293') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24248, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "今天我们在教室里模拟了一次了地震。", "corrected_sentence": "今天我们在教室里模拟了一次地震。", "error_description": "动态助词“了”只用一个，应紧跟动词，说“模拟了一次地震”；“模拟了一次了地震”多用了一个“了”，应删去“一次”后的“了”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1c111ab3-6829-4c95-9540-89a478329293') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
