INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24250, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '81cf0d6c-ad07-44cf-a5e9-ede6f1da6fcb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24250, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "机器工作时的状态和情况。", "primary_collocate": null, "pronunciation": "gōng kuàng", "ipa": "kʊŋ⁵⁵ kʰwɑŋ⁵¹", "syllable_count": 2, "sentences": [{"text": "师傅听声音就知道机器的工况好不好。", "target_word": "工况", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "机器的工况正常，请放心使用。", "target_word": "工况", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这台机器工况不好，需要马上检修。", "target_word": "工况", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "工况变了，机器的速度也跟着变了。", "target_word": "工况", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "夜里工况稳定，机器可以一直开着。", "target_word": "工况", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师傅一看仪表就明白机器的工况。", "target_word": "工况", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "工厂的新机器已经在最难的工况下试过了。", "target_word": "工况", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "屏幕上的数字表示了机器现在的工况。", "target_word": "工况", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他每小时都要检查一次这台机器的工况。", "target_word": "工况", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "冷天里，机器的工况会变差。", "target_word": "工况", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "工況", "label": "繁体"}, {"form": "设计工况", "label": "复合"}, {"form": "额定工况", "label": "复合"}], "register": "专业", "sense_fingerprint": "工况：机器工作时的状态和情况", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd3c95f3d-3cf8-40ea-b1f4-10f0941e860d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24250, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "工况", "is_correct": true, "explanation": "正确：工况指机器工作时的状态，与“听声音就知道”相符。"}, {"text": "心情", "is_correct": false, "explanation": "语义：机器没有心情，不能用“好不好”来形容。"}, {"text": "生日", "is_correct": false, "explanation": "语义：“生日”指出生日期，不能用来判断机器工作时的状态。"}, {"text": "口味", "is_correct": false, "explanation": "搭配：“口味”只用于食物或饮食，不能说机器的口味。"}], "explanations": {"工况": "正确：工况指机器工作时的状态，与“听声音就知道”相符。", "心情": "语义：机器没有心情，不能用“好不好”来形容。", "生日": "语义：“生日”指出生日期，不能用来判断机器工作时的状态。", "口味": "搭配：“口味”只用于食物或饮食，不能说机器的口味。"}, "sentence_index": 0, "correct_answer": "工况"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他的生活工况越来越好了。", "explanation": "这里应该用〈状况〉。“工况”只指机器运行状态，人的生活要用“状况”。"}, {"text": "这家餐厅的菜品工况很好，很多人来吃。", "explanation": "这里应该用〈质量〉。“工况”只用于机器运行状态，菜品好坏要说“质量”。"}, {"text": "他最近的心理工况很稳定。", "explanation": "这里应该用〈状态〉。“工况”只用于机器，人的心理要用“状态”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '81cf0d6c-ad07-44cf-a5e9-ede6f1da6fcb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24250, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "工况", "is_correct": true, "explanation": "正确：工况指设备在工作中的条件，“在最难的工况下试过”合理。"}, {"text": "课程", "is_correct": false, "explanation": "搭配：“最难的……下”指条件或环境，不能说课程，与“试过”不搭配。"}, {"text": "电话", "is_correct": false, "explanation": "语义：电话不是可以用来“试”的条件，“在最难的电话下试过”不通。"}, {"text": "作文", "is_correct": false, "explanation": "语义：作文不能作为机器试验的条件，句子不通。"}], "explanations": {"工况": "正确：工况指设备在工作中的条件，“在最难的工况下试过”合理。", "课程": "搭配：“最难的……下”指条件或环境，不能说课程，与“试过”不搭配。", "电话": "语义：电话不是可以用来“试”的条件，“在最难的电话下试过”不通。", "作文": "语义：作文不能作为机器试验的条件，句子不通。"}, "sentence_index": 6, "correct_answer": "工况"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "明天的天气工况不错，适合出门。", "explanation": "这里应该用〈情况〉。“工况”只指设备运行状态，天气要用“情况”。"}, {"text": "比赛的工况很热烈，观众都在喊。", "explanation": "这里应该用〈气氛〉。“工况”不能用来形容比赛现场的热闹氛围。"}, {"text": "孩子的健康工况不太好，要多休息。", "explanation": "这里应该用〈状况〉。“工况”只用于机器，人的健康要用“状况”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '81cf0d6c-ad07-44cf-a5e9-ede6f1da6fcb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24250, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "机器在一只低温工况下停了。", "corrected_sentence": "机器在一种低温工况下停了。", "error_description": "错误：“一只”。正确：“一种”。“工况”是抽象名词，“只”用于有个体的具体事物，应用量词“种”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '81cf0d6c-ad07-44cf-a5e9-ede6f1da6fcb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24250, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "冬天到了，机器的工况变了差。", "corrected_sentence": "冬天到了，机器的工况变差了。", "error_description": "错误：“变了差”，“了”放在结果补语“差”之前。正确：“变差了”。补语“差”应紧跟“变”，“了”放在句末。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '81cf0d6c-ad07-44cf-a5e9-ede6f1da6fcb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
