INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24252, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "一次又一次地换新的。", "primary_collocate": null, "pronunciation": "dié dài", "ipa": "tjɛ˧˥ taɪ˥˩", "syllable_count": 2, "sentences": [{"text": "手机每年都迭代，功能越来越多。", "target_word": "迭代", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个软件迭代得很快。", "target_word": "迭代", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公司打算每个月迭代一次产品。", "target_word": "迭代", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "新技术让产品迭代得越来越快。", "target_word": "迭代", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们的游戏已经迭代了五个版本。", "target_word": "迭代", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这款汽车迭代后，更省油了。", "target_word": "迭代", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "好的产品要不断迭代。", "target_word": "迭代", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们的网站上个月刚迭代过。", "target_word": "迭代", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "电脑迭代太快，我不想总换新的。", "target_word": "迭代", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "工程师正在迭代这个小程序。", "target_word": "迭代", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "迭代了", "label": "完成体"}, {"form": "迭代过", "label": "经历体"}, {"form": "版本迭代", "label": "复合词"}], "register": "中性", "sense_fingerprint": "一次又一次地更新换代", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd0a0f57a-406e-4360-81b4-dcb946f1ae89') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24252, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "迭代", "is_correct": true, "explanation": "正确：“迭代”指产品反复换新，与“每年都”和“功能越来越多”相合。"}, {"text": "停止", "is_correct": false, "explanation": "语义：“停止”与“功能越来越多”的变化相反，句意矛盾。"}, {"text": "冻结", "is_correct": false, "explanation": "语义：“冻结”会使功能停滞，与“功能越来越多”矛盾。"}, {"text": "沉睡", "is_correct": false, "explanation": "语义：“沉睡”指长时间处于静止不动的状态，与“功能越来越多”的变化相反，句意矛盾。"}], "explanations": {"迭代": "正确：“迭代”指产品反复换新，与“每年都”和“功能越来越多”相合。", "停止": "语义：“停止”与“功能越来越多”的变化相反，句意矛盾。", "冻结": "语义：“冻结”会使功能停滞，与“功能越来越多”矛盾。", "沉睡": "语义：“沉睡”指长时间处于静止不动的状态，与“功能越来越多”的变化相反，句意矛盾。"}, "sentence_index": 0, "correct_answer": "迭代"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我每年都迭代一部新手机。", "explanation": "这里应该用〈更换〉。迭代指产品、技术反复换新，由开发者进行；个人用户只能说“更换”手机。"}, {"text": "他每年都迭代一次身高。", "explanation": "迭代只用于产品、技术的版本更新，不能描述人身高的变化。"}, {"text": "学生每天迭代背单词。", "explanation": "这里应该用〈重复〉。迭代强调反复换新，不是单纯的重复动作，背单词只能说“重复”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4d1481fe-33c0-4c92-b450-0540642db1fa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24252, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "迭代", "is_correct": true, "explanation": "正确：“迭代”指产品不断换新，与“好的产品要不断”的语境相合。"}, {"text": "停滞", "is_correct": false, "explanation": "语义：“停滞”与“不断”相悖，好产品不应要求不断停滞。"}, {"text": "发福", "is_correct": false, "explanation": "体貌：“发福”只用于人的体形变化，不能用于描述产品。"}, {"text": "吵闹", "is_correct": false, "explanation": "语义：“吵闹”指发出噪声，与产品的更新改进无关，句意不通。"}], "explanations": {"迭代": "正确：“迭代”指产品不断换新，与“好的产品要不断”的语境相合。", "停滞": "语义：“停滞”与“不断”相悖，好产品不应要求不断停滞。", "发福": "体貌：“发福”只用于人的体形变化，不能用于描述产品。", "吵闹": "语义：“吵闹”指发出噪声，与产品的更新改进无关，句意不通。"}, "sentence_index": 6, "correct_answer": "迭代"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "工程师正在迭代这顿晚饭。", "explanation": "迭代用于产品或技术的更新，不能用于一顿饭。"}, {"text": "季节正在迭代。", "explanation": "这里应该用〈变化〉。迭代只用于产品、技术的换新，不用于季节的更替。"}, {"text": "他每天迭代钢琴。", "explanation": "这里应该用〈练习〉。迭代指产品的反复更新，不能用于演奏乐器。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4d1481fe-33c0-4c92-b450-0540642db1fa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24252, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这个游戏每年都迭代两个次。", "corrected_sentence": "这个游戏每年都迭代两次。", "error_description": "错误形式：「迭代两个次」，量词错误。正确形式：「迭代两次」。表示动作次数时，动量词「次」前直接接数词，不加「个」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4d1481fe-33c0-4c92-b450-0540642db1fa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24252, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "工程师正在迭代了这个应用。", "corrected_sentence": "工程师正在迭代这个应用。", "error_description": "“正在”表示动作进行中，不能与表示完成的“了”同用，应删去“了”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4d1481fe-33c0-4c92-b450-0540642db1fa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
