INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24256, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "控制技术就是教机器或东西怎么动、怎么工作的办法。", "primary_collocate": null, "pronunciation": "kòng zhì jì shù", "ipa": "kʰʊŋ˥˩ ʈʂʐ̩˥˩ tɕi˥˩ ʂu˥˩", "syllable_count": 4, "sentences": [{"text": "玩具机器人用简单的控制技术走路。", "target_word": "控制技术", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学生们在课上学习机器的控制技术。", "target_word": "控制技术", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这辆小车靠控制技术自己转弯。", "target_word": "控制技术", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师给我们讲了机器手臂的控制技术。", "target_word": "控制技术", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "有了控制技术，机器才知道怎么动。", "target_word": "控制技术", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他想学控制技术，做一个会跳舞的机器人。", "target_word": "控制技术", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "洗衣机里也有控制技术。", "target_word": "控制技术", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这种控制技术很简单，孩子也学得会。", "target_word": "控制技术", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "控制技术告诉机器什么时候该停。", "target_word": "控制技术", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公司请他教大家机器的控制技术。", "target_word": "控制技术", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "书面", "sense_fingerprint": "教机器怎么动、怎么工作的办法", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '13b5a66e-7b75-47f7-a8ec-a1433fb6fbd0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24256, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "颜色", "is_correct": false, "explanation": "语义：颜色不能用来让机器人走路，句意不通。"}, {"text": "价格", "is_correct": false, "explanation": "搭配：“用……走路”后面要接让机器运动的方法，“价格”不能充当。"}, {"text": "控制技术", "is_correct": true, "explanation": "正确：控制技术教机器怎么动，“用简单的控制技术走路”指用简单的办法让机器人动起来，与句意一致。"}, {"text": "钢琴", "is_correct": false, "explanation": "语义：钢琴不是让机器人走路的方法，句意不通。"}], "explanations": {"颜色": "语义：颜色不能用来让机器人走路，句意不通。", "价格": "搭配：“用……走路”后面要接让机器运动的方法，“价格”不能充当。", "控制技术": "正确：控制技术教机器怎么动，“用简单的控制技术走路”指用简单的办法让机器人动起来，与句意一致。", "钢琴": "语义：钢琴不是让机器人走路的方法，句意不通。"}, "sentence_index": 0, "correct_answer": "控制技术"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这座房子用的控制技术很结实。", "explanation": "这里应该用〈材料〉。房子结不结实由建材决定，应说材料；控制技术是一种方法，不能形容结实。"}, {"text": "小狗吃了一口控制技术。", "explanation": "这里应该用〈食物〉。小狗吃的是食物；控制技术是抽象的方法，不能被吃。"}, {"text": "这台机器人的控制技术是蓝色的。", "explanation": "这里应该用〈外观〉。颜色属于外观；控制技术是抽象的方法，没有颜色，不能说“是蓝色的”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '87d323d0-9ac7-4f2a-8051-0f1e63c4561c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24256, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "午饭", "is_correct": false, "explanation": "语义：午饭不是洗衣机的组成部分，洗衣机里不会有午饭。"}, {"text": "作者", "is_correct": false, "explanation": "语义：作者是写作的人，洗衣机里不会有作者。"}, {"text": "诗歌", "is_correct": false, "explanation": "语义：洗衣机里不会有“诗歌”，句意不通。"}, {"text": "控制技术", "is_correct": true, "explanation": "正确：洗衣机里的控制技术指教它怎么工作的办法，与句子的语境一致。"}], "explanations": {"午饭": "语义：午饭不是洗衣机的组成部分，洗衣机里不会有午饭。", "作者": "语义：作者是写作的人，洗衣机里不会有作者。", "诗歌": "语义：洗衣机里不会有“诗歌”，句意不通。", "控制技术": "正确：洗衣机里的控制技术指教它怎么工作的办法，与句子的语境一致。"}, "sentence_index": 6, "correct_answer": "控制技术"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我们去控制技术里看了一场电影。", "explanation": "这里应该用〈电影院〉。看电影要去电影院这样的场所；控制技术是一种办法，不是场所，不能说“去……里”。"}, {"text": "我的哥哥是很好的控制技术。", "explanation": "控制技术是一门技术，不能指人。做这项工作的人应说〈控制工程师〉。"}, {"text": "妈妈用控制技术做了一碗面条。", "explanation": "这里应该用〈厨艺〉。做面条靠厨艺；控制技术指使机器或系统按目标运行的技术，不能用来做面条。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '87d323d0-9ac7-4f2a-8051-0f1e63c4561c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24256, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这个玩具车靠一条简单的控制技术向前开。", "corrected_sentence": "这个玩具车靠一项简单的控制技术向前开。", "error_description": "量词错误：错误形式为“一条”，正确形式为“一项”。“条”用于细长的东西，不能修饰控制技术；技术通常用量词“项”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '87d323d0-9ac7-4f2a-8051-0f1e63c4561c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24256, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这台玩具车的控制技术很简单地。", "corrected_sentence": "这台玩具车的控制技术很简单。", "error_description": "副词错误：错误形式在“很简单”后加了“地”，正确形式为“很简单”。“很”后面的形容词作谓语时不加“地”，“简单地”只用于修饰动词。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '87d323d0-9ac7-4f2a-8051-0f1e63c4561c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24258, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "呼出", "is_correct": true, "explanation": "“呼出”指把气体从体内排出，与“吸入”把气体吸进体内正相反。"}, {"text": "翻译", "is_correct": false, "explanation": "“翻译”指把一种语言转换成另一种语言，与“吸入”没有反义关系。"}, {"text": "砍伐", "is_correct": false, "explanation": "“砍伐”指砍倒树木，与“吸入”没有反义关系。"}, {"text": "浇灌", "is_correct": false, "explanation": "“浇灌”指把水浇到植物上，与“吸入”没有反义关系。"}], "correct_answer": "呼出", "explanations": {"呼出": "“呼出”指把气体从体内排出，与“吸入”把气体吸进体内正相反。", "翻译": "“翻译”指把一种语言转换成另一种语言，与“吸入”没有反义关系。", "砍伐": "“砍伐”指砍倒树木，与“吸入”没有反义关系。", "浇灌": "“浇灌”指把水浇到植物上，与“吸入”没有反义关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '36751d0d-d99d-4665-83b3-5ea04844abff') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24258, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "呼出", "is_correct": true, "explanation": "“呼出”指把气体从体内排出，与“吸入”把气体吸进体内正相反。"}, {"text": "缝补", "is_correct": false, "explanation": "“缝补”指用针线修补破损的衣物，与“吸入”没有反义关系。"}, {"text": "挖掘", "is_correct": false, "explanation": "“挖掘”指向下掘取泥土或矿物，与“吸入”没有反义关系。"}, {"text": "烘烤", "is_correct": false, "explanation": "“烘烤”指用热力使食物变熟或变干，与“吸入”没有反义关系。"}], "correct_answer": "呼出", "explanations": {"呼出": "“呼出”指把气体从体内排出，与“吸入”把气体吸进体内正相反。", "缝补": "“缝补”指用针线修补破损的衣物，与“吸入”没有反义关系。", "挖掘": "“挖掘”指向下掘取泥土或矿物，与“吸入”没有反义关系。", "烘烤": "“烘烤”指用热力使食物变熟或变干，与“吸入”没有反义关系。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '36751d0d-d99d-4665-83b3-5ea04844abff') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24258, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "把空气吸到身体里。", "primary_collocate": null, "pronunciation": "xī rù", "ipa": "ɕi˥ ʐu˥˩", "syllable_count": 2, "sentences": [{"text": "深深吸入一口气，然后慢慢吐出来。", "target_word": "吸入", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "医生让他用鼻子慢慢吸入空气。", "target_word": "吸入", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他吸入新鲜空气，觉得很舒服。", "target_word": "吸入", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "跑完步，我大口吸入空气。", "target_word": "吸入", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "游泳前，先吸入一口气。", "target_word": "吸入", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "山上的空气很干净，吸入后很舒服。", "target_word": "吸入", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她闭上眼睛，慢慢吸入空气。", "target_word": "吸入", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "吸入空气时，肚子会慢慢变大。", "target_word": "吸入", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师让我们先吸入一口气，再慢慢呼出。", "target_word": "吸入", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他吸入了一口冷空气，咳了起来。", "target_word": "吸入", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "吸入了", "label": "体标"}, {"form": "吸入过", "label": "体标"}], "register": "通用", "sense_fingerprint": "吸气，把空气吸进身体", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e7250d00-77e8-4de8-a520-b9d293cc7300') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24258, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "吸入", "is_correct": true, "explanation": "“吸入”指把空气吸进身体，“深深吸入一口气”正是吸气的动作。"}, {"text": "吃", "is_correct": false, "explanation": "语义：“吃一口气”说不通，“吃”不能用于空气。"}, {"text": "写", "is_correct": false, "explanation": "语义：“写一口气”说不通，“写”不能用于气息。"}, {"text": "唱", "is_correct": false, "explanation": "搭配：“唱”不能与“一口气”搭配作宾语。"}], "explanations": {"吸入": "“吸入”指把空气吸进身体，“深深吸入一口气”正是吸气的动作。", "吃": "语义：“吃一口气”说不通，“吃”不能用于空气。", "写": "语义：“写一口气”说不通，“写”不能用于气息。", "唱": "搭配：“唱”不能与“一口气”搭配作宾语。"}, "sentence_index": 0, "correct_answer": "吸入"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "渴了就大口吸入水。", "explanation": "这里应该用〈喝〉。喝指把液体送入口中咽下，吸入指经呼吸把气体吸进体内，不能用于水。"}, {"text": "她吸入了一口苹果，很甜。", "explanation": "这里应该用〈咬〉。咬指用牙齿切开或嚼碎食物，吸入只用于气体、烟雾等。"}, {"text": "她吸入一朵花。", "explanation": "这里应该用〈摘〉。摘指把花从植物上取下，吸入指经呼吸把气体吸进体内，不能用于花朵。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '36751d0d-d99d-4665-83b3-5ea04844abff') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24258, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "吸入", "is_correct": true, "explanation": "“吸入”指把空气吸进身体，“她闭上眼睛，慢慢吸入空气”描写的是吸气动作。"}, {"text": "切", "is_correct": false, "explanation": "语义：空气不能被“切”，句子说不通。"}, {"text": "擦", "is_correct": false, "explanation": "搭配：“擦”的对象是有形的表面，不能与“空气”搭配。"}, {"text": "修", "is_correct": false, "explanation": "语义：空气不能被“修”，句子说不通。"}], "explanations": {"吸入": "“吸入”指把空气吸进身体，“她闭上眼睛，慢慢吸入空气”描写的是吸气动作。", "切": "语义：空气不能被“切”，句子说不通。", "擦": "搭配：“擦”的对象是有形的表面，不能与“空气”搭配。", "修": "语义：空气不能被“修”，句子说不通。"}, "sentence_index": 6, "correct_answer": "吸入"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他吸入一颗糖，很甜。", "explanation": "这里应该用〈吞下〉。吞下指把东西咽进肚里，吸入只用于气体、烟雾等。"}, {"text": "他把钥匙吸入口袋里。", "explanation": "这里应该用〈放〉。放指把东西放到某处，吸入指经呼吸把气体吸进身体，不能用来把钥匙放进口袋。"}, {"text": "她吸入了我的肩膀。", "explanation": "这里应该用〈拍〉。拍指用手轻击，吸入指把气体吸进体内，不能用于身体部位。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '36751d0d-d99d-4665-83b3-5ea04844abff') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24258, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "她明天出门前，要先吸入了一口冷空气。", "corrected_sentence": "她明天出门前，要先吸入一口冷空气。", "error_description": "“了”误用：“明天”的动作还没有发生，“要”后面的“吸入”不能加“了”，应说“要先吸入一口冷空气”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '36751d0d-d99d-4665-83b3-5ea04844abff') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24258, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我从来没吸入了这么多油烟。", "corrected_sentence": "我从来没吸入过这么多油烟。", "error_description": "“了”误用：“从来没有”后表示经历要用“过”，应说“从来没吸入过”，不能用“了”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '36751d0d-d99d-4665-83b3-5ea04844abff') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
