INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24260, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "property", "definition": "机器做事情的本领。", "primary_collocate": null, "pronunciation": "xìng néng", "ipa": "ɕiŋ⁵¹ nɤŋ³⁵", "syllable_count": 2, "sentences": [{"text": "这台电脑的性能很好。", "target_word": "性能", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "买手机时，我先看性能。", "target_word": "性能", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这辆新车的性能比旧车好。", "target_word": "性能", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这种机器性能稳定，很多工厂都用。", "target_word": "性能", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "玩这个游戏需要性能强的电脑。", "target_word": "性能", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个手机价格不高，性能也不错。", "target_word": "性能", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "新手机的性能提高了不少。", "target_word": "性能", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师问我们怎么测试机器的性能。", "target_word": "性能", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这台冰箱性能很好，一个月只用很少的电。", "target_word": "性能", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他很了解这辆车的性能。", "target_word": "性能", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "性能：名词，机器、设备工作时表现出的能力", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '48420b25-8f0d-4c8e-9a02-21c20436390e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24260, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "性能", "is_correct": true, "explanation": "“性能”指机器的工作能力，符合“这台电脑的___很好”的句意。"}, {"text": "性格", "is_correct": false, "explanation": "语义：“性格”只用于人，不能用来说电脑的性格。"}, {"text": "脾气", "is_correct": false, "explanation": "语义：“脾气”只用于人或动物，不能说电脑的脾气。"}, {"text": "口味", "is_correct": false, "explanation": "搭配：“口味”用于食物、饮料，不能与“电脑”搭配。"}], "explanations": {"性能": "“性能”指机器的工作能力，符合“这台电脑的___很好”的句意。", "性格": "语义：“性格”只用于人，不能用来说电脑的性格。", "脾气": "语义：“脾气”只用于人或动物，不能说电脑的脾气。", "口味": "搭配：“口味”用于食物、饮料，不能与“电脑”搭配。"}, "sentence_index": 0, "correct_answer": "性能"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这个按钮的性能是打开灯。", "explanation": "这里应该用〈功能〉。性能指机器的工作能力，按钮做什么要用功能。"}, {"text": "他的性能很强，工作很快。", "explanation": "这里应该用〈能力〉。性能只用于机器、设备，人的本领要用能力。"}, {"text": "这碗汤的性能很好，味道很鲜。", "explanation": "这里应该用〈质量〉。性能指机器的工作能力，食物的好坏要用质量。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '47265947-1e40-4671-85c6-c3d8184e273d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24260, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "性能", "is_correct": true, "explanation": "“性能”指手机的工作能力，符合“新手机的___提高了不少”的句意。"}, {"text": "颜色", "is_correct": false, "explanation": "搭配：“提高”不能用于颜色，不说颜色提高。"}, {"text": "味道", "is_correct": false, "explanation": "搭配：“提高”不能用于味道，不说味道提高。"}, {"text": "年龄", "is_correct": false, "explanation": "语义：年龄是时间的积累，不能被“提高”。"}], "explanations": {"性能": "“性能”指手机的工作能力，符合“新手机的___提高了不少”的句意。", "颜色": "搭配：“提高”不能用于颜色，不说颜色提高。", "味道": "搭配：“提高”不能用于味道，不说味道提高。", "年龄": "语义：年龄是时间的积累，不能被“提高”。"}, "sentence_index": 6, "correct_answer": "性能"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这次手术的性能很好。", "explanation": "这里应该用〈效果〉。性能指机器、设备的工作能力，手术的成效要用效果。"}, {"text": "这家餐厅的性能是菜做得快。", "explanation": "这里应该用〈特点〉。性能只指机器、设备的能力，餐厅的特色要用特点。"}, {"text": "这座城市的性能很好，人口很多。", "explanation": "这里应该用〈状况〉。性能指机器、设备的工作能力，城市的情况要用状况。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '47265947-1e40-4671-85c6-c3d8184e273d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24260, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这台洗衣机的性能很多。", "corrected_sentence": "这台洗衣机的性能很好。", "error_description": "搭配错误：“性能”说的是好不好、强不强，不能用“多”来说，应改为“性能很好”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '47265947-1e40-4671-85c6-c3d8184e273d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24260, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这辆车的性能好很。", "corrected_sentence": "这辆车的性能很好。", "error_description": "程度副词位置错误：“很”应放在形容词“好”之前，“好很”是错误语序。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '47265947-1e40-4671-85c6-c3d8184e273d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
