INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24262, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "像水一样快速喷出的一股东西。", "primary_collocate": null, "pronunciation": "shè liú", "ipa": "ʂɤ⁵¹ ljoʊ³⁵", "syllable_count": 2, "sentences": [{"text": "鲸鱼的头上喷出一股白色的射流。", "target_word": "射流", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "喷泉中间的射流有三米高。", "target_word": "射流", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "管子破了，一道射流喷到了墙上。", "target_word": "射流", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "冰冷的射流吓了小孩一跳。", "target_word": "射流", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "消防员用强大的射流灭了大火。", "target_word": "射流", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "咖啡机喷出的射流很热，请小心。", "target_word": "射流", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "洗车时，射流把车上的泥冲干净了。", "target_word": "射流", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "水球破了，一股射流打湿了他的衣服。", "target_word": "射流", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那条射流又细又直，像一根白线。", "target_word": "射流", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师说，射流是快速喷出的一股水或气。", "target_word": "射流", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "水射流", "label": "复合"}, {"form": "射流泵", "label": "复合"}], "register": "中性", "sense_fingerprint": "射流：像水一样快速喷出的一股东西", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd3c95f3d-3cf8-40ea-b1f4-10f0941e860d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24262, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "射流", "is_correct": true, "explanation": "“射流”指像水一样快速喷出的一股东西，鲸鱼头上喷出的白色水柱正合此意。"}, {"text": "火焰", "is_correct": false, "explanation": "语义：鲸鱼头上不会喷出火焰，与句中的喷出情境不符。"}, {"text": "布条", "is_correct": false, "explanation": "搭配：“一股”不用于布条，布条也不会从头上喷出。"}, {"text": "面条", "is_correct": false, "explanation": "语义：面条不会从鲸鱼头上喷出，句子不符合常理。"}], "explanations": {"射流": "“射流”指像水一样快速喷出的一股东西，鲸鱼头上喷出的白色水柱正合此意。", "火焰": "语义：鲸鱼头上不会喷出火焰，与句中的喷出情境不符。", "布条": "搭配：“一股”不用于布条，布条也不会从头上喷出。", "面条": "语义：面条不会从鲸鱼头上喷出，句子不符合常理。"}, "sentence_index": 0, "correct_answer": "射流"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "屋檐上的射流慢慢地落下来。", "explanation": "这里应该用〈水滴〉。射流是快速喷出的一股东西，屋檐上慢慢滴落的水要用〈水滴〉。"}, {"text": "山上的射流慢慢地流下来，清凉可口。", "explanation": "这里应该用〈泉水〉。射流是快速喷出的，慢慢流下的清水要用〈泉水〉。"}, {"text": "杯子里的射流一动不动，很平静。", "explanation": "这里应该用〈水〉。射流是快速喷出的一股东西，杯子里一动不动的是水。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '81cf0d6c-ad07-44cf-a5e9-ede6f1da6fcb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24262, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "射流", "is_correct": true, "explanation": "“射流”是快速喷出的水或气，用来冲洗车身上的泥，符合洗车语境。"}, {"text": "锯子", "is_correct": false, "explanation": "语义：锯子用于切割，不能把泥冲干净，与“洗车”语境不符。"}, {"text": "毛巾", "is_correct": false, "explanation": "搭配：“冲”一般用于水或水流，毛巾多用于擦拭，不说毛巾把泥冲干净。"}, {"text": "颜料", "is_correct": false, "explanation": "语义：颜料是用来涂色的，不能把车上的泥冲掉。"}], "explanations": {"射流": "“射流”是快速喷出的水或气，用来冲洗车身上的泥，符合洗车语境。", "锯子": "语义：锯子用于切割，不能把泥冲干净，与“洗车”语境不符。", "毛巾": "搭配：“冲”一般用于水或水流，毛巾多用于擦拭，不说毛巾把泥冲干净。", "颜料": "语义：颜料是用来涂色的，不能把车上的泥冲掉。"}, "sentence_index": 6, "correct_answer": "射流"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "山谷里的射流又宽又平，像一面镜子。", "explanation": "这里应该用〈湖水〉。射流细而急，从窄口高速喷出，不能形容又宽又平、像镜子一样的水面。"}, {"text": "射流慢慢地流过草地，叮咚作响。", "explanation": "这里应该用〈溪水〉。射流是快速喷出的流，不会慢慢流过草地；缓缓流淌、叮咚作响的水要用〈溪水〉。"}, {"text": "他脸上的射流一颗颗滚落下来。", "explanation": "这里应该用〈泪水〉。射流是快速喷出的一股东西，一颗颗滚落的是泪水。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '81cf0d6c-ad07-44cf-a5e9-ede6f1da6fcb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24262, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "一座有力的射流从水管里喷了出来。", "corrected_sentence": "一股有力的射流从水管里喷了出来。", "error_description": "量词错误：“座”用于山、桥、建筑等大型固定的东西，射流是喷出的流体，要用“股”或“道”。错误形式是“一座有力的射流”，正确形式是“一股有力的射流”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '81cf0d6c-ad07-44cf-a5e9-ede6f1da6fcb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24262, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "消防员拿着水管，一块射流喷了出来。", "corrected_sentence": "消防员拿着水管，一道射流喷了出来。", "error_description": "“一块射流”错，应为“一道射流”。“块”用于成块的固体，射流是喷出的流体，要用“道”“股”等量词。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '81cf0d6c-ad07-44cf-a5e9-ede6f1da6fcb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
