INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24268, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "把不同东西加在一起，变成新东西。", "primary_collocate": null, "pronunciation": "hé chéng", "ipa": "xɤ˧˥ ʈʂʰɤŋ˧˥", "syllable_count": 2, "sentences": [{"text": "这张照片是用两张图合成的。", "target_word": "合成", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "实验室里能用石油合成塑料。", "target_word": "合成", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "工厂用这些原料合成新材料。", "target_word": "合成", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他把三段录音合成了一个文件。", "target_word": "合成", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "科学家想合成一种新药。", "target_word": "合成", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "植物能用阳光合成养分。", "target_word": "合成", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "她把几张图片合成一张海报。", "target_word": "合成", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这段视频是把几个镜头合成的。", "target_word": "合成", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师教我们用软件合成声音。", "target_word": "合成", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "化学家把两种药合成了一种新药。", "target_word": "合成", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "合成了", "label": "体标"}, {"form": "合成过", "label": "体标"}, {"form": "合成物", "label": "复合"}], "register": "中性", "sense_fingerprint": "把几种东西结合成一个新的整体或新物质", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '22aa5821-43c2-4f1a-bd68-eccc7ce09b8e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24268, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "拍摄", "is_correct": false, "explanation": "语义：拍摄指用相机记录影像，照片不是靠拍摄由两张图得到的，句子不通。"}, {"text": "拆分", "is_correct": false, "explanation": "语义：拆分是分开，与“合”的结合义相反，句子说不通。"}, {"text": "合成", "is_correct": true, "explanation": "正确：合成指把几部分结合成一个整体，与“用两张图”的语境相符。"}, {"text": "调配", "is_correct": false, "explanation": "搭配：调配多用于颜料、饮品，不说“用两张图调配”。"}], "explanations": {"拍摄": "语义：拍摄指用相机记录影像，照片不是靠拍摄由两张图得到的，句子不通。", "拆分": "语义：拆分是分开，与“合”的结合义相反，句子说不通。", "合成": "正确：合成指把几部分结合成一个整体，与“用两张图”的语境相符。", "调配": "搭配：调配多用于颜料、饮品，不说“用两张图调配”。"}, "sentence_index": 0, "correct_answer": "合成"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他把一个大文件合成了三个小文件。", "explanation": "这里应该用〈分割〉。合成指把几部分合为一体，把一个文件变成三个要用“分割”。"}, {"text": "我们把那面墙合成了三块，好搬走。", "explanation": "这里应该用〈拆成〉。合成指把几部分合为一体，把墙分成几块要用“拆成”。"}, {"text": "这个老师把学生合成了三组，分别上课。", "explanation": "这里应该用〈分成〉。合成指把几部分合为一体，把学生分组要用“分成”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '70be7a17-cd0a-4913-9080-5d7b3005c701') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24268, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "切割", "is_correct": false, "explanation": "语义：切割是把整体分开，与“合成一张海报”的结合义相反。"}, {"text": "擦拭", "is_correct": false, "explanation": "搭配：擦拭的对象是表面，不说“擦拭几张图片”。"}, {"text": "编纂", "is_correct": false, "explanation": "语域：编纂是书面、正式的整理工作，用来描述做一张海报显得不协调。"}, {"text": "合成", "is_correct": true, "explanation": "正确：合成指把几张图片结合成一张，与“合成一张海报”的语境相符。"}], "explanations": {"切割": "语义：切割是把整体分开，与“合成一张海报”的结合义相反。", "擦拭": "搭配：擦拭的对象是表面，不说“擦拭几张图片”。", "编纂": "语域：编纂是书面、正式的整理工作，用来描述做一张海报显得不协调。", "合成": "正确：合成指把几张图片结合成一张，与“合成一张海报”的语境相符。"}, "sentence_index": 6, "correct_answer": "合成"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "工程师用尺子合成了桌子的长度。", "explanation": "这里应该用〈测量〉。“合成”指把几种东西结合成新东西，量长度要用“测量”。"}, {"text": "学生用打印机合成了作业。", "explanation": "这里应该用〈打印〉。合成指结合成整体或新物质，输出作业要用“打印”。"}, {"text": "他用一根木头合成了一张桌子。", "explanation": "这里应该用〈加工〉。“合成”指把几种东西结合成新东西，把一根木头做成桌子要用“加工”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '70be7a17-cd0a-4913-9080-5d7b3005c701') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24268, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "工厂把两种原料合成了一只新材料。", "corrected_sentence": "工厂把两种原料合成了一种新材料。", "error_description": "量词错误：“新材料”应搭配“种”，“只”用于动物。正确说法是“合成了一种新材料”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '70be7a17-cd0a-4913-9080-5d7b3005c701') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24268, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "实验室用碳和氢合成了一只气体。", "corrected_sentence": "实验室用碳和氢合成了一种气体。", "error_description": "量词错误：“气体”应搭配“种”，“只”用于动物。正确说法是“合成了一种气体”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '70be7a17-cd0a-4913-9080-5d7b3005c701') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
