INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24270, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "两个人或东西不再在一起。", "primary_collocate": null, "pronunciation": "fēn lí", "ipa": "fən˥ li˧˥", "syllable_count": 2, "sentences": [{"text": "战争让一家人分离了很多年。", "target_word": "分离", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们分离了十年，终于又见面了。", "target_word": "分离", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "朋友毕业后就要分离了。", "target_word": "分离", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小狗不愿意和主人分离。", "target_word": "分离", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我不想和家人分离。", "target_word": "分离", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "分离的时候，大家都哭了。", "target_word": "分离", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "长时间的分离让他们很想念对方。", "target_word": "分离", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "因为工作，夫妻只好长期分离。", "target_word": "分离", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那只小鸟和妈妈分离了，叫个不停。", "target_word": "分离", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子第一次和妈妈分离，哭得很厉害。", "target_word": "分离", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "分離", "label": "繁体"}, {"form": "分离了", "label": "体标"}, {"form": "分离过", "label": "体标"}], "register": "通用", "sense_fingerprint": "人或事物离别，不再在一起", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e7250d00-77e8-4de8-a520-b9d293cc7300') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24270, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "分离", "is_correct": true, "explanation": "与听到的读音一致，fēn lí，意思是两个人或东西不再在一起。"}, {"text": "奋力", "is_correct": false, "explanation": "fèn lì：两个字都是第四声，而 fēn lí 是第一声加第二声。意思是尽力、用力。"}, {"text": "分立", "is_correct": false, "explanation": "fēn lì（第四声）与 fēn lí 的 lí（第二声）声调不同，意思是分开设立、彼此独立。"}, {"text": "风力", "is_correct": false, "explanation": "fēng lì：第一个字是后鼻音 fēng，不是 fēn；第二个字是第四声 lì，不是第二声 lí。意思是风的力量。"}], "explanations": {"分离": "与听到的读音一致，fēn lí，意思是两个人或东西不再在一起。", "奋力": "fèn lì：两个字都是第四声，而 fēn lí 是第一声加第二声。意思是尽力、用力。", "分立": "fēn lì（第四声）与 fēn lí 的 lí（第二声）声调不同，意思是分开设立、彼此独立。", "风力": "fēng lì：第一个字是后鼻音 fēng，不是 fēn；第二个字是第四声 lì，不是第二声 lí。意思是风的力量。"}, "sentence_index": null, "correct_answer": "分离"}, "level_3": {"options": [{"text": "分离", "is_correct": true, "explanation": "分离：指一家人长期被隔开、不在一起，符合句意。"}, {"text": "游泳", "is_correct": false, "explanation": "语义：“游泳”与战争造成的隔开毫无关系，“战争让一家人游泳了很多年”句意荒谬。"}, {"text": "合唱", "is_correct": false, "explanation": "搭配：“合唱”是多人一起唱歌，不能作“战争让……”这类结构的结果。"}, {"text": "跳舞", "is_correct": false, "explanation": "语义：“跳舞”与战争造成的隔开毫无关系，“战争让一家人跳舞了很多年”句意荒谬。"}], "explanations": {"分离": "分离：指一家人长期被隔开、不在一起，符合句意。", "游泳": "语义：“游泳”与战争造成的隔开毫无关系，“战争让一家人游泳了很多年”句意荒谬。", "合唱": "搭配：“合唱”是多人一起唱歌，不能作“战争让……”这类结构的结果。", "跳舞": "语义：“跳舞”与战争造成的隔开毫无关系，“战争让一家人跳舞了很多年”句意荒谬。"}, "sentence_index": 0, "correct_answer": "分离"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他在比赛中分离了冠军的机会。", "explanation": "这里应该用〈失去〉。分离指两者原本在一起后不再在一起，丢掉机会要用失去，不能说分离机会。"}, {"text": "我一个人在家，很快就分离了。", "explanation": "这里应该用〈出门〉。分离至少需要两者，句中只有“我”一人，一个人离家不是分离，应说出门。"}, {"text": "他的心情很快就分离了。", "explanation": "这里应该用〈好转〉。分离要求两者原本在一起，心情只是一个人的状态，不能说分离。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '36751d0d-d99d-4665-83b3-5ea04844abff') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24270, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "分离", "is_correct": true, "explanation": "分离：指长时间不在一起，符合“很想念对方”的语境。"}, {"text": "聚会", "is_correct": false, "explanation": "语义：“聚会”指大家在一起，与“很想念对方”所需的分开语境相反。"}, {"text": "欢笑", "is_correct": false, "explanation": "语义：“欢笑”是高兴的表现，不会使人很想念对方。"}, {"text": "笑话", "is_correct": false, "explanation": "语义：“笑话”不能使人长时间想念对方，“长时间的笑话让他们很想念对方”句意不通。"}], "explanations": {"分离": "分离：指长时间不在一起，符合“很想念对方”的语境。", "聚会": "语义：“聚会”指大家在一起，与“很想念对方”所需的分开语境相反。", "欢笑": "语义：“欢笑”是高兴的表现，不会使人很想念对方。", "笑话": "语义：“笑话”不能使人长时间想念对方，“长时间的笑话让他们很想念对方”句意不通。"}, "sentence_index": 6, "correct_answer": "分离"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "士兵们很快分离了阵地。", "explanation": "这里应该用〈撤离〉。分离指两者原本在一起后不再在一起，士兵离开阵地要用撤离，不能说分离阵地。"}, {"text": "列车分离了站台。", "explanation": "这里应该用〈离开〉。分离要求双方原本在一起，列车与站台不是这种关系，应说列车离开站台。"}, {"text": "他终于分离了危险。", "explanation": "这里应该用〈脱离〉。危险不是可以与人分开的事物，应说脱离危险。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '36751d0d-d99d-4665-83b3-5ea04844abff') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24270, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他们因为误会分离着两年，最后又团聚了。", "corrected_sentence": "他们因为误会分离了两年，最后又团聚了。", "error_description": "体标错误：叙述的是已经结束的两年分开，“分离”后应用“了”，用“着”表示持续状态不对。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '36751d0d-d99d-4665-83b3-5ea04844abff') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24270, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "孩子给父母分离了很久。", "corrected_sentence": "孩子和父母分离了很久。", "error_description": "介词错误：“分离”的对象应由“和”引出，“给”表示给予，不能说“给父母分离”，应为“和父母分离”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '36751d0d-d99d-4665-83b3-5ea04844abff') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24274, 1, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '36751d0d-d99d-4665-83b3-5ea04844abff') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24274, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '36751d0d-d99d-4665-83b3-5ea04844abff') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24274, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "最新的、最好的技术。", "primary_collocate": null, "pronunciation": "qián yán jì shù", "ipa": "t͡ɕʰi̯ɛn˧˥ i̯ɛn˧˥ t͡ɕi˥˩ ʂu˥˩", "syllable_count": 4, "sentences": [{"text": "这款手机采用了前沿技术，拍照效果非常好。", "target_word": "前沿技术", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们的工厂有很多前沿技术。", "target_word": "前沿技术", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们要学习国外的前沿技术。", "target_word": "前沿技术", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这辆电动车用的是世界上最好的前沿技术。", "target_word": "前沿技术", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师说，前沿技术就是最新最好的技术。", "target_word": "前沿技术", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "医院买了用前沿技术做的新机器。", "target_word": "前沿技术", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "想让公司发展得快，就要用前沿技术。", "target_word": "前沿技术", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个小城市的工厂也开始用前沿技术了。", "target_word": "前沿技术", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "前沿技术很贵，不是每家公司都买得起。", "target_word": "前沿技术", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他每天看新闻，了解各种前沿技术。", "target_word": "前沿技术", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "一项前沿技术", "label": "量词"}, {"form": "前沿技術", "label": "繁体"}], "register": "书面", "sense_fingerprint": "最新最好的技术", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e7250d00-77e8-4de8-a520-b9d293cc7300') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24274, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "前沿技术", "is_correct": true, "explanation": "正确：“采用了”后接的是手机所用的技术，“前沿技术”与拍照效果的描述相符。"}, {"text": "古法造纸", "is_correct": false, "explanation": "语义：古法造纸与手机的拍照效果毫无关系，句子无法成立。"}, {"text": "家庭作业", "is_correct": false, "explanation": "语义：家庭作业不是手机的组成部分，不能被手机“采用”。"}, {"text": "家常菜", "is_correct": false, "explanation": "语义：“家常菜”不是手机能“采用”的东西，“这款手机采用了家常菜”句意荒谬。"}], "explanations": {"前沿技术": "正确：“采用了”后接的是手机所用的技术，“前沿技术”与拍照效果的描述相符。", "古法造纸": "语义：古法造纸与手机的拍照效果毫无关系，句子无法成立。", "家庭作业": "语义：家庭作业不是手机的组成部分，不能被手机“采用”。", "家常菜": "语义：“家常菜”不是手机能“采用”的东西，“这款手机采用了家常菜”句意荒谬。"}, "sentence_index": 0, "correct_answer": "前沿技术"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我们工厂买了一只前沿技术。", "explanation": "这里应该用〈一项〉。“只”用于动物或单件物品，技术要用“项”或“门”计数。"}, {"text": "这家农场的前沿技术就是那片靠近国界线的田地，一年到头几乎没人来。", "explanation": "这里应该用〈边境地带〉。“前沿”另有边境地带的意思，而“前沿技术”指最新、最好的技术，不能指一片田地。"}, {"text": "这位木匠的前沿技术是祖传的老手艺，做的桌子很结实。", "explanation": "这里应该用〈传统手艺〉。“前沿技术”指最新、最好的技术，与“祖传的老手艺”自相矛盾。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '36751d0d-d99d-4665-83b3-5ea04844abff') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24274, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "前沿技术", "is_correct": true, "explanation": "正确：“用”后接的是促进发展的手段，“前沿技术”符合这一语境。"}, {"text": "午睡", "is_correct": false, "explanation": "语义：“午睡”与公司发展的快慢没有关系，“用午睡发展公司”句意不通。"}, {"text": "老式家具", "is_correct": false, "explanation": "语义：老式家具与公司发展的快慢之间没有因果关系。"}, {"text": "加班费", "is_correct": false, "explanation": "搭配：“用”后接的应是手段、方法，“加班费”是报酬，不能作为手段。"}], "explanations": {"前沿技术": "正确：“用”后接的是促进发展的手段，“前沿技术”符合这一语境。", "午睡": "语义：“午睡”与公司发展的快慢没有关系，“用午睡发展公司”句意不通。", "老式家具": "语义：老式家具与公司发展的快慢之间没有因果关系。", "加班费": "搭配：“用”后接的应是手段、方法，“加班费”是报酬，不能作为手段。"}, "sentence_index": 6, "correct_answer": "前沿技术"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这家小作坊的前沿技术全是几十年前的旧法子，一点也不新。", "explanation": "这里应该用〈传统工艺〉。“前沿技术”指最新、最好的技术，而几十年前沿用的旧法子属于传统工艺，两者不能指同一件事。"}, {"text": "这家小店引进了一台前沿技术。", "explanation": "这里应该用〈一项〉。“台”用于机器、设备，技术不是具体的机器，要用“项”或“门”计数。"}, {"text": "她去超市称了三斤前沿技术。", "explanation": "这里应该用〈一项〉。“斤”是重量单位，技术没有重量，不能称，也不能用“斤”计量，应说“一项前沿技术”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '36751d0d-d99d-4665-83b3-5ea04844abff') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24274, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我们工厂引进了一本前沿技术。", "corrected_sentence": "我们工厂引进了一项前沿技术。", "error_description": "错误形式“一本前沿技术”，正确形式“一项前沿技术”。“本”用于书籍、册子，技术不是可以翻阅的书，应改用“项”计数。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '36751d0d-d99d-4665-83b3-5ea04844abff') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24274, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他们学会着前沿技术。", "corrected_sentence": "他们学会了前沿技术。", "error_description": "错误形式“学会着前沿技术”，正确形式“学会了前沿技术”。“学会”表示动作完成后获得的结果，应用“了”表示完成；“着”表示动作或状态的持续，与“学会”这种瞬间完成的结果不搭配。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '36751d0d-d99d-4665-83b3-5ea04844abff') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
