INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24276, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '81cf0d6c-ad07-44cf-a5e9-ede6f1da6fcb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24276, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "算出题目的答案。", "primary_collocate": null, "pronunciation": "qiú jiě", "ipa": "tɕʰjoʊ˧˥ tɕjɛ˨˩˦", "syllable_count": 2, "sentences": [{"text": "这道应用题我求解了很久。", "target_word": "求解", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师请小明上台求解这道题。", "target_word": "求解", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "先看清题目，再开始求解。", "target_word": "求解", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这道题太难，我没办法求解。", "target_word": "求解", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他一边看书，一边求解数学题。", "target_word": "求解", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "同学们都在认真求解练习题。", "target_word": "求解", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "求解这道题只要五分钟。", "target_word": "求解", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她用了三种方法求解这道几何题。", "target_word": "求解", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "考试时，我先求解容易的题目。", "target_word": "求解", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这道物理题他求解过两次。", "target_word": "求解", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "求解了", "label": "完成体"}, {"form": "求解过", "label": "经历体"}], "register": "书面", "sense_fingerprint": "算出习题或题目的答案", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd3c95f3d-3cf8-40ea-b1f4-10f0941e860d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24276, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "求解", "is_correct": true, "explanation": "“求解”指算出题目的答案，与“应用题”搭配，符合句意。"}, {"text": "购买", "is_correct": false, "explanation": "语义：应用题不能被购买，句子不通。"}, {"text": "修理", "is_correct": false, "explanation": "搭配：“修理”用于机器、房屋等实体，不用于应用题。"}, {"text": "煮", "is_correct": false, "explanation": "语义：应用题不能被煮，与“算出答案”的语境无关。"}], "explanations": {"求解": "“求解”指算出题目的答案，与“应用题”搭配，符合句意。", "购买": "语义：应用题不能被购买，句子不通。", "修理": "搭配：“修理”用于机器、房屋等实体，不用于应用题。", "煮": "语义：应用题不能被煮，与“算出答案”的语境无关。"}, "sentence_index": 0, "correct_answer": "求解"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "老师耐心地求解了这个道理。", "explanation": "这里应该用〈解释〉。求解用于算出题目的答案，道理要用〈解释〉。"}, {"text": "他认真求解了这篇古文。", "explanation": "这里应该用〈解读〉。求解用于算出题目的答案，古文的意思要用〈解读〉。"}, {"text": "老师当场求解了那个破碎的花瓶。", "explanation": "这里应该用〈修补〉。求解只用于算出题目的答案，修复花瓶要用〈修补〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '81cf0d6c-ad07-44cf-a5e9-ede6f1da6fcb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24276, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "求解", "is_correct": true, "explanation": "“求解”指算出题目的答案，“这道题”与“五分钟”的语境相符。"}, {"text": "浇", "is_correct": false, "explanation": "语义：题目不能被“浇”，与五分钟内算出题目的语境不符。"}, {"text": "打扫", "is_correct": false, "explanation": "搭配：“打扫”用于房间、场地等，不用于题目。"}, {"text": "洗", "is_correct": false, "explanation": "语义：“洗”不能用来指做题，句子不通。"}], "explanations": {"求解": "“求解”指算出题目的答案，“这道题”与“五分钟”的语境相符。", "浇": "语义：题目不能被“浇”，与五分钟内算出题目的语境不符。", "打扫": "搭配：“打扫”用于房间、场地等，不用于题目。", "洗": "语义：“洗”不能用来指做题，句子不通。"}, "sentence_index": 6, "correct_answer": "求解"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "消防员把被困的人求解了出来。", "explanation": "这里应该用〈解救〉。求解只用于算出题目的答案，把被困的人救出来要用〈解救〉。"}, {"text": "政府终于求解了这项禁令。", "explanation": "这里应该用〈解除〉。求解只用于算出题目的答案，禁令要用〈解除〉。"}, {"text": "导游耐心地求解了每一处景点。", "explanation": "这里应该用〈解说〉。求解只用于算出题目的答案，景点的讲解要用〈解说〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '81cf0d6c-ad07-44cf-a5e9-ede6f1da6fcb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24276, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这道几何题我终于求解出去了。", "corrected_sentence": "这道几何题我终于求解出来了。", "error_description": "“求解出去”错，应为“求解出来”。“出来”表示算出结果，“出去”表示向外离开，不能用于题目的答案。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '81cf0d6c-ad07-44cf-a5e9-ede6f1da6fcb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24276, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我正在认真求解过这道奥数题。", "corrected_sentence": "我正在认真求解这道奥数题。", "error_description": "“求解过”错，应为“求解”。“正在”表示动作正在进行，而“过”表示经历过的动作，两者不能搭配。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '81cf0d6c-ad07-44cf-a5e9-ede6f1da6fcb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
