INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24278, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "进入里面，了解很多。", "primary_collocate": null, "pronunciation": "shēn rù", "ipa": "ʂən˥ ɻu˥˩", "syllable_count": 2, "sentences": [{"text": "我们想深入了解这个城市的历史。", "target_word": "深入", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "记者深入山区，看到了很多孩子。", "target_word": "深入", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师说，我们要深入学习这篇课文。", "target_word": "深入", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们深入森林，找到了一条小河。", "target_word": "深入", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "医生深入检查了他的身体。", "target_word": "深入", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他在中国住了五年，深入了当地人的生活。", "target_word": "深入", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们的谈话越来越深入。", "target_word": "深入", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这次旅行让我深入了解了中国文化。", "target_word": "深入", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "工人们深入地下几百米工作。", "target_word": "深入", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师和学生深入地讨论了这个问题。", "target_word": "深入", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "深入了", "label": "完成体"}, {"form": "深入过", "label": "经历体"}, {"form": "深入浅出", "label": "复合"}], "register": "书面", "sense_fingerprint": "进入到里面去，把事情了解得很多很细", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ffce3848-4e7c-4ec3-885e-673579ba7e56') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24278, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "深入", "is_correct": true, "explanation": "深入指进到事物内部并探究，与“了解这个城市的历史”相合。"}, {"text": "大声", "is_correct": false, "explanation": "语义：“了解”是认知活动，不能用“大声”修饰。"}, {"text": "猛烈", "is_correct": false, "explanation": "语义：“猛烈”形容力量或行动，与了解历史的认知义不合。"}, {"text": "清澈", "is_correct": false, "explanation": "搭配：“清澈”形容水或眼神，不能修饰“了解”。"}], "explanations": {"深入": "深入指进到事物内部并探究，与“了解这个城市的历史”相合。", "大声": "语义：“了解”是认知活动，不能用“大声”修饰。", "猛烈": "语义：“猛烈”形容力量或行动，与了解历史的认知义不合。", "清澈": "搭配：“清澈”形容水或眼神，不能修饰“了解”。"}, "sentence_index": 0, "correct_answer": "深入"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "老师深入了教室，然后开始上课。", "explanation": "这里应该用〈进入〉。深入强调进到内部并探究，普通地走进教室不说深入。"}, {"text": "他们明天早上七点深入去北京。", "explanation": "这里应该用〈出发〉。深入指进入某处内部并探究，离开家去远方要说出发。"}, {"text": "这件衣服的颜色很深入。", "explanation": "这里应该用〈深〉。深入指进到内部、了解得很多，颜色浓要说颜色很深。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ad60c45b-4ca7-40b4-bf0c-f205e95e64b0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24278, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "深入", "is_correct": true, "explanation": "深入形容谈话逐步进到深处，与“谈话越来越”相合。"}, {"text": "美丽", "is_correct": false, "explanation": "语义：谈话不是可以用“美丽”来形容的事物，句意不通。"}, {"text": "高大", "is_correct": false, "explanation": "语义：“高大”形容体型或建筑，不能形容谈话。"}, {"text": "健壮", "is_correct": false, "explanation": "搭配：“健壮”形容人或身体，不能修饰谈话。"}], "explanations": {"深入": "深入形容谈话逐步进到深处，与“谈话越来越”相合。", "美丽": "语义：谈话不是可以用“美丽”来形容的事物，句意不通。", "高大": "语义：“高大”形容体型或建筑，不能形容谈话。", "健壮": "搭配：“健壮”形容人或身体，不能修饰谈话。"}, "sentence_index": 6, "correct_answer": "深入"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我的深入很大，大家都很佩服我。", "explanation": "词性：深入是动词或形容词，不能当名词用，说能力要用“能力”或“水平”。"}, {"text": "这块蛋糕很深入。", "explanation": "这里应该用〈松软〉。深入指进到内部、探究到底，形容蛋糕的口感要说松软。"}, {"text": "孩子们深入吃了一顿饭。", "explanation": "这里应该用〈痛快〉。深入指进到内部、探究到底，形容吃得尽兴要说痛快地吃。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ad60c45b-4ca7-40b4-bf0c-f205e95e64b0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24278, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "医生正在深入了研究这种药的作用。", "corrected_sentence": "医生正在深入研究这种药的作用。", "error_description": "错误：“正在”表示动作进行，不能与表示完成的“了”同用，应去掉“了”。正确：“医生正在深入研究这种药的作用。”", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ad60c45b-4ca7-40b4-bf0c-f205e95e64b0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24278, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他们深入得研究了这个问题。", "corrected_sentence": "他们深入地研究了这个问题。", "error_description": "错误：“深入”修饰动词作状语时可用“地”，这里误用了补语标志“得”。正确：“他们深入地研究了这个问题。”", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ad60c45b-4ca7-40b4-bf0c-f205e95e64b0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24280, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "共性", "is_correct": true, "explanation": "共性指事物或群体共有的性质，与特性（独有的性质）相对，是特性的反义。"}, {"text": "体积", "is_correct": false, "explanation": "体积指物体所占空间的大小，与特性不构成反义关系。"}, {"text": "温度", "is_correct": false, "explanation": "温度指冷热程度，与特性不构成反义关系。"}, {"text": "规律", "is_correct": false, "explanation": "规律指事物发展中稳定的联系，与特性不构成反义关系。"}], "correct_answer": "共性", "explanations": {"共性": "共性指事物或群体共有的性质，与特性（独有的性质）相对，是特性的反义。", "体积": "体积指物体所占空间的大小，与特性不构成反义关系。", "温度": "温度指冷热程度，与特性不构成反义关系。", "规律": "规律指事物发展中稳定的联系，与特性不构成反义关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1275f817-9b11-44be-8995-531972d780f9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24280, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "共性", "is_correct": true, "explanation": "共性指事物或群体共有的性质，与特性（独有的性质）相对，是特性的反义。"}, {"text": "长度", "is_correct": false, "explanation": "长度指线状事物的长短，与特性不构成反义关系。"}, {"text": "寿命", "is_correct": false, "explanation": "寿命指存续的时间，与特性不构成反义关系。"}, {"text": "密度", "is_correct": false, "explanation": "密度指单位体积内物质的多少，与特性不构成反义关系。"}], "correct_answer": "共性", "explanations": {"共性": "共性指事物或群体共有的性质，与特性（独有的性质）相对，是特性的反义。", "长度": "长度指线状事物的长短，与特性不构成反义关系。", "寿命": "寿命指存续的时间，与特性不构成反义关系。", "密度": "密度指单位体积内物质的多少，与特性不构成反义关系。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1275f817-9b11-44be-8995-531972d780f9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24280, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "property", "definition": "特性就是一个人或东西特别的地方。", "primary_collocate": null, "pronunciation": "tè xìng", "ipa": "tʰɤ˥˩ ɕiŋ˥˩", "syllable_count": 2, "sentences": [{"text": "每种材料都有自己的特性。", "target_word": "特性", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "猫的特性是喜欢安静，也喜欢睡觉。", "target_word": "特性", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这种植物的特性是不怕冷。", "target_word": "特性", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "老师要了解每个孩子的特性。", "target_word": "特性", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "金属的特性是容易导电。", "target_word": "特性", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我们先看看这种动物有什么特性。", "target_word": "特性", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他把这个产品的特性写在了纸上。", "target_word": "特性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "不同的茶有不同的特性，味道也不一样。", "target_word": "特性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "竹子的特性让它很适合做桌子。", "target_word": "特性", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我很喜欢这个手机的几个特性。", "target_word": "特性", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "种", "label": "量词"}], "register": "中性", "sense_fingerprint": "人或事物独有的性质和特点", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cebcaa39-880a-494e-9b7b-c3edf04ba17b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24280, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "特性", "is_correct": true, "explanation": "特性指事物本身独有的性质，每种材料都有自己独特的性质，符合句意。"}, {"text": "身高", "is_correct": false, "explanation": "体貌：「身高」是人的外形特征，材料不能说有身高。"}, {"text": "学历", "is_correct": false, "explanation": "语义：「学历」指人受教育的经历，材料不能有学历，句意不通。"}, {"text": "嗓音", "is_correct": false, "explanation": "搭配：「嗓音」只与能发声的人或动物搭配，材料没有嗓音。"}], "explanations": {"特性": "特性指事物本身独有的性质，每种材料都有自己独特的性质，符合句意。", "身高": "体貌：「身高」是人的外形特征，材料不能说有身高。", "学历": "语义：「学历」指人受教育的经历，材料不能有学历，句意不通。", "嗓音": "搭配：「嗓音」只与能发声的人或动物搭配，材料没有嗓音。"}, "sentence_index": 0, "correct_answer": "特性"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "今天的特性下了一场大雨，我们没法去公园。", "explanation": "这里应该用〈天气〉。特性指事物本身的性质，不能下雨；说下雨要用〈天气〉。"}, {"text": "这个活动的特性是三个小时，大家都累了。", "explanation": "这里应该用〈时间〉。特性指事物本身的性质，不能用几个小时来说；说活动持续多久要用〈时间〉。"}, {"text": "我去商店买了很多特性。", "explanation": "这里应该用〈商品〉。特性是事物本身的性质，不是可以买卖的东西；去商店买的是〈商品〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1275f817-9b11-44be-8995-531972d780f9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24280, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "特性", "is_correct": true, "explanation": "特性指产品本身的性质，「把这个产品的特性写在纸上」符合句意。"}, {"text": "心情", "is_correct": false, "explanation": "语义：「心情」是人的情绪，产品没有心情。"}, {"text": "辈分", "is_correct": false, "explanation": "语义：「辈分」指人际关系中的代际次序，不能用于产品。"}, {"text": "胃口", "is_correct": false, "explanation": "搭配：「胃口」指食欲，只能说人或动物的胃口，不能说产品的胃口。"}], "explanations": {"特性": "特性指产品本身的性质，「把这个产品的特性写在纸上」符合句意。", "心情": "语义：「心情」是人的情绪，产品没有心情。", "辈分": "语义：「辈分」指人际关系中的代际次序，不能用于产品。", "胃口": "搭配：「胃口」指食欲，只能说人或动物的胃口，不能说产品的胃口。"}, "sentence_index": 6, "correct_answer": "特性"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这辆车的特性坏了一个，要换个新的。", "explanation": "这里应该用〈轮胎〉。特性是抽象的性质，不能坏了再换新的；车上可以坏、可以换的是〈轮胎〉。"}, {"text": "我把这只猫的特性抱回了家。", "explanation": "这里应该用〈猫〉。特性是抽象的性质，不能抱回家；被抱回家的是猫本身。"}, {"text": "我去厨房炒了一盘特性。", "explanation": "这里应该用〈菜〉。特性是抽象的性质，不能用来炒；炒的是菜。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1275f817-9b11-44be-8995-531972d780f9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24280, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这种材料地特性很稳定，所以很常用。", "corrected_sentence": "这种材料的特性很稳定，所以很常用。", "error_description": "错误：「地」用错。「地」用于修饰动词或形容词，修饰名词「特性」要用「的」，应说「这种材料的特性」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1275f817-9b11-44be-8995-531972d780f9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24280, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这台相机有一把很实用的特性。", "corrected_sentence": "这台相机有一种很实用的特性。", "error_description": "错误：量词错误。〈把〉用于有柄的器具，修饰抽象名词「特性」应用〈种〉，应说「一种很实用的特性」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1275f817-9b11-44be-8995-531972d780f9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
