INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24284, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "很难解决的问题。", "primary_collocate": null, "pronunciation": "nán tí", "ipa": "nan˧˥ tʰi˧˥", "syllable_count": 2, "sentences": [{"text": "这道数学难题没有人会做。", "target_word": "难题", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师给我们出了一个难题。", "target_word": "难题", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他终于解决了这个难题。", "target_word": "难题", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "买房子是很多年轻人的难题。", "target_word": "难题", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个难题让大家想了一个晚上。", "target_word": "难题", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "照顾年迈的父母是他的一大难题。", "target_word": "难题", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们一起想办法解决难题。", "target_word": "难题", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他把难题写在黑板上。", "target_word": "难题", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "考试里有两个难题，我都没做出来。", "target_word": "难题", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "工作中总会遇到各种难题。", "target_word": "难题", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "个", "label": "量词"}, {"form": "道", "label": "量词"}], "register": "中性", "sense_fingerprint": "难以解决的问题", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cdc1bb5e-b14c-41de-8ff0-76ccf8bb8da0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24284, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "作文", "is_correct": false, "explanation": "搭配：“数学”修饰的是题目，“数学作文”说不通。"}, {"text": "难题", "is_correct": true, "explanation": "难题：指很难解决的问题，与“没有人会做”相合。"}, {"text": "天气", "is_correct": false, "explanation": "语义：天气不是可以“做”出来的东西，句意不通。"}, {"text": "公园", "is_correct": false, "explanation": "语义：公园不是需要解答的对象，“没有人会做”说不通。"}], "explanations": {"作文": "搭配：“数学”修饰的是题目，“数学作文”说不通。", "难题": "难题：指很难解决的问题，与“没有人会做”相合。", "天气": "语义：天气不是可以“做”出来的东西，句意不通。", "公园": "语义：公园不是需要解答的对象，“没有人会做”说不通。"}, "sentence_index": 0, "correct_answer": "难题"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "老师今天出了一只难题。", "explanation": "这里应该用量词〈道〉。“只”用于动物等，不用于题目。"}, {"text": "我对这个结果有难题。", "explanation": "这里应该用〈疑问〉。难题指需要解决的困难问题，心里的不解要说“疑问”，不说“有难题”。"}, {"text": "这次考试的难题很大。", "explanation": "这里应该用〈难度〉。“很大”形容程度，难题是具体的问题，不说“难题很大”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd63076ef-1850-48aa-a439-995318801ef7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24284, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "礼物", "is_correct": false, "explanation": "搭配：“解决”接问题、困难，不能接“礼物”。"}, {"text": "难题", "is_correct": true, "explanation": "难题：指很难解决的问题，与“解决”搭配，句意通顺。"}, {"text": "天空", "is_correct": false, "explanation": "语义：天空不是可以“解决”的对象，句意不通。"}, {"text": "歌曲", "is_correct": false, "explanation": "搭配：“解决”不能接“歌曲”，“解决歌曲”说不通。"}], "explanations": {"礼物": "搭配：“解决”接问题、困难，不能接“礼物”。", "难题": "难题：指很难解决的问题，与“解决”搭配，句意通顺。", "天空": "语义：天空不是可以“解决”的对象，句意不通。", "歌曲": "搭配：“解决”不能接“歌曲”，“解决歌曲”说不通。"}, "sentence_index": 6, "correct_answer": "难题"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "听到这个消息，她心里一阵难题。", "explanation": "这里应该用〈难过〉。难题指需要解决的问题，表示心里的伤感要说“难过”，不能说“一阵难题”。"}, {"text": "这个难题的价钱很高。", "explanation": "这里应该用〈商品〉。难题是抽象的问题，没有价钱，说“价钱很高”的应是商品。"}, {"text": "他给这道难题加了很多盐。", "explanation": "这里应该用〈菜〉。难题是问题，不能加盐调味，加盐的应是菜。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd63076ef-1850-48aa-a439-995318801ef7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24284, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "老师出的这只难题，我想了一下午。", "corrected_sentence": "老师出的这道难题，我想了一下午。", "error_description": "量词错误：“难题”应配量词“道”，“只”用于动物，不能用于题目，正确为“这道难题”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd63076ef-1850-48aa-a439-995318801ef7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24284, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我们终于解决得这道难题。", "corrected_sentence": "我们终于解决了这道难题。", "error_description": "补语错误：“解决得”不成立，“得”不能接在“解决”后面，完成体应为“解决了”，正确为“我们终于解决了这道难题”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd63076ef-1850-48aa-a439-995318801ef7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
