INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24288, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "把很多小东西合在一起，变成一个整体。", "primary_collocate": null, "pronunciation": "jí chéng", "ipa": "tɕi˧˥ ʈʂʰɤŋ˧˥", "syllable_count": 2, "sentences": [{"text": "这块芯片集成了很多小零件。", "target_word": "集成", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "工人把小零件集成在一块板上。", "target_word": "集成", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这台机器集成了五个小装置。", "target_word": "集成", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "设计师想把所有按键集成到一起。", "target_word": "集成", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "手表里集成了很多小东西。", "target_word": "集成", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他们把几个小模块集成为一个整体。", "target_word": "集成", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个盒子集成了灯、喇叭和电池。", "target_word": "集成", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "厂家把三块小板集成在一起。", "target_word": "集成", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个设备集成了很多小部件。", "target_word": "集成", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我想把这些小东西集成为一个整体。", "target_word": "集成", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "集成了", "label": "体标（了）"}, {"form": "集成过", "label": "体标（过）"}, {"form": "集成电路", "label": "复合词"}, {"form": "系统集成", "label": "复合词"}], "register": "书面", "sense_fingerprint": "把许多小零件合成一个整体（实物）", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd0a0f57a-406e-4360-81b4-dcb946f1ae89') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24288, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "集成", "is_correct": true, "explanation": "正确答案：集成（jí chéng），指把许多小零件合成一个整体。"}, {"text": "继承", "is_correct": false, "explanation": "声调不同：继承（jì chéng）第一音节为第四声，集成为第二声；意思是承接、传承。"}, {"text": "几成", "is_correct": false, "explanation": "声调不同：几成（jǐ chéng）第一音节为第三声，集成为第二声；意思是十分之几。"}, {"text": "计程", "is_correct": false, "explanation": "声调不同：计程（jì chéng）第一音节为第四声，集成为第二声；意思是计算路程。"}], "explanations": {"集成": "正确答案：集成（jí chéng），指把许多小零件合成一个整体。", "继承": "声调不同：继承（jì chéng）第一音节为第四声，集成为第二声；意思是承接、传承。", "几成": "声调不同：几成（jǐ chéng）第一音节为第三声，集成为第二声；意思是十分之几。", "计程": "声调不同：计程（jì chéng）第一音节为第四声，集成为第二声；意思是计算路程。"}, "sentence_index": null, "correct_answer": "集成"}, "level_3": {"options": [{"text": "集成", "is_correct": true, "explanation": "正确：“集成”指把零件组合为一体，与“这块芯片…了很多小零件”的语境相合。"}, {"text": "谈论", "is_correct": false, "explanation": "语义：芯片不能谈论，“谈论”与句中装有零件的意思不合。"}, {"text": "吞下", "is_correct": false, "explanation": "语义：“吞下”指咽进口中，与零件组合进芯片的意思不合。"}, {"text": "喂养", "is_correct": false, "explanation": "配价：“喂养”要求有生命的施事，句中的“芯片”不能喂养零件。"}], "explanations": {"集成": "正确：“集成”指把零件组合为一体，与“这块芯片…了很多小零件”的语境相合。", "谈论": "语义：芯片不能谈论，“谈论”与句中装有零件的意思不合。", "吞下": "语义：“吞下”指咽进口中，与零件组合进芯片的意思不合。", "喂养": "配价：“喂养”要求有生命的施事，句中的“芯片”不能喂养零件。"}, "sentence_index": 0, "correct_answer": "集成"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他把花瓶集成在窗台上。", "explanation": "这里应该用〈摆放〉。集成是把零件合为整体，不指把独立的物品摆放到某处。"}, {"text": "我把一束花集成在花瓶里。", "explanation": "这里应该用〈插〉。集成针对零件的组合，不指把花插进容器。"}, {"text": "他把书集成进箱子里。", "explanation": "这里应该用〈放〉。集成的对象是零件或功能，不是把书放进箱子。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4d1481fe-33c0-4c92-b450-0540642db1fa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24288, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "集成", "is_correct": true, "explanation": "正确：“集成”指把灯、喇叭和电池组合进盒子，与句中的描述相合。"}, {"text": "烧毁", "is_correct": false, "explanation": "语义：“烧毁”是损坏，与“集成”把部件合为一体的意思相反。"}, {"text": "粉碎", "is_correct": false, "explanation": "语义：“粉碎”会破坏零件，与盒子内装有灯、喇叭和电池的描述不合。"}, {"text": "哺育", "is_correct": false, "explanation": "配价：“哺育”要求有生命的施事，盒子不能哺育东西。"}], "explanations": {"集成": "正确：“集成”指把灯、喇叭和电池组合进盒子，与句中的描述相合。", "烧毁": "语义：“烧毁”是损坏，与“集成”把部件合为一体的意思相反。", "粉碎": "语义：“粉碎”会破坏零件，与盒子内装有灯、喇叭和电池的描述不合。", "哺育": "配价：“哺育”要求有生命的施事，盒子不能哺育东西。"}, "sentence_index": 6, "correct_answer": "集成"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "妈妈想把这块猪肉集成一锅汤。", "explanation": "这里应该用〈熬〉。集成指把许多小部件合为一个整体，一块肉熬成汤要说熬。"}, {"text": "他把这块石头集成了一座雕像。", "explanation": "这里应该用〈雕刻〉。集成指把许多小部件合为一个整体，把一块石头雕成雕像要说雕刻。"}, {"text": "他想把这些小东西集成一场音乐会。", "explanation": "这里应该用〈举办〉。集成指把部件合为整体，不用于组织活动；办音乐会要说“举办”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4d1481fe-33c0-4c92-b450-0540642db1fa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24288, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这台仪器集成了了六个小装置。", "corrected_sentence": "这台仪器集成了六个小装置。", "error_description": "错误形式“集成了了六个”。“了”只能用一次，紧跟动词，多出的“了”应去掉，说“集成了六个小装置”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4d1481fe-33c0-4c92-b450-0540642db1fa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24288, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "工人把零件集成板上。", "corrected_sentence": "工人把零件集成到板上。", "error_description": "“集成”后接处所时需用介词“到”或“在”，不能直接接名词，应说“集成到板上”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4d1481fe-33c0-4c92-b450-0540642db1fa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
