INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24290, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "从事物理学研究的人所组成的领域或群体。", "primary_collocate": null, "pronunciation": "wù lǐ xué jiè", "ipa": "u˥˩ li˨˩˦ ɕɥe˧˥ tɕje˥˩", "syllable_count": 4, "sentences": [{"text": "我爸爸在物理学界工作。", "target_word": "物理学界", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "物理学界的人都认识这位老师。", "target_word": "物理学界", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这件事在物理学界很有名。", "target_word": "物理学界", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "物理学界有很多聪明的人。", "target_word": "物理学界", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他想进入物理学界当研究员。", "target_word": "物理学界", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "物理学界的专家常常一起开会讨论问题。", "target_word": "物理学界", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她是物理学界的新人。", "target_word": "物理学界", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个消息传遍了物理学界。", "target_word": "物理学界", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "物理学界欢迎年轻人加入。", "target_word": "物理学界", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小林长大后想去物理学界工作。", "target_word": "物理学界", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "物理學界", "label": "繁体"}], "register": "中性", "sense_fingerprint": "研究物理的人们一起工作的圈子", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '91d27849-f17d-475a-ae9e-30e433cef473') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24290, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "物理学界", "is_correct": true, "explanation": "正确。“我爸爸在物理学界工作”中，“物理学界”是他工作的圈子。"}, {"text": "童年", "is_correct": false, "explanation": "语义：“童年”是一段时间，不是可以工作的领域，“在童年工作”不通。"}, {"text": "饭圈", "is_correct": false, "explanation": "语域：“饭圈”是网络用语，指追星群体，不是职业领域，与“工作”不搭。"}, {"text": "童话世界", "is_correct": false, "explanation": "语义：“童话世界”是虚构的场景，不能作为爸爸实际工作的地方。"}], "explanations": {"物理学界": "正确。“我爸爸在物理学界工作”中，“物理学界”是他工作的圈子。", "童年": "语义：“童年”是一段时间，不是可以工作的领域，“在童年工作”不通。", "饭圈": "语域：“饭圈”是网络用语，指追星群体，不是职业领域，与“工作”不搭。", "童话世界": "语义：“童话世界”是虚构的场景，不能作为爸爸实际工作的地方。"}, "sentence_index": 0, "correct_answer": "物理学界"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他大学学的是物理学界。", "explanation": "这里应该用〈物理学专业〉。“物理学界”指研究物理的人群，不是可以报考的专业。"}, {"text": "我们明天上物理学界。", "explanation": "这里应该用〈物理课〉。“物理学界”是人群，不是可以去上的课。"}, {"text": "这个物理学界每年都招收一百名新生。", "explanation": "这里应该用〈物理学院〉。“物理学界”是人群，不是能招生的学校机构。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6359f1c4-dd0c-4ea1-88f1-4a5a819f84de') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24290, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "物理学界", "is_correct": true, "explanation": "正确。“她是物理学界的新人”指她刚进入这个圈子，“物理学界”符合语境。"}, {"text": "动物界", "is_correct": false, "explanation": "语义：动物界不是人可以“加入”的职业圈子，“她是动物界的新人”不通。"}, {"text": "石头", "is_correct": false, "explanation": "语义：“石头”不是人可以成为“新人”的群体或领域，“她是石头的新人”不通。"}, {"text": "二次元", "is_correct": false, "explanation": "语义：“二次元”是网络用语，指动漫世界，不是专业研究的领域，与句意不合。"}], "explanations": {"物理学界": "正确。“她是物理学界的新人”指她刚进入这个圈子，“物理学界”符合语境。", "动物界": "语义：动物界不是人可以“加入”的职业圈子，“她是动物界的新人”不通。", "石头": "语义：“石头”不是人可以成为“新人”的群体或领域，“她是石头的新人”不通。", "二次元": "语义：“二次元”是网络用语，指动漫世界，不是专业研究的领域，与句意不合。"}, "sentence_index": 6, "correct_answer": "物理学界"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我们明天有物理学界。", "explanation": "这里应该用〈物理考试〉。“有”后面要接事件，“物理学界”是人群，不能说“有”。"}, {"text": "这份物理学界每月出版一期。", "explanation": "这里应该用〈物理学术期刊〉。“物理学界”指人群，不是可以按期出版的刊物，不能说“每月出版一期”。"}, {"text": "小林长大后想去一家物理学界工作。", "explanation": "这里应该用〈物理研究所〉。“家”用于机构，“物理学界”指人群，不是可以入职的单位，不能用“一家”来计量。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6359f1c4-dd0c-4ea1-88f1-4a5a819f84de') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24290, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "表姐物理学界工作。", "corrected_sentence": "表姐在物理学界工作。", "error_description": "缺少介词“在”。表示工作的地点时要说“在物理学界工作”，去掉“在”就不通。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6359f1c4-dd0c-4ea1-88f1-4a5a819f84de') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24290, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "物理学界们都很热情。", "corrected_sentence": "物理学界的人都很热情。", "error_description": "“们”不能直接加在“物理学界”后面，应说“物理学界的人”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6359f1c4-dd0c-4ea1-88f1-4a5a819f84de') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24294, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "遵守", "is_correct": true, "explanation": "正确。“遵守”与“违背”互为反义词，都指是否按要求、规则去做。"}, {"text": "收集", "is_correct": false, "explanation": "不构成反义关系：“收集”指聚拢、搜集，与“违背”没有对立关系。"}, {"text": "唱歌", "is_correct": false, "explanation": "不构成反义关系：“唱歌”指歌唱，与“违背”不是对立关系。"}, {"text": "解释", "is_correct": false, "explanation": "不构成反义关系：“解释”指说明道理，与“违背”没有对立关系。"}], "correct_answer": "遵守", "explanations": {"遵守": "正确。“遵守”与“违背”互为反义词，都指是否按要求、规则去做。", "收集": "不构成反义关系：“收集”指聚拢、搜集，与“违背”没有对立关系。", "唱歌": "不构成反义关系：“唱歌”指歌唱，与“违背”不是对立关系。", "解释": "不构成反义关系：“解释”指说明道理，与“违背”没有对立关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '81cf0d6c-ad07-44cf-a5e9-ede6f1da6fcb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24294, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "遵从", "is_correct": true, "explanation": "正确。“遵从”与“违背”互为反义词，都指是否照着规则去做。"}, {"text": "观察", "is_correct": false, "explanation": "不构成反义关系：“观察”指仔细看，与“违背”没有对立关系。"}, {"text": "赞美", "is_correct": false, "explanation": "不构成反义关系：“赞美”指表扬，与“违背”不是对立关系。"}, {"text": "保存", "is_correct": false, "explanation": "不构成反义关系：“保存”指留存，与“违背”没有对立关系。"}], "correct_answer": "遵从", "explanations": {"遵从": "正确。“遵从”与“违背”互为反义词，都指是否照着规则去做。", "观察": "不构成反义关系：“观察”指仔细看，与“违背”没有对立关系。", "赞美": "不构成反义关系：“赞美”指表扬，与“违背”不是对立关系。", "保存": "不构成反义关系：“保存”指留存，与“违背”没有对立关系。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '81cf0d6c-ad07-44cf-a5e9-ede6f1da6fcb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24294, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "不按照要求或规则去做。", "primary_collocate": null, "pronunciation": "wéi bèi", "ipa": "weɪ˧˥ peɪ˥˩", "syllable_count": 2, "sentences": [{"text": "他违背了老师的要求。", "target_word": "违背", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学生违背校规，要写检查。", "target_word": "违背", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "违背安全规定很危险。", "target_word": "违背", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他违背了比赛的规则。", "target_word": "违背", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "谁违背了规定，谁就要负责。", "target_word": "违背", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "病人不能违背医生的要求。", "target_word": "违背", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这样做违背了公司的规定。", "target_word": "违背", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我从没违背过家里的规矩。", "target_word": "违背", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们违背了开会的约定。", "target_word": "违背", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子们违背了游戏规则，大家都不高兴。", "target_word": "违背", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "违背了", "label": "完成体"}, {"form": "违背过", "label": "经历体"}, {"form": "違背", "label": "繁体"}], "register": "书面", "sense_fingerprint": "不按要求或规则去做", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd3c95f3d-3cf8-40ea-b1f4-10f0941e860d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24294, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "违背", "is_correct": true, "explanation": "正确。“违背”表示不遵照要求去做，与句意相符。"}, {"text": "批改", "is_correct": false, "explanation": "搭配：“批改”用于作业、作文等，不用于要求。"}, {"text": "发明", "is_correct": false, "explanation": "语义：要求是提出来的，不能被发明，句意不合。"}, {"text": "观看", "is_correct": false, "explanation": "语义：要求不是可以观看的对象，句意不合。"}], "explanations": {"违背": "正确。“违背”表示不遵照要求去做，与句意相符。", "批改": "搭配：“批改”用于作业、作文等，不用于要求。", "发明": "语义：要求是提出来的，不能被发明，句意不合。", "观看": "语义：要求不是可以观看的对象，句意不合。"}, "sentence_index": 0, "correct_answer": "违背"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他在晚会上违背了一首歌。", "explanation": "这里应该用〈唱〉。违背针对的是约定、规则、要求，歌不是规则，应说唱了一首歌。"}, {"text": "他违背了学校的桌椅，要赔偿。", "explanation": "这里应该用〈弄坏〉。违背针对约定、规则，不能用于具体的桌椅。"}, {"text": "他违背了这张地图，最后迷了路。", "explanation": "这里应该用〈参考〉。违背针对约定、规则、要求，地图不是需要遵守的规则，应说参考地图。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '81cf0d6c-ad07-44cf-a5e9-ede6f1da6fcb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24294, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "违背", "is_correct": true, "explanation": "正确。“违背”表示不遵守规定，与“这样做”的语境相符。"}, {"text": "唱", "is_correct": false, "explanation": "搭配：“唱”不能与“规定”搭配，规定不是可以唱的东西。"}, {"text": "参观", "is_correct": false, "explanation": "搭配：“参观”用于场所或展览，不能用于规定。"}, {"text": "欣赏", "is_correct": false, "explanation": "语义：规定是约束性的，不能被欣赏，句意不合。"}], "explanations": {"违背": "正确。“违背”表示不遵守规定，与“这样做”的语境相符。", "唱": "搭配：“唱”不能与“规定”搭配，规定不是可以唱的东西。", "参观": "搭配：“参观”用于场所或展览，不能用于规定。", "欣赏": "语义：规定是约束性的，不能被欣赏，句意不合。"}, "sentence_index": 6, "correct_answer": "违背"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他违背了上次的记录，这次成绩很好。", "explanation": "这里应该用〈打破〉。违背针对约定、规则，记录是用来超越的，应说打破记录。"}, {"text": "他昨天晚上违背了一本小说。", "explanation": "这里应该用〈读〉。违背针对的是约定、规则、要求，小说不是规则，应说读了一本小说。"}, {"text": "他违背了老师的字迹，把每一笔都照着描了一遍。", "explanation": "这里应该用〈临摹〉。违背针对约定、规则、要求，不能用于字迹；照着字迹写一遍要用〈临摹〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '81cf0d6c-ad07-44cf-a5e9-ede6f1da6fcb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24294, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他没有违背了老师的要求。", "corrected_sentence": "他没有违背老师的要求。", "error_description": "“了”误用：“没有”已经否定了动作，不能再加“了”。错误形式是“没有违背了”，正确形式是“没有违背”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '81cf0d6c-ad07-44cf-a5e9-ede6f1da6fcb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24294, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他曾经违背了过公司的规定。", "corrected_sentence": "他曾经违背过公司的规定。", "error_description": "“了”与“过”重复：“违背过”已经表示曾经有过的经历，不能再加“了”。错误形式是“违背了过”，正确形式是“违背过”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '81cf0d6c-ad07-44cf-a5e9-ede6f1da6fcb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
