INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24302, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "按照计划、命令或规定去做某件事。", "primary_collocate": null, "pronunciation": "zhí xíng", "ipa": "ʈʂʅ˧˥ ɕiŋ˧˥", "syllable_count": 2, "sentences": [{"text": "工人们认真执行经理的计划。", "target_word": "执行", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "警察执行任务时很小心。", "target_word": "执行", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们要执行学校的新规定。", "target_word": "执行", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个计划很好，但是很难执行。", "target_word": "执行", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他不执行老板的决定。", "target_word": "执行", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公司已经执行了新办法。", "target_word": "执行", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "大家都要执行这个规定。", "target_word": "执行", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "军人必须执行命令。", "target_word": "执行", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这次任务由他来执行。", "target_word": "执行", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "医院严格执行安全规定。", "target_word": "执行", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "执行了", "label": "体标"}, {"form": "执行过", "label": "体标"}, {"form": "执行着", "label": "体标"}, {"form": "執行", "label": "繁体"}], "register": "中性", "sense_fingerprint": "按照计划、命令或规定去做某件事", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '810ac7fa-1260-4d9e-be13-37017ce45fe6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24302, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "执行", "is_correct": true, "explanation": "正确：「执行计划」指按计划去做，与「认真」和「经理的计划」搭配，符合句意。"}, {"text": "吃", "is_correct": false, "explanation": "语义：计划不能被吃，「认真吃经理的计划」语义不通。"}, {"text": "唱", "is_correct": false, "explanation": "搭配：「唱」不与「计划」搭配，不能说唱计划。"}, {"text": "洗", "is_correct": false, "explanation": "搭配：「洗」不与「计划」搭配，不能说洗计划。"}], "explanations": {"执行": "正确：「执行计划」指按计划去做，与「认真」和「经理的计划」搭配，符合句意。", "吃": "语义：计划不能被吃，「认真吃经理的计划」语义不通。", "唱": "搭配：「唱」不与「计划」搭配，不能说唱计划。", "洗": "搭配：「洗」不与「计划」搭配，不能说洗计划。"}, "sentence_index": 0, "correct_answer": "执行"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我去银行执行了开户手续。", "explanation": "这里应该用〈办理〉。「执行」指按计划、规定去做，办理手续要用「办理」，不说「执行手续」。"}, {"text": "这位演员在舞台上执行得很精彩。", "explanation": "这里是「表演、演出」的意思，不是「执行」。「执行」只表示按计划、规定或命令去做某件事，不用于演出。"}, {"text": "我们明天执行一次体检。", "explanation": "这里应该用〈进行〉。「执行」搭配计划、规定、命令，体检等活动要用「进行」。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '792dd777-1725-4a90-833e-a1a265eb0b88') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24302, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "执行", "is_correct": true, "explanation": "正确：「执行这个规定」指照规定去做，与「大家都要」的要求一致。"}, {"text": "画", "is_correct": false, "explanation": "搭配：「画」不能与「规定」搭配，不能说画规定。"}, {"text": "扔", "is_correct": false, "explanation": "搭配：「扔」不能与「规定」搭配，不能说扔规定。"}, {"text": "喝", "is_correct": false, "explanation": "搭配：「喝」不能与「规定」搭配，语义不通。"}], "explanations": {"执行": "正确：「执行这个规定」指照规定去做，与「大家都要」的要求一致。", "画": "搭配：「画」不能与「规定」搭配，不能说画规定。", "扔": "搭配：「扔」不能与「规定」搭配，不能说扔规定。", "喝": "搭配：「喝」不能与「规定」搭配，语义不通。"}, "sentence_index": 6, "correct_answer": "执行"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我们执行了一次郊游，大家都很开心。", "explanation": "这里应该用〈组织〉。「执行」用于计划、规定或命令，组织郊游要用「组织」，不说「执行郊游」。"}, {"text": "学校执行了一场运动会，全校都来参加。", "explanation": "这里应该用〈举办〉。「执行」用于计划、规定或命令，举办运动会要用「举办」，不说「执行运动会」。"}, {"text": "他去学校执行了奖学金，很开心。", "explanation": "这里应该用〈领取〉。「执行」指按规定去做，领取奖学金要用「领取」，不说「执行奖学金」。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '792dd777-1725-4a90-833e-a1a265eb0b88') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24302, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这个计划我们执行很好。", "corrected_sentence": "这个计划我们执行得很好。", "error_description": "错误在于程度补语缺少结构助词「得」：动词「执行」后接程度补语时须用「得」连接，应说「执行得很好」，不能说「执行很好」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '792dd777-1725-4a90-833e-a1a265eb0b88') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24302, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他已经把计划执行。", "corrected_sentence": "他已经把计划执行完了。", "error_description": "补语缺失：「把」字句中的动词后要有补语或「了」等成分，应说「把计划执行完了」，不能只说「把计划执行」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '792dd777-1725-4a90-833e-a1a265eb0b88') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
