INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24306, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "抬头和低头，比如人一会儿看天一会儿看地。", "primary_collocate": null, "pronunciation": "fǔ yǎng", "ipa": "fu˨˩˦ jɑŋ˨˩˦", "syllable_count": 2, "sentences": [{"text": "他站在山顶，俯仰天地，心里很平静。", "target_word": "俯仰", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "医生让我做几次头部俯仰的动作。", "target_word": "俯仰", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小鸡吃米时，头不停地俯仰。", "target_word": "俯仰", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老人的头随着音乐轻轻俯仰。", "target_word": "俯仰", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他一会儿看黑板，一会儿看本子，头不停俯仰。", "target_word": "俯仰", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子躺在草地上，随着云朵的移动，头不停地俯仰。", "target_word": "俯仰", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "做颈部运动时，要慢慢俯仰，不要太快。", "target_word": "俯仰", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "啄木鸟的头一直在俯仰，不停地啄树。", "target_word": "俯仰", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他坐在车里，头随着车的晃动俯仰着。", "target_word": "俯仰", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "河边的白鹭俯仰着，一会儿喝水一会儿看天。", "target_word": "俯仰", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "俯仰着", "label": "体标"}, {"form": "俯仰了", "label": "体标"}, {"form": "俯仰角", "label": "复合"}], "register": "书面", "sense_fingerprint": "俯仰|头部一低一抬的动作", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '91d27849-f17d-475a-ae9e-30e433cef473') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24306, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "俯仰", "is_correct": true, "explanation": "正确：「俯仰天地」指抬头看天、低头看地，与站在山顶的环境相符。"}, {"text": "修剪", "is_correct": false, "explanation": "语义：「修剪」指剪去多余的枝叶，用于天地不合语境。"}, {"text": "打扫", "is_correct": false, "explanation": "语义：「打扫」指清除脏物，用于天地没有意义。"}, {"text": "喂养", "is_correct": false, "explanation": "搭配：「喂养」只用于生物，不能搭配「天地」。"}], "explanations": {"俯仰": "正确：「俯仰天地」指抬头看天、低头看地，与站在山顶的环境相符。", "修剪": "语义：「修剪」指剪去多余的枝叶，用于天地不合语境。", "打扫": "语义：「打扫」指清除脏物，用于天地没有意义。", "喂养": "搭配：「喂养」只用于生物，不能搭配「天地」。"}, "sentence_index": 0, "correct_answer": "俯仰"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他俯仰着向左右张望，没有说话。", "explanation": "这里应该用〈转头〉。「俯仰」指头部上下低抬，左右转动要用〈转头〉。"}, {"text": "老人随着音乐轻轻俯仰着双脚。", "explanation": "这里应该用〈踩〉。俯仰指头部一低一抬，不能用于脚的动作。"}, {"text": "他俯仰着说不行。", "explanation": "这里应该用〈摇头〉。俯仰指头部上下低抬，表示否定要左右摇头，不能用俯仰。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6359f1c4-dd0c-4ea1-88f1-4a5a819f84de') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24306, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "俯仰", "is_correct": true, "explanation": "正确：「慢慢俯仰」指头部缓慢地低抬，与颈部运动相符。"}, {"text": "弹奏", "is_correct": false, "explanation": "搭配：「弹奏」需要乐器作对象，不能用于颈部运动。"}, {"text": "游泳", "is_correct": false, "explanation": "语义：「游泳」是在水中划动身体，与颈部运动的情境不合。"}, {"text": "书写", "is_correct": false, "explanation": "语义：「书写」是写字，与做颈部运动无关。"}], "explanations": {"俯仰": "正确：「慢慢俯仰」指头部缓慢地低抬，与颈部运动相符。", "弹奏": "搭配：「弹奏」需要乐器作对象，不能用于颈部运动。", "游泳": "语义：「游泳」是在水中划动身体，与颈部运动的情境不合。", "书写": "语义：「书写」是写字，与做颈部运动无关。"}, "sentence_index": 6, "correct_answer": "俯仰"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "小猫一俯仰跳上了窗台。", "explanation": "这里应该用〈纵身〉。俯仰指头部一低一抬，不能描述整个身体跃起。"}, {"text": "她轻轻俯仰手，向我挥手告别。", "explanation": "这里应该用〈摆〉。俯仰只指头部上下低抬，不能用于手的动作，手的摆动要用〈摆〉。"}, {"text": "白鹭俯仰着翅膀飞走了。", "explanation": "这里应该用〈扇动〉。俯仰指头部上下低抬，翅膀的动作要用〈扇动〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6359f1c4-dd0c-4ea1-88f1-4a5a819f84de') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24306, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "小鸡吃米时，头俯仰地很快。", "corrected_sentence": "小鸡吃米时，头俯仰得很快。", "error_description": "「地」误用。「俯仰」后带程度补语「很快」时须用「得」，不用「地」，应为「俯仰得很快」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6359f1c4-dd0c-4ea1-88f1-4a5a819f84de') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24306, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "小鸭子在水里俯仰了觅食。", "corrected_sentence": "小鸭子在水里俯仰着觅食。", "error_description": "体标误用。表示动作持续进行要在「俯仰」后用「着」，不能用「了」，应说「俯仰着觅食」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6359f1c4-dd0c-4ea1-88f1-4a5a819f84de') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
