INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24308, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ff311b2a-2373-4426-b094-f398ef626907') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24308, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "飞机或船走错了方向。", "primary_collocate": null, "pronunciation": "piān háng", "ipa": "pʰiɛn˥ xɑŋ˧˥", "syllable_count": 2, "sentences": [{"text": "飞机偏航了，塔台马上通知飞行员。", "target_word": "偏航", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "船在大海上偏航，船长一直没发现。", "target_word": "偏航", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "天黑以后，小船偏航了很远。", "target_word": "偏航", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "船长看错了地图，轮船就偏航了。", "target_word": "偏航", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这架飞机为什么偏航？因为指南针坏了。", "target_word": "偏航", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "渔船遇到大风，偏航到了别的海域。", "target_word": "偏航", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他开的游艇偏航了，差点撞上礁石。", "target_word": "偏航", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "飞行员发现飞机偏航，赶紧回到原来的方向。", "target_word": "偏航", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "雾太大，船长看不见灯塔，船偏航了。", "target_word": "偏航", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "方向舵坏了，飞机一直向右偏航。", "target_word": "偏航", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "偏航了", "label": "体标（了）"}, {"form": "偏航过", "label": "体标（过）"}, {"form": "偏航角", "label": "复合词"}], "register": "中性", "sense_fingerprint": "飞机或船走错方向", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c66931b5-dcfc-499a-a2a1-727dbdea5a01') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24308, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "偏航", "is_correct": true, "explanation": "正确：飞机偏离航线，塔台通知飞行员。"}, {"text": "充电", "is_correct": false, "explanation": "语义：“充电”与飞机偏离航线无关，不能描述飞机的这种状态。"}, {"text": "发芽", "is_correct": false, "explanation": "语义：“发芽”指植物长出新芽，与飞机偏离航线无关，不能用于飞机。"}, {"text": "停课", "is_correct": false, "explanation": "语义：“停课”指学校停止上课，不能用于飞机。"}], "explanations": {"偏航": "正确：飞机偏离航线，塔台通知飞行员。", "充电": "语义：“充电”与飞机偏离航线无关，不能描述飞机的这种状态。", "发芽": "语义：“发芽”指植物长出新芽，与飞机偏离航线无关，不能用于飞机。", "停课": "语义：“停课”指学校停止上课，不能用于飞机。"}, "sentence_index": 0, "correct_answer": "偏航"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他在山里偏航了，找不到回家的路。", "explanation": "这里应该用〈迷路〉。偏航只用于飞机、船只偏离航线，人在陆地上走错路说迷路。"}, {"text": "火车因为大雾偏航了，比原定时间晚到。", "explanation": "这里应该用〈误点〉。偏航专指飞机、船只偏离航线，火车晚到用误点。"}, {"text": "他因为堵车偏航了，错过了会议。", "explanation": "这里应该用〈迟到〉。偏航不用于人的时间延误，赶不上会议说迟到。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ff311b2a-2373-4426-b094-f398ef626907') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24308, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "偏航", "is_correct": true, "explanation": "正确：游艇偏离航线，差点撞上礁石。"}, {"text": "发霉", "is_correct": false, "explanation": "语义：“发霉”指物品长霉，与撞上礁石的情境无关。"}, {"text": "褪色", "is_correct": false, "explanation": "语义：“褪色”指颜色变淡，不能解释游艇差点撞上礁石。"}, {"text": "降价", "is_correct": false, "explanation": "搭配：“降价”指商品价格下降，不能用于描述游艇的运行状态。"}], "explanations": {"偏航": "正确：游艇偏离航线，差点撞上礁石。", "发霉": "语义：“发霉”指物品长霉，与撞上礁石的情境无关。", "褪色": "语义：“褪色”指颜色变淡，不能解释游艇差点撞上礁石。", "降价": "搭配：“降价”指商品价格下降，不能用于描述游艇的运行状态。"}, "sentence_index": 6, "correct_answer": "偏航"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "饼干在盘子里偏航了，挪到了盘边。", "explanation": "这里应该用〈挪动〉。偏航只用于飞机、船只偏离航线，饼干在盘子里挪位置应说挪动。"}, {"text": "画框偏航了，我把它扶正了。", "explanation": "这里应该用〈歪〉。偏航只用于飞机、船只，挂在墙上的画框歪了说歪。"}, {"text": "书从桌上偏航到了地上。", "explanation": "这里应该用〈滑落〉。偏航用于航行器，书本从桌上掉落说滑落。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ff311b2a-2373-4426-b094-f398ef626907') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24308, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "渔船在雾里偏航的很远，船员用罗盘重新定位。", "corrected_sentence": "渔船在雾里偏航得很远，船员用罗盘重新定位。", "error_description": "错误：补语标记用了“的”（偏航的很远）；正确：“得”。“得”引出动词后的状态补语，“的”不能接在动词之后。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ff311b2a-2373-4426-b094-f398ef626907') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24308, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "游艇没偏航了，一直按原定航线行驶。", "corrected_sentence": "游艇没偏航，一直按原定航线行驶。", "error_description": "错误：否定句中用了“了”（没偏航了）；正确：“没偏航”，否定已发生的动作不带“了”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ff311b2a-2373-4426-b094-f398ef626907') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
