INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24310, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "去寻找、了解未知的事物。", "primary_collocate": null, "pronunciation": "tàn suǒ", "ipa": "tʰan˥˩ suo˨˩˦", "syllable_count": 2, "sentences": [{"text": "孩子喜欢探索新的地方。", "target_word": "探索", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "科学家正在探索海底的秘密。", "target_word": "探索", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们想探索这座山里有什么。", "target_word": "探索", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他用手电筒探索黑黑的山洞。", "target_word": "探索", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小狗在花园里探索了很久。", "target_word": "探索", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "人们一直在探索太空。", "target_word": "探索", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "暑假里，我们去森林探索自然。", "target_word": "探索", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他喜欢一个人探索陌生的城市。", "target_word": "探索", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们想去探索大海深处的世界。", "target_word": "探索", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这位老人探索过很多山洞。", "target_word": "探索", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "探索了", "label": "体标"}, {"form": "探索着", "label": "体标"}, {"form": "探索过", "label": "体标"}], "register": "中性", "sense_fingerprint": "寻找、了解未知的事物", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cca8c494-ae71-4330-9c72-7312641af8a3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24310, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "探索", "is_correct": true, "explanation": "正确：探索指去了解未知的事物，与“新的地方”相符。"}, {"text": "逃避", "is_correct": false, "explanation": "语义：“逃避”表示躲开，与“喜欢”相抵触。"}, {"text": "忘记", "is_correct": false, "explanation": "搭配：“忘记”的宾语多为事情或内容，不说“忘记新的地方”。"}, {"text": "讨厌", "is_correct": false, "explanation": "语义：“讨厌”与“喜欢”意思相反，句子自相矛盾。"}], "explanations": {"探索": "正确：探索指去了解未知的事物，与“新的地方”相符。", "逃避": "语义：“逃避”表示躲开，与“喜欢”相抵触。", "忘记": "搭配：“忘记”的宾语多为事情或内容，不说“忘记新的地方”。", "讨厌": "语义：“讨厌”与“喜欢”意思相反，句子自相矛盾。"}, "sentence_index": 0, "correct_answer": "探索"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "周末，我去医院探索生病的奶奶。", "explanation": "这里应该用〈探望〉。探望是去看望人，探索是去了解未知的事物，不能用于人。"}, {"text": "孩子在草丛里探索掉落的钥匙。", "explanation": "这里应该用〈寻找〉。寻找指找已经丢失的东西，探索针对尚未了解的事物，丢失的钥匙是已知物品，不说探索。"}, {"text": "这个仪器用来探索室外的温度。", "explanation": "这里应该用〈探测〉。探测是用仪器测量数据，探索是人去了解未知事物，不说探索温度。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1c111ab3-6829-4c95-9540-89a478329293') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24310, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "探索", "is_correct": true, "explanation": "正确：探索指去了解未知的事物，与“森林”和“自然”的语境相符。"}, {"text": "破坏", "is_correct": false, "explanation": "语义：“破坏”指毁坏，与暑假去森林游玩的意图相抵触。"}, {"text": "污染", "is_correct": false, "explanation": "语义：“污染”指使环境受害，与去森林的美好意图相抵触。"}, {"text": "修剪", "is_correct": false, "explanation": "搭配：“修剪”的对象是植物或枝叶，不说“修剪自然”。"}], "explanations": {"探索": "正确：探索指去了解未知的事物，与“森林”和“自然”的语境相符。", "破坏": "语义：“破坏”指毁坏，与暑假去森林游玩的意图相抵触。", "污染": "语义：“污染”指使环境受害，与去森林的美好意图相抵触。", "修剪": "搭配：“修剪”的对象是植物或枝叶，不说“修剪自然”。"}, "sentence_index": 6, "correct_answer": "探索"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我探索了已经背熟的课文。", "explanation": "这里应该用〈背〉。背指凭记忆诵读；探索指了解未知的事物，课文已经背熟，不说探索。"}, {"text": "消防员探索了被困的人。", "explanation": "这里应该用〈救出〉。救出是把人带离危险，探索不能用于救人。"}, {"text": "他用眼睛探索了桌上的水杯，水杯就放在他面前。", "explanation": "这里应该用〈看〉。看是用眼睛注视眼前的东西，探索指找不知道的东西，水杯就在面前，不用探索。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1c111ab3-6829-4c95-9540-89a478329293') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24310, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他曾经探索了过很多未知的岛屿。", "corrected_sentence": "他曾经探索过很多未知的岛屿。", "error_description": "“探索过”已用“过”表示经历，不能再加“了”；应说“曾经探索过”，不说“曾经探索了过”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1c111ab3-6829-4c95-9540-89a478329293') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24310, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "航天员们将要把探索火星的环境。", "corrected_sentence": "航天员们将要探索火星的环境。", "error_description": "“把”字句中，“把”须紧接受处置的名词性宾语；本句“把”后直接接动词短语“探索火星的环境”，结构不成立，应删去“把”，说“将要探索火星的环境”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1c111ab3-6829-4c95-9540-89a478329293') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
