INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24316, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "身体或东西转圈。", "primary_collocate": null, "pronunciation": "gǔn zhuǎn", "ipa": "kuən˨˩˦ ʈʂuan˨˩˦", "syllable_count": 2, "sentences": [{"text": "石磙在地面上缓缓滚转，把新铺的路压平。", "target_word": "滚转", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "滚筒在电机带动下持续滚转，衣物被翻来覆去地搅动。", "target_word": "滚转", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "车轮沿着泥泞的小路缓缓滚转，溅起不少泥点。", "target_word": "滚转", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "圆木在林间的斜坡上一路滚转，发出沉闷的声响。", "target_word": "滚转", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "硬币掉在桌面上，滚转了几圈才停下。", "target_word": "滚转", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "石球在凹槽里来回滚转，慢慢停了下来。", "target_word": "滚转", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "轮胎在平地上匀速滚转，发出轻微的摩擦声。", "target_word": "滚转", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "碎石在河床上被水流冲得不断滚转。", "target_word": "滚转", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "水轮在水流的冲击下不停滚转。", "target_word": "滚转", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "木桶在地上滚转着向前，发出咕噜咕噜的响声。", "target_word": "滚转", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "滚转了", "label": "体标（了）"}, {"form": "滚转着", "label": "体标（着）"}, {"form": "滚转过", "label": "体标（过）"}], "register": "中性", "sense_fingerprint": "身体或物体一边转圈一边翻动", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c66931b5-dcfc-499a-a2a1-727dbdea5a01') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24316, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "滚转", "is_correct": true, "explanation": "正确：石磙在地面上转圈前进，把路压平。"}, {"text": "飞起", "is_correct": false, "explanation": "语义：“飞起”指离开地面，与“在地面上缓缓”矛盾。"}, {"text": "倒塌", "is_correct": false, "explanation": "语义：“倒塌”指倒下垮掉，石磙不会因此把路压平。"}, {"text": "吊起", "is_correct": false, "explanation": "搭配：“吊起”需外力提起，与“在地面上缓缓”的运动状态不搭配。"}], "explanations": {"滚转": "正确：石磙在地面上转圈前进，把路压平。", "飞起": "语义：“飞起”指离开地面，与“在地面上缓缓”矛盾。", "倒塌": "语义：“倒塌”指倒下垮掉，石磙不会因此把路压平。", "吊起": "搭配：“吊起”需外力提起，与“在地面上缓缓”的运动状态不搭配。"}, "sentence_index": 0, "correct_answer": "滚转"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "大楼在风里一阵阵地滚转，窗户震得直响。", "explanation": "这里应该用〈摇晃〉。滚转指物体绕自身转圈翻动，大楼左右晃动应说摇晃。"}, {"text": "箱子被推着在地上滚转，发出刺耳的声音。", "explanation": "这里应该用〈移动〉。滚转指物体绕自身轴转圈翻动，箱子被推着平移只说移动。"}, {"text": "水龙头被拧得滚转起来。", "explanation": "这里应该用〈旋转〉。滚转强调翻动，拧水龙头这种原地转动用旋转。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ff311b2a-2373-4426-b094-f398ef626907') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24316, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "滚转", "is_correct": true, "explanation": "正确：轮胎在平地上转圈匀速运动，发出摩擦声。"}, {"text": "悬停", "is_correct": false, "explanation": "语义：“悬停”指停在空中不动，与“在平地上匀速”矛盾。"}, {"text": "凝固", "is_correct": false, "explanation": "语义：“凝固”指液体变硬，与轮胎的运动状态不符。"}, {"text": "叠放", "is_correct": false, "explanation": "搭配：“叠放”是把物体堆起来，不能与“匀速”搭配表示运动。"}], "explanations": {"滚转": "正确：轮胎在平地上转圈匀速运动，发出摩擦声。", "悬停": "语义：“悬停”指停在空中不动，与“在平地上匀速”矛盾。", "凝固": "语义：“凝固”指液体变硬，与轮胎的运动状态不符。", "叠放": "搭配：“叠放”是把物体堆起来，不能与“匀速”搭配表示运动。"}, "sentence_index": 6, "correct_answer": "滚转"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "钟摆在墙上左右滚转，发出滴答的声音。", "explanation": "这里应该用〈摆动〉。钟摆左右来回摆动，不是转圈翻动，应说摆动。"}, {"text": "窗帘在风里不停滚转，像在跳舞。", "explanation": "这里应该用〈飘动〉。滚转指物体转圈翻动，窗帘随风起伏应说飘动。"}, {"text": "电梯在楼层间滚转，直到顶楼才停下。", "explanation": "这里应该用〈升降〉。滚转指物体转圈翻动，电梯上下运行不说滚转。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ff311b2a-2373-4426-b094-f398ef626907') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24316, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "石球顺着凹槽滚转的很慢，停在了脚边。", "corrected_sentence": "石球顺着凹槽滚转得很慢，停在了脚边。", "error_description": "错误：状态补语标记用了“的”（滚转的很慢）；正确：“得”。“滚转得很慢”中“得”引出补语，“的”不能接在动词后。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ff311b2a-2373-4426-b094-f398ef626907') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24316, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "木球在斜面上滚转了三个，停在了洞口。", "corrected_sentence": "木球在斜面上滚转了三圈，停在了洞口。", "error_description": "错误：动量词用了“个”；正确：“圈”。“滚转”计量转动次数用“圈”，不能用“个”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ff311b2a-2373-4426-b094-f398ef626907') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
