INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24318, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "每个都不一样。", "primary_collocate": null, "pronunciation": "gè yì", "ipa": "kɤ˥˩ i˥˩", "syllable_count": 2, "sentences": [{"text": "这五个孩子的身高各异。", "target_word": "各异", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "桌上的杯子大小各异。", "target_word": "各异", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们班同学的家乡各异。", "target_word": "各异", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公园里的树高矮各异。", "target_word": "各异", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这些帽子的样式各异，我都很喜欢。", "target_word": "各异", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们三个人的职业各异，有医生、老师和司机。", "target_word": "各异", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "书架上的书厚薄各异。", "target_word": "各异", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "三个房间的布置各异。", "target_word": "各异", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这些小狗的毛色各异。", "target_word": "各异", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "路边的灯形状各异，晚上很好看。", "target_word": "各异", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "书面", "sense_fingerprint": "一个个都不一样，多作谓语，书面语", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f4f8477c-c623-4811-8372-e8a5d9f6c5fc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24318, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "各异", "is_correct": true, "explanation": "正确：“各异”指每个都不一样，与“身高”各不相同的意思相符。"}, {"text": "千篇一律", "is_correct": false, "explanation": "语义：“千篇一律”指彼此没有差别，与“身高各异”的意思相反。"}, {"text": "五花八门", "is_correct": false, "explanation": "搭配：“五花八门”多形容种类，不说身高五花八门。"}, {"text": "单一", "is_correct": false, "explanation": "搭配：“单一”多形容种类或内容，不说身高单一。"}], "explanations": {"各异": "正确：“各异”指每个都不一样，与“身高”各不相同的意思相符。", "千篇一律": "语义：“千篇一律”指彼此没有差别，与“身高各异”的意思相反。", "五花八门": "搭配：“五花八门”多形容种类，不说身高五花八门。", "单一": "搭配：“单一”多形容种类或内容，不说身高单一。"}, "sentence_index": 0, "correct_answer": "各异"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这些树的高度都各异，都是三米。", "explanation": "这里应该用〈相同〉。“各异”说彼此不同，与“都是三米”相矛盾；说高度一样时要用〈相同〉。"}, {"text": "我一个人的身高各异。", "explanation": "这里应该直接说〈一米七〉这样的具体数值。“各异”要求多个人或事物彼此比较，只说一个人的身高时不用“各异”。"}, {"text": "孩子们在公园里各异地玩耍。", "explanation": "这里应该用〈各自〉。“各异”说的是事物之间彼此不同，不表示“每人分开做某事”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '73b6de39-9b1c-4462-afcd-62cb8c028ff7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24318, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "各异", "is_correct": true, "explanation": "正确：“各异”指每本书的厚薄都不一样，与句意相符。"}, {"text": "明亮", "is_correct": false, "explanation": "搭配：“明亮”说光线或颜色，不能用来形容书的厚薄。"}, {"text": "热烈", "is_correct": false, "explanation": "搭配：“热烈”说气氛或情绪，不能修饰书的厚薄。"}, {"text": "高大", "is_correct": false, "explanation": "体貌：“高大”形容人或物的体型，书的厚薄不说高大。"}], "explanations": {"各异": "正确：“各异”指每本书的厚薄都不一样，与句意相符。", "明亮": "搭配：“明亮”说光线或颜色，不能用来形容书的厚薄。", "热烈": "搭配：“热烈”说气氛或情绪，不能修饰书的厚薄。", "高大": "体貌：“高大”形容人或物的体型，书的厚薄不说高大。"}, "sentence_index": 6, "correct_answer": "各异"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "路边的灯各异地亮着，很整齐。", "explanation": "这里应该用〈各自〉。“各异”说的是事物之间彼此不同，不表示“每盏灯分开亮着”。"}, {"text": "这盏灯的形状各异。", "explanation": "这里应该用〈独特〉。“各异”要求多个对象彼此比较，只说一盏灯的形状时用“独特”，不用“各异”。"}, {"text": "我把路边的花各异了。", "explanation": "这里应该用〈分开〉。“各异”是形容词，表示状态，不能带宾语，也不能用于“把”字句；要说把花分开，用〈分开〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '73b6de39-9b1c-4462-afcd-62cb8c028ff7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24318, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这三幅画的风格很各异。", "corrected_sentence": "这三幅画的风格各异。", "error_description": "错误：“很各异”。正确：“各异”。“各异”本身已表示各不相同，是描述状态的形容词，前面不能加程度副词“很”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '73b6de39-9b1c-4462-afcd-62cb8c028ff7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24318, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这三间教室的布置正在各异。", "corrected_sentence": "这三间教室的布置各异。", "error_description": "错误：“正在各异”。正确：“各异”。“正在”表示动作进行，“各异”是描述状态的形容词，不能用进行体。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '73b6de39-9b1c-4462-afcd-62cb8c028ff7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24320, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "起飞", "is_correct": true, "explanation": "正确：“起飞”与“降落”互为反义，指飞机从地面飞上天。"}, {"text": "坐下", "is_correct": false, "explanation": "坐下指臀部着座，与“降落”没有反义关系。"}, {"text": "休息", "is_correct": false, "explanation": "休息指停止劳动或活动，与“降落”不构成反义。"}, {"text": "睡觉", "is_correct": false, "explanation": "睡觉指入睡，与“降落”没有反义关系。"}], "correct_answer": "起飞", "explanations": {"起飞": "正确：“起飞”与“降落”互为反义，指飞机从地面飞上天。", "坐下": "坐下指臀部着座，与“降落”没有反义关系。", "休息": "休息指停止劳动或活动，与“降落”不构成反义。", "睡觉": "睡觉指入睡，与“降落”没有反义关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ff311b2a-2373-4426-b094-f398ef626907') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24320, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "起飞", "is_correct": true, "explanation": "正确：“起飞”与“降落”互为反义，指飞机从地面飞上天。"}, {"text": "漫步", "is_correct": false, "explanation": "漫步指悠闲地走，与“降落”不构成反义。"}, {"text": "游水", "is_correct": false, "explanation": "游水指在水里游动，与“降落”不构成反义。"}, {"text": "慢跑", "is_correct": false, "explanation": "慢跑指慢速跑步，与“降落”不构成反义。"}], "correct_answer": "起飞", "explanations": {"起飞": "正确：“起飞”与“降落”互为反义，指飞机从地面飞上天。", "漫步": "漫步指悠闲地走，与“降落”不构成反义。", "游水": "游水指在水里游动，与“降落”不构成反义。", "慢跑": "慢跑指慢速跑步，与“降落”不构成反义。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ff311b2a-2373-4426-b094-f398ef626907') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24320, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "从天上下来。", "primary_collocate": null, "pronunciation": "jiàng luò", "ipa": "tɕjaŋ⁵¹ lwo⁵¹", "syllable_count": 2, "sentences": [{"text": "飞机从天上降落，大家都鼓掌。", "target_word": "降落", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小飞机降落在田边的小路上。", "target_word": "降落", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "降落以前，飞行员一直看着前面。", "target_word": "降落", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "白色的热气球慢慢降落了。", "target_word": "降落", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们的飞机十二点降落在广州。", "target_word": "降落", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "飞机降落的时候，我有点紧张。", "target_word": "降落", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请问，飞机几点降落？", "target_word": "降落", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "跳伞的人安全降落了，大家都很高兴。", "target_word": "降落", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "大雨让飞机不能降落，只好去别的机场。", "target_word": "降落", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "飞机降落后，我给妈妈打了电话。", "target_word": "降落", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "降落了", "label": "体标"}, {"form": "降落过", "label": "体标"}, {"form": "降落伞", "label": "复合"}], "register": "通用", "sense_fingerprint": "通俗说法：飞机等从天上下来，落到地上", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c66931b5-dcfc-499a-a2a1-727dbdea5a01') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24320, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "降落", "is_correct": true, "explanation": "正确：“降落”指从天上下来，与“从天上”及大家鼓掌的场景相符。"}, {"text": "下楼", "is_correct": false, "explanation": "搭配：“下楼”指人从楼上走下来，不能用于从天上下来的飞机。"}, {"text": "游泳", "is_correct": false, "explanation": "搭配：“游泳”指在水中活动，不用于从天上下来的飞机。"}, {"text": "熄灭", "is_correct": false, "explanation": "语义：“熄灭”指火或灯灭掉，与“从天上下来”不符。"}], "explanations": {"降落": "正确：“降落”指从天上下来，与“从天上”及大家鼓掌的场景相符。", "下楼": "搭配：“下楼”指人从楼上走下来，不能用于从天上下来的飞机。", "游泳": "搭配：“游泳”指在水中活动，不用于从天上下来的飞机。", "熄灭": "语义：“熄灭”指火或灯灭掉，与“从天上下来”不符。"}, "sentence_index": 0, "correct_answer": "降落"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "气温慢慢降落到零度。", "explanation": "这里应该用〈下降〉。降落指从天上下来，气温变化要说下降。"}, {"text": "汽车降落在路边。", "explanation": "这里应该用〈停车〉。降落指从天上下来，车辆停下要说停车。"}, {"text": "他的成绩降落了，妈妈很着急。", "explanation": "这里应该用〈降低〉。降落只指从天上下来，成绩下滑要说降低。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ff311b2a-2373-4426-b094-f398ef626907') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24320, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "降落", "is_correct": true, "explanation": "正确：“降落”指飞机落地，与询问“几点降落”的语境相符。"}, {"text": "下课", "is_correct": false, "explanation": "搭配：“下课”指学校结束上课，不用于飞机。"}, {"text": "放学", "is_correct": false, "explanation": "搭配：“放学”指学生离开学校，飞机不说放学。"}, {"text": "沉没", "is_correct": false, "explanation": "语义：“沉没”指沉入水中，与询问飞机何时落地的语境不符。"}], "explanations": {"降落": "正确：“降落”指飞机落地，与询问“几点降落”的语境相符。", "下课": "搭配：“下课”指学校结束上课，不用于飞机。", "放学": "搭配：“放学”指学生离开学校，飞机不说放学。", "沉没": "语义：“沉没”指沉入水中，与询问飞机何时落地的语境不符。"}, "sentence_index": 6, "correct_answer": "降落"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "小李下午五点降落了，才离开办公室。", "explanation": "这里应该用〈下班〉。降落只指从天上下来，人结束工作离开单位要说下班。"}, {"text": "比赛终于降落了。", "explanation": "这里应该用〈结束〉。降落只指从天上下来，比赛结束要说结束。"}, {"text": "他的心情降落了，一整天都不说话。", "explanation": "这里应该用〈低落〉。降落只指从天上下来，形容情绪低沉要说低落。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ff311b2a-2373-4426-b094-f398ef626907') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24320, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "一架小飞机降落了在田边。", "corrected_sentence": "一架小飞机降落在田边。", "error_description": "错误：“了”位置不当，夹在“降落”和“在田边”之间。“降落在田边”后不加“了”，应删去“了”，说“一架小飞机降落在田边。”", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ff311b2a-2373-4426-b094-f398ef626907') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24320, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "飞机降落了乘客，乘客们纷纷站了起来。", "corrected_sentence": "飞机降落了，乘客们纷纷站了起来。", "error_description": "错误：“降落”是不及物动词，不能直接带宾语“乘客”。应说“飞机降落了，乘客们纷纷站了起来。”", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ff311b2a-2373-4426-b094-f398ef626907') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24322, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "降落", "is_correct": true, "explanation": "正确：“降落”与“起飞”互为反义，指飞机落回地面。"}, {"text": "坐下", "is_correct": false, "explanation": "坐下指臀部着座，与“起飞”没有反义关系。"}, {"text": "休息", "is_correct": false, "explanation": "休息指停止劳动或活动，与“起飞”不构成反义。"}, {"text": "睡觉", "is_correct": false, "explanation": "睡觉指入睡，与“起飞”没有反义关系。"}], "correct_answer": "降落", "explanations": {"降落": "正确：“降落”与“起飞”互为反义，指飞机落回地面。", "坐下": "坐下指臀部着座，与“起飞”没有反义关系。", "休息": "休息指停止劳动或活动，与“起飞”不构成反义。", "睡觉": "睡觉指入睡，与“起飞”没有反义关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ff311b2a-2373-4426-b094-f398ef626907') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24322, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "降落", "is_correct": true, "explanation": "正确：“降落”与“起飞”互为反义，指飞机落回地面。"}, {"text": "漫步", "is_correct": false, "explanation": "漫步指悠闲地走，与“起飞”不构成反义。"}, {"text": "游水", "is_correct": false, "explanation": "游水指在水里游动，与“起飞”不构成反义。"}, {"text": "慢跑", "is_correct": false, "explanation": "慢跑指慢速跑步，与“起飞”不构成反义。"}], "correct_answer": "降落", "explanations": {"降落": "正确：“降落”与“起飞”互为反义，指飞机落回地面。", "漫步": "漫步指悠闲地走，与“起飞”不构成反义。", "游水": "游水指在水里游动，与“起飞”不构成反义。", "慢跑": "慢跑指慢速跑步，与“起飞”不构成反义。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ff311b2a-2373-4426-b094-f398ef626907') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24322, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "飞机从地面飞上天。", "primary_collocate": null, "pronunciation": "qǐ fēi", "ipa": "tɕʰi²¹⁴ fei⁵⁵", "syllable_count": 2, "sentences": [{"text": "飞机已经起飞了，现在在天上。", "target_word": "起飞", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "起飞时，飞机的速度越来越快。", "target_word": "起飞", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们的飞机十点起飞，九点要到机场。", "target_word": "起飞", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "飞机起飞以后，我看见城市变小了。", "target_word": "起飞", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "飞机在跑道尽头慢慢转弯，准备起飞。", "target_word": "起飞", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "飞行员说，飞机五分钟后起飞。", "target_word": "起飞", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "大雾散了以后，第一架飞机起飞了。", "target_word": "起飞", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "起飞的时候，我的耳朵有点不舒服。", "target_word": "起飞", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "飞机还没起飞，请把手机关掉。", "target_word": "起飞", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "今天风太大，所有的飞机都不能起飞。", "target_word": "起飞", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "起飞了", "label": "体标"}, {"form": "起飞过", "label": "体标"}, {"form": "起飞线", "label": "复合"}], "register": "通用", "sense_fingerprint": "飞机离开地面，飞上天空", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c66931b5-dcfc-499a-a2a1-727dbdea5a01') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24322, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "起飞", "is_correct": true, "explanation": "正确：“起飞”指飞机离开地面，与“现在在天上”的状态相衔接。"}, {"text": "降落", "is_correct": false, "explanation": "语义：“降落”是从空中落回地面，与“现在在天上”矛盾。"}, {"text": "下课", "is_correct": false, "explanation": "搭配：“下课”指学校结束上课，不用于飞机。"}, {"text": "睡醒", "is_correct": false, "explanation": "搭配：“睡醒”只用于人或动物，飞机不能睡醒。"}], "explanations": {"起飞": "正确：“起飞”指飞机离开地面，与“现在在天上”的状态相衔接。", "降落": "语义：“降落”是从空中落回地面，与“现在在天上”矛盾。", "下课": "搭配：“下课”指学校结束上课，不用于飞机。", "睡醒": "搭配：“睡醒”只用于人或动物，飞机不能睡醒。"}, "sentence_index": 0, "correct_answer": "起飞"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "飞机在空中起飞了两个小时。", "explanation": "这里应该用〈飞行〉。起飞指离开地面的那一刻，不能表示持续两个小时。"}, {"text": "这辆公共汽车早上八点起飞。", "explanation": "这里应该用〈发车〉。起飞只用于飞机等飞行器离开地面，公共汽车开出要说发车。"}, {"text": "发动机终于起飞了。", "explanation": "这里应该用〈启动〉。发动机是启动，起飞指飞行器离开地面，不能用于发动机。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ff311b2a-2373-4426-b094-f398ef626907') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24322, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "起飞", "is_correct": true, "explanation": "正确：“起飞”指飞机离开地面，与“大雾散了以后”的时间顺序相符。"}, {"text": "迷路", "is_correct": false, "explanation": "搭配：“迷路”指人或动物找不到方向，飞机不说迷路。"}, {"text": "放学", "is_correct": false, "explanation": "搭配：“放学”指学生离开学校，不用于飞机。"}, {"text": "停飞", "is_correct": false, "explanation": "语义：“停飞”表示停止飞行，与“第一架飞机”在雾散后起飞的情形相反。"}], "explanations": {"起飞": "正确：“起飞”指飞机离开地面，与“大雾散了以后”的时间顺序相符。", "迷路": "搭配：“迷路”指人或动物找不到方向，飞机不说迷路。", "放学": "搭配：“放学”指学生离开学校，不用于飞机。", "停飞": "语义：“停飞”表示停止飞行，与“第一架飞机”在雾散后起飞的情形相反。"}, "sentence_index": 6, "correct_answer": "起飞"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "妹妹每天七点就起飞。", "explanation": "这里应该用〈起床〉。起飞用于飞机、火箭等飞行器，人醒来起身要说起床。"}, {"text": "这艘渔船明天凌晨起飞，去海上捕鱼。", "explanation": "这里应该用〈启航〉。起飞指飞行器离开地面，船只离岸出海要说启航。"}, {"text": "电梯从一楼起飞到十楼。", "explanation": "这里应该用〈上升〉。电梯在楼层之间运行，不是飞行器离地，要说上升。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ff311b2a-2373-4426-b094-f398ef626907') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24322, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我们的班机向杭州起飞。", "corrected_sentence": "我们的班机从杭州起飞。", "error_description": "错误：“向杭州起飞”。“向”表示朝某个方向去，而“起飞”的出发地要用“从”引出；正确的说法是“从杭州起飞”，“从杭州”表示起点。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ff311b2a-2373-4426-b094-f398ef626907') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24322, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "雾一散，第一架飞机就把起飞了。", "corrected_sentence": "雾一散，第一架飞机就起飞了。", "error_description": "错误：多了“把”。“把”字句要求“把”后接受事宾语，“起飞”是不及物动词，不能带受事，应删去“把”，说“雾一散，第一架飞机就起飞了。”", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ff311b2a-2373-4426-b094-f398ef626907') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
