INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24324, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "abstract", "definition": "说到最后，就是因为某一个原因。", "primary_collocate": null, "pronunciation": "guī jié wéi", "ipa": "kweɪ˥ tɕjɛ˧˥ weɪ˧˥", "syllable_count": 3, "sentences": [{"text": "说到底，这些问题都归结为一个字：钱。", "target_word": "归结为", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他迟到的原因，最后归结为起晚了。", "target_word": "归结为", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "比赛输了，大家把原因归结为天气太热。", "target_word": "归结为", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这次吵架归结为一件小事：谁洗碗。", "target_word": "归结为", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她的烦恼，说到底归结为没有时间。", "target_word": "归结为", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家店生意不好，归结为位置太差。", "target_word": "归结为", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子生病，妈妈把原因归结为自己没照顾好。", "target_word": "归结为", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们的矛盾，最终归结为互相不了解。", "target_word": "归结为", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这场事故的原因，归结为司机太累。", "target_word": "归结为", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的进步，可以归结为每天都练习。", "target_word": "归结为", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "书面", "sense_fingerprint": "说到底，原因就在某一点", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c66931b5-dcfc-499a-a2a1-727dbdea5a01') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24324, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "归结为", "is_correct": true, "explanation": "正确：归结为表示说到底落在某一个字上，与“说到底”相合。"}, {"text": "分为", "is_correct": false, "explanation": "搭配：“分为”要求划分成几部分，不能说“分为一个字：钱”。"}, {"text": "打碎", "is_correct": false, "explanation": "语义：“打碎”表示破成碎片，与“说到底，归结为一个字”的概括义不符。"}, {"text": "添加", "is_correct": false, "explanation": "语义：“添加”表示增加，与“说到底”归结为一个字的概括义不符。"}], "explanations": {"归结为": "正确：归结为表示说到底落在某一个字上，与“说到底”相合。", "分为": "搭配：“分为”要求划分成几部分，不能说“分为一个字：钱”。", "打碎": "语义：“打碎”表示破成碎片，与“说到底，归结为一个字”的概括义不符。", "添加": "语义：“添加”表示增加，与“说到底”归结为一个字的概括义不符。"}, "sentence_index": 0, "correct_answer": "归结为"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "老板把任务归结为每个人。", "explanation": "这里应该用〈分配〉。归结为指概括原因或结论，不能用来说把任务交给每个人。"}, {"text": "这个城市归结为三个区。", "explanation": "这里应该用〈划分〉。归结为不能用来说把城市分成几个区。"}, {"text": "这间屋子归结为两把椅子。", "explanation": "这里不能用归结为。它只用于概括原因、本质或结论，不能用来统计具体东西的数量。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ff311b2a-2373-4426-b094-f398ef626907') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24324, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "归结为", "is_correct": true, "explanation": "正确：归结为表示把原因概括为某一点，与“妈妈把原因”和后面的小句相合。"}, {"text": "推卸", "is_correct": false, "explanation": "搭配：“推卸”的对象是责任，不能说“推卸原因”。"}, {"text": "推迟", "is_correct": false, "explanation": "语义：“推迟”指把时间往后延，不能用来说原因。"}, {"text": "忘记", "is_correct": false, "explanation": "语义：“忘记”表示遗忘，与“妈妈把原因……”所表示的思考义不符。"}], "explanations": {"归结为": "正确：归结为表示把原因概括为某一点，与“妈妈把原因”和后面的小句相合。", "推卸": "搭配：“推卸”的对象是责任，不能说“推卸原因”。", "推迟": "语义：“推迟”指把时间往后延，不能用来说原因。", "忘记": "语义：“忘记”表示遗忘，与“妈妈把原因……”所表示的思考义不符。"}, "sentence_index": 6, "correct_answer": "归结为"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这条裙子归结为红色。", "explanation": "这里应该用〈是〉。归结为表示说到最后是因为某一个原因，不能用来描述事物的颜色。"}, {"text": "这次会议归结为星期三。", "explanation": "这里应该用〈安排在〉。归结为是说明原因，不能用来说会议安排的时间。"}, {"text": "这条路归结为两公里。", "explanation": "这里应该用〈长〉。归结为不能用来说路的长度。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ff311b2a-2373-4426-b094-f398ef626907') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24324, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他的成绩不好，主要归结为为基础不牢。", "corrected_sentence": "他的成绩不好，主要归结为基础不牢。", "error_description": "错误：“为”重复。“归结为”只用一个“为”，应说“主要归结为基础不牢”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ff311b2a-2373-4426-b094-f398ef626907') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24324, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这份工作的难度，把归结为时间太紧。", "corrected_sentence": "这份工作的难度，归结为时间太紧。", "error_description": "错误：多了“把”。“把”字句要求“把”后接受事宾语，这里“把”后直接是“归结为”，没有受事，应删去“把”，说“这份工作的难度，归结为时间太紧。”", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ff311b2a-2373-4426-b094-f398ef626907') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
