INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24336, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "让心里的想法或感受在行动或脸上表现出来。", "primary_collocate": null, "pronunciation": "wài huà", "ipa": "wai̯˥˩ xu̯a˥˩", "syllable_count": 2, "sentences": [{"text": "他不想让失望外化为表情。", "target_word": "外化", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她的紧张很快外化成了发抖的双手。", "target_word": "外化", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师希望学生把学到的知识外化为行动。", "target_word": "外化", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他心里的愤怒外化为一句冷冷的话。", "target_word": "外化", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "开心的心情外化在她的笑容里。", "target_word": "外化", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他把对家人的爱外化为每天的问候。", "target_word": "外化", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "内心的不安外化为不停地看手机。", "target_word": "外化", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "好演员把情绪外化为动作，自然又真实。", "target_word": "外化", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他不喜欢把感情外化，总是很安静。", "target_word": "外化", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的高兴一下子外化成了跳起来的动作。", "target_word": "外化", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "外化了", "label": "完成体"}], "register": "书面语", "sense_fingerprint": "心里的想法或感受在行动、表情上表现出来", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7a98d740-f54a-4403-9fa2-3db6e5ff3669') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24336, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "外化", "is_correct": true, "explanation": "正确：外化（wài huà）指心里的想法或感受在行动或脸上表现出来。"}, {"text": "外挂", "is_correct": false, "explanation": "h（huà）与 g（guà）声母不同，外挂指游戏或软件的插件，意思不同。"}, {"text": "外号", "is_correct": false, "explanation": "hào 与 huà 韵母不同，外号指绰号，意思不同。"}, {"text": "外患", "is_correct": false, "explanation": "huàn 比 huà 多了韵尾 n，外患指来自外部的祸患。"}], "explanations": {"外化": "正确：外化（wài huà）指心里的想法或感受在行动或脸上表现出来。", "外挂": "h（huà）与 g（guà）声母不同，外挂指游戏或软件的插件，意思不同。", "外号": "hào 与 huà 韵母不同，外号指绰号，意思不同。", "外患": "huàn 比 huà 多了韵尾 n，外患指来自外部的祸患。"}, "sentence_index": null, "correct_answer": "外化"}, "level_3": {"options": [{"text": "外化", "is_correct": true, "explanation": "正确：“外化为表情”指失望在脸上显露出来，与“不想让”的语境相符。"}, {"text": "消化", "is_correct": false, "explanation": "搭配：“消化”多用于食物或知识，不说“消化为表情”，搭配不当。"}, {"text": "升华", "is_correct": false, "explanation": "搭配：“升华”多指情感转化为更高的境界，不用于具体的表情。"}, {"text": "清除", "is_correct": false, "explanation": "语义：“清除”是把失望去掉，与“不想让失望外化为表情”的意图矛盾。"}], "explanations": {"外化": "正确：“外化为表情”指失望在脸上显露出来，与“不想让”的语境相符。", "消化": "搭配：“消化”多用于食物或知识，不说“消化为表情”，搭配不当。", "升华": "搭配：“升华”多指情感转化为更高的境界，不用于具体的表情。", "清除": "语义：“清除”是把失望去掉，与“不想让失望外化为表情”的意图矛盾。"}, "sentence_index": 0, "correct_answer": "外化"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他把窗外的雨外化成了一句话。", "explanation": "这里误把“外化”当成〈变成〉的意思，把雨说成了一句话。“外化”只指心里的想法或感受表现出来，雨不属于这一范畴。"}, {"text": "他的影子落在墙上，像是把身影外化了一样。", "explanation": "这里误把“外化”当成〈显现〉的意思。身影本就在墙上可见，并不存在由内向外表现的过程，“外化”只用于心里的想法或感受。"}, {"text": "他把门口的石头外化为一扇门。", "explanation": "这里误把“外化”当成〈改造〉的意思，把石头改造成了门。“外化”指心里的想法或感受表现出来，石头是实物，不能这样用。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '85a560c0-e25b-45da-8d09-012977d92966') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24336, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "外化", "is_correct": true, "explanation": "正确：外化（wài huà）指心里的想法或感受在行动或脸上表现出来。"}, {"text": "外汇", "is_correct": false, "explanation": "huà 与 huì 韵母不同（a 与 i），外汇指不同国家货币之间的兑换。"}, {"text": "外环", "is_correct": false, "explanation": "huán 与 huà 韵母不同（an 与 a），外环指城市外围的环形道路。"}, {"text": "怪话", "is_correct": false, "explanation": "guài 比 wài 多了声母 g，怪话指奇怪、不中听的话。"}], "explanations": {"外化": "正确：外化（wài huà）指心里的想法或感受在行动或脸上表现出来。", "外汇": "huà 与 huì 韵母不同（a 与 i），外汇指不同国家货币之间的兑换。", "外环": "huán 与 huà 韵母不同（an 与 a），外环指城市外围的环形道路。", "怪话": "guài 比 wài 多了声母 g，怪话指奇怪、不中听的话。"}, "sentence_index": null, "correct_answer": "外化"}, "level_3": {"options": [{"text": "外化", "is_correct": true, "explanation": "正确：“外化为不停地看手机”表示内心的不安在行为上表现出来，与句意相符。"}, {"text": "平复", "is_correct": false, "explanation": "语义：“平复”指恢复平静，与“不停地看手机”所显示的焦躁矛盾。"}, {"text": "消解", "is_correct": false, "explanation": "搭配：“消解”指消除，不说“消解为行为”，搭配不当。"}, {"text": "凝聚", "is_correct": false, "explanation": "搭配：“凝聚”多指力量或人心汇集，不指不安变成具体行为。"}], "explanations": {"外化": "正确：“外化为不停地看手机”表示内心的不安在行为上表现出来，与句意相符。", "平复": "语义：“平复”指恢复平静，与“不停地看手机”所显示的焦躁矛盾。", "消解": "搭配：“消解”指消除，不说“消解为行为”，搭配不当。", "凝聚": "搭配：“凝聚”多指力量或人心汇集，不指不安变成具体行为。"}, "sentence_index": 6, "correct_answer": "外化"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他把动作外化为心里的高兴。", "explanation": "这里误把“外化”当成〈内化〉的意思，方向说反了。动作是外在的，却被说成转为内在的高兴。“外化”是让内在的想法或感受在行动或脸上表现出来。"}, {"text": "他把高兴外化在心里，从来不让别人知道。", "explanation": "这里误把“外化”当成〈隐藏〉的意思（藏在心里）。“外化”是让内在感受表现出来，与“在心里”“从来不让别人知道”相矛盾。"}, {"text": "他把弟弟外化成了一个玩具。", "explanation": "这里误把“外化”当成〈做成〉的意思，把人做成了玩具。“外化”只指心里的想法或感受表现在行动或脸上，不能用于人。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '85a560c0-e25b-45da-8d09-012977d92966') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24336, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他心里的不满很快外化下来了。", "corrected_sentence": "他心里的不满很快外化出来了。", "error_description": "补语错误：“外化”后应接“出来”，表示内在的感受显露到外部；“下来”表示由高向低或固定，与“外化”不搭配。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '85a560c0-e25b-45da-8d09-012977d92966') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24336, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "她的高兴一下子外化了笑声。", "corrected_sentence": "她的高兴一下子外化成了笑声。", "error_description": "缺少连接成分：“外化”后应用“成”或“为”引出结果，“外化了笑声”不通，应说“外化成了笑声”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '85a560c0-e25b-45da-8d09-012977d92966') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
