INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24337, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4626a58c-eb93-4819-bf7d-f85fcc0a7cf9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24337, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "改变自己来跟新情况配合。", "primary_collocate": null, "pronunciation": "shì yìng", "ipa": "ʂɻ̩˥˩ iŋ˥˩", "syllable_count": 2, "sentences": [{"text": "我已经适应了这里的天气。", "target_word": "适应", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "刚到新学校，他还不太适应。", "target_word": "适应", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子需要一些时间适应新环境。", "target_word": "适应", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她很快就适应了新工作。", "target_word": "适应", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "南方人不太适应北方的冬天。", "target_word": "适应", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "搬到国外后，我慢慢适应了当地的饮食。", "target_word": "适应", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他很难适应早起的生活。", "target_word": "适应", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你要学会适应不同的老师。", "target_word": "适应", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我还没适应一个人住的日子。", "target_word": "适应", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "动物要适应环境才能活下去。", "target_word": "适应", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "适应了", "label": "完成体"}, {"form": "适应过", "label": "经历体"}, {"form": "适应不了", "label": "可能补语"}], "register": "中性", "sense_fingerprint": "改变自己去配合新环境或新情况", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'af672a29-e1eb-4780-8f57-35ac2a0384e7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24337, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "适应", "is_correct": true, "explanation": "正确：“适应了这里的天气”指慢慢配合新环境，语境相符。"}, {"text": "煮", "is_correct": false, "explanation": "语义：“煮”是加热食物的动作，不能用于天气。"}, {"text": "购买", "is_correct": false, "explanation": "搭配：“购买”的对象是商品，不能与“这里的天气”搭配。"}, {"text": "拆", "is_correct": false, "explanation": "语义：“拆”指拆开或拆除，与天气无关。"}], "explanations": {"适应": "正确：“适应了这里的天气”指慢慢配合新环境，语境相符。", "煮": "语义：“煮”是加热食物的动作，不能用于天气。", "购买": "搭配：“购买”的对象是商品，不能与“这里的天气”搭配。", "拆": "语义：“拆”指拆开或拆除，与天气无关。"}, "sentence_index": 0, "correct_answer": "适应"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这件衣服很适应我的身材。", "explanation": "这里应该用〈适合〉。“适应”指人或生物改变自己去配合环境，衣服与身材的匹配要用“适合”。"}, {"text": "我妈妈昨天适应了一份工资。", "explanation": "这里应该用〈领〉。“适应”指人改变自己去配合环境，领取工资要用“领”。"}, {"text": "他用一句话就适应了老师的提问。", "explanation": "这里应该用〈应付〉。“适应”指人改变自己去配合环境，回应老师突然的提问要用“应付”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4626a58c-eb93-4819-bf7d-f85fcc0a7cf9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24337, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "适应", "is_correct": true, "explanation": "正确：“很难适应早起的生活”指不习惯早起，语境相符。"}, {"text": "熨", "is_correct": false, "explanation": "语义：“熨”指用熨斗烫平衣物，与生活无关。"}, {"text": "测量", "is_correct": false, "explanation": "搭配：“测量”的对象是长度、温度等，不能用于“生活”。"}, {"text": "计算", "is_correct": false, "explanation": "语义：“计算”指算数，与早起的生活无关。"}], "explanations": {"适应": "正确：“很难适应早起的生活”指不习惯早起，语境相符。", "熨": "语义：“熨”指用熨斗烫平衣物，与生活无关。", "测量": "搭配：“测量”的对象是长度、温度等，不能用于“生活”。", "计算": "语义：“计算”指算数，与早起的生活无关。"}, "sentence_index": 6, "correct_answer": "适应"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他一下子就适应了一座大山。", "explanation": "这里应该用〈爬上〉。“适应”指人改变自己去配合环境，翻越大山要说“爬上”。"}, {"text": "小明很适应我的建议，决定去做。", "explanation": "这里应该用〈接受〉。“接受”表示同意或采纳意见，“适应”指改变自己去配合环境。"}, {"text": "他很快就适应了这个电话号码。", "explanation": "这里应该用〈记住〉。电话号码要用“记住”，“适应”指配合新环境。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4626a58c-eb93-4819-bf7d-f85fcc0a7cf9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24337, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他终于被适应了南方的湿热天气。", "corrected_sentence": "他终于适应了南方的湿热天气。", "error_description": "「被适应了」错误。“适应”表示人主动改变自己去配合环境，不能用“被”字句，正确为「适应了」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4626a58c-eb93-4819-bf7d-f85fcc0a7cf9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24337, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他适应了不这个城市的节奏，想回老家。", "corrected_sentence": "他适应不了这个城市的节奏，想回老家。", "error_description": "「适应了不」错误。可能补语的否定形式是“适应不了”，“不”应放在“了”之前。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4626a58c-eb93-4819-bf7d-f85fcc0a7cf9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
