INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24340, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "自然法则就是大自然里一直存在的规则，比如苹果会掉到地上。", "primary_collocate": null, "pronunciation": "zì rán fǎ zé", "ipa": "tsɿ˥˩ ʐan˧˥ fa˨˩˦ tsɤ˧˥", "syllable_count": 4, "sentences": [{"text": "苹果会掉到地上，这是自然法则。", "target_word": "自然法则", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "太阳每天从东边升起，是自然法则。", "target_word": "自然法则", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "冬天很冷，夏天很热，这是自然法则。", "target_word": "自然法则", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "鱼不能离开水，这是自然法则。", "target_word": "自然法则", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "老师教小朋友认识自然法则。", "target_word": "自然法则", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "人人都要尊重自然法则。", "target_word": "自然法则", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "石头扔上去会掉下来，这是自然法则。", "target_word": "自然法则", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "书里讲了很多有趣的自然法则。", "target_word": "自然法则", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "水总是从高处流向低处，是自然法则。", "target_word": "自然法则", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "花开花落，都是自然法则。", "target_word": "自然法则", "complexity_tier": "T1", "sentence_source": "generated"}], "morphological_forms": [{"form": "条", "label": "量词"}, {"form": "自然法則", "label": "繁体"}], "register": "中性", "sense_fingerprint": "大自然里一直存在的规则", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '427906b5-fb0b-4248-ba62-52818e8c3b15') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24340, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "自然法则", "is_correct": true, "explanation": "正确：“自然法则”指大自然里一直存在的规则，苹果落地正是这样的规则。"}, {"text": "习俗", "is_correct": false, "explanation": "语义：“习俗”是人们长期形成的生活习惯，不是苹果落地这样的客观规律。"}, {"text": "时尚", "is_correct": false, "explanation": "语义：“时尚”指一时流行的风气，与物体下落无关，填入后意思不通。"}, {"text": "脾气", "is_correct": false, "explanation": "搭配：“这是……”后面接的应是规律或现象，“脾气”指人的性情，不能这样用。"}], "explanations": {"自然法则": "正确：“自然法则”指大自然里一直存在的规则，苹果落地正是这样的规则。", "习俗": "语义：“习俗”是人们长期形成的生活习惯，不是苹果落地这样的客观规律。", "时尚": "语义：“时尚”指一时流行的风气，与物体下落无关，填入后意思不通。", "脾气": "搭配：“这是……”后面接的应是规律或现象，“脾气”指人的性情，不能这样用。"}, "sentence_index": 0, "correct_answer": "自然法则"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "学校有很多自然法则，大家都要遵守。", "explanation": "这里应该用〈规矩〉。“自然法则”指大自然的规律，学校的要求应说“规矩”。"}, {"text": "他从小就养成了早睡的自然法则。", "explanation": "这里应该用〈习惯〉。“养成”搭配“习惯”，自然法则是客观存在的规律，不能靠人养成。"}, {"text": "他按照一个自然法则写了一篇作文。", "explanation": "这里应该用〈提纲〉。“自然法则”指大自然的规律，写作文时的框架应说“提纲”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '07b6ee61-cecc-48e4-9ec5-c4d0a6ee8713') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24340, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "自然法则", "is_correct": true, "explanation": "正确：石头扔上去会掉下来，是大自然里一直存在的规则，“自然法则”符合句意。"}, {"text": "价格", "is_correct": false, "explanation": "语义：“价格”指东西值多少钱，石头下落这一现象不能说成“价格”。"}, {"text": "礼节", "is_correct": false, "explanation": "语义：“礼节”是人际交往中的规范，与石头下落这样的现象无关。"}, {"text": "节目", "is_correct": false, "explanation": "搭配：“节目”指表演或播出的内容，不能用“这是节目”来指称自然现象。"}], "explanations": {"自然法则": "正确：石头扔上去会掉下来，是大自然里一直存在的规则，“自然法则”符合句意。", "价格": "语义：“价格”指东西值多少钱，石头下落这一现象不能说成“价格”。", "礼节": "语义：“礼节”是人际交往中的规范，与石头下落这样的现象无关。", "节目": "搭配：“节目”指表演或播出的内容，不能用“这是节目”来指称自然现象。"}, "sentence_index": 6, "correct_answer": "自然法则"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "公司有一套完善的自然法则。", "explanation": "这里应该用〈制度〉。“自然法则”指自然界的客观规律，公司的规定是人为制定的，应说“制度”。"}, {"text": "这种食品必须符合国家自然法则。", "explanation": "这里应该用〈标准〉。“符合标准”指符合人为规定的要求，“国家自然法则”不能用来指国家的规定。"}, {"text": "班里制定了一个自然法则。", "explanation": "这里应该用〈规定〉。“自然法则”是客观存在的，不能由人来制定；班里定下的要求应说“规定”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '07b6ee61-cecc-48e4-9ec5-c4d0a6ee8713') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24340, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "科学家总结出了一本自然法则。", "corrected_sentence": "科学家总结出了一条自然法则。", "error_description": "量词错误：“自然法则”应用量词“条”，应说“一条自然法则”。“本”用于书籍、册子，不能用来数“自然法则”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '07b6ee61-cecc-48e4-9ec5-c4d0a6ee8713') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24340, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "孩子们应该吃自然法则。", "corrected_sentence": "孩子们应该尊重自然法则。", "error_description": "动宾搭配错误：“吃”不能搭配“自然法则”，应改为“尊重”。只需替换这一个动词。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '07b6ee61-cecc-48e4-9ec5-c4d0a6ee8713') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
