INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24342, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "飞机翅膀上可以动的部分。", "primary_collocate": null, "pronunciation": "jīn yì", "ipa": "tɕin˥ i˥˩", "syllable_count": 2, "sentences": [{"text": "飞机的翅膀上有可以动的襟翼。", "target_word": "襟翼", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "飞机要降落了，襟翼慢慢放下来。", "target_word": "襟翼", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我在窗边看见机翼上的襟翼动了。", "target_word": "襟翼", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师给我们讲了襟翼的作用。", "target_word": "襟翼", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "起飞的时候，襟翼会向下动一点。", "target_word": "襟翼", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "模型飞机的襟翼是用塑料做的。", "target_word": "襟翼", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "襟翼打开后，飞机可以飞得慢一点。", "target_word": "襟翼", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这架飞机左边的襟翼有问题。", "target_word": "襟翼", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他把襟翼画在了飞机的翅膀上。", "target_word": "襟翼", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "工人正在修飞机上的襟翼。", "target_word": "襟翼", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "一对襟翼", "label": "量词"}, {"form": "后缘襟翼", "label": "复合"}], "register": "中性", "sense_fingerprint": "飞机翅膀上能活动的部分，通俗说法", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f4f8477c-c623-4811-8372-e8a5d9f6c5fc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24342, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "襟翼", "is_correct": true, "explanation": "正确：“襟翼”是翅膀上可以动的部分，与句意相符。"}, {"text": "窗户", "is_correct": false, "explanation": "语义：窗户在机身上，不在翅膀上，与“翅膀上有可以动的”不符。"}, {"text": "座椅", "is_correct": false, "explanation": "语义：座椅在机舱内，不在翅膀上，与句意矛盾。"}, {"text": "零食", "is_correct": false, "explanation": "搭配：“可以动的”多指机械部件，不说零食可以动。"}], "explanations": {"襟翼": "正确：“襟翼”是翅膀上可以动的部分，与句意相符。", "窗户": "语义：窗户在机身上，不在翅膀上，与“翅膀上有可以动的”不符。", "座椅": "语义：座椅在机舱内，不在翅膀上，与句意矛盾。", "零食": "搭配：“可以动的”多指机械部件，不说零食可以动。"}, "sentence_index": 0, "correct_answer": "襟翼"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我买了一辆襟翼。", "explanation": "这里应该用〈个〉或〈对〉。“辆”用于车辆，襟翼是飞机的翼面，不能用“辆”。"}, {"text": "飞机转弯时要靠襟翼控制方向。", "explanation": "这里应该用〈副翼〉。襟翼用于增加升力，控制转弯要用〈副翼〉。"}, {"text": "发动机给飞机提供动力，襟翼也给飞机提供动力。", "explanation": "这里应该用〈升力〉。襟翼增加的是机翼的升力，它不提供动力，“提供动力”不是襟翼的作用。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '73b6de39-9b1c-4462-afcd-62cb8c028ff7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24342, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "襟翼", "is_correct": true, "explanation": "正确：“襟翼”打开后会改变升力，使飞机可以飞得慢一点，与句意相符。"}, {"text": "窗帘", "is_correct": false, "explanation": "语义：窗帘打开与飞机飞得快慢无关，与句意矛盾。"}, {"text": "水龙头", "is_correct": false, "explanation": "语义：水龙头打开与飞机飞得快慢无关，与句意矛盾。"}, {"text": "抽屉", "is_correct": false, "explanation": "语义：抽屉打开与飞机飞行速度无关，不能使飞机飞得慢。"}], "explanations": {"襟翼": "正确：“襟翼”打开后会改变升力，使飞机可以飞得慢一点，与句意相符。", "窗帘": "语义：窗帘打开与飞机飞得快慢无关，与句意矛盾。", "水龙头": "语义：水龙头打开与飞机飞得快慢无关，与句意矛盾。", "抽屉": "语义：抽屉打开与飞机飞行速度无关，不能使飞机飞得慢。"}, "sentence_index": 6, "correct_answer": "襟翼"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "她衣服的襟翼上有一个扣子。", "explanation": "这里应该用〈衣襟〉。“襟翼”是飞机翅膀上可以动的部分，不是衣服的一部分；衣服前面的部分叫〈衣襟〉。"}, {"text": "工人正在修飞机上的一根襟翼。", "explanation": "这里应该用〈个〉或〈对〉。“根”用于细长的东西，襟翼是翼面，不能用“根”。"}, {"text": "襟翼在飞机尾部，用来控制俯仰。", "explanation": "这里应该用〈尾翼〉。襟翼位于机翼后缘，不在尾部，控制俯仰要用〈尾翼〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '73b6de39-9b1c-4462-afcd-62cb8c028ff7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24342, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "襟翼一直打着。", "corrected_sentence": "襟翼一直开着。", "error_description": "动词搭配错误：“打”指敲击等动作，襟翼不能“打着”，应说“襟翼一直开着”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '73b6de39-9b1c-4462-afcd-62cb8c028ff7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24342, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "襟翼慢慢收起了来。", "corrected_sentence": "襟翼慢慢收起来了。", "error_description": "错误：“收起了来”。正确：“收起来了”。趋向补语“起来”不能拆开，“了”要放在“起来”之后。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '73b6de39-9b1c-4462-afcd-62cb8c028ff7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24344, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "动荡", "is_correct": true, "explanation": "正确：“动荡”指形势或经济不安定，与“平稳”构成反义，可用于“经济发展”。"}, {"text": "热烈", "is_correct": false, "explanation": "热烈形容气氛或情绪高涨，与“平稳”不构成反义。"}, {"text": "清楚", "is_correct": false, "explanation": "清楚形容明白、分明，与“平稳”没有反义关系。"}, {"text": "漂亮", "is_correct": false, "explanation": "漂亮形容外貌或做事出色，与“平稳”不构成反义。"}], "correct_answer": "动荡", "explanations": {"动荡": "正确：“动荡”指形势或经济不安定，与“平稳”构成反义，可用于“经济发展”。", "热烈": "热烈形容气氛或情绪高涨，与“平稳”不构成反义。", "清楚": "清楚形容明白、分明，与“平稳”没有反义关系。", "漂亮": "漂亮形容外貌或做事出色，与“平稳”不构成反义。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '07b6ee61-cecc-48e4-9ec5-c4d0a6ee8713') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24344, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '07b6ee61-cecc-48e4-9ec5-c4d0a6ee8713') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24344, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "事情没有大的变化，安安定定的。", "primary_collocate": null, "pronunciation": "píng wěn", "ipa": "pʰiŋ˧˥ wən˨˩˦", "syllable_count": 2, "sentences": [{"text": "他的收入平稳，不用担心钱。", "target_word": "平稳", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "公司的利润一直平稳，没有大起大落。", "target_word": "平稳", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "爷爷退休后，过着平稳安定的日子。", "target_word": "平稳", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "今年经济发展平稳，大家都放心。", "target_word": "平稳", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我想过平稳的日子，不想总搬家。", "target_word": "平稳", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个小镇的生活平稳，很少发生大事。", "target_word": "平稳", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他的成绩一直比较平稳，没有太大变化。", "target_word": "平稳", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "两国关系平稳发展，对大家都有好处。", "target_word": "平稳", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "孩子上学后，我们家的生活平稳多了。", "target_word": "平稳", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "房价这几个月比较平稳，没有涨也没有跌。", "target_word": "平稳", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "生活、工作、发展等没有大变化，安定", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '427906b5-fb0b-4248-ba62-52818e8c3b15') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24344, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "平稳", "is_correct": true, "explanation": "正确：“平稳”指收入没有大的波动，与“不用担心钱”相合。"}, {"text": "清楚", "is_correct": false, "explanation": "搭配：“收入”可说稳定、丰厚，不说“收入清楚”。"}, {"text": "安静", "is_correct": false, "explanation": "语义：收入不会“安静”，“安静”形容环境或声音小，与句意无关。"}, {"text": "遥远", "is_correct": false, "explanation": "语义：“遥远”指距离很远，不能形容收入的状态。"}], "explanations": {"平稳": "正确：“平稳”指收入没有大的波动，与“不用担心钱”相合。", "清楚": "搭配：“收入”可说稳定、丰厚，不说“收入清楚”。", "安静": "语义：收入不会“安静”，“安静”形容环境或声音小，与句意无关。", "遥远": "语义：“遥远”指距离很远，不能形容收入的状态。"}, "sentence_index": 0, "correct_answer": "平稳"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这条街很平稳，车来车往，吵得人睡不着。", "explanation": "这里应该用〈嘈杂〉。“平稳”说的是没有大的变化，街上声音大、人声杂应说“嘈杂”。"}, {"text": "这座山很平稳，爬起来很累。", "explanation": "这里应该用〈陡峭〉。“平稳”说的是没有大的变化，山的坡度大应说“陡峭”。"}, {"text": "最近大家都很平稳，没有时间休息。", "explanation": "这里应该用〈忙碌〉。“平稳”说的是没有大的变化，人们的劳累状态应说“忙碌”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '07b6ee61-cecc-48e4-9ec5-c4d0a6ee8713') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24344, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "平稳", "is_correct": true, "explanation": "正确：“平稳”形容成绩没有大的起伏，与“没有太大变化”相合。"}, {"text": "辛苦", "is_correct": false, "explanation": "语义：“辛苦”形容劳累，不能用来形容成绩的状态。"}, {"text": "柔软", "is_correct": false, "explanation": "语义：“柔软”形容质地，不能用来形容成绩。"}, {"text": "嘹亮", "is_correct": false, "explanation": "搭配：“嘹亮”多形容声音，不能修饰“成绩”。"}], "explanations": {"平稳": "正确：“平稳”形容成绩没有大的起伏，与“没有太大变化”相合。", "辛苦": "语义：“辛苦”形容劳累，不能用来形容成绩的状态。", "柔软": "语义：“柔软”形容质地，不能用来形容成绩。", "嘹亮": "搭配：“嘹亮”多形容声音，不能修饰“成绩”。"}, "sentence_index": 6, "correct_answer": "平稳"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这家超市的商品很平稳，每个区都有很多选择。", "explanation": "这里应该用〈丰富〉。“平稳”说的是没有大的变化，商品种类多应说“丰富”。"}, {"text": "这次涨价很平稳，一下子涨了一倍。", "explanation": "这里应该用〈厉害〉。“平稳”说的是没有大的变化；“一下子涨了一倍”说明涨得很厉害。"}, {"text": "这家旅馆的房间很平稳，床单也很干净。", "explanation": "这里应该用〈整洁〉。“平稳”说的是没有大的变化，房间的整齐干净应说“整洁”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '07b6ee61-cecc-48e4-9ec5-c4d0a6ee8713') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24344, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这几年，他的收入慢慢平稳出来了。", "corrected_sentence": "这几年，他的收入慢慢平稳下来了。", "error_description": "补语错误：表示变得平稳应用趋向补语「下来」，应说「慢慢平稳下来」，「平稳出来」不符合说法。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '07b6ee61-cecc-48e4-9ec5-c4d0a6ee8713') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24344, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这家店的生意一直的平稳。", "corrected_sentence": "这家店的生意一直很平稳。", "error_description": "结构助词错误：“平稳”作谓语时，前面用程度副词“很”，或直接说“一直平稳”；此处用结构助词“的”不通，应说「一直很平稳」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '07b6ee61-cecc-48e4-9ec5-c4d0a6ee8713') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
