INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24346, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "缝翼是飞机机翼上可以活动的一块板子，用来帮助飞机飞得更稳。", "primary_collocate": null, "pronunciation": "fèng yì", "ipa": "fɤŋ˥˩ i˥˩", "syllable_count": 2, "sentences": [{"text": "缝翼是机翼上能活动的一块板子。", "target_word": "缝翼", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "飞机起飞时，缝翼会向前伸出。", "target_word": "缝翼", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "缝翼可以帮助飞机飞得更稳。", "target_word": "缝翼", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我在书上看到了缝翼的照片。", "target_word": "缝翼", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "缝翼位于机翼的前缘。", "target_word": "缝翼", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "飞机降落前，缝翼慢慢打开了。", "target_word": "缝翼", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师指着图上的缝翼问我们它有什么用。", "target_word": "缝翼", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这架小飞机的缝翼是白色的。", "target_word": "缝翼", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "缝翼不能动，飞机就飞不稳。", "target_word": "缝翼", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他用纸做了一个小飞机，还做了缝翼。", "target_word": "缝翼", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "一对缝翼", "label": "量词"}, {"form": "縫翼", "label": "繁体"}, {"form": "前缘缝翼", "label": "复合"}], "register": "中性", "sense_fingerprint": "机翼上可活动的板子，帮助飞机飞稳，通俗说法", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f4f8477c-c623-4811-8372-e8a5d9f6c5fc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24346, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "缝翼", "is_correct": true, "explanation": "正确答案。缝翼（fèng yì）指机翼上能活动、帮助飞机飞稳的板子。"}, {"text": "风衣", "is_correct": false, "explanation": "两个音节声调都不同：fēng（第一声）与 fèng（第四声），yī（第一声）与 yì（第四声）。意思是风衣。"}, {"text": "缝衣", "is_correct": false, "explanation": "缝衣（féng yī）：缝制衣服。两个音节的声调都与 fèng yì 不同。"}, {"text": "缝隙", "is_correct": false, "explanation": "第二个音节声母不同：xì 与 yì。意思是缝隙。"}, {"text": "风力", "is_correct": false, "explanation": "第一个音节声调不同，第二个音节声母不同：lì 与 yì。意思是风的力量。"}, {"text": "风气", "is_correct": false, "explanation": "第一个音节声调不同，第二个音节声母不同：qì 与 yì。意思是风气。"}], "explanations": {"缝翼": "正确答案。缝翼（fèng yì）指机翼上能活动、帮助飞机飞稳的板子。", "风衣": "两个音节声调都不同：fēng（第一声）与 fèng（第四声），yī（第一声）与 yì（第四声）。意思是风衣。", "缝衣": "缝衣（féng yī）：缝制衣服。两个音节的声调都与 fèng yì 不同。", "缝隙": "第二个音节声母不同：xì 与 yì。意思是缝隙。", "风力": "第一个音节声调不同，第二个音节声母不同：lì 与 yì。意思是风的力量。", "风气": "第一个音节声调不同，第二个音节声母不同：qì 与 yì。意思是风气。"}, "sentence_index": null, "correct_answer": "缝翼"}, "level_3": {"options": [{"text": "缝翼", "is_correct": true, "explanation": "正确答案。缝翼是机翼上能活动的板子，与句中描述一致。"}, {"text": "窗帘", "is_correct": false, "explanation": "语义：窗帘不装在机翼上，不是机翼上能活动的板子。"}, {"text": "螺丝钉", "is_correct": false, "explanation": "搭配：“螺丝钉”指小零件，不能说成“一块板子”。"}, {"text": "机舱", "is_correct": false, "explanation": "语义：机舱是载人的空间，不是能活动的板子。"}], "explanations": {"缝翼": "正确答案。缝翼是机翼上能活动的板子，与句中描述一致。", "窗帘": "语义：窗帘不装在机翼上，不是机翼上能活动的板子。", "螺丝钉": "搭配：“螺丝钉”指小零件，不能说成“一块板子”。", "机舱": "语义：机舱是载人的空间，不是能活动的板子。"}, "sentence_index": 0, "correct_answer": "缝翼"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "起飞时，缝翼会从机翼后缘放下来。", "explanation": "这里应该用〈襟翼〉。缝翼位于机翼前缘，襟翼才在后缘放下。"}, {"text": "飞机的翼尖装着缝翼，可以减少飞行阻力。", "explanation": "这里应该用〈翼梢小翼〉。翼梢小翼装在翼尖，减少阻力；缝翼位于机翼前缘，不装在翼尖。"}, {"text": "我用缝翼给衣服钉扣子。", "explanation": "缝翼是机翼上的可动板，不是针线用具，这句把它当成了缝纫工具。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '73b6de39-9b1c-4462-afcd-62cb8c028ff7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24346, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "缝翼", "is_correct": true, "explanation": "正确答案。缝翼是图上可以指出来的实物，句子问的是它的用途。"}, {"text": "心情", "is_correct": false, "explanation": "语义：心情看不见，不能指着图上的某处。"}, {"text": "声音", "is_correct": false, "explanation": "语义：声音听得见却看不见，不能指着图上的某处。"}, {"text": "时光", "is_correct": false, "explanation": "搭配：“指着”指向看得见的东西，不能指“时光”。"}], "explanations": {"缝翼": "正确答案。缝翼是图上可以指出来的实物，句子问的是它的用途。", "心情": "语义：心情看不见，不能指着图上的某处。", "声音": "语义：声音听得见却看不见，不能指着图上的某处。", "时光": "搭配：“指着”指向看得见的东西，不能指“时光”。"}, "sentence_index": 6, "correct_answer": "缝翼"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "飞机靠缝翼推动前进。", "explanation": "这里应该用〈螺旋桨〉。推动飞机前进的是螺旋桨，缝翼只是机翼上的可动板，不产生推力。"}, {"text": "小鸟靠缝翼飞行。", "explanation": "这里应该用〈翅膀〉。缝翼是飞机机翼上的部件，小鸟飞行靠的是翅膀。"}, {"text": "飞机向左倾斜时，靠缝翼来调整机身。", "explanation": "这里应该用〈副翼〉。副翼控制机身倾斜，缝翼只在起降时伸出、增加升力。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '73b6de39-9b1c-4462-afcd-62cb8c028ff7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24346, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "机翼上装着两本缝翼。", "corrected_sentence": "机翼上装着两块缝翼。", "error_description": "量词错误：缝翼是板状部件，应用“块”；“本”只用于书籍、册子，不能用于机翼部件。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '73b6de39-9b1c-4462-afcd-62cb8c028ff7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24346, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "缝翼一直伸了着，飞机很稳。", "corrected_sentence": "缝翼一直伸着，飞机很稳。", "error_description": "体标错误：“着”表示持续，不能与“了”同时用在“伸”后，应删去“了”，说“伸着”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '73b6de39-9b1c-4462-afcd-62cb8c028ff7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
