INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24356, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "非常好，比很多人都好。", "primary_collocate": null, "pronunciation": "zhuó yuè", "ipa": "ʈʂwɔ˧˥ yɛ˥˩", "syllable_count": 2, "sentences": [{"text": "这个学生的成绩卓越，老师很满意。", "target_word": "卓越", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她唱歌的本领卓越，大家都爱听。", "target_word": "卓越", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "王老师的教学卓越，学生都喜欢他。", "target_word": "卓越", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家饭店的服务卓越，我们下次还来。", "target_word": "卓越", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他是一位卓越的医生，帮助过很多人。", "target_word": "卓越", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小李的表现卓越，老板给他加了工资。", "target_word": "卓越", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这部电影的音乐卓越，我很喜欢。", "target_word": "卓越", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "运动员取得了卓越的成绩。", "target_word": "卓越", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她做事认真，能力卓越，同事都很佩服她。", "target_word": "卓越", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这位老人有卓越的手艺，做的家具又好又结实。", "target_word": "卓越", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "通用", "sense_fingerprint": "非常好，比很多人都好", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7a98d740-f54a-4403-9fa2-3db6e5ff3669') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24356, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "卓越", "is_correct": true, "explanation": "卓越修饰“成绩”，表示成绩非常好，与后句“老师很满意”相符。"}, {"text": "低下", "is_correct": false, "explanation": "语义：“低下”指水平差，与后句“老师很满意”相矛盾。"}, {"text": "沉重", "is_correct": false, "explanation": "搭配：“沉重”多形容负担、心情，一般不说“成绩沉重”。"}, {"text": "狭窄", "is_correct": false, "explanation": "搭配：“狭窄”描写空间或范围，不能修饰“成绩”。"}], "explanations": {"卓越": "卓越修饰“成绩”，表示成绩非常好，与后句“老师很满意”相符。", "低下": "语义：“低下”指水平差，与后句“老师很满意”相矛盾。", "沉重": "搭配：“沉重”多形容负担、心情，一般不说“成绩沉重”。", "狭窄": "搭配：“狭窄”描写空间或范围，不能修饰“成绩”。"}, "sentence_index": 0, "correct_answer": "卓越"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这位演员长得很卓越，走到哪里都引人注目。", "explanation": "这里应该用〈出众〉。卓越形容能力、成绩等水平，描写外貌要用“出众”。"}, {"text": "这只箱子的重量很卓越，我一个人搬不动。", "explanation": "这里应该用〈重〉。卓越形容能力或成就超出一般，说明物体的轻重要用“重”，不能说“重量卓越”。"}, {"text": "这幅画的尺寸很卓越，挂在墙上很醒目。", "explanation": "这里应该用〈大〉。卓越形容能力或水平，描述尺寸要用“大”，不能说“尺寸卓越”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '85a560c0-e25b-45da-8d09-012977d92966') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24356, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "卓越", "is_correct": true, "explanation": "卓越作谓语，说明音乐很出色，与后句“我很喜欢”相符。"}, {"text": "刺耳", "is_correct": false, "explanation": "语义：“刺耳”指声音难听，与后句“我很喜欢”相矛盾。"}, {"text": "枯燥", "is_correct": false, "explanation": "语义：“枯燥”指单调没有趣味，与后句“我很喜欢”相矛盾。"}, {"text": "潦草", "is_correct": false, "explanation": "搭配：“潦草”多形容字迹或做事不认真，一般不用来形容音乐。"}], "explanations": {"卓越": "卓越作谓语，说明音乐很出色，与后句“我很喜欢”相符。", "刺耳": "语义：“刺耳”指声音难听，与后句“我很喜欢”相矛盾。", "枯燥": "语义：“枯燥”指单调没有趣味，与后句“我很喜欢”相矛盾。", "潦草": "搭配：“潦草”多形容字迹或做事不认真，一般不用来形容音乐。"}, "sentence_index": 6, "correct_answer": "卓越"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这座山的高度很卓越，爬起来特别累。", "explanation": "这里应该用〈高〉。卓越形容能力或成就超出一般，说山的高矮要用“高”，不能说“高度卓越”。"}, {"text": "这只杯子的容量很卓越，能装下两升水。", "explanation": "这里应该用〈大〉。卓越形容能力或水平，说容量要用“大”，不能说“容量卓越”。"}, {"text": "这位老人的脾气卓越，从不跟人吵架。", "explanation": "这里应该用〈温和〉。卓越形容能力或成就，描写性情要用“温和”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '85a560c0-e25b-45da-8d09-012977d92966') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24356, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这个学生考出了卓越地成绩，老师很满意。", "corrected_sentence": "这个学生考出了卓越的成绩，老师很满意。", "error_description": "错误形式是“卓越地成绩”，正确形式是“卓越的成绩”。“卓越”修饰名词“成绩”时要用“的”，“地”只修饰动词。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '85a560c0-e25b-45da-8d09-012977d92966') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24356, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这部电影的插曲非常很卓越，我很喜欢。", "corrected_sentence": "这部电影的插曲非常卓越，我很喜欢。", "error_description": "错误在于“非常”和“很”重复修饰“卓越”，应删去“很”，改为“非常卓越”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '85a560c0-e25b-45da-8d09-012977d92966') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24358, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "书面", "is_correct": true, "explanation": "正确：“书面”与“口头”相对，指写下来的，是反义词。"}, {"text": "公开", "is_correct": false, "explanation": "与“口头”无反义关系，“公开”指不隐蔽，与说话方式无关。"}, {"text": "具体", "is_correct": false, "explanation": "与“口头”无反义关系，“具体”指明确细致，不对应说话方式。"}, {"text": "直接", "is_correct": false, "explanation": "与“口头”无反义关系，“直接”常与“间接”相对，不与“口头”相对。"}], "correct_answer": "书面", "explanations": {"书面": "正确：“书面”与“口头”相对，指写下来的，是反义词。", "公开": "与“口头”无反义关系，“公开”指不隐蔽，与说话方式无关。", "具体": "与“口头”无反义关系，“具体”指明确细致，不对应说话方式。", "直接": "与“口头”无反义关系，“直接”常与“间接”相对，不与“口头”相对。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ad60c45b-4ca7-40b4-bf0c-f205e95e64b0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
