INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24358, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "abstract", "definition": "用嘴说的，不是写下来的。", "primary_collocate": null, "pronunciation": "kǒu tóu", "ipa": "kʰou˨˩˦ tʰou˧˥", "syllable_count": 2, "sentences": [{"text": "老师给了我们口头通知，没有写下来。", "target_word": "口头", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请用口头的方式回答这个问题。", "target_word": "口头", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这次考试分口头和书面两部分。", "target_word": "口头", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他口头上说好，可是没有去做。", "target_word": "口头", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小李做了一个口头报告。", "target_word": "口头", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们只有口头约定，没有写合同。", "target_word": "口头", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这件事他只是口头答应了。", "target_word": "口头", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈妈口头同意我去旅行，但是没有写下来。", "target_word": "口头", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "汉语课上，我们先做口头练习，再写字。", "target_word": "口头", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的口头表达能力很强。", "target_word": "口头", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "口头报告", "label": "复合"}], "register": "中性", "sense_fingerprint": "用嘴说出来的方式，不是用文字写下来的", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ffce3848-4e7c-4ec3-885e-673579ba7e56') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24358, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "口头", "is_correct": true, "explanation": "正确：口头，指用嘴说的，与“书面”相对。"}, {"text": "扣头", "is_correct": false, "explanation": "kòu（第四声）与 kǒu（第三声）声调不同，扣头指减价的数额。"}, {"text": "苦头", "is_correct": false, "explanation": "kǔ 与 kǒu 韵母不同，苦头指吃苦的经历。"}, {"text": "狗头", "is_correct": false, "explanation": "gǒu 与 kǒu 声母不同（g 与 k），狗头指狗的脑袋。"}], "explanations": {"口头": "正确：口头，指用嘴说的，与“书面”相对。", "扣头": "kòu（第四声）与 kǒu（第三声）声调不同，扣头指减价的数额。", "苦头": "kǔ 与 kǒu 韵母不同，苦头指吃苦的经历。", "狗头": "gǒu 与 kǒu 声母不同（g 与 k），狗头指狗的脑袋。"}, "sentence_index": null, "correct_answer": "口头"}, "level_3": {"options": [{"text": "口头", "is_correct": true, "explanation": "正确：口头通知指用嘴说的通知，与后文“没有写下来”一致。"}, {"text": "书面", "is_correct": false, "explanation": "语义：“书面通知”指写下来的通知，与后文“没有写下来”矛盾。"}, {"text": "亲笔", "is_correct": false, "explanation": "语义：“亲笔”指亲手写的，与“没有写下来”矛盾。"}, {"text": "慢性", "is_correct": false, "explanation": "搭配：“慢性”多用于病症，不能修饰“通知”。"}], "explanations": {"口头": "正确：口头通知指用嘴说的通知，与后文“没有写下来”一致。", "书面": "语义：“书面通知”指写下来的通知，与后文“没有写下来”矛盾。", "亲笔": "语义：“亲笔”指亲手写的，与“没有写下来”矛盾。", "慢性": "搭配：“慢性”多用于病症，不能修饰“通知”。"}, "sentence_index": 0, "correct_answer": "口头"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他口头唱了一首新歌，大家都很喜欢。", "explanation": "这里应该用〈演唱〉。“口头”指用嘴说，不指唱歌，“口头唱歌”说不通。"}, {"text": "我口头看完了这本小说，很有意思。", "explanation": "这里应该用〈默读〉。“口头”指用嘴说，读书是用眼睛看，不能说“口头看完”。"}, {"text": "他买了一个口头的杯子，颜色很漂亮。", "explanation": "这里把“口头”误当成了修饰实物的形容词，好像杯子是用嘴说的。“口头”只能修饰通知、约定等与话语有关的事，不能修饰杯子。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ad60c45b-4ca7-40b4-bf0c-f205e95e64b0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24358, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "口头", "is_correct": true, "explanation": "正确：口头，指用嘴说的，与“书面”相对。"}, {"text": "叩头", "is_correct": false, "explanation": "kòu（第四声）与 kǒu（第三声）声调不同，叩头指磕头。"}, {"text": "喉头", "is_correct": false, "explanation": "hóu 与 kǒu 声母和声调都不同（h 与 k），喉头指喉咙。"}, {"text": "口条", "is_correct": false, "explanation": "tiáo 与 tóu 韵母不同，口条指猪或牛的舌头，是一种食物。"}], "explanations": {"口头": "正确：口头，指用嘴说的，与“书面”相对。", "叩头": "kòu（第四声）与 kǒu（第三声）声调不同，叩头指磕头。", "喉头": "hóu 与 kǒu 声母和声调都不同（h 与 k），喉头指喉咙。", "口条": "tiáo 与 tóu 韵母不同，口条指猪或牛的舌头，是一种食物。"}, "sentence_index": null, "correct_answer": "口头"}, "level_3": {"options": [{"text": "口头", "is_correct": true, "explanation": "正确：“口头答应”指用嘴说出同意，与“只是”的语气相符。"}, {"text": "彻底", "is_correct": false, "explanation": "搭配：“彻底”修饰改变、结束之类的动作，不能修饰“答应”。"}, {"text": "强硬", "is_correct": false, "explanation": "搭配：“强硬”形容态度，不用来说“答应”的方式，语义别扭。"}, {"text": "暴躁", "is_correct": false, "explanation": "语义：“暴躁”描写性情，与“答应”这件事的语气不相符。"}], "explanations": {"口头": "正确：“口头答应”指用嘴说出同意，与“只是”的语气相符。", "彻底": "搭配：“彻底”修饰改变、结束之类的动作，不能修饰“答应”。", "强硬": "搭配：“强硬”形容态度，不用来说“答应”的方式，语义别扭。", "暴躁": "语义：“暴躁”描写性情，与“答应”这件事的语气不相符。"}, "sentence_index": 6, "correct_answer": "口头"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他习惯口头写作业。", "explanation": "这里应该用〈书面〉。“口头”指用嘴说，写作业是书面的，不能说“口头写”。"}, {"text": "会议的内容我都口头记下来了。", "explanation": "这里应该用〈笔录〉。“口头”指用嘴说，记录要用笔写下来，“口头记下来”自相矛盾。"}, {"text": "他每天口头吃三次药。", "explanation": "这里应该用〈口服〉。“口头”指用嘴说，吃药要说〈口服〉，不能说“口头吃药”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ad60c45b-4ca7-40b4-bf0c-f205e95e64b0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24358, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "老师给了我们口头了通知，明天不用来上课。", "corrected_sentence": "老师给了我们口头通知，明天不用来上课。", "error_description": "错误：“了”不能放在“口头”和“通知”之间，应说“口头通知”。正确：“老师给了我们口头通知”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ad60c45b-4ca7-40b4-bf0c-f205e95e64b0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24358, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "爸爸口头的答应了周末带我去动物园。", "corrected_sentence": "爸爸口头答应了周末带我去动物园。", "error_description": "错误：“口头”修饰动词“答应”时作状语，直接放在动词前，不加“的”。正确：“爸爸口头答应了周末带我去动物园。”", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ad60c45b-4ca7-40b4-bf0c-f205e95e64b0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
