INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24360, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "人们讲的一个老故事，里面可能有神奇的人和事。", "primary_collocate": null, "pronunciation": "mín jiān chuán shuō", "ipa": "min˧˥ tɕjɛn˥ ʈʂʰwan˧˥ ʂwo˥", "syllable_count": 4, "sentences": [{"text": "奶奶给我讲了一个民间传说。", "target_word": "民间传说", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个民间传说很有名。", "target_word": "民间传说", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我喜欢听民间传说。", "target_word": "民间传说", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这本书里有很多中国民间传说。", "target_word": "民间传说", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个民间传说里有一条龙。", "target_word": "民间传说", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老人们常常讲民间传说。", "target_word": "民间传说", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他把这个民间传说写成了书。", "target_word": "民间传说", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "民间传说里常常有神仙。", "target_word": "民间传说", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个民间传说讲的是一个女孩。", "target_word": "民间传说", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "晚上，爸爸给孩子讲民间传说。", "target_word": "民间传说", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "个", "label": "量词"}, {"form": "民間傳說", "label": "繁体"}], "register": "中性", "sense_fingerprint": "老百姓一代一代讲下来的老故事，常有神奇的人和事", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a89628db-2a92-48c4-bb2a-aa8338e4bf66') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24360, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "民间传说", "is_correct": true, "explanation": "民间传说：老百姓口耳相传的老故事，与“奶奶给我讲了一个”的语境相符。"}, {"text": "歌曲", "is_correct": false, "explanation": "搭配：“讲”用于故事、话语，不能说讲歌曲。"}, {"text": "饺子", "is_correct": false, "explanation": "语义：饺子是食物，不是可以讲述的内容。"}, {"text": "照片", "is_correct": false, "explanation": "搭配：照片要用量词“张”，而且“讲”不接照片，“一个照片”也不成立。"}], "explanations": {"民间传说": "民间传说：老百姓口耳相传的老故事，与“奶奶给我讲了一个”的语境相符。", "歌曲": "搭配：“讲”用于故事、话语，不能说讲歌曲。", "饺子": "语义：饺子是食物，不是可以讲述的内容。", "照片": "搭配：照片要用量词“张”，而且“讲”不接照片，“一个照片”也不成立。"}, "sentence_index": 0, "correct_answer": "民间传说"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我每天早上喝一杯民间传说。", "explanation": "这里应该用〈牛奶〉。民间传说是流传下来的老故事，不能喝。"}, {"text": "我的自行车坏了，我要买一个新的民间传说。", "explanation": "这里应该用〈车铃〉。民间传说是故事，不是自行车的零件，不能买来换上。"}, {"text": "电视里播报了明天的民间传说。", "explanation": "这里应该用〈天气预报〉。播报的是将来的信息，民间传说是老故事，不能拿来播报。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b9405f69-aefb-4e89-9803-91f08f3f19d9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24360, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "民间传说", "is_correct": true, "explanation": "民间传说：老百姓流传的故事，可以被写成书，与“写成了书”的语境相符。"}, {"text": "天气", "is_correct": false, "explanation": "语义：天气是自然现象，不能被写成书。"}, {"text": "颜色", "is_correct": false, "explanation": "语义：颜色是视觉属性，不是可以写成书的内容。"}, {"text": "面貌", "is_correct": false, "explanation": "语义：面貌指人或事物的外表，不是可以写成书的故事。"}], "explanations": {"民间传说": "民间传说：老百姓流传的故事，可以被写成书，与“写成了书”的语境相符。", "天气": "语义：天气是自然现象，不能被写成书。", "颜色": "语义：颜色是视觉属性，不是可以写成书的内容。", "面貌": "语义：面貌指人或事物的外表，不是可以写成书的故事。"}, "sentence_index": 6, "correct_answer": "民间传说"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我昨天买了一只民间传说。", "explanation": "这里应该用〈个〉。“只”多用于动物，民间传说是故事，应该用“个”。"}, {"text": "爸爸昨天讲了一台民间传说。", "explanation": "这里应该用〈个〉。“台”用于机器等，民间传说是故事，不用“台”来计量。"}, {"text": "书架上放着一张民间传说。", "explanation": "这里应该用〈个〉。“张”用于平面的东西，民间传说是故事，不用“张”来计量。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b9405f69-aefb-4e89-9803-91f08f3f19d9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24360, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我小时候常听一只民间传说。", "corrected_sentence": "我小时候常听一个民间传说。", "error_description": "量词错误：“民间传说”应该用“个”，不能用“只”。“只”多用于动物，应说“一个民间传说”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b9405f69-aefb-4e89-9803-91f08f3f19d9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24360, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这是一个有名地民间传说。", "corrected_sentence": "这是一个有名的民间传说。", "error_description": "错误：“有名地民间传说”。正确：“有名的民间传说”。“的”用于定语修饰名词，“地”用于状语修饰动词，这里应用“的”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b9405f69-aefb-4e89-9803-91f08f3f19d9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
