INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24362, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "爸爸就是父亲，孩子对自己父亲的口语称呼。", "primary_collocate": null, "pronunciation": "bà ba", "ipa": "pa⁵¹ pa", "syllable_count": 2, "sentences": [{"text": "爸爸叫我宝贝，我很开心。", "target_word": "爸爸", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "有爸爸在，我什么都不怕。", "target_word": "爸爸", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "晚上走夜路，爸爸一直走在我前面保护我。", "target_word": "爸爸", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子哭了，爸爸马上把她抱起来。", "target_word": "爸爸", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我生病的时候，爸爸整夜坐在床边。", "target_word": "爸爸", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "爸爸说，不管发生什么事，他都站在我这边。", "target_word": "爸爸", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小女孩跑过去，大声叫了一声“爸爸”。", "target_word": "爸爸", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "爸爸的手很大，牵着我过马路。", "target_word": "爸爸", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我考得不好，爸爸没有生气，只是抱抱我。", "target_word": "爸爸", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "爸爸每天早上给我做早饭，再送我上学。", "target_word": "爸爸", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "老爸", "label": "口语称呼"}, {"form": "爸爸们", "label": "复数"}, {"form": "一个爸爸", "label": "量词：个"}, {"form": "一位爸爸", "label": "量词：位"}], "register": "口语", "sense_fingerprint": "名词：孩子的父亲（口语称呼）", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '03bc8be5-758a-4101-a27b-8c54507243b1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24362, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "爸爸", "is_correct": true, "explanation": "正确答案。bà ba，第二音节为轻声，指保护孩子、疼爱孩子的父亲。"}, {"text": "罢了", "is_correct": false, "explanation": "罢了读作 bà le，第一音节与 bà ba 相同，第二音节不同，意思是“而已”，与父亲无关。"}, {"text": "拜拜", "is_correct": false, "explanation": "拜拜读作 bài bai，第一音节韵母不同（ai 与 a），意思是再见，与父亲无关。"}, {"text": "爸妈", "is_correct": false, "explanation": "bà mā 与 bà ba 第二音节声母不同（b 与 m），声调也改变，意思是父母，指两人。"}], "explanations": {"爸爸": "正确答案。bà ba，第二音节为轻声，指保护孩子、疼爱孩子的父亲。", "罢了": "罢了读作 bà le，第一音节与 bà ba 相同，第二音节不同，意思是“而已”，与父亲无关。", "拜拜": "拜拜读作 bài bai，第一音节韵母不同（ai 与 a），意思是再见，与父亲无关。", "爸妈": "bà mā 与 bà ba 第二音节声母不同（b 与 m），声调也改变，意思是父母，指两人。"}, "sentence_index": null, "correct_answer": "爸爸"}, "level_3": {"options": [{"text": "爸爸", "is_correct": true, "explanation": "爸爸：父亲亲昵地叫孩子“宝贝”，符合保护、疼爱孩子的语境。"}, {"text": "树", "is_correct": false, "explanation": "语义：树不会叫人“宝贝”，句中的“叫我宝贝”需要有感情的人作主语。"}, {"text": "汽车", "is_correct": false, "explanation": "语义：汽车不会叫人“宝贝”，句中的“叫我宝贝”需要有感情的人作主语。"}, {"text": "椅子", "is_correct": false, "explanation": "语义：椅子不会说话，不能叫人“宝贝”，句子需要有感情的人作主语。"}], "explanations": {"爸爸": "爸爸：父亲亲昵地叫孩子“宝贝”，符合保护、疼爱孩子的语境。", "树": "语义：树不会叫人“宝贝”，句中的“叫我宝贝”需要有感情的人作主语。", "汽车": "语义：汽车不会叫人“宝贝”，句中的“叫我宝贝”需要有感情的人作主语。", "椅子": "语义：椅子不会说话，不能叫人“宝贝”，句子需要有感情的人作主语。"}, "sentence_index": 0, "correct_answer": "爸爸"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我的爸爸是我爸爸的爸爸，每次见面都给我压岁钱。", "explanation": "这里应该用〈爷爷〉。爸爸指父亲，不能指父亲的父亲；父亲的父亲应称〈爷爷〉。"}, {"text": "我的爸爸是我妈妈的哥哥，每年春节都给我寄红包。", "explanation": "这里应该用〈舅舅〉。爸爸指父亲，不能指母亲的哥哥；母亲的哥哥应称〈舅舅〉。"}, {"text": "我的爸爸今年六岁，每天背着书包去上学。", "explanation": "这里应该用〈孩子〉。爸爸指成年的父亲，不能指六岁、背着书包上学的小孩；这样的小孩应称〈孩子〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c4f41e8b-5b5f-4b38-b6a8-f796304b6d66') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24362, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "爸爸", "is_correct": true, "explanation": "正确答案。bà ba，第二音节为轻声，指保护孩子、疼爱孩子的父亲。"}, {"text": "巴巴", "is_correct": false, "explanation": "巴巴读作 bā ba。第一音节是第一声，与 bà ba 的声调不同。意思是急切、迫切，与父亲无关。"}, {"text": "白白", "is_correct": false, "explanation": "白白读作 bái bai，第一音节声调与 bà ba 不同（第二声），意思是没有代价地、徒然，与父亲无关。"}, {"text": "怕怕", "is_correct": false, "explanation": "怕怕读作 pà pa。它的声调与 bà ba 相同，只有声母不同（p 与 b）。这是儿语，意思是害怕，与父亲无关。"}], "explanations": {"爸爸": "正确答案。bà ba，第二音节为轻声，指保护孩子、疼爱孩子的父亲。", "巴巴": "巴巴读作 bā ba。第一音节是第一声，与 bà ba 的声调不同。意思是急切、迫切，与父亲无关。", "白白": "白白读作 bái bai，第一音节声调与 bà ba 不同（第二声），意思是没有代价地、徒然，与父亲无关。", "怕怕": "怕怕读作 pà pa。它的声调与 bà ba 相同，只有声母不同（p 与 b）。这是儿语，意思是害怕，与父亲无关。"}, "sentence_index": null, "correct_answer": "爸爸"}, "level_3": {"options": [{"text": "爸爸", "is_correct": true, "explanation": "爸爸：小女孩大声叫的是父亲，符合“跑过去”“叫一声”的语境。"}, {"text": "石头", "is_correct": false, "explanation": "语义：石头不能被称呼，这里的“叫”要求一个能被称呼的人。"}, {"text": "窗户", "is_correct": false, "explanation": "搭配：“叫一声”的对象应是人，窗户不能作为称呼。"}, {"text": "书包", "is_correct": false, "explanation": "语义：书包不是人，与“大声叫”的语境不符。"}], "explanations": {"爸爸": "爸爸：小女孩大声叫的是父亲，符合“跑过去”“叫一声”的语境。", "石头": "语义：石头不能被称呼，这里的“叫”要求一个能被称呼的人。", "窗户": "搭配：“叫一声”的对象应是人，窗户不能作为称呼。", "书包": "语义：书包不是人，与“大声叫”的语境不符。"}, "sentence_index": 6, "correct_answer": "爸爸"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "刚出生的爸爸还不会说话。", "explanation": "这里应该用〈婴儿〉。爸爸指成年的父亲，刚出生、还不会说话的应是〈婴儿〉。"}, {"text": "爸爸还在念小学三年级，每天要在课堂上举手发言。", "explanation": "这里应该用〈小学生〉。爸爸指孩子的父亲，不能指还在念小学的孩子，这样的孩子应称〈小学生〉。"}, {"text": "我的爸爸比我小两岁，每天要我陪他玩。", "explanation": "这里应该用〈弟弟〉。爸爸指父亲，比我小的兄弟应称〈弟弟〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c4f41e8b-5b5f-4b38-b6a8-f796304b6d66') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24362, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我的爸爸们每天下班后都会陪我玩。", "corrected_sentence": "我的爸爸每天下班后都会陪我玩。", "error_description": "复数错误：“爸爸们”表示多位父亲，这里只指我一个父亲，应去掉“们”，说“我的爸爸”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c4f41e8b-5b5f-4b38-b6a8-f796304b6d66') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24362, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "那边有一只爸爸在陪孩子看书。", "corrected_sentence": "那边有一位爸爸在陪孩子看书。", "error_description": "量词错误：“爸爸”指人，量词应用“位”（或“个”），“只”只用于动物，不能说“一只爸爸”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c4f41e8b-5b5f-4b38-b6a8-f796304b6d66') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24364, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "听", "is_correct": true, "explanation": "正确：“听”与“讲”相对，指用耳朵接收别人说的话，与用嘴说出话相反。"}, {"text": "跑", "is_correct": false, "explanation": "跑是快速移动双腿，与“讲”没有反义关系。"}, {"text": "洗", "is_correct": false, "explanation": "洗是用水去除污垢，与“讲”没有反义关系。"}, {"text": "写", "is_correct": false, "explanation": "写是书写文字，与“讲”没有反义关系。"}], "correct_answer": "听", "explanations": {"听": "正确：“听”与“讲”相对，指用耳朵接收别人说的话，与用嘴说出话相反。", "跑": "跑是快速移动双腿，与“讲”没有反义关系。", "洗": "洗是用水去除污垢，与“讲”没有反义关系。", "写": "写是书写文字，与“讲”没有反义关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '522a0a63-ca91-46af-bf7c-07bce5feac33') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24364, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "听", "is_correct": true, "explanation": "正确：“听”与“讲”相对，指用耳朵接收别人说的话，与用嘴说出话相反。"}, {"text": "读", "is_correct": false, "explanation": "读是看着文字出声或默念，与“讲”没有反义关系。"}, {"text": "画", "is_correct": false, "explanation": "画是用线条或颜色描绘，与“讲”没有反义关系。"}, {"text": "唱", "is_correct": false, "explanation": "唱是发出乐音，与“讲”没有反义关系。"}], "correct_answer": "听", "explanations": {"听": "正确：“听”与“讲”相对，指用耳朵接收别人说的话，与用嘴说出话相反。", "读": "读是看着文字出声或默念，与“讲”没有反义关系。", "画": "画是用线条或颜色描绘，与“讲”没有反义关系。", "唱": "唱是发出乐音，与“讲”没有反义关系。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '522a0a63-ca91-46af-bf7c-07bce5feac33') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24364, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "用嘴巴说出话来。", "primary_collocate": null, "pronunciation": "jiǎng", "ipa": "tɕiɑŋ²¹⁴", "syllable_count": 1, "sentences": [{"text": "老师在给我们讲故事。", "target_word": "讲", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "请你再讲一遍。", "target_word": "讲", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "他讲得很慢，我听懂了。", "target_word": "讲", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "爷爷常常讲以前的事。", "target_word": "讲", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "她会讲三种语言。", "target_word": "讲", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他在台上讲了十分钟。", "target_word": "讲", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他用很小的声音讲了一句话。", "target_word": "讲", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这件事我没跟别人讲过。", "target_word": "讲", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子们安静地听奶奶讲。", "target_word": "讲", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你能不能讲讲你的想法？", "target_word": "讲", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "讲着", "label": "体标"}, {"form": "讲了", "label": "体标"}, {"form": "讲过", "label": "体标"}, {"form": "讲讲", "label": "重叠"}, {"form": "讲话", "label": "复合"}, {"form": "講", "label": "繁体"}], "register": "中性", "sense_fingerprint": "用嘴说话、叙述或说明", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '172f7e52-d98b-43ac-869e-8829631459cd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24364, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "讲", "is_correct": true, "explanation": "正确：jiǎng（第三声）即“讲”，意思是用嘴说出话来。"}, {"text": "江", "is_correct": false, "explanation": "jiāng（第一声）与 jiǎng（第三声）声调不同，意思是江河。"}, {"text": "想", "is_correct": false, "explanation": "xiǎng 与 jiǎng 声母不同（x 与 j），意思是思考或想念。"}, {"text": "降", "is_correct": false, "explanation": "jiàng（第四声）与 jiǎng 声调不同，意思是下降。"}, {"text": "剪", "is_correct": false, "explanation": "jiǎn 与 jiǎng 韵母不同（n 与 ng），意思是剪断。"}], "explanations": {"讲": "正确：jiǎng（第三声）即“讲”，意思是用嘴说出话来。", "江": "jiāng（第一声）与 jiǎng（第三声）声调不同，意思是江河。", "想": "xiǎng 与 jiǎng 声母不同（x 与 j），意思是思考或想念。", "降": "jiàng（第四声）与 jiǎng 声调不同，意思是下降。", "剪": "jiǎn 与 jiǎng 韵母不同（n 与 ng），意思是剪断。"}, "sentence_index": null, "correct_answer": "讲"}, "level_3": {"options": [{"text": "讲", "is_correct": true, "explanation": "正确：“讲故事”是用语言叙述故事，符合句意。"}, {"text": "洗", "is_correct": false, "explanation": "配价：“洗”通常接衣物等，不接“故事”作宾语。"}, {"text": "吃", "is_correct": false, "explanation": "语义：故事不能吃，“给我们吃故事”句意不通。"}, {"text": "摘", "is_correct": false, "explanation": "语义：摘是采下果实等，不能用于故事。"}], "explanations": {"讲": "正确：“讲故事”是用语言叙述故事，符合句意。", "洗": "配价：“洗”通常接衣物等，不接“故事”作宾语。", "吃": "语义：故事不能吃，“给我们吃故事”句意不通。", "摘": "语义：摘是采下果实等，不能用于故事。"}, "sentence_index": 0, "correct_answer": "讲"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "她每天在家讲三首歌，很开心。", "explanation": "这里应该用〈唱〉。讲指用嘴说出话来，唱歌要用唱。"}, {"text": "他把一封长信讲进信封，寄给朋友。", "explanation": "这里应该用〈装〉。讲指用嘴说出话来，把信装进信封要用“装”。"}, {"text": "妈妈在厨房里讲饺子。", "explanation": "这里应该用〈包〉。讲指用嘴说出话来，包饺子要用包。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '522a0a63-ca91-46af-bf7c-07bce5feac33') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24364, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "讲", "is_correct": true, "explanation": "正确：jiǎng（第三声）即“讲”，意思是用嘴说出话来。"}, {"text": "抢", "is_correct": false, "explanation": "qiǎng 与 jiǎng 声母不同（q 与 j），意思是抢夺。"}, {"text": "将", "is_correct": false, "explanation": "jiāng（第一声）与 jiǎng 声调不同，意思是将要。"}, {"text": "酱", "is_correct": false, "explanation": "jiàng（第四声）与 jiǎng（第三声）声调不同，意思是酱料。"}], "explanations": {"讲": "正确：jiǎng（第三声）即“讲”，意思是用嘴说出话来。", "抢": "qiǎng 与 jiǎng 声母不同（q 与 j），意思是抢夺。", "将": "jiāng（第一声）与 jiǎng 声调不同，意思是将要。", "酱": "jiàng（第四声）与 jiǎng（第三声）声调不同，意思是酱料。"}, "sentence_index": null, "correct_answer": "讲"}, "level_3": {"options": [{"text": "讲", "is_correct": true, "explanation": "正确：“讲了一句话”是用声音说出一句话，符合句意。"}, {"text": "吼", "is_correct": false, "explanation": "语义：吼是大声喊叫，与“很小的声音”矛盾。"}, {"text": "写", "is_correct": false, "explanation": "语义：写是书写，不发声，与“用很小的声音”矛盾。"}, {"text": "吃", "is_correct": false, "explanation": "语义：吃是把食物咽下，不能用声音“吃”一句话，句意不通。"}], "explanations": {"讲": "正确：“讲了一句话”是用声音说出一句话，符合句意。", "吼": "语义：吼是大声喊叫，与“很小的声音”矛盾。", "写": "语义：写是书写，不发声，与“用很小的声音”矛盾。", "吃": "语义：吃是把食物咽下，不能用声音“吃”一句话，句意不通。"}, "sentence_index": 6, "correct_answer": "讲"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我每天晚上都讲一本书，九点睡觉。", "explanation": "这里应该用〈看〉。讲指用嘴说出话来，看书要用“看”。"}, {"text": "他在河里讲了一个小时，很累。", "explanation": "这里应该用〈游〉。讲指用嘴说出话来，在河里游泳要用“游”。"}, {"text": "妹妹讲了一张很漂亮的画。", "explanation": "这里应该用〈画〉。讲指用嘴说出话来，作画要用“画”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '522a0a63-ca91-46af-bf7c-07bce5feac33') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24364, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "她讲很清楚，大家都听懂了。", "corrected_sentence": "她讲得很清楚，大家都听懂了。", "error_description": "补语标记缺失：“讲很清楚”应为“讲得很清楚”。形容词作补语前必须用“得”引出。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '522a0a63-ca91-46af-bf7c-07bce5feac33') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24364, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他以前讲了过这个故事。", "corrected_sentence": "他以前讲过这个故事。", "error_description": "“讲了过”错误：“过”已表示曾经有过的经历，不能再加“了”，应为“讲过”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '522a0a63-ca91-46af-bf7c-07bce5feac33') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
