INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24366, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "可控性是说一件事能不能被我们管住或控制住。", "primary_collocate": null, "pronunciation": "kě kòng xìng", "ipa": "kʰɤ˨˩ kʰʊŋ˥˩ ɕiŋ˥˩", "syllable_count": 3, "sentences": [{"text": "这件事的可控性不高，我们只能慢慢看。", "target_word": "可控性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "开会前先想想，哪些问题的可控性比较大。", "target_word": "可控性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "天气的可控性很小，所以我们要带伞。", "target_word": "可控性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子的情绪有时候可控性不强，家长要耐心。", "target_word": "可控性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这辆车的可控性很好，新手也能开。", "target_word": "可控性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "做计划时，要先看事情的可控性。", "target_word": "可控性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "事情的可控性越大，我们越不用担心。", "target_word": "可控性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们应该多做可控性高的事。", "target_word": "可控性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "水灾的可控性很低，大家要提前准备。", "target_word": "可控性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师说，学习时间的可控性很重要。", "target_word": "可控性", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "通用", "sense_fingerprint": "一件事能不能被我们管住、控制住", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7a98d740-f54a-4403-9fa2-3db6e5ff3669') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24366, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "可控性", "is_correct": true, "explanation": "正确：“可控性”指事情能否被管住，与“这件事的……不高，我们只能慢慢看”的语境相合。"}, {"text": "颜色", "is_correct": false, "explanation": "搭配：“高”用于程度、水平，颜色不说“不高”，应说颜色深浅。"}, {"text": "体积", "is_correct": false, "explanation": "搭配：“体积”用大小描述，不说“体积不高”。"}, {"text": "亮度", "is_correct": false, "explanation": "搭配：“亮度”指光的明暗，不能用来形容事情，“这件事的亮度不高”不成立。"}], "explanations": {"可控性": "正确：“可控性”指事情能否被管住，与“这件事的……不高，我们只能慢慢看”的语境相合。", "颜色": "搭配：“高”用于程度、水平，颜色不说“不高”，应说颜色深浅。", "体积": "搭配：“体积”用大小描述，不说“体积不高”。", "亮度": "搭配：“亮度”指光的明暗，不能用来形容事情，“这件事的亮度不高”不成立。"}, "sentence_index": 0, "correct_answer": "可控性"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "天气的可控性很高，我们可以提前安排出行。", "explanation": "这里应该用〈可预测性〉。可控性指能否被人管住，天气管不住，提前安排依靠的是可预测性。"}, {"text": "这道菜的可控性很高，大家都说好吃。", "explanation": "这里应该用〈味道〉。可控性指能否被管住，说菜好吃要用味道，不能用可控性。"}, {"text": "这个消息的可控性很高，大家都很相信。", "explanation": "这里应该用〈可信度〉。可控性说的是能否被管住，消息值不值得相信要用可信度。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '85a560c0-e25b-45da-8d09-012977d92966') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24366, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "可控性", "is_correct": true, "explanation": "正确：“事情的可控性越大，我们越不用担心”，“可控性”指事情能否被管住，语境相合。"}, {"text": "温度", "is_correct": false, "explanation": "语义：温度越大往往令人更担心，与“越不用担心”的语义相反。"}, {"text": "噪音", "is_correct": false, "explanation": "语义：噪音越大越让人烦躁，与“越不用担心”的语义相反。"}, {"text": "面积", "is_correct": false, "explanation": "搭配：“面积”形容空间大小，不修饰“事情”。"}], "explanations": {"可控性": "正确：“事情的可控性越大，我们越不用担心”，“可控性”指事情能否被管住，语境相合。", "温度": "语义：温度越大往往令人更担心，与“越不用担心”的语义相反。", "噪音": "语义：噪音越大越让人烦躁，与“越不用担心”的语义相反。", "面积": "搭配：“面积”形容空间大小，不修饰“事情”。"}, "sentence_index": 6, "correct_answer": "可控性"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这张沙发的可控性很高，坐一整天也不累。", "explanation": "这里应该用〈舒适度〉。可控性指能否被控制，坐着不累说的是舒适度。"}, {"text": "这段文字的可控性很高，每个字都看得清。", "explanation": "这里应该用〈清晰度〉。可控性不说明文字是否清楚，看得清要用清晰度。"}, {"text": "这座桥的可控性很高，大家都放心过。", "explanation": "这里应该用〈安全性〉。可控性指能否被管住，让人放心通过说的是安全性。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '85a560c0-e25b-45da-8d09-012977d92966') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24366, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这次装修地可控性不高，我们只能等。", "corrected_sentence": "这次装修的可控性不高，我们只能等。", "error_description": "错误：“地”是状语标记，不能用来修饰名词“可控性”。修饰名词应用定语标记“的”，应说“这次装修的可控性不高”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '85a560c0-e25b-45da-8d09-012977d92966') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24366, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这次活动的很可控性越大，大家越放心。", "corrected_sentence": "这次活动的可控性越大，大家越放心。", "error_description": "错误：副词“很”修饰名词“可控性”，这样用不成立。“的”后应直接接“可控性”，应删去“很”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '85a560c0-e25b-45da-8d09-012977d92966') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24370, 1, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '262058fb-ffae-436a-9afa-628a922d9e2c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24370, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '262058fb-ffae-436a-9afa-628a922d9e2c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24370, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "地面上升起来的高高的部分，比如石头山或土山。", "primary_collocate": null, "pronunciation": "shān", "ipa": "ʂan˥", "syllable_count": 1, "sentences": [{"text": "这座山上没有树，只有很多大石头。", "target_word": "山", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "村子旁边那座山上长满了草。", "target_word": "山", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "山很陡，路也不好走。", "target_word": "山", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子们站在山下看风景。", "target_word": "山", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那座山上有一座小庙。", "target_word": "山", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这座山不高，半天就能爬到上面。", "target_word": "山", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们把车停在山前。", "target_word": "山", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "山那边是另一个村子。", "target_word": "山", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我小时候每天看着这座山。", "target_word": "山", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "下雨以后，山更绿了。", "target_word": "山", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "座", "label": "量词"}, {"form": "山路", "label": "复合"}], "register": "中性", "sense_fingerprint": "地面隆起的高处，如石头山、土山", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9396a7ad-604e-4eae-9004-ebab4a4f74bb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24370, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "山", "is_correct": true, "explanation": "正确。shān（第一声），指地面隆起的高处，如石头山、土山。"}, {"text": "三", "is_correct": false, "explanation": "sān（第一声）与 shān（第一声）声母不同（s 与 sh），意思是“三”。"}, {"text": "伤", "is_correct": false, "explanation": "shāng（第一声）与 shān（第一声）韵母不同（-ang 与 -an），意思是“伤”。"}, {"text": "闪", "is_correct": false, "explanation": "shǎn（第三声）与 shān（第一声）声调不同，意思是“闪”。"}, {"text": "身", "is_correct": false, "explanation": "shēn（第一声）与 shān（第一声）韵母不同（-en 与 -an），意思是“身体”。"}], "explanations": {"山": "正确。shān（第一声），指地面隆起的高处，如石头山、土山。", "三": "sān（第一声）与 shān（第一声）声母不同（s 与 sh），意思是“三”。", "伤": "shāng（第一声）与 shān（第一声）韵母不同（-ang 与 -an），意思是“伤”。", "闪": "shǎn（第三声）与 shān（第一声）声调不同，意思是“闪”。", "身": "shēn（第一声）与 shān（第一声）韵母不同（-en 与 -an），意思是“身体”。"}, "sentence_index": null, "correct_answer": "山"}, "level_3": {"options": [{"text": "山", "is_correct": true, "explanation": "正确。“这座……上没有树”指的是地面隆起的高处，与“大石头”相符。"}, {"text": "大楼", "is_correct": false, "explanation": "语义：大楼是人造建筑，与“没有树、只有大石头”描写的自然地貌不符。"}, {"text": "房子", "is_correct": false, "explanation": "语义：房子是人造建筑，“没有树，只有很多大石头”描写的是自然地貌，与房子不符。"}, {"text": "宫殿", "is_correct": false, "explanation": "语义：宫殿是人造建筑，不是地面隆起的部分，与“大石头”的自然景象不符。"}], "explanations": {"山": "正确。“这座……上没有树”指的是地面隆起的高处，与“大石头”相符。", "大楼": "语义：大楼是人造建筑，与“没有树、只有大石头”描写的自然地貌不符。", "房子": "语义：房子是人造建筑，“没有树，只有很多大石头”描写的是自然地貌，与房子不符。", "宫殿": "语义：宫殿是人造建筑，不是地面隆起的部分，与“大石头”的自然景象不符。"}, "sentence_index": 0, "correct_answer": "山"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "孩子们把那座山种在院子里。", "explanation": "这里不能说“种”。“种”的对象应是植物，山是地形，不能被种。"}, {"text": "孩子们把那座山喝了下去。", "explanation": "这里不能说“喝”。“喝”的对象应是液体，山不能被喝下去。"}, {"text": "孩子们站在一只山下看风景。", "explanation": "这里应该用〈座〉。山的量词是“座”，“只”多用于动物，不能用于山。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '262058fb-ffae-436a-9afa-628a922d9e2c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24370, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "山", "is_correct": true, "explanation": "正确。shān（第一声），指地面隆起的高处。"}, {"text": "善", "is_correct": false, "explanation": "shàn（第四声）与 shān（第一声）声调不同，意思是“善良”。"}, {"text": "深", "is_correct": false, "explanation": "shēn（第一声）与 shān（第一声）韵母不同（-en 与 -an），意思是“深”。"}, {"text": "扇", "is_correct": false, "explanation": "shàn（第四声）与 shān（第一声）声调不同，意思是“扇子”。"}], "explanations": {"山": "正确。shān（第一声），指地面隆起的高处。", "善": "shàn（第四声）与 shān（第一声）声调不同，意思是“善良”。", "深": "shēn（第一声）与 shān（第一声）韵母不同（-en 与 -an），意思是“深”。", "扇": "shàn（第四声）与 shān（第一声）声调不同，意思是“扇子”。"}, "sentence_index": null, "correct_answer": "山"}, "level_3": {"options": [{"text": "山", "is_correct": true, "explanation": "正确。“停在……前”指的是地面上的一处地点，山前可以停车。"}, {"text": "地图", "is_correct": false, "explanation": "语义：地图是纸上的图，不是可以停车的地面处所，“停在地图前”不成立。"}, {"text": "云", "is_correct": false, "explanation": "语义：云在空中，不是可以停车的地面处所，与句子的语境不符。"}, {"text": "海", "is_correct": false, "explanation": "语义：海是广阔的水域，车不能停在海的前面。"}], "explanations": {"山": "正确。“停在……前”指的是地面上的一处地点，山前可以停车。", "地图": "语义：地图是纸上的图，不是可以停车的地面处所，“停在地图前”不成立。", "云": "语义：云在空中，不是可以停车的地面处所，与句子的语境不符。", "海": "语义：海是广阔的水域，车不能停在海的前面。"}, "sentence_index": 6, "correct_answer": "山"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他把那座山放进了书包。", "explanation": "这里不能说“放进书包”。山体积太大，不能装进书包，它不是可以随身携带的小东西。"}, {"text": "他用那座山写字。", "explanation": "这里不能说“用……写字”。山不是书写工具，“用”后应接笔、纸等工具。"}, {"text": "她煮了那座山，给大家吃。", "explanation": "这里不能说“煮”。“煮”的对象应是食物，山不能被煮，也不能被吃。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '262058fb-ffae-436a-9afa-628a922d9e2c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24370, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "孩子们爬上了那只山。", "corrected_sentence": "孩子们爬上了那座山。", "error_description": "量词错误：“山”的量词应用“座”，不用“只”。“只”多用于小动物或成对的物品。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '262058fb-ffae-436a-9afa-628a922d9e2c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24370, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我们昨天去看了一只山。", "corrected_sentence": "我们昨天去看了一座山。", "error_description": "量词错误：“山”的量词应用“座”，不用“只”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '262058fb-ffae-436a-9afa-628a922d9e2c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
