INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24372, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "老人就是年纪很大的人。", "primary_collocate": null, "pronunciation": "lǎo rén", "ipa": "lau̯˨˩˦ ʐən˧˥", "syllable_count": 2, "sentences": [{"text": "那位老人八十岁了。", "target_word": "老人", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "公园里有很多老人。", "target_word": "老人", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "老人坐在门口看报纸。", "target_word": "老人", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "我帮一位老人拿东西。", "target_word": "老人", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "这位老人每天早上去散步。", "target_word": "老人", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "在公交车上，我给老人让了座。", "target_word": "老人", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "老人的手里拿着一把旧伞。", "target_word": "老人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "村子里的老人都很喜欢讲过去的故事。", "target_word": "老人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他从小和老人住在一起，很会照顾他们。", "target_word": "老人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "路上，一位老人慢慢走在我前面。", "target_word": "老人", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "位", "label": "量词"}, {"form": "老人们", "label": "复数形式"}, {"form": "老人家", "label": "复合词"}], "register": "中性", "sense_fingerprint": "年纪很大的人", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ed69058d-24aa-4c07-bc40-36884250d128') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24372, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "老人", "is_correct": true, "explanation": "老人指年纪很大的人，与“八十岁”相配，符合句意。"}, {"text": "婴儿", "is_correct": false, "explanation": "语义：婴儿刚出生，不可能八十岁。"}, {"text": "小伙子", "is_correct": false, "explanation": "搭配：小伙子指年轻男子，与“八十岁”搭配不当。"}, {"text": "少年", "is_correct": false, "explanation": "语义：少年指未成年的人，与“八十岁”矛盾。"}], "explanations": {"老人": "老人指年纪很大的人，与“八十岁”相配，符合句意。", "婴儿": "语义：婴儿刚出生，不可能八十岁。", "小伙子": "搭配：小伙子指年轻男子，与“八十岁”搭配不当。", "少年": "语义：少年指未成年的人，与“八十岁”矛盾。"}, "sentence_index": 0, "correct_answer": "老人"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "刚出生的老人很可爱。", "explanation": "这里应该用〈婴儿〉。老人指年纪很大的人，刚出生的孩子要说婴儿。"}, {"text": "这位老人才二十岁，很年轻。", "explanation": "这里应该用〈年轻人〉。老人指年纪很大的人，二十岁的人要说年轻人。"}, {"text": "院子里的老人正在玩积木，他才三岁。", "explanation": "这里应该用〈幼儿〉。老人指年纪很大的人，三岁的孩子要说幼儿。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b40bdfe4-ba79-4ecd-b88f-4c9a825bd20a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24372, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "老人", "is_correct": true, "explanation": "老人是人，能拿旧伞，与“手里”相配，符合句意。"}, {"text": "石头", "is_correct": false, "explanation": "语义：石头没有手，不能拿伞。"}, {"text": "小猫", "is_correct": false, "explanation": "语义：小猫的前爪不是手，不能说手里拿着伞。"}, {"text": "桌子", "is_correct": false, "explanation": "语义：桌子没有手，不能拿伞。"}], "explanations": {"老人": "老人是人，能拿旧伞，与“手里”相配，符合句意。", "石头": "语义：石头没有手，不能拿伞。", "小猫": "语义：小猫的前爪不是手，不能说手里拿着伞。", "桌子": "语义：桌子没有手，不能拿伞。"}, "sentence_index": 6, "correct_answer": "老人"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "路上，一位老人才十岁，慢慢走在我前面。", "explanation": "这里应该用〈小朋友〉。老人指年纪很大的人，十岁的孩子要说小朋友。"}, {"text": "路上，一位老人正在上小学，慢慢走在我前面。", "explanation": "这里应该用〈小学生〉。老人指年纪很大的人，上小学的孩子要说小学生。"}, {"text": "路上，一位老人在妈妈怀里睡觉，他才一岁。", "explanation": "这里应该用〈婴儿〉。老人指年纪很大的人，一岁的孩子要说婴儿。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b40bdfe4-ba79-4ecd-b88f-4c9a825bd20a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24372, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "两位老人们在公园里散步。", "corrected_sentence": "两位老人在公园里散步。", "error_description": "错误：数词“两”加量词“位”后，名词“老人”后面不能再加“们”，应说“两位老人”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b40bdfe4-ba79-4ecd-b88f-4c9a825bd20a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24372, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "一位的老人慢慢走过来。", "corrected_sentence": "一位老人慢慢走过来。", "error_description": "错误：数量短语“一位”和名词“老人”之间不能加“的”，应说“一位老人”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b40bdfe4-ba79-4ecd-b88f-4c9a825bd20a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
